t.guides["forever/40-50/shendralas"] = (function() return {
		["A Prowler gave up a {quest:93568}: {npc:255385}, north of the temple, knows whose it was."] = "배회자가 {quest:93568}을(를) 떨어뜨렸습니다. 사원 북쪽의 {npc:255385}이(가) 주인을 알고 있습니다.",
		["About a dozen quests on a short trip into Forever's new zone (about 45-46 for the Alliance, 47 for the Horde), then on to {zone:1444}."] = "Forever의 새 지역을 잠깐 들러 퀘스트 십여 개를 하고(얼라이언스 약 45-46레벨, 호드 47레벨) {zone:1444}(으)로 넘어갑니다.",
		["Back into the {area:2657}"] = "다시 {area:2657}(으)로",
		["Back to your route"] = "원래 경로로 돌아가기",
		["Back west along the valley road and south to {npc:253471}. {quest:93016} asks you to hear him out: talk to him once more, then hand it in."] = "골짜기 길을 따라 다시 서쪽으로 간 뒤 남쪽의 {npc:253471}에게 가십시오. {quest:93016}은(는) 그의 이야기를 들어야 합니다. 한 번 더 대화한 뒤 제출하십시오.",
		["East again along {area:405}'s southern edge: the {area:2657} opens into {area:16651}."] = "{area:405}의 남쪽 가장자리를 따라 다시 동쪽으로 가십시오. {area:2657}은(는) {area:16651}(으)로 이어집니다.",
		["East along the valley road to the eastern pylon and repair it the same way, a {npc:252711} first, coming in from the west: {npc:253527} (level 43, elite) and his bodyguards hold the south side of the quilboar camp, and a Corpsefeeder (level 45, elite) walks the road."] = "골짜기 길을 따라 동쪽 수정탑으로 가서 같은 방법으로 수리하십시오. 먼저 {npc:252711}을(를) 잡되 서쪽에서 접근하십시오. {npc:253527}(43레벨, 정예)와(과) 그의 호위병이 가시멧돼지 야영지 남쪽을 차지하고 있고, 시체포식자(45레벨, 정예)가 길을 돌아다닙니다.",
		["East along the valley road to the quilboar of {area:16677}: the second pylon stands at the eastern end of their camp. A Corpsefeeder (level 45, elite) walks this road: let it pass. The Bristlebacks (levels 42-43) attack on sight; {npc:253527} (level 43, elite) and his bodyguards hold the south side of the camp."] = "골짜기 길을 따라 동쪽 {area:16677}의 멧돼지인에게 가십시오. 두 번째 수정탑은 야영지 동쪽 끝에 있습니다. 이 길에는 시체포식자(45레벨, 정예)가 다니니 지나가게 두십시오. 뻣뻣한갈기 멧돼지인(42-43레벨)은 보는 즉시 공격하며, {npc:253527}(43레벨, 정예)와(과) 호위병들이 야영지 남쪽을 지킵니다.",
		["East of the temple the {quest:93341} have run wild, and their plants attack on sight. Examine the pedestal at the gardens' southern end."] = "사원 동쪽의 {quest:93341}은(는) 황폐해졌고, 식물들이 보이는 즉시 공격합니다. 정원 남쪽 끝의 받침대를 조사하십시오.",
		["Fly to {area:608}"] = "{area:608}(으)로 날아가기",
		["Into the {area:2657}"] = "{area:2657}(으)로",
		["New in Forever: this guide follows what players did in {zone:2652}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\n{zone:2652} lies south of {area:405}, through the {area:2657}, and has no flight path of its own. From {area:1099} ride north-west on the road past {area:2577} and on north into {area:405}: the road comes out on {area:405}'s southern edge."] = "Forever 신규 콘텐츠: 이 가이드는 플레이어들이 {zone:2652}에서 진행한 내용을 따릅니다. 잘못된 단계가 있으면 Polestar의 Discord나 GitHub에 해당 단계를 적어 알려 주십시오.\n{zone:2652}은(는) {area:405} 남쪽, {area:2657} 너머에 있으며 자체 비행 경로가 없습니다. {area:1099}에서 길을 따라 북서쪽으로 {area:2577}을(를) 지나 계속 북쪽 {area:405}(으)로 가십시오. 길은 {area:405}의 남쪽 끝으로 이어집니다.",
		["New in Forever: this guide follows what players did in {zone:2652}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\n{zone:2652} lies south of {area:405}, through the {area:2657}, and has no flight path of its own. Its quests are for levels 41-45. Coming from the Eastern Kingdoms, take the boat from {area:150} to Theramore first."] = "Forever 신규 콘텐츠: 이 가이드는 플레이어들이 {zone:2652}에서 진행한 내용을 따릅니다. 잘못된 단계가 있으면 Polestar의 Discord나 GitHub에 해당 단계를 적어 알려 주십시오.\n{zone:2652}은(는) {area:405} 남쪽, {area:2657} 너머에 있으며 자체 비행 경로가 없습니다. 퀘스트는 41-45레벨용입니다. 동부 왕국에서 온다면 먼저 {area:150}에서 배를 타고 테라모어로 가십시오.",
		["New in Forever: this guide follows what players did in {zone:2652}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\n{zone:2652} lies south of {area:405}, through the {area:2657}, and has no flight path of its own. Its quests are for levels 41-45. Coming from the Eastern Kingdoms, take the zeppelin to {zone:1454} first (from {object:3202} or the {zone:1458})."] = "Forever 신규 콘텐츠: 이 가이드는 플레이어들이 {zone:2652}에서 진행한 내용을 따릅니다. 잘못된 단계가 있으면 Polestar의 Discord나 GitHub에 해당 단계를 적어 알려 주십시오.\n{zone:2652}은(는) {area:405} 남쪽, {area:2657} 너머에 있으며 자체 비행 경로가 없습니다. 퀘스트는 41-45레벨용입니다. 동부 왕국에서 온다면 먼저 {object:3202}이나 {zone:1458}에서 비행선을 타고 {zone:1454}(으)로 가십시오.",
		["North into {area:405}"] = "북쪽 {area:405}(으)로",
		["North-west from the temple to {npc:253471}'s camp on the overlook, beside the spirit healer: the {quest:93644} is his, and he wants to hear about the pylons."] = "신전에서 북서쪽, 영혼의 치유사 옆 전망대에 있는 {npc:253471}의 야영지로 가십시오. {quest:93644}은(는) 그의 것이며, 그는 수정탑 이야기를 듣고 싶어 합니다.",
		["Ride east along {area:405}'s southern edge (from {area:2408}: past {area:606}): the {area:2657} opens there into {area:16651}."] = "{area:405}의 남쪽 끝을 따라 동쪽으로 가십시오({area:2408}에서 출발하면 {area:606}을(를) 지나서). 그곳에서 {area:2657}이(가) {area:16651}(으)로 이어집니다.",
		["Ride south from {area:608} down the road through eastern {area:405} to {area:604}: just past its western edge the path climbs into the {area:2657} and {area:16651}."] = "{area:608}에서 {area:405} 동부를 지나는 길을 따라 남쪽 {area:604}(으)로 가십시오. 그 서쪽 끝을 막 지나면 길이 {area:2657}와(과) {area:16651}(으)로 올라갑니다.",
		["Rowdy Roses and Terrible Tulips grow all over the gardens; the Malevolent Marigolds keep to the northern part. {npc:254674}, the treant in the middle of the gardens, has a request of his own that needs water from {area:2100}, a dungeon: this guide leaves it.\nThe Shen'dralar who wander the gardens are neutral, like the temple's guards: leave them be and pull the flowers away from them. Careful: Nascent Pylon Protectors (elites, 43) wander the zone's middle, the gardens too: keep clear of them."] = "정원 곳곳에 난폭한 장미와 끔찍한 튤립이 자라고, 악의에 찬 금잔화는 북쪽에 모여 있습니다. 정원 한가운데 있는 나무정령 {npc:254674}도 따로 부탁을 하는데, 던전인 {area:2100}의 물이 필요하므로 이 가이드에서는 다루지 않습니다.\n정원을 돌아다니는 셴드랄라는 사원 경비병처럼 중립이니 건드리지 말고 꽃들을 그들에게서 떨어진 곳으로 끌어오십시오. 주의: 갓 깨어난 수정탑 수호자(정예, 43)가 지역 중앙과 정원을 돌아다니니 멀리하십시오.",
		["South to the Shen'dralar temple at the zone's heart, keeping west of Kog'thug's bodyguards: the third pylon stands inside. The temple's guards are neutral: leave them be."] = "코그투그의 호위병 서쪽으로 비켜 지역 중심부의 센드랄라 신전으로 남쪽으로 가십시오. 세 번째 수정탑은 안에 있습니다. 신전 경비병은 중립이니 건드리지 마십시오.",
		["The temple of {zone:2652}: the third pylon"] = "{zone:2652} 신전: 세 번째 수정탑",
		["The temple: the {item:255662}"] = "사원: {item:255662}",
		["The temple: {npc:254656}"] = "사원: {npc:254656}",
		["The western pylon"] = "서쪽 수정탑",
		["The western pylon: repair it"] = "서쪽 수정탑: 수리하기",
		["The {area:2657}: a {quest:93644}"] = "{area:2657}: {quest:93644}",
		["The {quest:93341}"] = "{quest:93341}",
		["The {quest:93341}: the pedestal"] = "{quest:93341}: 받침대",
		["West along {area:405}'s southern edge to {area:606}: the {item:255657} lies at its southern end, watched by Gelkis Guardians (levels 39-41)."] = "{area:405}의 남쪽 가장자리를 따라 서쪽 {area:606}(으)로 가십시오. {item:255657}은(는) 마을 남쪽 끝에 있으며, 겔키스 수호병(39-41레벨)이 지키고 있습니다.",
		["the eastern pylon"] = "동쪽 수정탑",
		["{area:16677}: repair the eastern pylon"] = "{area:16677}: 동쪽 수정탑 수리하기",
		["{area:16677}: the eastern pylon"] = "{area:16677}: 동쪽 수정탑",
		["{area:2408} flight master"] = "{area:2408} 비행 조련사",
		["{area:405}, where the road from {zone:1444} comes in"] = "{zone:1444}에서 오는 길이 들어오는 {area:405}",
		["{npc:252711}, then {spell:1289727} on it"] = "{npc:252711} 처치 후 {spell:1289727} 사용",
		["{npc:253471} sends you for the {item:255662}, kept inside the temple beside {npc:255486}. {quest:96018} asks you to gather mana with the Sieve before you repair the pylons: with it in your bags you can handle the Unstable Mana Rifts, the floating sparks of mana all along the road north."] = "{npc:253471}은(는) {npc:255486} 옆, 사원 안에 보관된 {item:255662}을(를) 가져오라고 합니다. {quest:96018}에서는 수정탑을 수리하기 전에 여과기로 마나를 모아야 합니다. 여과기를 가방에 넣고 있으면 북쪽 길을 따라 떠다니는 마나 불꽃인 불안정한 마나 균열을 다룰 수 있습니다.",
		["{npc:253471} wants a fragment and a shard of the pylons back from {area:405}'s two centaur villages: {area:604} lies just beyond the valley's northern way out.\nCareful: if you have killed Magram or Gelkis centaurs, that clan's guards may attack you when you walk into its village."] = "{npc:253471}은(는) {area:405}의 두 켄타우로스 마을에서 수정탑 파편과 조각을 되찾아 오길 원합니다. {area:604}은(는) 골짜기 북쪽 출구 바로 너머에 있습니다.\n주의: 마그람이나 겔키스 켄타우로스를 죽였다면, 그 부족 마을에 들어갈 때 경비병이 공격할 수 있습니다.",
		["{npc:253471}: hear him out"] = "{npc:253471}: 이야기 듣기",
		["{npc:254656} waits inside the temple. Then {npc:254578}, on the temple's eastern side, has work in the {quest:93341}."] = "{npc:254656}은(는) 사원 안에서 기다립니다. 그다음 사원 동쪽의 {npc:254578}이(가) {quest:93341}에서 할 일을 줍니다.",
		["{npc:255486}, inside the temple, has a task for you now that you have met {npc:254656}: the heart of a {npc:252711} (42-43, not elite), a short ride back up the road north."] = "{npc:254656}을(를) 만났으니 사원 안의 {npc:255486}이(가) 할 일을 줍니다. 길을 따라 북쪽으로 조금 돌아가면 있는 {npc:252711}(42-43, 비정예)의 심장입니다.",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
		["{zone:2652} is done. Your {zone:1444} guide picks up from here: ride back north through the {area:2657}, west along {area:405}'s southern edge and south into {zone:1444}, to the dock on the {area:1108} where the boat crosses to {area:1116}."] = "{zone:2652} 완료. 여기서부터 {zone:1444} 가이드가 이어집니다. {area:2657}을(를) 지나 다시 북쪽으로, {area:405}의 남쪽 가장자리를 따라 서쪽으로 간 뒤 남쪽 {zone:1444}(으)로 들어가, {area:1116}(으)로 가는 배가 출발하는 {area:1108}의 부두로 가십시오.",
} end)()
t.guides["forever/alliance/02-westfall"] = (function() return {
		["Class trainer"] = "직업 상급자",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "데피아즈단 견습마술사가 {area:86} 기슭에 야영하며, 붉은 리넨 복면도 떨어뜨립니다. {object:56}은(는) 북동쪽 기슭의 멀록 마을에 있습니다.",
		["Fill the vial at the farm's well"] = "농장 우물에서 약병 채우기",
		["Fill the vial at the well"] = "우물에서 약병 채우기",
		["Follow the hills south to the tower."] = "언덕을 따라 남쪽 탑으로 가십시오.",
		["For your {area:16919} run: the {area:2257} from the {object:28027} to {zone:1455}."] = "{area:16919} 공략용: {object:28027}에서 {zone:1455}행 {area:2257}.",
		["For your {area:16919} run: {npc:265003} and {npc:264943} stand a few steps apart on the city's west side, west of the {object:171709}. The hall's door is a short walk further west."] = "{area:16919} 공략용: {npc:265003}와(과) {npc:264943}은(는) 도시 서쪽, {object:171709} 서쪽에서 서로 몇 걸음 떨어져 서 있습니다. 전당 입구는 서쪽으로 조금 더 걸어가면 있습니다.",
		["For {npc:266} in {area:69}, Redridge"] = "붉은마루 산맥 {area:69}의 {npc:266}에게",
		["Gnoll Paws"] = "놀의 앞발",
		["Harvest Watchers"] = "허수아비골렘 보초",
		["Harvest Watchers north of {area:107}"] = "{area:107} 북쪽의 허수아비골렘 보초",
		["Head to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "{zone:1453}으로 가세요. 샤먼 훈련사가 없습니다: {object:28027}에서 {area:2257}을 타고 {zone:1455}로 가서 {npc:258098}에게 훈련받고, 배를 위해 트램을 타고 돌아오세요.",
		["It lies by the river north-west of the logging camp."] = "벌목장 북서쪽 강가에 있습니다.",
		["Kobold Diggers"] = "코볼트 채굴꾼",
		["Level 12, 14 and 16 spells"] = "12, 14, 16레벨 주문",
		["Longshore Murloc Gills"] = "기나긴 해안 멀록 아가미",
		["Murloc Coastrunners and Raiders line the north coast from above the mine east toward the {area:916}: work along the beach eastward. They flee at low health: pull one at a time."] = "멀록 길잡이와 멀록 약탈꾼이 광산 위쪽에서 동쪽 {area:916}까지 북쪽 해안에 늘어서 있습니다. 해변을 따라 동쪽으로 나아가십시오. 생명력이 낮으면 도망치니 하나씩 끌어오십시오.",
		["North along the road from {area:87} to {zone:1453}: {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}. Use the {item:6928} at the summoning circle there and defeat the voidwalker it calls, then back south through {area:87} to {zone:1436}."] = "{area:87}에서 길을 따라 북쪽 {zone:1453}(으)로 가십시오. {npc:6122}은(는) {object:2101}에 있는 {object:2164}의 지하실에서 기다립니다. 그곳 소환진에서 {item:6928}을(를) 사용해 불러낸 공허방랑자를 물리친 뒤, {area:87}을(를) 지나 남쪽 {zone:1436}(으)로 돌아가십시오.",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "엘윈 숲에서 {item:1972}을(를) 획득한 경우에만: 오른쪽 클릭하십시오",
		["Red Linen Bandanas"] = "붉은 리넨 복면",
		["Ride the tram back from {object:171524} to {zone:1453}'s {object:28027}."] = "지하철을 타고 {object:171524}에서 {zone:1453}의 {object:28027}(으)로 돌아가십시오.",
		["Riverpaw Miners"] = "갈퀴발일족 광부",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "갈퀴발일족 놀이 {area:86} 서쪽 언덕에 야영하며, {quest:91725}은(는) 그들의 야영지에 있습니다.",
		["Shaman training"] = "주술사 수련",
		["South along the road, past the fork. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west. Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way."] = "도로를 따라 남쪽, 갈림길을 지나서. {npc:233}은 밖에, {npc:235}는 집 안에, {npc:253395}는 서쪽 헛간에 있습니다. 어린 멧돼지와 살찢이가 농장 주변 들판을 돌아다닙니다: 가는 길에 간과 스튜 고기를 먼저 모으세요.",
		["The bridge"] = "다리",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "야영지는 다리 북동쪽에 있습니다. 장작 더미는 야영지 주변과 북쪽 숲에 있습니다.",
		["The gnoll camps"] = "놀 야영지",
		["The gnoll hills"] = "놀 언덕",
		["The {area:113}"] = "{area:113}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the {object:28027} (Hunters), the Park (Druids)."] = "상급자: {object:2100}(전사, 도적), 대성당(성기사, 사제), {object:2101}(마법사, 흑마법사), {object:28027}(사냥꾼), 공원(드루이드).",
		["Tram to {zone:1453}"] = "지하철을 타고 {zone:1453}(으)로",
		["While you're in the city: Warriors and Rogues train in {object:2100}, Paladins and Priests in the Cathedral of Light across {object:2098}, Mages and Warlocks in the {object:2101}, Hunters in the {object:28027}."] = "도시에 있는 동안: 전사와 도적은 {object:2100}, 성기사와 사제는 {object:2098} 건너편 빛의 대성당, 마법사와 흑마법사는 {object:2101}, 사냥꾼은 {object:28027}에서 훈련합니다.",
		["{area:16919} is a dungeon for a group of five at about level 15 to 16, under {zone:1455}. Its door is on the west side of the city, a short walk west of {npc:264943}.\nInside: the Enraged Apparitions and Tormented Souls are {npc:264943}'s, the Dwarven Heirlooms Thom's, and {npc:261319}, the {object:147516} commander deep in the vaults, carries the head King Magni wants. A {npc:265002} inside gives An Ancient Grudge, for {npc:261306}, and takes it back there; a {item:281030} found inside starts a quest for King Magni."] = "{area:16919}은(는) {zone:1455} 아래에 있는 약 15~16레벨 5인 파티용 던전입니다. 입구는 도시 서쪽, {npc:264943}에서 서쪽으로 조금 걸어가면 있습니다.\n내부: Enraged Apparition과 Tormented Soul은 {npc:264943}의 퀘스트, Dwarven Heirloom은 톰의 퀘스트용이며, 금고 깊숙한 곳의 {object:147516} 지휘관 {npc:261319}이(가) 국왕 마그니가 원하는 머리를 지니고 있습니다. 내부의 {npc:265002}이(가) {npc:261306}에게 가는 'An Ancient Grudge'를 주며, 그곳에서 다시 받아 갑니다. 내부에서 찾은 {item:281030}은(는) 국왕 마그니에게 가는 퀘스트를 시작합니다.",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{zone:1439}의 약재 모으기(6123)에 필요한 {item:2449}: {npc:1313}, 연금술 용품. 약초채집가는 대신 그곳에서 채집하세요",
		["{item:2589}: you have it from {zone:1436}'s Defias; if not, the Auction House here in the {object:2096} (not the level 25 thugs in {object:2100})"] = "{item:2589}: {zone:1436}의 데피아즈에게서 얻었을 것입니다. 없다면 이곳 {object:2096}의 경매장을 이용하십시오({object:2100}의 25레벨 불량배는 피하십시오)",
		["{item:6529}, from {npc:5494}"] = "{item:6529}, {npc:5494}에게서",
		["{item:729}: Fleshrippers"] = "{item:729}: 식인독수리",
		["{item:814}: keep five for {npc:392} at the {area:115}, later on the route"] = "{item:814}: 경로 후반에 {area:115}의 {npc:392}에게 줄 5개를 남겨 두세요",
		["{npc:1416}: his package for {npc:1343} in {zone:1432}, later on the route"] = "{npc:1416}: {zone:1432}의 {npc:1343}에게 전할 소포 (경로상 나중에)",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234}와(과) {npc:821}은(는) 돌탑 꼭대기에 있습니다. {npc:491}은(는) 탑 안에, {npc:878}은(는) 언덕 남쪽의 여관과 그리폰 조련사 {npc:523} 옆에 있습니다.",
		["{npc:237}: Humans may have it already from {npc:963} in Elwynn"] = "{npc:237}: 인간이라면 엘윈의 {npc:963}에게서 이미 받았을 수 있습니다",
		["{npc:253092}, beside {npc:878}"] = "{npc:253092}, {npc:878} 옆",
		["{npc:265003} and {npc:264943}"] = "{npc:265003}와(과) {npc:264943}",
		["{npc:376} is in the Cathedral of Light."] = "{npc:376}은(는) 빛의 대성당에 있습니다.",
		["{npc:523}, on the south side of the hill"] = "{npc:523}, 언덕 남쪽",
		["{npc:523}: the free flight he offers goes to {zone:1453}"] = "{npc:523}: 그가 제공하는 무료 비행은 {zone:1453}(으)로 갑니다",
		["{npc:5480} trains warriors in {object:2100}, near {npc:1323}'s shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480}은(는) {npc:1323}의 상점 근처 {object:2100}에서 전사를 훈련시킵니다. {zone:1455}에서 오는 지하철은 그 북쪽의 {object:28027}에 도착합니다. {npc:6089}와(과) {npc:6090}은(는) 그곳 {object:2152} 옆에 함께 서 있습니다. {npc:6090}은(는) 자기 잔을 걸고 당신과 싸웁니다. {npc:5480}이(가) {quest:1638}을(를) 주지 않으면 곧장 {npc:6089}에게 가세요. 그 퀘스트 없이도 {quest:1639}을(를) 줍니다.",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494}은(는) {object:2096} 바로 서쪽 운하를 따라 낚시 용품을 판매합니다. {npc:267118}은(는) 배로 가는 길의 항구에서 낚시를 합니다.",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}, 마법사의 성소: {quest:1861}",
		["{npc:5676}: use the {item:6928} at the circle"] = "{npc:5676}: 소환진에서 {item:6928} 사용",
		["{npc:6122}'s {quest:1689} needs {item:6810}: {npc:881} (level 9) stands by the farmhouse of the {area:62}, just south of the river."] = "{npc:6122}의 {quest:1689}에는 {item:6810}이(가) 필요합니다. {npc:881}(9레벨)은(는) 강 바로 남쪽, {area:62}의 농가 옆에 서 있습니다.",
		["{quest:96393}: King Magni sits on the {object:171709}, east of the hall's door."] = "{quest:96393}: 국왕 마그니는 전당 입구 동쪽의 {object:171709}에 앉아 있습니다.",
		["{quest:96393}: {npc:261319}, inside"] = "{quest:96393}: {npc:261319}, 내부",
		["{quest:96394}, inside"] = "{quest:96394}, 내부",
		["{quest:96403}: the heirlooms, inside"] = "{quest:96403}: 가보, 내부",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["After using the {item:12347}, kill Xabraxxis, then click his Demon Bag on the ground to collect the talisman. If Xabraxxis despawns before you get it, retake the quest for a new bowl."] = "{item:12347}을(를) 사용한 뒤 자브락시스를 처치하고, 땅에 떨어진 악마 가방을 클릭해 부적을 획득하십시오. 부적을 얻기 전에 자브락시스가 사라지면 퀘스트를 다시 받아 새 그릇을 받으십시오.",
		["At the {area:2362}"] = "{area:2362}에서",
		["Back north-east into the mountains to the crystal."] = "북동쪽 산으로 돌아가 수정에게 가십시오.",
		["Bears and the Blackwood camp"] = "곰과 검은나무일족 야영지",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "검은나무일족 길잡이와 검은나무일족 풍수사가 {area:442} 남동쪽 야영지를 지키고 있습니다.",
		["Blackwood furbolgs"] = "검은나무일족 펄볼그",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "{area:447} 동쪽의 산을 오르십시오. {object:175524}은(는) 바위 턱 위에 있습니다.",
		["Crawler Legs"] = "집게다리",
		["East of Buzzbox 323, {npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}.\nCareful: Dark Strand Voidcallers (28-29) with their voidwalkers and {npc:3660} (31) stand in the tower itself: take the parchments from the Fanatics south of it and keep away from the tower."] = "버즈박스 323 동쪽, {npc:3661}은(는) 탑 아래에서 암흑이교도 광신자들 사이에 숨어 있습니다. 그의 편지는 {zone:1440}의 수호자 델그렌에게 가져가야 하니 보관하세요.\n주의: 암흑이교도 소환사(28-29)는 공허방랑자를 데리고 {npc:3660}(31)와(과) 함께 탑 안에 있습니다. 탑 남쪽의 광신자들에게서 양피지를 얻고 탑에는 가까이 가지 마세요.",
		["Fill the tube at the moonwell in the village"] = "마을의 달샘에서 시험관을 채우십시오",
		["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "언덕을 따라 북쪽의 {area:456}까지 간 다음 폭포로 올라가십시오. 북쪽 해안에 떠밀려 온 사체가 두 개 더 있습니다: {area:443} 근처, {quest:954} 북쪽.",
		["Grell Earrings"] = "그렐족 귀걸이",
		["Highborne Relics"] = "명가의 유물",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "{area:442} 동쪽 언덕에서 광포한 엉겅퀴곰을 처치한 다음, 그 남동쪽의 펄볼그 야영지로 걸어가십시오. 아직 처치할 것은 없습니다.",
		["Moonstalker Fangs"] = "달표범 송곳니",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "달표범이 {quest:954}와(과) 탑 사이의 언덕을 배회합니다. {quest:1002}은(는) 탑 서쪽 언덕에 서 있습니다.",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path. Then take the portal up to {npc:4217} in the {area:1658}."] = "나이트 엘프는 {area:442}에서 {area:702}(으)로 날아가십시오. 스카이본은 {area:442} 부두에서 배를 타고 가서 루테란 비행 경로를 익히십시오. 그다음 차원문을 타고 {area:1658}의 {npc:4217}에게 올라가십시오.",
		["Plagued bears"] = "병든 곰",
		["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "광포한 엉겅퀴곰이 {area:442} 바로 동쪽 언덕을 돌아다닙니다. 한 마리에게 {quest:2139}을(를) 사용하고 그에게 데려가십시오.",
		["Read the {object:17188}"] = "{object:17188}을(를) 읽으십시오",
		["Read the {object:17189}"] = "{object:17189}을(를) 읽으십시오",
		["The WANTED poster outside the inn"] = "여관 밖의 현상수배 포스터",
		["The bay wrecks"] = "만의 난파선",
		["The beach"] = "해변",
		["The cave and the {npc:6788}"] = "동굴과 {npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls."] = "동굴은 폭포 남쪽에 있습니다. {item:5271}은(는) 동굴 곳곳에 자라고, {item:5270}은(는) 맨 안쪽에 있습니다. {npc:6788}은(는) 폭포 남쪽 언덕에 둥지를 틀고 있습니다.",
		["The flame burns in the south of {area:447}."] = "불꽃은 {area:447} 남쪽에서 타오르고 있습니다.",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "반쪽 펜던트는 {zone:1439}와(과) {zone:1436}에 있습니다: 경로 후반에",
		["The red crystal"] = "붉은 수정",
		["The skeletal turtle"] = "거북 해골",
		["The {object:16393}"] = "{object:16393}",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "왕바닷게는 마을 아래 해안을 따라 기어다니고, {quest:983}은(는) 부두 바로 남쪽 해변에 서 있습니다. 어둠의해안 트레샤돈은 얕은 물에서 헤엄칩니다. {object:175207}은(는) 마을 바로 남쪽 해안에 놓여 있습니다.",
		["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore.\nCareful: The murlocs inside the wrecks are close together and fast. They often swim through the hull walls and holes, so you will usually pull extra murlocs."] = "{area:442} 북쪽 만의 바다 밑에 난파선 두 척이 있고, 각각 금고가 하나씩 있습니다. 이 해안에는 모래톱게와 등껍질 왕바닷게가 늘어서 있습니다.\n주의: 난파선 안의 멀록은 서로 가까이 있고 빠릅니다. 선체 벽과 구멍을 자주 헤엄쳐 통과하므로 대개 멀록을 더 끌어오게 됩니다.",
		["{item:12238}: fish from the pier"] = "{item:12238}: 부두에서 낚시",
		["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289}, 부두 서쪽 해변, 물속",
		["{item:12349}, at the waterfall"] = "{item:12349}, 폭포에서",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}: 폭포 옆 동굴 입구에서",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, 호수 안의 {object:177785}에서",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: 데스릴 사티로스",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}: 암흑이교도 광신자",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. {quest:29} runs on a timer: no teleport or Hearthstone until {npc:11799} has it. Then fly back to {area:442} from {area:2361}."] = "{npc:11802}은(는) {area:2361}에 있는 자기 건물 위층에 서 있습니다. 건물 안에서 올라가세요. 화살표는 층을 구분하지 못합니다. 성소 장신구는 {area:2361} 아래 {area:656} 바닥의 용기 속에 있습니다. 하나를 북서쪽의 {area:2362}(으)로 가져가 그곳에서 사용하고 {npc:11799}와(과) 대화하세요. {quest:29}에는 시간 제한이 있습니다. {npc:11799}이(가) 받을 때까지 순간이동이나 귀환석을 쓰지 마세요. 그런 다음 {area:2361}에서 {area:442}(으)로 날아 돌아오세요.",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639}은(는) 폐허 북쪽 끝에 서 있습니다. 저주받은 명가의 원혼, 고뇌하는 명가의 원혼, {npc:2178}이(가) 폐허를 떠돕니다. {npc:3667}의 유령이 그 사이를 거닐고, 올빼미 {npc:270196}이(가) 폐허 동쪽을 맴돕니다. 두 석판은 폐허 안에 있고, {quest:4722}은(는) 폐허 서쪽 해안에 있습니다.",
		["{npc:3644}, on the pier"] = "{npc:3644}, 부두 위",
		["{npc:3649}, north end of the village"] = "{npc:3649}, 마을 북쪽 끝",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}: {zone:1453}의 {npc:1646}에게",
		["{npc:3666}, upstairs in the inn"] = "{npc:3666}, 여관 위층",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}: {area:445}에서 채집기를 채우십시오",
} end)()
t.guides["forever/alliance/03-darkshore-return"] = (function() return {
		["Back south"] = "다시 남쪽으로",
		["Back to {npc:11802}"] = "{npc:11802}에게 돌아가기",
		["Both half pendants in your bags (the {zone:1436} half from your last {zone:1436} visit, the {zone:1439} half from the north coast): stand by the {area:2362} on the north-west shore of the lake and use a half to join them, then take the pendant to {npc:11802} with the {spell:499} hand-in. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "반쪽 펜던트 두 개를 모두 가방에 가지고({zone:1436} 반쪽은 지난번 {zone:1436} 방문 때, {zone:1439} 반쪽은 북쪽 해안에서 얻음) 호수 북서쪽 기슭의 {area:2362} 옆에 서서 반쪽 하나를 사용해 합치십시오. 그런 다음 {spell:499} 제출 때 함께 펜던트를 {npc:11802}에게 가져가십시오. {npc:11802}은(는) 건물 위층에 서 있습니다. 건물 안에서 올라가십시오. 화살표는 층을 구분하지 못합니다.",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. No {area:493} flight path yet? Learn it from {npc:10897}, south of the lake: the flight master in {area:2361} flies only Druids, from her gossip, and has none to learn."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있는 자기 건물 위층에 서 있습니다. 건물 안에서 올라가세요. 화살표는 층을 구분하지 못합니다. 아직 {area:493} 비행 경로가 없나요? 호수 남쪽의 {npc:10897}에게서 배우세요. {area:2361}의 비행 조련사는 대화를 통해 드루이드만 태워주며, 배울 비행 경로가 없습니다.",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "그녀를 글레이브 밖으로 호위하십시오. 제출은 {zone:1440}의 테리실에게 합니다",
		["Fine Moonstalker Pelts"] = "고급 달표범 모피",
		["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore. Careful: {npc:270294}, an elite naga (21), walks the ruins among them: pull the naga away from him, or fight him at full health."] = "해안을 따라 북동쪽의 {area:443}(으)로 가십시오. {quest:951}은(는) 폐허 곳곳에 있고, 폭풍비늘일족 미르미돈, 폭풍비늘일족 여마법사, 폭풍비늘일족 전사가 지키고 있으며, 폭풍비늘 야수조련사가 해안을 거닙니다. 주의: 정예 나가인 {npc:270294}(21)이(가) 그들 사이로 폐허를 돌아다닙니다. 나가를 그에게서 떼어 끌어오거나, 생명력이 가득 찬 상태로 그와 싸우십시오.",
		["Follow the road north."] = "길을 따라 북쪽으로 가십시오.",
		["For your {area:2797} run, on the {area:414} in the next guide: {npc:8997} stands a short walk west of {npc:3693}."] = "{area:2797} 공략용(다음 가이드의 {area:414}): {npc:8997}은(는) {npc:3693}에서 서쪽으로 조금 걸어가면 서 있습니다.",
		["From the dock (or the inn, if you used your Hearthstone), up to the north end of the village first ({npc:3649}, {npc:3702} by the moonwell, {npc:2913}), then down the main street: the WANTED poster outside the inn, {npc:3693} at its east end, where the road leaves south. {npc:3694} ({quest:990}) is beside {npc:3693} only for a few minutes at a time: she comes shortly after someone hands in {npc:3692}'s escort and leaves again about 5 minutes later. If she isn't there, don't wait: the guide offers her quest again when you hand in {npc:3692}'s escort to {npc:3693} yourself. Changing layer can also find her."] = "부두(귀환석을 썼다면 여관)에서 먼저 마을 북쪽 끝으로 가서({npc:3649}, 달샘 옆의 {npc:3702}, {npc:2913}), 큰길을 따라 내려오십시오. 여관 밖의 현상수배 게시판, 그리고 길이 남쪽으로 빠지는 동쪽 끝의 {npc:3693}. {npc:3694}({quest:990})은(는) 잠깐씩만 {npc:3693} 옆에 있습니다. 누군가 {npc:3692}의 호위 퀘스트를 제출하면 곧 나타났다가 약 5분 뒤 떠납니다. 없다면 기다리지 마십시오. 직접 {npc:3692}의 호위 퀘스트를 {npc:3693}에게 제출할 때 가이드가 그녀의 퀘스트를 다시 안내합니다. 레이어를 바꿔도 그녀를 찾을 수 있습니다.",
		["Grizzled Scalps"] = "불곰 가죽",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "엉겅퀴불곰이 숲 주변 언덕을 돌아다닙니다. {quest:1003}은(는) 그 서쪽, 곰들 사이에 서 있습니다.",
		["Moonstalker Sires prowl the woods around the glaive. The {object:12666} sits at the bottom of the crater; {npc:3584} stands on its north side. For {quest:948}'s quest, use the {item:5251} at the bottom of the crater: it makes the {object:10076}, and you hand the quest in to the bowl."] = "덩치큰 달표범이 글레이브 주변 숲을 배회합니다. {object:12666}은(는) 구덩이 바닥에 있고, {npc:3584}은(는) 구덩이 북쪽에 서 있습니다. {quest:948}의 퀘스트는 구덩이 바닥에서 {item:5251}을(를) 사용하십시오: {object:10076}이(가) 나타나며, 퀘스트는 그 그릇에 제출합니다.",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "나이트 엘프는 {area:442}에서 {area:702}(으)로 날아가십시오. 스카이본은 {area:442} 부두에서 배를 타고 가서 그곳의 루테란 비행 경로를 익히십시오. 차원문을 타고 {area:1658}의 {npc:4217}에게 올라가십시오.",
		["No {quest:990} yet? Give it a minute after the hand-in: {npc:3694} comes to {npc:3693}'s side shortly after {npc:3692}'s escort is handed in. Changing layer can also find her."] = "아직 {quest:990}이(가) 없나요? 제출 후 잠시 기다리십시오. {npc:3692}의 호위 퀘스트가 제출되면 곧 {npc:3694}이(가) {npc:3693} 옆으로 옵니다. 레이어를 바꿔도 그녀를 찾을 수 있습니다.",
		["On the way south to the Grove: the Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}, a short way off the road; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "남쪽의 숲으로 가는 길에: 달버섯은 {area:442} 바로 동쪽 언덕, 길에서 조금 떨어진 달빛야수 동굴에서 자랍니다. 그곳의 달빛야수는 성미가 사납습니다. {item:2449}에는 {skill:182}이(가) 필요합니다: 약초 채집가는 {zone:1439} 곳곳에서 캘 수 있고, 그 외에는 {zone:1453}({npc:1313})이나 경매장에서 구해 오십시오.",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "신도나 암살단원이 {item:5352}을(를) 떨어뜨렸을 때만: 오른쪽 클릭하십시오",
		["She gives you the {item:15826}"] = "그녀가 {item:15826}을(를) 줍니다",
		["The WANTED poster"] = "현상수배 포스터",
		["The naga"] = "나가",
		["The relics of the Barrow Dens"] = "지하굴의 성물",
		["The {area:443}"] = "{area:443}",
		["The {object:10076}"] = "{object:10076}",
		["The {object:12666}"] = "{object:12666}",
		["Underwater"] = "물속",
		["{item:15851} and {item:2449}"] = "{item:15851}와(과) {item:2449}",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}: 폐허 서쪽, 북쪽 해안 앞바다 물속의 {object:177792}",
		["{item:15885}: join the halves at the {area:2362}"] = "{item:15885}: {area:2362}에서 반쪽 합치기",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}: 황혼의망치단 신도와 황혼의망치단 암살단원",
		["{npc:10323}'s beach"] = "{npc:10323}의 해변",
		["{npc:11802}: the welcome from {npc:5504}"] = "{npc:11802}: {npc:5504}의 환영 인사",
		["{npc:11802}: {quest:5061}, for {npc:4217}"] = "{npc:11802}: {quest:5061}, {npc:4217}에게",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}: {item:15826}을(를) 사용하십시오. {zone:1439} 전역을 돌아다닙니다",
		["{npc:3616}, at the Grove"] = "{npc:3616}, 고대정령의 숲에서",
		["{npc:3694}, beside {npc:3693} if she is there: for {npc:3691} in {area:415}, in the next guide"] = "{npc:3694}, 있다면 {npc:3693} 옆: 다음 가이드에서 {area:415}의 {npc:3691}에게",
		["{npc:3694}, once she comes: {quest:990}, for {npc:3691} in {area:415} on your next {zone:1440} visit"] = "{npc:3694}, 나타나면: {quest:990}, 다음 {zone:1440} 방문 때 {area:415}의 {npc:3691}에게",
		["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667}은(는) 폐허 앞바다의 작은 섬에 숨어 있습니다. 열쇠 조각은 거대한 숲타조(윗부분), 잿빛안개멀록(가운데), 사나운 모래톱게(아랫부분)에게서 떨어집니다.",
		["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}: 떠밀려 온 사체 아홉 개를 모두 반납하면 {npc:10219}이(가) 줍니다",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394}(나이트 엘프)와(과) {npc:272054}(스카이본)이(가) {area:493} 남쪽에서 기다립니다. 세 유물은 그 동쪽의 {area:2363}에 있습니다. 첫 몇 주의 제보에 따르면 다른 플레이어가 유물을 획득하는 중에는 아무것도 나오지 않습니다: 잠시 기다렸다가 다시 시도하십시오.",
} end)()
t.guides["forever/alliance/03-loch-modan"] = (function() return {
		["Back down to the east shore below the boars' hills: {npc:270693}, a crocolisk, patrols it among the Loch Crocolisks."] = "멧돼지 언덕 아래 동쪽 기슭으로 다시 내려가십시오. 악어인 {npc:270693}이(가) 호수 악어 사이를 순찰합니다.",
		["Back north to {npc:234}. For your {area:1581} run he then sends you after {npc:639}, and {npc:820}, beside him at the top of the tower, wants {quest:214}. Look for a group now if you have none yet."] = "북쪽 {npc:234}에게 돌아가십시오. {area:1581} 공략을 위해 그가 {npc:639}을(를) 쫓으라고 보내며, 탑 꼭대기 그의 옆에 있는 {npc:820}은(는) {quest:214}을(를) 원합니다. 아직 파티가 없다면 지금 구하십시오.",
		["Back toward town, swim east from the bridge into {area:68}; the chest lies on the lake bed beside a sunken boat. Murloc Flesheaters and Tidecallers line the south shore around it: any of them can carry a {item:1467}.\nCareful: Lake Threshers, level 25 elites, swim in the lake: keep your distance from them while you dive for the chest."] = "마을 쪽으로 돌아가며 다리에서 동쪽 {area:68}(으)로 헤엄쳐 가십시오. 상자는 가라앉은 배 옆 호수 바닥에 있습니다. 주변 남쪽 호숫가에 멀록 청소부와 멀록 파도술사가 늘어서 있으며, 누구든 {item:1467}을(를) 지니고 있을 수 있습니다.\n주의: 25레벨 정예 호수 트레샤돈이 호수에서 헤엄치니 상자를 찾아 잠수하는 동안 거리를 두십시오.",
		["Boat to {area:150}"] = "배를 타고 {area:150}(으)로",
		["Cathedral of Light"] = "빛의 대성당",
		["Class trainer"] = "직업 상급자",
		["Druids on Trial of the Sea Lion: from the {area:113}, west to the shore and north along it. The {object:177790} lies on the sea floor off the coast (about 18,33); then back south along the coast to the lighthouse."] = "바다사자의 시험 중인 드루이드: {area:113}에서 서쪽 해안으로 가서 해안을 따라 북쪽으로 가십시오. {object:177790}은(는) 앞바다 해저(약 18,33)에 있습니다. 그런 다음 해안을 따라 남쪽 등대로 돌아가십시오.",
		["Elder Mountain Boars"] = "늙은 산멧돼지",
		["Fly to {area:1537}"] = "{area:1537}(으)로 비행",
		["Fly to {area:69}"] = "{area:69}(으)로 비행",
		["Fly to {zone:1453}"] = "{zone:1453}로 비행",
		["For your {area:717} run, later in {zone:1453}: keep it until then."] = "{area:717} 공략용(나중에 {zone:1453}에서): 그때까지 보관하십시오.",
		["Out of the mine and north up the road to {area:108}: {npc:234} stands at the top of the tower."] = "광산에서 나와 길을 따라 북쪽 {area:108}(으)로 가십시오. {npc:234}은(는) 탑 꼭대기에 서 있습니다.",
		["Through the South Gate tunnel and west along the road to {zone:1455}. Know the {zone:1455} flight path already? Fly from {area:144} instead: these two waypoints drop once you are in the city."] = "남쪽 관문 터널을 지나 길을 따라 서쪽으로 {zone:1455}까지 가세요. {zone:1455} 비행 경로를 이미 알고 있나요? 대신 {area:144}에서 비행하세요: 도시에 들어서면 이 두 경유지는 사라집니다.",
		["Train on the way to the harbour: {object:2100} (Warriors, Rogues), the Cathedral of Light (Paladins, Priests), the {object:2101} (Mages, Warlocks), the {object:28027} (Hunters)."] = "항구로 가는 길에 훈련하십시오: {object:2100}(전사, 도적), 빛의 대성당(성기사, 사제), {object:2101}(마법사, 흑마법사), {object:28027}(사냥꾼).",
		["Tram to {zone:1453}"] = "지하철을 타고 {zone:1453}(으)로",
		["Use the {item:6866} on {npc:6172}"] = "{npc:6172}에게 {item:6866} 사용",
		["You have the {area:1537} flight path: back north to {area:144}'s gryphons, quicker than walking through the tunnel and across {zone:1426}."] = "{area:1537} 비행 경로를 이미 알고 있습니다: 북쪽의 {area:144} 그리폰으로 돌아가세요. 터널을 지나 {zone:1426}을(를) 가로질러 걷는 것보다 빠릅니다.",
		["{area:144} flight master"] = "{area:144} 비행 조련사",
		["{area:1581} is a dungeon for a group of five, about levels 17 to 24, and a full run takes about an hour. Its door is the mine below {area:20}, where the traitor led you: the portal is at the far end of the mine's tunnels.\nInside: the Defias drop the {quest:214}, and {npc:639} waits on the ship at the end. Open the Unsent Letter he drops: its quest goes to {zone:1453}, where this guide hands it in."] = "{area:1581}은(는) 약 17~24레벨 5인 파티용 던전이며, 전체 공략에 약 1시간이 걸립니다. 입구는 배신자가 당신을 데려갔던 {area:20} 아래 광산입니다. 차원문은 광산 터널 맨 끝에 있습니다.\n내부: 데피아즈단이 {quest:214}을(를) 떨어뜨리고, {npc:639}은(는) 끝의 배에서 기다립니다. 그가 떨어뜨리는 부치지 않은 편지를 여십시오. 그 퀘스트는 {zone:1453}(으)로 이어지며, 이 가이드가 그곳에서 제출합니다.",
		["{area:20} and the Defias hills"] = "{area:20}와(과) 데피아즈단 언덕",
		["{item:15882}: the {object:177790}"] = "{item:15882}: {object:177790}",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}, {area:20} 주변 상자에서",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}: 붉은마루일족 약탈자",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}: 데피아즈단 견습마술사",
		["{item:915}: the Defias"] = "{item:915}: 데피아즈단",
		["{npc:1092} is inside the bunker at the tunnel post: go in by its door on the south-east side."] = "{npc:1092}은(는) 터널 초소의 벙커 안에 있습니다. 남동쪽 문으로 들어가십시오.",
		["{npc:1092}, inside"] = "{npc:1092}, 내부",
		["{npc:1343}: {npc:1416}'s package"] = "{npc:1343}: {npc:1416}의 소포",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, {object:32372} 안",
		["{npc:1646}, the city architect, is on your way west to the harbour. His next errand, {quest:389}, leads into the {area:717}: it is for a {area:717} run at about 29, so leave it unless you chose that dungeon."] = "도시 건축가 {npc:1646}은(는) 서쪽 항구로 가는 길에 있습니다. 그의 다음 심부름인 {quest:389}은(는) {area:717}(으)로 이어집니다. 약 29레벨의 {area:717} 공략용이므로, 그 던전을 고르지 않았다면 받지 마십시오.",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}: {area:442}에서 온 툰드리스의 편지",
		["{npc:1646}: for {npc:1719}, at the {area:717}'s gate"] = "{npc:1646}: {area:717} 입구의 {npc:1719}에게",
		["{npc:344}, in the town hall"] = "{npc:344}, 마을 회관 안",
		["{npc:6171}: Redemption"] = "{npc:6171}: 구원",
		["{npc:820} keeps watch at the top of the {area:108} tower."] = "{npc:820}은(는) {area:108} 탑 꼭대기에서 망을 보고 있습니다.",
		["{npc:820}, at the top of the tower"] = "{npc:820}, 탑 꼭대기",
} end)()
t.guides["forever/alliance/04-redridge-mountains"] = (function() return {
		["Back to {area:69}"] = "{area:69}(으)로 돌아가기",
		["Cross the long bridge north into town: {npc:381} on the docks, {npc:900} in the town hall, {npc:342} in her garden at the west end. {npc:382} and {npc:341} stand at the north end of the bridge: the Blackrock camps' quests and {quest:98386} are worked on this visit's loop east of the lake."] = "긴 다리를 건너 북쪽 마을로 들어가세요. {npc:381}은(는) 부두에, {npc:900}은(는) 마을 회관에, {npc:342}은(는) 서쪽 끝 자기 정원에 있습니다. {npc:382}와(과) {npc:341}은(는) 다리 북쪽 끝에 서 있습니다. 검은바위부족 야영지 퀘스트와 {quest:98386}은(는) 이번 방문의 호수 동쪽 경로에서 진행합니다.",
		["Fly to {area:108} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn."] = "{area:108}(으)로 날아가 북서쪽 해안으로 가세요. {object:177790}은(는) 해안 앞바다의 바닥에 있습니다. 그런 다음 길을 따라 동쪽으로 엘윈 숲을 지나가세요.",
		["Follow the road along the south shore of {area:68} to the gryphon master. {npc:903} stands by the road next to her."] = "{area:68}의 남쪽 기슭을 따라 길을 가면 그리폰 조련사가 있습니다. {npc:903}은(는) 그녀 옆 길가에 서 있습니다.",
		["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "묘지를 지나 길을 따라 북서쪽으로, 숲 서쪽 끝의 {npc:311}의 야영지까지 가십시오. {npc:893}은(는) {npc:311} 옆에 서 있습니다.",
		["Follow the road south from {area:1002} into {zone:1431}; {area:42} lies on the east side of the forest."] = "{area:1002}에서 길을 따라 남쪽 {zone:1431}(으)로 가십시오. {area:42}은(는) 숲 동쪽에 있습니다.",
		["For your {area:717} run, in {zone:1453} at about 29: {npc:270} is in the town hall. Keep it until then."] = "{area:717} 공략용(약 29레벨에 {zone:1453}에서): {npc:270}은(는) 마을 회관에 있습니다. 그때까지 보관하십시오.",
		["Greater Tarantulas crawl on the slopes around {quest:98386}, north-east of the lake; their Tarantula Eggs lie on the ground among them: click six."] = "거대한 타란툴라는 호수 북동쪽 {quest:98386} 주변 비탈을 기어다니며, 타란툴라 알은 그들 사이 땅에 있습니다. 여섯 개를 클릭하십시오.",
		["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "키샨은 계곡 맨 북쪽 끝, {zone:1428} 경계 근처에 숨어 있습니다. 그를 호위하여 {area:69}까지 내려가세요. 가는 길에 검은바위부족 오크가 습격합니다.",
		["Murloc Flesheaters and Tidecallers line the south shore of {area:68}, just east of the gryphons and the bridge. Any of them can carry a fin."] = "멀록 청소부와 파도술사는 그리폰과 다리 바로 동쪽, {area:68}의 남쪽 기슭에 늘어서 있습니다. 누구든 지느러미를 지니고 있을 수 있습니다.",
		["The Wanted poster by the inn"] = "여관 옆의 현상수배 전단",
		["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends (23-25) walk its southern half and carry the fingers; for the fangs, Flesh Eaters (24-25) drop the most, so leave the Bone Chewers, Plague Spreaders and Fetid Corpses (26-30) further in alone. {npc:522}, an elite, wanders the graves: keep away from him.\nCareful: Eliza, a level 31 elite, rises from her grave at the cemetery's north end: keep away from it."] = "묘지는 마을 북쪽에 있습니다. 해골 병사와 해골 악령(23-25)이 남쪽 절반을 돌아다니며 손가락을 지니고 있습니다. 송곳니는 굶주린 시체(24-25)가 가장 많이 떨어뜨리니, 더 안쪽의 뼈만남은 시체, 역병걸린 시체, 악취나는 시체(26-30)는 건드리지 마십시오. 정예 {npc:522}이(가) 무덤 사이를 돌아다니니 멀리하십시오.\n주의: 31레벨 정예 엘리자가 묘지 북쪽 끝의 무덤에서 일어나니 그곳을 멀리하십시오.",
		["The hermit's shack stands in the woods north-east of the {area:492}."] = "은둔자의 오두막은 {area:492} 북동쪽 숲속에 있습니다.",
		["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "대충 덮인 흙무더기는 농가 남쪽, 오래된 그루터기 옆에 있습니다.",
		["The road east through Elwynn crosses into Redridge at {area:1002}, where the roads to Redridge, {zone:1431} and Elwynn meet: south to {zone:1431} first."] = "엘윈 숲을 지나 동쪽으로 가는 길은 붉은마루 산맥, {zone:1431}, 엘윈 숲으로 가는 길이 만나는 {area:1002}에서 붉은마루 산맥으로 들어갑니다. 먼저 남쪽 {zone:1431}(으)로 가십시오.",
		["The {area:91}"] = "{area:91}",
		["Use the {item:6866} on {npc:6172}"] = "{npc:6172}에게 {item:6866} 사용",
		["Your new spells"] = "새 주문",
		["{item:1075}: any Shadowhide gnoll"] = "{item:1075}: 아무 잿빛가죽 놀",
		["{item:15882}: the {object:177790}"] = "{item:15882}: {object:177790}",
		["{item:281046}, from the {object:673515}"] = "{object:673515}에서 {item:281046}",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}: 데피아즈단 견습마술사",
		["{npc:2409}, at the north end of town"] = "{npc:2409}, 마을 북쪽 끝",
		["{npc:264}, in the town hall"] = "{npc:264}, 마을 회관",
		["{npc:267}, in the town hall"] = "{npc:267}, 마을 회관",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, 마을 회관 뒤 집",
		["{npc:276} is in her house at the east end of town. {quest:174} needs a {item:4371}, so this step shows only while you carry one: without a tube the guide passes {npc:276} and her chain."] = "{npc:276}은(는) 마을 동쪽 끝 자기 집에 있습니다. {quest:174}에는 {item:4371}이(가) 필요하므로, 이 단계는 그것을 가지고 있을 때만 표시됩니다. 없으면 가이드는 {npc:276}와(과) 그녀의 연계 퀘스트를 건너뜁니다.",
		["{npc:341}, beside him"] = "{npc:341}, 그의 옆",
		["{npc:344}, in the town hall"] = "{npc:344}, 마을 회관 안",
		["{npc:345} (level 24) roots around the pen just west of {area:69}, beside {npc:342}'s garden. Pull him away from the other boars and fight at full health."] = "{npc:345}(24레벨)는 {area:69} 바로 서쪽, {npc:342}의 정원 옆 우리에서 땅을 파헤칩니다. 다른 멧돼지들과 떨어뜨려 끌어온 뒤 생명력이 가득 찬 상태로 싸우세요.",
		["{npc:382}, at the north end of the bridge"] = "{npc:382}, 다리 북쪽 끝",
		["{npc:663}, by the town hall"] = "{npc:663}, 마을 회관 옆",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, 여관",
		["{npc:888} stands south of the road, at the {area:245}."] = "{npc:888}은(는) 길 남쪽 {area:245}에 서 있습니다.",
		["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}, 다리 남쪽 그리폰 옆",
} end)()
t.guides["forever/alliance/05-duskwood"] = (function() return {
		["/lay down beside {npc:7207}"] = "{npc:7207} 옆에서 /lay down",
		["Back to {area:42}"] = "{area:42}(으)로 돌아가기",
		["Cathedral of Light"] = "빛의 대성당",
		["Class trainer"] = "직업 전문가",
		["Fly to {area:42}"] = "{area:42}(으)로 날아가세요",
		["Ghoul Ribs"] = "구울 해골",
		["Head west along the road once more."] = "다시 한 번 길을 따라 서쪽으로 가십시오.",
		["Head west along the road out of {area:94} into {zone:1436}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "길을 따라 서쪽으로 {area:94}을(를) 벗어나 {zone:1436}(으)로 가십시오. {npc:7024}은(는) 경계 바로 안쪽 언덕에서 {npc:7053}의 탑을 감시합니다. 탑을 지키는 {npc:7051}(레벨 23)이(가) 열쇠를 가지고 있으며, 클라벤의 일지는 꼭대기의 상자에 있습니다.",
		["Head west to the hermit once more."] = "다시 한 번 서쪽의 은둔자에게 가십시오.",
		["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "그녀의 집은 {area:42} 남동쪽 언덕 위, {area:121} 위쪽에 있습니다.",
		["Next: training, then the flight from {zone:1453} to {area:150} for the {zone:1437}."] = "다음: 수련 후 {zone:1453}에서 {area:150}(으)로 비행해 {zone:1437}(으)로 향합니다.",
		["Rot Blossoms"] = "{item:1598}",
		["Shaman training"] = "주술사 수련",
		["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "{npc:202}은(는) {area:42}와(과) 마을 남동쪽 {area:121} 사이의 언덕을 돌아다니며, {item:1598}을(를) 떨어뜨립니다.",
		["Your new spells"] = "새 주문",
		["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372}: {npc:1313}, 연금술 용품",
		["{item:7908}, in the chest"] = "상자 안의 {item:7908}",
		["{npc:264}, in the town hall"] = "{npc:264}, 마을 회관",
		["{npc:267}, in the town hall"] = "{npc:267}, 마을 회관",
		["{npc:272} is in the Scarlet Raven Tavern too."] = "{npc:272}도 주점에 있습니다.",
		["{npc:273}, in the tavern"] = "{npc:273}, 주점",
		["{npc:288} hides in the house at the west end of {area:94}."] = "{npc:288}은(는) {area:94} 서쪽 끝의 집에 숨어 있습니다.",
		["{npc:332}: Poisons, and {item:18160}"] = "{npc:332}: 독, {item:18160}",
		["{npc:6171}: Redemption"] = "{npc:6171}: 구원",
		["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607}: {npc:7207}, 병영 지하실",
		["{quest:337}: a rare drop from {zone:1431}'s mobs"] = "{quest:337}: {zone:1431} 몹이 드물게 떨어뜨림",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453}에는 주술사 상급자가 없습니다. {object:28027}에서 {area:2257}을(를) 타고 {zone:1455}(으)로 가서 {npc:258098}에게 훈련을 받은 뒤, 지하철을 타고 돌아오세요.",
} end)()
t.guides["forever/alliance/06-ashenvale"] = (function() return {
		["Back north from the glaive (Druids: south along the road from {area:442}) to the {area:448}, where {npc:11218} sleeps beside Arbal. Take his quest: it gives you the {item:13536}. Use the horn to wake him and lead him south along the road to his bag at the southern edge of {zone:1439}; blow it again whenever he falls asleep. Then go on to {npc:11219} at {area:413}.\nCareful: Scripted ambushes of three mobs each attack along the road."] = "글레이브에서 다시 북쪽으로 (드루이드: {area:442}에서 길을 따라 남쪽으로) {area:448}까지 가세요. {npc:11218}이(가) 아발 옆에서 잠들어 있습니다. 그의 퀘스트를 받으면 {item:13536}을(를) 얻습니다. 뿔피리를 사용해 그를 깨우고, 길을 따라 남쪽으로 {zone:1439} 남쪽 끝에 있는 그의 가방까지 데려가세요. 그가 잠들 때마다 뿔피리를 다시 부세요. 그런 다음 {area:413}의 {npc:11219}에게 가세요.\n주의: 길을 따라 세 마리씩 이루어진 매복 무리가 정해진 대로 습격합니다.",
		["Below ground"] = "지하",
		["Boat to {area:150}"] = "배를 타고 {area:150}(으)로",
		["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site. Careful: Highland Lurkers and Horrors, level 28 elites, walk the same cave among them: pull the stalkers one at a time and keep clear of the elites."] = "긴다리동굴거미와 긴다리흡혈거미가 발굴 현장 남동쪽 동굴인 {area:1021}에 가득합니다. 주의: 28레벨 정예인 고원 잠복꾼과 고원 공포가 같은 동굴 안에서 그들 사이를 돌아다닙니다. 거미를 하나씩 끌어오고 정예는 피하세요.",
		["Fly to {area:1537}"] = "{area:1537}(으)로 비행",
		["Fly to {area:442}"] = "{area:442}(으)로 비행",
		["Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; {npc:1259} walks with a pack in the middle of it."] = "해안을 따라 북쪽으로 메네실 항구를 나가세요. 푸른아가미멀록이 늪에 가득하고, {npc:1259}은(는) 그 한가운데에서 무리와 함께 돌아다닙니다.",
		["From the marsh head east across the {zone:1437}. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "늪에서 동쪽으로 {zone:1437}을(를) 가로지르세요. 어린 저습지 악어가 발굴 현장 북쪽 웅덩이에 숨어 있습니다.",
		["Head south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}, north of the {area:2160}."] = "{area:421}을(를) 지나 남쪽으로 {area:1276} 굴에 들어가세요. 굴은 돌발톱 산맥의 {area:461}, {area:2160} 북쪽으로 이어집니다.",
		["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "정령을 처치해 {item:12220} 5개를 모은 뒤 {item:5456}을(를) 사용하세요",
		["Mosshide Gnolls and Mongrels hold the hills south-east of the {area:1025}."] = "이끼가죽 놀과 이끼가죽일족 싸움꾼이 {area:1025} 남동쪽 언덕을 차지하고 있습니다.",
		["North of Maestra's Post, plant bundles lie around the ruins of {area:411}. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "마에스트라 주둔지 북쪽, {area:411} 폐허 주변에 식물 꾸러미가 놓여 있습니다. 암흑이교도는 그 바로 남쪽 폐허를 차지하고 있으며, 누구든 {item:5366}을(를) 떨어뜨릴 수 있습니다.",
		["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "{zone:1439}에서 얻은 {item:5352}이(가) 있을 때만: {npc:2786}, {object:32383}",
		["Still carrying {quest:92748} (you used your Hearthstone at the end of {zone:1432})? The tram comes in at the {object:28027}, where {npc:11026} stands."] = "아직 {quest:92748}을(를) 가지고 있습니까({zone:1432} 끝에서 귀환석을 사용했다면)? 지하철은 {npc:11026}이(가) 서 있는 {object:28027}에 도착합니다.",
		["The Foulweald"] = "썩은나무 숲",
		["The Mosshide gnolls"] = "이끼가죽 놀",
		["The Venture Co. clear the forest of {area:461}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "투자개발회사가 {area:461}의 숲을 베어내고 있습니다. 나무꾼과 벌채꾼이 곳곳에서 일하고, 운전수가 벌목기를 몰며 그중 하나가 설계도를 지니고 있습니다.",
		["The excavation site sits on the hill south of the road."] = "발굴 현장은 길 남쪽 언덕 위에 있습니다.",
		["The raptor hills"] = "랩터 언덕",
		["The tears glow on the small isle east of {area:415}."] = "눈물은 {area:415} 동쪽의 작은 섬에서 빛납니다.",
		["Timber and iron piles lie around the keep and along the harbor's walls. Careful: {npc:270589}, a level 31 elite, roams the {zone:1437}' shores and roads: if it comes by, give it room."] = "목재와 철 더미가 성채 주변과 항구 성벽을 따라 놓여 있습니다. 주의: 31레벨 정예인 {npc:270589}이(가) {zone:1437}의 해안과 길을 돌아다닙니다. 다가오면 자리를 비켜 주세요.",
		["To {area:150}"] = "{area:150}(으)로",
		["Tram to {zone:1453}"] = "지하철을 타고 {zone:1453}(으)로",
		["Underwater"] = "물속",
		["Young crocolisks"] = "새끼 악어",
		["{area:2797} is a dungeon for a group of five, about levels 22 to 30, and a full run takes about an hour. The way in is the sunken ruins at the north end of the strand: go down the stairs into the pit, swim through the tunnels under the wall, past the blue crystals, to the portal.\nInside: the naga and the satyrs drop the Corrupted Brain Stems for Gershala. {npc:4787}, by a campfire in an underwater side room off Ghamoo-ra's room, has a quest for {zone:1457}, which this route leaves to the Dungeons page."] = "{area:2797}은(는) 약 22~30레벨 5인 파티용 던전이며, 전체 공략에 약 1시간이 걸립니다. 들어가는 길은 해안 북쪽 끝의 가라앉은 폐허입니다. 계단을 내려가 구덩이로 들어간 뒤, 성벽 아래 터널을 헤엄쳐 푸른 수정을 지나 차원문까지 가십시오.\n내부: 나가와 사티로스가 게르샬라에게 줄 타락한 뇌줄기를 떨어뜨립니다. 가무라의 방에서 이어지는 수중 곁방의 모닥불 옆에 있는 {npc:4787}은(는) {zone:1457}(으)로 가는 퀘스트를 주며, 이 경로는 그 퀘스트를 던전 페이지에 맡깁니다.",
		["{item:2594}, from {npc:1464}"] = "{item:2594}, {npc:1464}에게서",
		["{item:5424}, in the ruins on the shore"] = "{item:5424}, 해안의 폐허 안",
		["{npc:1021}; careful: {npc:270589}, a level 31 elite, roams these hills"] = "{npc:1021}; 주의: 31레벨 정예 {npc:270589}이(가) 이 언덕을 돌아다닙니다",
		["{npc:1239}, in the inn"] = "{npc:1239}, 여관 안",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}, 여관 북쪽 부두 위",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}: {area:442}에서 온 툰드리스의 편지",
		["{npc:2086}, in the keep"] = "{npc:2086}, 성채 안",
		["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093}은(는) 길가에 진을 치고 있고, {npc:1244}은(는) 더 동쪽 강가에 서 있습니다.",
		["{npc:2096}, by the north gate"] = "{npc:2096}, 북문 옆",
		["{npc:3691}, in the inn"] = "{npc:3691}, 여관 안",
		["{npc:3693} stands by the flight master, at the east end of the main street. No {quest:990} yet? Give it a minute after the hand-in: {npc:3694} comes to {npc:3693}'s side shortly after Volcor's escort is handed in. Changing layer can also find her. Then back west to the dock."] = "{npc:3693}은(는) 중앙 거리 동쪽 끝, 비행 조련사 옆에 서 있습니다. 아직 {quest:990}이(가) 없습니까? 제출 후 잠시 기다리세요. 볼코르 호위 퀘스트를 제출하면 곧 {npc:3694}이(가) {npc:3693} 옆으로 옵니다. 레이어를 바꿔도 그녀를 찾을 수 있습니다. 그런 다음 다시 서쪽 부두로 가세요.",
		["{npc:3693}: Volcor's escort from the end of {zone:1439}"] = "{npc:3693}: {zone:1439} 마지막의 볼코르 호위",
		["{npc:3694}, once she comes: {quest:990}, for {npc:3691} in {area:415} on your next {zone:1440} visit"] = "{npc:3694}, 나타나면: {quest:990}, 다음 {zone:1440} 방문 때 {area:415}의 {npc:3691}에게",
		["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}: {zone:1457}의 {npc:11401}에게 제출합니다. 나중에",
		["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}: {zone:1455}의 {npc:11406}에게 제출합니다. 나중에",
		["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}: {zone:1455}의 {npc:258785}에게 제출합니다. 나중에",
		["{npc:4201}, inside"] = "{npc:4201}, 내부",
		["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}: {zone:1413}의 {npc:6244}에게 제출합니다. 나중에",
		["{object:2164} is in the {object:2101}. Warlocks: {npc:6122} is in its cellar."] = "{object:2164}은(는) {object:2101}에 있습니다. 흑마법사: {npc:6122}은(는) 그 지하실에 있습니다.",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}: {area:415}의 {npc:3961}에게",
		["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009}은(는) 성난지느러미일족 경비병과 함께 {area:414}의 북쪽 끝을 돌아다닙니다.",
		["{quest:1010}, from the plant bundles"] = "{quest:1010}, 식물 꾸러미에서",
		["{quest:1275}: Corrupted Brain Stems"] = "{quest:1275}: 타락한 뇌줄기",
		["{quest:1483}, inside"] = "{quest:1483}, 내부",
} end)()
t.guides["forever/alliance/06-wetlands"] = (function() return {
		["Back south to Menethil: {npc:1217} stands in the {area:2104}."] = "남쪽 메네실로 돌아가세요. {npc:1217}은(는) {area:2104}에 있습니다.",
		["Back to the Cathedral of Light: {npc:928} stands inside."] = "빛의 대성당으로 돌아가세요. {npc:928}이(가) 안에 서 있습니다.",
		["Below ground"] = "지하",
		["Boat to {area:150}"] = "배를 타고 {area:150}(으)로",
		["Cathedral of Light"] = "빛의 대성당",
		["Dartol's Rod"] = "다르톨의 변신마법봉",
		["Ebenezer Rustlocke"] = "에벤에셀 러스트로크",
		["Fly to {area:150}"] = "{area:150}(으)로 비행",
		["Fly to {area:1537}"] = "{area:1537}(으)로 비행",
		["Fly to {area:442}"] = "{area:442}(으)로 비행",
		["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "길을 따라 동쪽으로 {area:429}의 사티로스 야영지까지 가십시오. {npc:3920}은(는) 야영지 가장자리에 숨어 있습니다.",
		["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "길을 따라 동쪽으로 {area:419}까지 가세요. {npc:3916}은(는) 달샘 옆에 서 있습니다.",
		["For Bolvar Fordragon in {object:2117}: keep it"] = "{object:2117}의 볼바르 폴드라곤에게: 보관하세요",
		["For your {area:17732} run, later in this guide: {npc:2094}, by the docks, wants hides from the raptors inside."] = "{area:17732} 공략용(이 가이드 후반): 부두 옆의 {npc:2094}이(가) 내부 랩터의 가죽을 원합니다.",
		["For your {area:17732} run, on the way back west: {npc:1244} wants the root core of a {npc:260808} inside."] = "{area:17732} 공략용(서쪽으로 돌아가는 길): {npc:1244}은(는) 내부의 {npc:260808}에게서 나오는 뿌리 핵을 원합니다.",
		["For your {area:717} run: {npc:1719} keeps the {area:717}'s gate, south of the {object:2098}."] = "{area:717} 공략용: {npc:1719}은(는) {object:2098} 남쪽에서 {area:717} 입구를 지키고 있습니다.",
		["For {npc:2228} in {area:271}: keep it"] = "{area:271}의 {npc:2228}에게: 보관하세요",
		["For {npc:3649} in {area:442}, on this guide's boat trip: keep it"] = "이 가이드의 배 여행 중 {area:442}의 {npc:3649}에게: 보관하세요",
		["From {area:413}, east to the Thistlefur camp north of {area:415}: {npc:3987} leads the furbolgs there. Then south to {area:415}.\nCareful: The furbolgs near him usually join in when he is pulled. Killing the ones along his path first lets you fight him alone."] = "{area:413}에서 동쪽으로 {area:415} 북쪽의 엉겅퀴털 야영지로 가세요. {npc:3987}이(가) 그곳 펄볼그를 이끌고 있습니다. 그런 다음 남쪽 {area:415}(으)로 가세요.\n주의: 그를 끌면 근처 펄볼그가 대개 함께 덤빕니다. 그의 이동 경로에 있는 펄볼그를 먼저 처치하면 그와 혼자 싸울 수 있습니다.",
		["Insane druids"] = "미치광이 드루이드",
		["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "정령을 처치해 {item:12220} 5개를 모은 뒤 {item:5456}을(를) 사용하세요",
		["Level 28"] = "28레벨",
		["Lightforge Ingots"] = "라이트포지 주괴",
		["Melyria and {npc:3901}"] = "파수꾼 멜리리아 프로스트섀도와 {npc:3901}",
		["Next: fly to {area:42}."] = "다음: {area:42}(으)로 날아가세요.",
		["North from the lake to the satyr camp of {area:430}, just west of {area:2358}: the {object:19901} stands in it, and {object:673431} lies beside it with the {item:281014}.\nCareful: The Felmusk Rogues in {area:428} often go stealthed, and {area:430} has satyr casters."] = "호수에서 북쪽으로, {area:2358} 바로 서쪽에 있는 {area:430}의 사티로스 야영지로 가십시오. 그 안에 {object:19901}이(가) 있고, 그 옆에 {item:281014}이(가) 든 {object:673431}이(가) 있습니다.\n주의: {area:428}의 펠머스크 도적은 은신해 있는 경우가 많고, {area:430}에는 사티로스 주문시전자가 있습니다.",
		["Not grouped? {quest:1012} (the {area:432}) is a fight for a group at this level: abandon it, the route doesn't come back for it."] = "파티가 없습니까? {quest:1012}({area:432})은(는) 이 레벨에서는 파티가 필요한 전투입니다. 포기하세요. 경로는 이 퀘스트를 위해 돌아오지 않습니다.",
		["Not grouped? {quest:1031} ({npc:4619}, 32) is a fight for a group at this level: abandon it, the route doesn't come back for it."] = "파티가 없습니까? {quest:1031}({npc:4619}, 32)은(는) 이 레벨에서는 파티가 필요한 전투입니다. 포기하세요. 경로는 이 퀘스트를 위해 돌아오지 않습니다.",
		["Off the boat, {npc:1480} stands beside Menethil's inn, on the way to the flight master."] = "배에서 내리면 비행 조련사에게 가는 길, 메네실 여관 옆에 {npc:1480}이(가) 서 있습니다.",
		["On the way south-east to {npc:3897}: the Foulweald furbolgs live in the woods south of the road, south-east of {area:415}. The Den Watcher and the Ursas guard the den."] = "{npc:3897}에게 남동쪽으로 가는 길에: 더러운숲 펄볼그는 {area:415} 남동쪽, 길 남쪽 숲에 삽니다. 굴 감시자와 우르사가 굴을 지킵니다.",
		["Only if you looted {quest:337} in {zone:1431}"] = "{zone:1431}에서 {quest:337}을(를) 획득한 경우에만",
		["Raptor valley"] = "랩터 계곡",
		["Still below level 28? That happens when you start this guide here without the {zone:1437} and {zone:1440} quests of the guides before it: top up on the Bluegill Raiders along the coast just south of Menethil before the boat, so {zone:1440}'s level 28-32 quests aren't too hard."] = "아직 28레벨 미만입니까? 이전 가이드의 {zone:1437} 및 {zone:1440} 퀘스트 없이 여기서 이 가이드를 시작하면 그렇게 됩니다. 배를 타기 전에 메네실 항구 바로 남쪽 해안의 푸른아가미 약탈자를 잡아 경험치를 채우십시오. 그래야 {zone:1440}의 28-32레벨 퀘스트가 너무 어렵지 않습니다.",
		["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end. Careful: Terrowulf Fleshrippers and Shadow Weavers (28-30) stand in tight packs around the tome, and the {npc:3792}, a level 32 rare, walks the vale. Pull the wolves one at a time from the tunnel and let the Packlord pass first."] = "굴을 지나 {area:419}(으)로 들어가십시오. 마법책은 서쪽 끝 폐허에 있습니다. 주의: 공포늑대 살점찢개와 그림자술사(28-30)가 마법책 주위에 빽빽하게 무리 지어 있고, 32레벨 희귀 몹인 {npc:3792}이(가) 골짜기를 돌아다닙니다. 굴에서 늑대를 하나씩 끌어내고, 무리 우두머리가 먼저 지나가게 두십시오.",
		["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "{object:171524}에서 {area:2257}을(를) 타고 {zone:1453}의 {object:28027}(으)로 간 뒤, {object:2098}까지 걸어가세요.",
		["The Bluegill hovels"] = "푸른아가미 오두막",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "달샘 북쪽의 광기어린 고대정령과 부패한 고대정령이 {item:5475}을(를) 지니고 있습니다. 그 열쇠로 여는 낡은 궤짝은 그들 사이에 있습니다.",
		["The Foulweald"] = "썩은나무 숲",
		["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it.\nGoaz Warders (elite, 32) stand among the relics and the {object:331}: work around them; don't pull them."] = "유물은 발굴지 안에 있습니다. 커다란 무쇠턱 랩터인 {npc:1353}은(는) 그 바로 서쪽의 랩터 계곡을 어슬렁거립니다.\n고아즈 감시자(정예, 32)가 유물과 {object:331} 사이에 서 있습니다. 끌어오지 말고 피해서 작업하십시오.",
		["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "두 번째 {object:19901}은(는) 서쪽으로 가는 길, {area:428} 골짜기에 있습니다.",
		["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "제단은 달샘 바로 남동쪽 언덕 위에 있습니다. 구불구불한 길을 따라 올라가십시오.",
		["The {item:270865} from your {area:17732} run: {npc:1077} is below ground in his dig, west of the entrance on the way back west."] = "{area:17732} 공략에서 얻은 {item:270865}: {npc:1077}은(는) 서쪽으로 돌아가는 길, 입구 서쪽의 발굴지 지하에 있습니다.",
		["Tram to {zone:1453}"] = "지하철을 타고 {zone:1453}(으)로",
		["Underwater"] = "물속",
		["Your Excavation Site hides: {npc:2094}, by the docks."] = "발굴 현장 가죽: 부두 옆의 {npc:2094}.",
		["Your {area:2797} brain stems: {npc:8997} stands a short walk west of {npc:3693}."] = "{area:2797}의 뇌줄기: {npc:8997}은(는) {npc:3693}에서 서쪽으로 조금 걸어가면 서 있습니다.",
		["grind on {npc:1418}"] = "{npc:1418} 사냥",
		["{area:17732} is a dungeon for a group of five at about level 28 to 31. Its entrance lies just south of the road west, east of Whelgar's dig.\nInside: the Thicket raptors and Shadetooth drop the hides for Halloran, a {npc:260808} the root core for {npc:1244}. Saltspine, Shadetooth and the {npc:260326} are the bosses; the {npc:260326} drops a {item:270865}, which starts a quest for {npc:1077}."] = "{area:17732}은(는) 약 28~31레벨 5인 파티용 던전입니다. 입구는 서쪽 길 바로 남쪽, 웰가르의 발굴지 동쪽에 있습니다.\n내부: Thicket 랩터와 Shadetooth가 할로란에게 줄 가죽을, {npc:260808}이(가) {npc:1244}에게 줄 뿌리 핵을 떨어뜨립니다. Saltspine, Shadetooth, {npc:260326}이(가) 우두머리이며, {npc:260326}은(는) {npc:1077}에게 가는 퀘스트를 시작하는 {item:270865}을(를) 떨어뜨립니다.",
		["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there, {npc:221269} a few steps east of her."] = "길 동쪽 끝의 나이트 엘프 전초기지 {area:2358}: {npc:3848}이(가) 그곳에 있고, {npc:221269}은(는) 그녀에게서 동쪽으로 몇 걸음 떨어져 있습니다.",
		["{area:717} is a dungeon for a group of five, about levels 23 to 29, and a run takes under an hour. Its gate is {npc:1719}'s, south of the {object:2098}.\nInside: the Defias prisoners, convicts and insurgents for Thelwater, {npc:1663}'s hand for Millstipe, and {quest:389} at the far end."] = "{area:717}은(는) 약 23~29레벨 5인 파티용 던전이며, 공략에 1시간이 채 걸리지 않습니다. 입구는 {object:2098} 남쪽, {npc:1719}이(가) 지키는 문입니다.\n내부: 텔워터를 위한 데피아즈단 죄수, 죄인, 폭도, 밀스타이프를 위한 {npc:1663}의 손, 그리고 맨 끝의 {quest:389}.",
		["{item:15885}: join the halves at the {area:2362}"] = "{item:15885}: {area:2362}에서 반쪽 합치기",
		["{item:2594}, from {npc:1464}"] = "{item:2594}, {npc:1464}에게서",
		["{item:2629}, from {npc:1160}"] = "{item:2629}, {npc:1160}에게서 획득",
		["{item:2661}: the {object:331}"] = "{item:2661}: {object:331}",
		["{item:279915} lies on the shore just south of {area:150}, a short walk past the town's south end. Then follow the coast north out of town to the hovels."] = "{item:279915}은(는) {area:150} 바로 남쪽 해안에 있습니다. 마을 남쪽 끝을 지나 조금만 걸어가면 됩니다. 그런 다음 해안을 따라 북쪽으로 마을을 벗어나 오두막까지 가세요.",
		["{item:279915}, from {npc:270844} in {area:150}"] = "{item:279915}, {area:150}의 {npc:270844}에게서",
		["{item:281014}, from {object:673431}"] = "{item:281014}, {object:673431}에서",
		["{npc:1077}, below ground"] = "{npc:1077}, 지하",
		["{npc:1077}: for {npc:5387} in {zone:1455}, at the end of this guide"] = "{npc:1077}: {zone:1455}의 {npc:5387}에게, 이 가이드 마지막에",
		["{npc:1078} and Whelgar"] = "{npc:1078}와(과) 웰가르",
		["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406}와(과) {npc:258785}은(는) {object:32362}의 {object:32386}에 있습니다.",
		["{npc:1158}; careful: {npc:270589}, a level 31 elite, roams this coast"] = "{npc:1158}; 주의: 31레벨 정예 {npc:270589}이(가) 이 해안을 돌아다닙니다",
		["{npc:1239}, in the inn"] = "{npc:1239}, 여관 안",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}, 여관 북쪽 부두 위",
		["{npc:1242}: for {npc:2104} in the keep"] = "{npc:1242}: 성채 안의 {npc:2104}에게",
		["{npc:1646} stands in the {object:2098}."] = "{npc:1646}은(는) {object:2098}에 서 있습니다.",
		["{npc:1646}: {quest:97914}, {npc:3649}'s letter, if you still carry it"] = "{npc:1646}: {quest:97914}, 아직 가지고 있다면 {npc:3649}의 편지",
		["{npc:1719}, at the gate"] = "{npc:1719}, 입구",
		["{npc:1719}: {quest:389}, from {npc:1646}"] = "{npc:1719}: {npc:1646}에게서 받은 {quest:389}",
		["{npc:221269}, a few steps east"] = "{npc:221269}, 동쪽으로 몇 걸음",
		["{npc:221269}: her husband's trail in {area:430}, on the way back from the lake"] = "{npc:221269}: 호수에서 돌아오는 길에 {area:430}에서 남편의 흔적 찾기",
		["{npc:2695}: for King Magni, on the same {zone:1455} stop"] = "{npc:2695}: 국왕 마그니 브론즈비어드에게, 같은 {zone:1455} 방문 때",
		["{npc:270844}, beside him"] = "{npc:270844}, 그의 곁",
		["{npc:270844}, beside {npc:2094} by the docks"] = "{npc:270844}, 부두 옆 {npc:2094} 곁",
		["{npc:3585} stands at the {area:416}, a short walk from Melyria and {npc:3901}."] = "{npc:3585}은(는) {area:416}에 서 있으며, 멜리리아와 {npc:3901}에게서 조금만 걸어가면 됩니다.",
		["{npc:3585}: {quest:945}, if you still carry it from {zone:1439}"] = "{npc:3585}: {quest:945}, {zone:1439}에서 받아 아직 가지고 있다면",
		["{npc:3649} stands at the north end of {area:442}, up the road from the dock."] = "{npc:3649}은(는) 부두에서 길을 따라 올라간 {area:442}의 북쪽 끝에 서 있습니다.",
		["{npc:3663}: {quest:967}, if you still carry it from {zone:1439}"] = "{npc:3663}: {quest:967}, {zone:1439}에서 받아 아직 가지고 있다면",
		["{npc:3691} stands in the inn, beside the innkeeper."] = "{npc:3691}은(는) 여관 안 여관주인 옆에 서 있습니다.",
		["{npc:3691}: {quest:990}, if you still carry it from {zone:1439}"] = "{npc:3691}: {quest:990}, {zone:1439}에서 받아 아직 가지고 있다면",
		["{npc:3693} stands by the flight master. No {quest:990} yet? Give it a minute after the hand-in: {npc:3694} comes to {npc:3693}'s side shortly after Volcor's escort is handed in. Changing layer can also find her."] = "{npc:3693}은(는) 비행 조련사 옆에 서 있습니다. 아직 {quest:990}이(가) 없습니까? 제출 후 잠시 기다리세요. 볼코르 호위 퀘스트를 제출하면 곧 {npc:3694}이(가) {npc:3693} 옆으로 옵니다. 레이어를 바꿔도 그녀를 찾을 수 있습니다.",
		["{npc:3693}: Volcor's escort from the end of {zone:1439}"] = "{npc:3693}: {zone:1439} 마지막의 볼코르 호위",
		["{npc:3694}, once she comes: {quest:990}, for {npc:3691} in {area:415}"] = "{npc:3694}, 그녀가 오면: {quest:990}, {area:415}의 {npc:3691}에게",
		["{npc:3845} and {npc:3970} stand by {area:415}'s flight master."] = "{npc:3845}와(과) {npc:3970}은(는) {area:415}의 비행 조련사 옆에 서 있습니다.",
		["{npc:3885} stands at the {area:420} on the east shore of {area:421}, just north of the road to {npc:3897}. Befouled Water Elementals wade in the lake; {npc:12759}, a level 27 water elemental, walks among them and drops the bracers too."] = "{npc:3885}은(는) {area:421} 동쪽 호숫가의 {area:420}, {npc:3897}에게 가는 길 바로 북쪽에 서 있습니다. 타락한 물의 정령이 호수를 돌아다니며, 27레벨 물의 정령인 {npc:12759}도 그들 사이를 돌아다니고 팔보호구를 떨어뜨립니다.",
		["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below {area:421}. Use {item:5462} near him first: he only speaks to you in furbolg form."] = "타락하지 않은 펄볼그 {npc:3897}은(는) {area:421} 아래 길 남쪽에 앉아 있습니다. 먼저 그의 근처에서 {item:5462}을(를) 사용하세요. 그는 펄볼그 모습일 때만 말을 겁니다.",
		["{npc:3901} stands beside Melyria."] = "{npc:3901}은(는) 멜리리아 옆에 서 있습니다.",
		["{npc:3901}: the {item:5461}"] = "{npc:3901}: {item:5461}",
		["{npc:3920}: {quest:1031}, from {npc:4619} (level 32): a fight for a group at this level"] = "{npc:3920}: {quest:1031}, {npc:4619}(32레벨)에게서: 이 레벨에서는 파티가 필요한 전투",
		["{npc:3970}: {quest:95737}, for {npc:1480} in {area:150}"] = "{npc:3970}: {quest:95737}, {area:150}의 {npc:1480}에게",
		["{npc:4619} leads the {area:429} satyrs; he carries the branch. He is level 32, above you here, among level 29-30 satyrs: grouping up is advised."] = "{npc:4619}은(는) {area:429} 사티로스의 우두머리이며 나뭇가지를 지니고 있습니다. 32레벨로 지금의 당신보다 높고, 29-30레벨 사티로스들 사이에 있습니다. 파티를 짜는 것을 권장합니다.",
		["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}, {object:2096}의 치즈 가게",
		["{npc:4959} and {npc:482}"] = "{npc:4959}와(과) {npc:482}",
		["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}, 빛의 대성당 안",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}: {area:415}의 {npc:3961}에게",
		["{quest:1012}, taken alone"] = "{quest:1012}, 혼자 받은 경우",
		["{quest:1031}, taken alone"] = "{quest:1031}, 혼자 받은 경우",
		["{quest:95646}: the root core, inside"] = "{quest:95646}: 뿌리 핵, 내부",
		["{quest:98815}: the hides, inside"] = "{quest:98815}: 가죽, 내부",
		["{quest:98824}: {npc:5387} stands in the {object:32356}, north-east of the {object:32372}."] = "{quest:98824}: {npc:5387}은(는) {object:32372} 북동쪽의 {object:32356}에 서 있습니다.",
		["{zone:1455} priests"] = "{zone:1455} 사제",
} end)()
t.guides["forever/alliance/07-thousand-needles"] = (function() return {
		["Back to {area:42}"] = "{area:42}(으)로 돌아가기",
		["Below ground"] = "지하",
		["Fly to {area:150}"] = "{area:150}(으)로 비행",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "다음 가이드에서 {zone:1453}의 {npc:1212}에게",
		["For {npc:482} in {zone:1453}, in the next guide"] = "다음 가이드에서 {zone:1453}의 {npc:482}에게",
		["Head south-west from {area:42} to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it. {npc:300} is inside the ogre mound's cave: go in by the cave mouth on the mound's west side."] = "{area:42}에서 남서쪽 오우거 소굴로 가세요. {object:119}은(는) 입구의 야영지에 있으며 망치주먹 오우거가 지킵니다. {npc:300}은(는) 오우거 소굴의 동굴 안에 있습니다. 소굴 서쪽의 동굴 입구로 들어가세요.",
		["Hearth back to {area:42} (bound at the start of this guide): {npc:311}'s camp is at the far west of {zone:1431}."] = "귀환석으로 {area:42}(으)로 돌아가세요(이 가이드 시작 시 설정). {npc:311}의 야영지는 {zone:1431} 서쪽 끝에 있습니다.",
		["Nightbane Dark Runners"] = "{npc:205}",
		["Nightbane Shadow Weavers"] = "{npc:533}",
		["Nightbane Vile Fangs and Tainted Ones"] = "파멸의어둠일족 송곳니투사와 오염된 자",
		["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "{npc:272273}이(가) {quest:96138}을(를) 떨어뜨렸을 때만: 오른쪽 클릭하세요",
		["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "암흑길잡이는 {area:42} 서쪽, 길 남쪽 숲을 어슬렁거립니다.",
		["The Defias camp lies in the south-west of {zone:1431}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "데피아즈단 야영지는 {zone:1431} 남서쪽, {area:94} 남쪽의 {zone:1436} 경계 근처에 있습니다. 금고는 천막들 사이에 있습니다.",
		["The grave stands among the skeletons at the cemetery's north-west corner, on the way to {npc:311}. Its quest and the next are talk-only, to {npc:268} and Commander Althea in {area:42}: level 35 quests, but no fight."] = "무덤은 {npc:311}에게 가는 길, 묘지 북서쪽 구석의 해골들 사이에 있습니다. 이 퀘스트와 다음 퀘스트는 {area:42}의 {npc:268}와(과) 사령관 알테아에게 대화만 하면 됩니다. 35레벨 퀘스트지만 전투가 없습니다.",
		["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}.\nCareful: {spell:8282} lasts 10 minutes and adds 13 to each hit of physical damage you take.\nCareful: Some worgen outside the cave stand in groups, including one camp of four. To avoid adds, pull them one at a time from the raised ground next to the cave entrance.\nCareful: Gutspill, a level 32 abomination, walks these woods: let it pass."] = "가장 강한 늑대인간은 {area:42} 남쪽, {area:121} 서쪽과 남쪽 숲을 돌아다닙니다.\n주의: {spell:8282}은(는) 10분간 지속되며, 받는 물리 피해가 타격마다 13 증가합니다.\n주의: 동굴 밖의 일부 늑대인간은 무리 지어 있으며, 4마리가 모인 곳도 있습니다. 추가로 끌려오지 않도록 동굴 입구 옆 높은 지대에서 하나씩 끌어오세요.\n주의: 32레벨 누더기골렘 거트스필이 이 숲을 돌아다닙니다. 지나가게 두세요.",
		["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "늑대인간이 {area:42} 서쪽, 길 북쪽의 밝은나무 숲을 차지하고 있습니다. 하나씩 끌어오세요.",
		["The {npc:511}"] = "{npc:511}",
		["The {npc:511} hides in the small crypt by the {area:121}, south of {area:42}. {npc:663}'s Nightbane Vile Fangs and Tainted Ones (level 29-31) roam the woods around it: they come at the end of this guide, a level later."] = "{npc:511}은(는) {area:42} 남쪽, {area:121} 옆의 작은 납골당에 숨어 있습니다. {npc:663}의 파멸의어둠일족 송곳니투사와 오염된 자(29-31레벨)는 그 주변 숲을 돌아다닙니다. 이들은 한 레벨 뒤, 이 가이드 끝에서 처리합니다.",
		["Wait a moment, then speak with her again"] = "잠시 기다렸다가 그녀와 다시 대화하세요",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "경로의 이전 방문 때 이것을 놓쳤습니다. 지금 이것부터 합니다. 금방 끝나며 뒤에 이어지는 퀘스트를 열어 줍니다.",
		["{npc:263}, in the town hall"] = "{npc:263}, 마을 회관 안",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, 마을 회관 뒤 집",
		["{npc:276}'s house stands at the east end of town, on the way to the flight master."] = "{npc:276}의 집은 비행 조련사로 가는 길, 마을 동쪽 끝에 있습니다.",
		["{npc:311}'s Camp"] = "{npc:311}의 야영지",
		["{npc:661}, by {npc:633}'s house; inside"] = "{npc:661}, {npc:633}의 집, 안",
		["{npc:663} and {npc:661}"] = "{npc:663}와(과) {npc:661}",
		["{npc:663}, by the town hall"] = "{npc:663}, 마을 회관 옆",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, 여관",
		["{npc:840}, at the north entrance of town; walks around {area:42}: look inside the circle on the map"] = "{npc:840}, 마을 북쪽 입구. {area:42}을(를) 돌아다닙니다. 지도의 원 안을 살펴보십시오",
		["{quest:377}, from your {area:717} run: {npc:270} is in the town hall, beside Commander Althea."] = "{area:717} 공략에서 얻은 {quest:377}: {npc:270}은(는) 마을 회관 안, 사령관 알테아 옆에 있습니다.",
} end)()
t.guides["forever/alliance/30-40/01-hillsbrad-foothills"] = (function() return {
		["A report for {object:2117}; inside"] = "{object:2117}에 보낼 보고서, 안",
		["Back east along the road to the {area:1025}: {npc:270637} camps among the Fenrunners, just west of {npc:1244}. Then west again to Menethil for the boat."] = "길을 따라 다시 동쪽 {area:1025}(으)로 가십시오. {npc:270637}은(는) {npc:1244} 바로 서쪽, Fenrunner 사이에 야영하고 있습니다. 그런 다음 배를 타러 다시 서쪽 메네실 항구로 가십시오.",
		["Back south to Menethil: {npc:1217} stands in the {area:2104}."] = "남쪽 메네실로 돌아가세요. {npc:1217}은(는) {area:2104}에 있습니다.",
		["Back to the same murlocs; not every one drops a head."] = "같은 멀록에게 돌아가십시오. 모두 머리를 떨어뜨리지는 않습니다.",
		["Below ground"] = "지하",
		["Boat to {area:271}"] = "{area:271}행 배",
		["Cathedral of Light"] = "빛의 대성당",
		["Daggerspine naga"] = "비수가시일족 나가",
		["Druid training"] = "드루이드 수련",
		["Ebenezer Rustlocke"] = "에벤에셀 러스트로크",
		["Farren"] = "파렌",
		["Fly to {area:1537}"] = "{area:1537}(으)로 비행",
		["Fly to {zone:1453}"] = "{zone:1453}로 비행",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "{zone:1455}의 {npc:2916}에게, 이 가이드 마지막에",
		["Level 30 and 32 spells"] = "30, 32레벨 주문",
		["Murloc heads"] = "멀록 머리",
		["North along the coast from Menethil to the wreck of the Intrepid: {npc:1160} (30) is aboard, and the locked strongbox sits in the wreck. Careful: {npc:270589}, a level 31-32 elite, roams the {zone:1437}: give it a wide berth."] = "메네실에서 해안을 따라 북쪽으로 인트레피드호 잔해까지 가십시오. {npc:1160}(30)이(가) 배 위에 있고, 잠긴 금고는 잔해 안에 있습니다. 주의: 31-32레벨 정예 {npc:270589}이(가) {zone:1437}을(를) 돌아다닙니다. 멀리 피하세요.",
		["North-east to the {area:1038}: {npc:271338} stands at the gates (use the {item:279996})."] = "북동쪽 {area:1038}(으)로 가십시오. {npc:271338}이(가) 성문에 있습니다({item:279996} 사용).",
		["Snapjaws"] = "무쇠턱거북",
		["South-east from Menethil to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "메네실 항구에서 남동쪽의 용아귀부족 {area:1036}(으)로 가십시오. 가는 길에 첫 번째 투석기가 있고, {object:671518}은(는) 야영지 안에 있습니다.",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "무쇠턱거북이 {area:271} 동쪽, {area:272}(호드) 남쪽 강을 따라 햇볕을 쬡니다.",
		["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}.\nCareful: One camp holds a tight cluster of Oracles that all aggro together."] = "너덜지느러미멀록이 {area:271} 남서쪽 {area:295}에 몰려 있습니다.\n주의: 한 야영지에는 신탁자가 빽빽이 모여 있어 한꺼번에 덤벼듭니다.",
		["The cheese shop in the {object:2096}."] = "{object:2096}의 치즈 가게입니다.",
		["The naga hold the shore south-east of {area:271}."] = "나가가 {area:271} 남동쪽 해안을 차지하고 있습니다.",
		["The root core from your {area:17732} run: {npc:1244} stands by the river, just east of {npc:270637}."] = "{area:17732} 공략에서 얻은 뿌리 핵: {npc:1244}은(는) {npc:270637} 바로 동쪽 강가에 서 있습니다.",
		["The yetis live in the cave in the hills north of {area:271}.\nStay in the {area:277}: the cave further north has Mountain and Giant Yetis (32-34) in pairs and {npc:13602}, a level 36 elite."] = "설인들은 {area:271} 북쪽 언덕의 동굴에 삽니다.\n{area:277}에만 머무르세요. 더 북쪽의 동굴에는 산악 설인과 거대한 설인(32-34)이 짝을 지어 있고, 36레벨 정예 {npc:13602}도 있습니다.",
		["The {item:270865} from your {area:17732} run: {npc:1077} is below ground in his dig, south of the road west."] = "{area:17732} 공략에서 얻은 {item:270865}: {npc:1077}은(는) 서쪽 길 남쪽의 발굴지 지하에 있습니다.",
		["Torn Fin murlocs"] = "너덜지느러미멀록",
		["Underwater"] = "물속",
		["West along the road to Menethil."] = "길을 따라 서쪽 메네실 항구로 가십시오.",
		["West from {area:271} to the {area:286} farms."] = "{area:271}에서 서쪽으로 {area:286} 농장까지 가십시오.",
		["Yeti cave"] = "설인 동굴",
		["grind on {npc:1418}"] = "{npc:1418} 사냥",
		["{item:2629}, from {npc:1160}"] = "{item:2629}, {npc:1160}에게서 획득",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, {npc:2381}에게서",
		["{npc:1077}, below ground"] = "{npc:1077}, 지하",
		["{npc:1077}: for {npc:5387} in {zone:1455}, at the end of this guide"] = "{npc:1077}: {zone:1455}의 {npc:5387}에게, 이 가이드 마지막에",
		["{npc:2094} stands by the docks; {npc:1239} sits in the {area:2104}, south of the keep."] = "{npc:2094}은(는) 부두 옆에 있고, {npc:1239}은(는) 성채 남쪽의 {area:2104}에 앉아 있습니다.",
		["{npc:2104}: for {npc:270637}, back east along the road"] = "{npc:2104}: 길을 따라 다시 동쪽의 {npc:270637}에게",
		["{npc:2382}: the lions come later"] = "{npc:2382}: 사자는 나중에",
		["{npc:251493} stands north-west of the flight master, on the way north to the yeti cave.\n{quest:98059}: {npc:251493} hands you a {item:279386} for the {area:287} council, in the farms west of {area:271}."] = "{npc:251493}은(는) 비행 조련사 북서쪽, 북쪽 설인 동굴로 가는 길에 있습니다.\n{quest:98059}: {npc:251493}이(가) {area:271} 서쪽 농장에 있는 {area:287} 의회에 전할 {item:279386}을(를) 줍니다.",
		["{npc:2695}: for King Magni, on the same {zone:1455} stop"] = "{npc:2695}: 국왕 마그니 브론즈비어드에게, 같은 {zone:1455} 방문 때",
		["{npc:2708} and {npc:4078} are in the {object:2164}; {npc:5081} south of the {object:2101}."] = "{npc:2708}와(과) {npc:4078}은(는) {object:2164}에, {npc:5081}은(는) {object:2101} 남쪽에 있습니다.",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}: 그의 흔적은 아라시 고원으로 이어집니다",
		["{npc:271460} stands in the ruins of {area:205} (use the {item:279996})."] = "{npc:271460}은(는) {area:205}의 폐허에 서 있습니다({item:279996} 사용).",
		["{npc:4078}: the Saltstone Basilisks at the {area:2240} drop the scales, in the next guide"] = "{npc:4078}: 다음 가이드에서 {area:2240}의 소금바위 바실리스크가 비늘을 떨어뜨립니다",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961}은(는) {object:2100}의 돼지와 휘파람 선술집에서 기다립니다. 그와 부하 둘이 덤벼들지만 쓰러뜨리면 멈춥니다.",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: {npc:2104}에게",
		["{zone:1455} flight master"] = "{zone:1455} 비행 조련사",
		["{zone:1455} has no druid trainer: {npc:5504} stands in {zone:1453}, north-west of the {object:2101}."] = "{zone:1455}에는 드루이드 상급자가 없습니다. {npc:5504}은(는) {zone:1453}의 {object:2101} 북서쪽에 있습니다.",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort {npc:5644}"] = "{npc:5644} 호위",
		["Fly to {area:442}"] = "{area:442}(으)로 비행",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "길을 따라 서쪽으로 {area:460}(호드)을(를) 지나, 남서쪽 {area:465}을(를) 거쳐 {zone:1443}(으)로 가십시오. {area:608}은(는) 고개 꼭대기에 있습니다.",
		["For {npc:5638}, at the end of this guide"] = "{npc:5638}에게, 이 가이드 마지막에",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building. {npc:5642} wants four of each kind of cultist on the way."] = "그녀의 오빠 {npc:5643}(36)는 불타는 칼날단 사교도(30-33)와 함께 요새를 돌아다닙니다. 그만 따로 끌어오세요. {npc:13019}은(는) 요새 본관에 홀을 가지고 있습니다. {npc:5642}은(는) 가는 길에 사교도를 종류별로 넷씩 원합니다.",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "{npc:5644}을(를) 요새 밖으로 데려가십시오. 요새를 벗어나면 그녀가 떠납니다. 가이드 마지막에 {area:608}에서 {npc:5642}에게 완료 보고를 하십시오.",
		["Malem chest"] = "말렘의 궤짝",
		["Out of Thunder Axe Fortress"] = "천둥도끼 요새 밖으로",
		["Swim out to {area:2406} off the far northern tip: {object:177786} stands on the shore beside the {object:177673}. Open it with both keys; leave the statue alone."] = "북쪽 끝에서 헤엄쳐 {area:2406}(으)로 가세요. {object:177786}은(는) 해안의 {object:177673} 옆에 있습니다. 두 열쇠로 여세요. 석상은 건드리지 마세요.",
		["The chest lies in the ruins south-west of {area:608}."] = "궤짝은 {area:608} 남서쪽 폐허에 있습니다.",
		["The wrecked ship lies just south-west of {npc:11863}'s tower; its chest sits beside {object:177787}."] = "난파선은 {npc:11863}의 탑 바로 남서쪽에 있습니다. 궤짝은 {object:177787} 옆에 있습니다.",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}, 마른집게 게에게서 획득",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "{npc:11596}의 야영지는 {area:609} 남쪽 길가, {area:596} 옆에 있습니다.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "{npc:11863}의 탑은 {area:599} 서쪽 언덕에 있습니다. 먼저 그의 퀘스트를 수락하십시오. 그가 원하는 홀은 요새 안에 있습니다.",
		["{npc:5396}, beside {npc:5752}"] = "{npc:5752} 옆의 {npc:5396}",
		["{npc:5638}: the wreck's chest lies below {npc:11863}'s tower, on the way to {area:599}"] = "{npc:5638}: 난파선의 궤짝은 {npc:11863}의 탑 아래, {area:599}(으)로 가는 길에 있습니다",
		["{npc:5643} and the Seer"] = "{npc:5643}와(과) 현자",
		["{npc:5752}: the Kolkar are at the end of this guide"] = "{npc:5752}: 콜카르는 이 가이드 끝에서 처리합니다",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["East through the canyons. {area:484}, a Horde camp with guards, sits on the mesa here: keep to the canyon floor and give the foot of its lifts a wide berth."] = "협곡을 지나 동쪽으로 가세요. 이곳 고원 위에는 경비병이 있는 호드 야영지 {area:484}이(가) 있습니다. 협곡 바닥으로만 다니고 승강기 아래쪽은 멀리 피하세요.",
		["Fly to Theramore"] = "테라모어 섬으로 비행",
		["Fly to {area:150}"] = "{area:150}(으)로 비행",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "협곡을 따라 동쪽의 소금 평원으로 가세요. {area:2240}의 고블린과 노움은 중립이며 양 진영 모두에게 퀘스트를 줍니다.",
		["For {quest:1132} in Theramore's inn, where this guide's boat goes"] = "테라모어 여관의 {quest:1132}용 (이 가이드의 배가 가는 곳)",
		["For {quest:5762} in Stranglethorn, later"] = "나중에 가시덤불 골짜기에서 {quest:5762}에게",
		["Lightforge Ingots"] = "라이트포지 주괴",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "{zone:1413}을(를) 지나 남쪽으로 가는 길에서, {npc:6244}은(는) 길 동쪽, {area:378} 북동쪽에 진을 치고 있습니다. 동쪽에서 접근하고 호드 경비병을 피하세요.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "메네실 항구 남서쪽 해변의 푸른아가미멀록들이 주괴를 지니고 있습니다.",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "비행 조련사는 {area:514} 성문 옆에 있으며, {npc:5083}와(과) {npc:4964}은(는) 성채 안에 있습니다.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "Flying Osprey의 난파선은 성채 남쪽 얕은 물에 있습니다.",
		["Theramore"] = "테라모어",
		["{area:976} flight master"] = "{area:976} 비행 조련사",
		["{item:5795}, from the Sparkleshell Tortoises"] = "{item:5795}, 소금껍질거북에게서 획득",
		["{npc:1217} stands in the {area:2104}, south of the keep, where {npc:4963} and {npc:5082} wait too."] = "{npc:1217}은(는) 성채 남쪽의 {area:2104}에 있으며, {npc:4963}와(과) {npc:5082}도 그곳에서 기다리고 있습니다.",
		["{npc:4455} stands by {area:2103}'s door, just north of the flight master."] = "{npc:4455}은(는) 비행 조련사 바로 북쪽, {area:2103} 문 옆에 서 있습니다.",
		["{quest:1132}, inside the inn in the north of town"] = "{quest:1132}, 마을 북쪽 여관 안",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: {zone:1443}(으)로 가는 길에 {zone:1440}에서",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: 서큐버스 옆의 인큐버스. {item:190309}은(는) {quest:1738} 근처에 있습니다",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "네싱워리를 지나 남쪽으로 돌아가세요. 퓨마와 {npc:685}은(는) 야영지 서쪽에서 해안 쪽 빈터를 뛰어다니고, 덩치큰 가시덤불 호랑이는 남서쪽 언덕을 차지하고 있습니다.",
		["Both roam the grass around the camp and along the road north."] = "둘 다 야영지 주변 풀밭과 북쪽 길을 따라 돌아다닙니다.",
		["Class training"] = "직업 수련",
		["Fly to {area:467}"] = "{area:467}(으)로 날아가기",
		["Fly to {zone:1453}"] = "{zone:1453}로 비행",
		["Gluggle (37, rare) on the coast west of camp drops the {item:4614}: four levels over you, leave him unless you are grouped"] = "야영지 서쪽 해안의 글루글(37, 희귀)이 {item:4614}을(를) 떨어뜨립니다. 당신보다 4레벨 높으니 파티가 아니면 건너뛰세요",
		["Panthers, raptors and elder tigers"] = "퓨마, 랩터, 덩치큰 호랑이",
		["River crocolisks"] = "민물악어",
		["Stranglethorn Tigers"] = "{npc:682}",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents. {quest:200}'s records lie in a hut on the compound's west side. Careful: Kurzen Elites and Witch Doctors (36) hold the compound's eastern half, by the cave: stay on its west side."] = "쿠르젠 반란군이 {area:99} 동쪽 야영지를 차지하고 있습니다. 쿠르젠 밀림전사와 쿠르젠 약사가 서 있는 바깥쪽부터 처리하고, 천막 옆 보급품 상자를 뒤지세요. {quest:200}의 장부는 주둔지 서쪽 오두막에 있습니다. 주의: 쿠르젠 정예병과 쿠르젠 주술사(36)가 동굴 옆 주둔지 동쪽 절반을 차지하고 있으니 서쪽에 머무르세요.",
		["The adult tigers prowl the hills just south and west of the camp."] = "다 자란 호랑이는 야영지 바로 남쪽과 서쪽 언덕을 어슬렁거립니다.",
		["The elder tigers come later, on the way back from the {area:99}"] = "덩치큰 가시덤불 호랑이는 나중에 {area:99}에서 돌아오는 길에 잡습니다",
		["The elder tigers next are 34-35: short of 33.2? Keep on the Kurzen Jungle Fighters and Medicine Men around the compound's outer edge until level 33.2. Or, with a group, run the {area:796} dungeon (Library) instead."] = "다음 덩치큰 가시덤불 호랑이는 34-35레벨입니다. 33.2레벨이 안 되나요? 33.2레벨이 될 때까지 주둔지 바깥쪽의 쿠르젠 밀림전사와 쿠르젠 약사를 계속 잡으세요. 아니면 파티와 함께 {area:796} 던전(도서관)을 도세요.",
		["The haunted island"] = "유령의 섬",
		["Warlocks fly to {area:415} for the {quest:1738}, on the way west."] = "흑마법사는 서쪽으로 가는 길에 {quest:1738}을(를) 위해 {area:415}(으)로 날아가세요.",
		["You know the {area:467} flight: it lands closer to {zone:1443} than {area:415} does. From the peak, follow the road south through the mountains to the {area:465}."] = "{area:467} 비행 경로를 알고 있습니다. {area:415}보다 {zone:1443}에 더 가깝게 내립니다. 봉우리에서 길을 따라 산맥을 지나 남쪽의 {area:465}(으)로 가세요.",
		["Young tigers and panthers"] = "새끼 호랑이와 새끼 퓨마",
		["keep it: the Lashtail Raptors come on the second loop (04b), around {npc:729}'s hill"] = "보관하세요: 채찍꼬리랩터는 두 번째 순회(04b)에서 {npc:729}의 언덕 주변에서 잡습니다",
		["keep it: the Shadowmaw Panthers (37-38) wait for the 40-50 Stranglethorn guide"] = "보관하세요: 그림자퓨마(37-38)는 40-50 가시덤불 골짜기 가이드에서 잡습니다",
		["{item:190309}, north of {area:413}"] = "{item:190309}, {area:413} 북쪽",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, {object:263} 상자에서",
		["{npc:2495}, by the bank; inside"] = "{npc:2495}, 은행, 안",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, 선술집 위층",
		["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}, {object:56910}, 위층",
		["{npc:469}, in the hut"] = "{npc:469}, 오두막 안",
		["{npc:715}, from {zone:1441}"] = "{zone:1441}에서 온 {npc:715}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716}이(가) {item:2755}을(를) 모읍니다. 책장은 밀림의 거의 모든 인간형 몹이 떨어뜨립니다. 모이는 대로 책장을 장(章)으로 묶으세요.",
		["{npc:737}'s Bloodscalp ears wait for the second Stranglethorn loop: keep the quest."] = "{npc:737}의 붉은머리부족 귀는 두 번째 가시덤불 골짜기 순회 때 모읍니다. 퀘스트는 보관하세요.",
		["{npc:737}, in the tavern"] = "{npc:737}, 선술집 안",
		["{npc:738}, at the foot of the path"] = "오솔길 아래쪽 끝의 {npc:738}",
		["{npc:770}: for {npc:773} in {area:35}, later in this guide"] = "{npc:770}: {area:35}의 {npc:773}에게, 이 가이드 후반",
		["{object:661516}, a looted crate west of Nesingwary's camp: the Stolen Shipments lie in the Bloodscalp ruins on the coast, for the second Stranglethorn loop"] = "{object:661516}, 네싱워리 야영지 서쪽의 털린 상자: 도난당한 화물은 해안의 붉은머리부족 폐허에 있으며, 두 번째 가시덤불 골짜기 순회 때 처리합니다",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: 사냥꾼 야영지를 둘러보기만 하세요",
} end)()
t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = (function() return {
		["East to {area:101}: Herod's records lie in a hut on its west side."] = "동쪽의 {area:101}(으)로 가세요. 헤로드의 장부는 서쪽에 있는 오두막 안에 있습니다.",
		["Fly to {area:42}"] = "{area:42}(으)로 날아가세요",
		["For Archmage Ansirem in {zone:1416}"] = "{zone:1416}의 대마법사 앤자이럼 룬위버에게",
		["For characters of 35 to 36, but several quests here are level 37-38: on purpose, for their experience. The water elementals are 36-37: pull them one at a time."] = "35~36레벨 캐릭터용이지만, 여기 퀘스트 몇 개는 37-38레벨입니다. 경험치를 위해 일부러 넣었습니다. 물의 정령은 36-37레벨이니 하나씩 끌어오세요.",
		["For {npc:4631} in {area:35}, at the end of this loop"] = "이 경로 끝에 {area:35}의 {npc:4631}에게",
		["North along the coast to the ruins on the hill: the last two tablets lie there. {npc:268992}, a goblin, is caged beside the third tablet: any Bloodscalp can drop his {item:277957}, then lead him out of the ruins. The Stolen Shipments lie at the ruins' east edge. Pick up Green Hills pages as they drop.\nCareful: the Bloodscalp Berserkers, Headhunters and Witch Doctors (36-37) hold the ruins' core: pull them one at a time."] = "해안을 따라 북쪽의 언덕 위 폐허로 가세요. 마지막 석판 두 개가 그곳에 있습니다. 고블린 {npc:268992}은(는) 세 번째 석판 옆에 갇혀 있습니다. 붉은머리부족 누구나 {item:277957}을(를) 떨어뜨릴 수 있으니, 그를 풀어 폐허 밖으로 데리고 나가세요. 도난당한 화물은 폐허 동쪽 끝에 있습니다. 푸른 언덕 페이지가 떨어지면 주우세요.\n주의: 붉은머리부족 광전사, 머리사냥꾼, 의술사(36-37)가 폐허 중심부를 지키니 하나씩 끌어오세요.",
		["North-east up the road to the {area:99}, then back south through the jungle."] = "길을 따라 북동쪽의 {area:99}(으)로 간 뒤, 밀림을 지나 다시 남쪽으로 내려오세요.",
		["Snapjaw Crocolisks"] = "{npc:1152}",
		["Snapjaw Crocolisks bask along the river in the middle of the jungle, on the way south to {area:35}."] = "{area:35}(으)로 남쪽으로 가는 길에, 밀림 한가운데 강가에서 무쇠턱 악어가 햇볕을 쬐고 있습니다.",
		["South along the road: the hunters' tents stand just west of it. {npc:717} and Hemet gave you these on the first loop: take them now only if you didn't."] = "길을 따라 남쪽으로 가세요. 사냥꾼들의 천막은 길 바로 서쪽에 있습니다. {npc:717}와(과) 헤멧이 첫 번째 순회에서 이 퀘스트들을 주었습니다. 받지 않았을 때만 지금 수락하세요.",
		["The Lashtail raptors"] = "채찍꼬리랩터",
		["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "유령이 출몰하는 섬은 두 번째 석판 서쪽 해안 바로 앞에 있습니다. 하급 물의 정령이 섬 주변 물속에서 솟아오릅니다.",
		["The jungle ruins"] = "밀림의 폐허",
		["The {area:102}"] = "{area:102}",
		["West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west.\nCareful: the Saltscale murlocs on the shore near the second tablet are elite (35-37): swim to the tablet from the water and keep clear of them."] = "밀림을 가로질러 서쪽의 트롤 폐허로 가세요. 폐허마다 트롤 전설이 새겨진 석판이 하나씩 있습니다. 처음 두 개는 네싱워리 야영지 남서쪽 폐허에, 마지막 두 개는 북서쪽 언덕에 있습니다.\n주의: 두 번째 석판 근처 해안의 소금비늘 멀록은 정예(35-37)입니다. 물 쪽에서 헤엄쳐 석판으로 가고 그들을 피하세요.",
		["keep it: the Skullsplitter Witch Doctors (41-42) wait for the 40-50 Stranglethorn guide"] = "보관하세요: 백골가루부족 의술사(41-42)는 40-50 가시덤불 골짜기 가이드에서 처치합니다",
		["{item:277957}, from the Bloodscalp trolls"] = "{item:277957}, 피투성이부족 트롤에게서",
		["{npc:218230}, a cook, is caged at the compound's western edge: take his quest now and keep it, his cage key and the fighter's uniform come on the 40-50 Stranglethorn guide, when the Subchiefs and Elites are your level. Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave, and Herod's strongbox sits by the cave mouth. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use {spell:7964}. {npc:813}, an elite of 39-40, stands at the compound's north end: leave him be."] = "요리사 {npc:218230}은(는) 주둔지 서쪽 끝에 갇혀 있습니다. 지금 퀘스트를 받아 두고 보관하세요. 우리 열쇠와 투사의 제복은 부족장과 정예가 레벨에 맞을 때 40-50 가시덤불 골짜기 가이드에서 진행합니다. 머리사냥꾼은 주둔지 더 안쪽에 있고, 특전사는 주둔지 주변과 동굴 안에서 은신한 채 숨어 있으며, 헤로드의 금고는 동굴 입구 옆에 있습니다. 푸른 언덕 페이지가 떨어지면 주우세요.\n주의: 쿠르젠 특전사는 34-35레벨로 정예는 아니지만 은신한 채 나타나는 일이 많고, 죽기 직전에 {spell:7964}을(를) 사용합니다. 39-40레벨 정예인 {npc:813}은(는) 주둔지 북쪽 끝에 서 있으니 건드리지 마세요.",
		["{npc:218230}, in his cage"] = "{npc:218230}, 우리 안",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, 선술집 위층",
		["{npc:268992}, in his cage beside the third tablet"] = "{npc:268992}, 세 번째 석판 옆 우리 안",
		["{npc:4631}, on the docks"] = "{npc:4631}, 부두 위",
		["{npc:715}: the Jungle Stalkers come in 40-50"] = "{npc:715}: 줄무늬정글랩터는 40-50에서 진행",
		["{npc:773}, upstairs: this optional quest needs four {item:4278}. Mine Lesser Bloodstone Deposits in {zone:1417} with {skill:186} 75, or buy the ore at the Auction House or ask a miner friend. The kobolds do not drop it; skip this quest if you cannot get the ore."] = "{npc:773}은(는) 위층에 있습니다. 이 선택 퀘스트에는 {item:4278} 4개가 필요합니다. {zone:1417}에서 {skill:186} 75로 저급 혈석 광맥을 캐거나, 경매장에서 광석을 사거나, 채광하는 친구에게 부탁하세요. 코볼트는 이 광석을 떨어뜨리지 않습니다. 광석을 구할 수 없으면 이 퀘스트는 건너뛰세요.",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A group stop: two level 40 water elementals ambush {npc:2768}'s escort, and the Daggerspine naga in the reef are 38-40, with Sorceresses among them. Grouping up is encouraged, look for people to do it with. Skip it if you are alone.\nSouth along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "파티 구간: 40레벨 물의 정령 둘이 {npc:2768} 호위를 기습하고, 암초의 가시돋친 나가는 38-40이며 마녀도 섞여 있습니다. 파티를 권장하니 함께할 사람을 찾아보세요. 혼자라면 건너뛰세요.\n서해안을 따라 남쪽으로 고블린의 만까지 가세요. 롤로가 그 위 바위에서 망을 봅니다.",
		["A {npc:2434} (37-38) lurks stealthed on the edge of {area:271}, and few players find him. Careful: he is a level or two over you; fight him only at full health, or leave him. His contract goes to {npc:2276}. Don't wait for him: the rest of this step doesn't need him."] = "{npc:2434}(37-38)이(가) {area:271} 외곽에 은신한 채 숨어 있어 그를 찾는 플레이어는 드뭅니다. 주의: 당신보다 한두 레벨 높습니다. 생명력이 가득할 때만 싸우거나 그냥 두세요. 그의 계약서는 {npc:2276}에게 가져갑니다. 그를 기다리지는 마세요. 이 단계의 나머지는 그가 없어도 됩니다.",
		["Back out of the grate to Modera's camp on the lake shore."] = "창살 밖으로 나와 호숫가의 모데라 야영지로 돌아가십시오.",
		["Back west through {zone:1430} to {area:42}."] = "{zone:1430}을(를) 지나 서쪽으로 {area:42}까지 돌아가세요.",
		["Below ground"] = "지하",
		["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps north of the village. Leave him be."] = "주의: 비밀결사대 첩자와 암살자는 은신해 있을 수 있습니다. 암살자는 독도 겁니다.\n주의: {npc:2306}(40)은(는) 한 번에 한 곳에만 나타납니다. {area:280} 여관의 지하실, 또는 마을 북쪽의 비밀결사대 천막 야영지 중 한 곳입니다. 그는 내버려 두세요.",
		["City of Dalaran"] = "달라란 시",
		["Crushridge ogres"] = "산사태 오우거",
		["East along the road to the {area:76}. The {quest:1389} are the glowing blue crystals among the Lost Ones' tents: click them. Any {npc:254797} counts for {npc:254775}, and the Lost One Fishermen on the sanctuary's west side carry {npc:254770}'s {item:258530}. {quest:1392} walks a long path through the ruins; his cudgel starts a quest for {npc:1776}. Don't wait for him.\nCareful: Noboru is level 39, two over you here: fight him only with a friend or from level 38; otherwise let him pass."] = "길을 따라 동쪽의 {area:76}(으)로 가세요. {quest:1389}은(는) 드레노어 난민들의 천막 사이에서 빛나는 푸른 수정이니 클릭하세요. {npc:254797}은(는) 모두 {npc:254775}의 목표로 인정되며, 성역 서쪽의 드레노어 난민 낚시꾼이 {npc:254770}의 {item:258530}을(를) 가지고 있습니다. {quest:1392}은(는) 폐허를 지나는 긴 경로를 걸어 다니며, 그의 곤봉은 {npc:1776}의 퀘스트를 시작합니다. 그를 기다리지 마세요.\n주의: 노보루는 39레벨로 지금보다 두 레벨 높습니다. 친구와 함께이거나 38레벨 이상일 때만 싸우고, 아니면 그냥 보내세요.",
		["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "{quest:681}에서 동쪽으로 고원 북부를 가로지르세요. 파편은 {area:314} 북쪽, {area:333} 옆 언덕에서 반짝입니다.",
		["Fly to {area:144}"] = "{area:144}(으)로 비행",
		["Fly to {area:271}"] = "{area:271}(으)로 날아가세요",
		["Fly to {area:42}"] = "{area:42}(으)로 날아가세요",
		["Fly to {zone:1453}"] = "{zone:1453}(으)로 날아가세요",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings."] = "길을 따라 북쪽으로 {area:271}을(를) 나가 산으로 들어가세요. 산사자가 비탈을 돌아다니고, {area:280}의 비밀결사대가 인장 반지를 끼고 있습니다.",
		["Follow the road north to the draenei of the {area:657}. {npc:254775} and {npc:254770} stand beside {npc:1776}: their Lost Ones are the ones you meet in the {area:76} anyway."] = "길을 따라 북쪽의 {area:657} 드레나이에게 가세요. {npc:254775}와(과) {npc:254770}은(는) {npc:1776} 옆에 서 있습니다. 그들의 드레노어 난민은 어차피 {area:76}에서 만나게 됩니다.",
		["For your City of Dalaran run, next: the {npc:269127} wants the arcane remnants in the city thinned out and a mote from the heart of the disruption. {quest:92458} brings the {item:277507}, which opens the grate."] = "달라란 시 공략용(다음): {npc:269127}은(는) 도시의 비전 잔재를 줄이고 교란의 중심에서 티끌 하나를 가져오기를 원합니다. {quest:92458}은(는) 창살을 여는 {item:277507}을(를) 줍니다.",
		["For {npc:1356} in {zone:1455}, at the end of this guide"] = "{zone:1455}의 {npc:1356}에게, 이 가이드 마지막에",
		["For {npc:1440} in {zone:1453}: keep it"] = "{zone:1453}의 {npc:1440}에게: 보관하세요",
		["For {npc:2487} in {area:35}: keep it"] = "{area:35}의 {npc:2487}에게: 보관하세요",
		["For {npc:2542} in {area:35}: keep it"] = "{area:35}의 {npc:2542}에게: 보관하세요",
		["For {npc:2711} in {area:271}"] = "{area:271}의 {npc:2711}에게",
		["From the Syndicate camp, follow the road east over {area:1057} to {area:320}."] = "비밀결사대 야영지에서 길을 따라 동쪽으로 {area:1057}을(를) 넘어 {area:320}까지 가세요.",
		["From {npc:2712}'s camp, a short way north-east to the {object:2691}, by the shards' hill north of {area:314}. The {object:2702}, where the three keys go, stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "{npc:2712}의 야영지에서 북동쪽으로 조금 가면 {area:314} 북쪽 파편 언덕 옆에 {object:2691}이(가) 있습니다. 세 열쇠를 가져갈 {object:2702}은(는) {area:320} 서쪽에 서 있습니다.\n주의: 각 중앙 돌은 39레벨 정도의 정령 셋가량이 지키며, 처치하지 않고 돌을 클릭하면 함께 공격합니다. 서부는 떠도는 불의 정령, 외곽은 떠도는 천둥 정령, 동부는 떠도는 물의 정령입니다.",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "{zone:1455}에서 동쪽 굴을 지나 {zone:1426}을(를) 거쳐 {zone:1432}에 들어간 뒤, 길을 따라 {area:144}까지 가세요.",
		["Lost Ones: Hunters, Muckdwellers, Seers and Riftseekers all count"] = "드레노어 난민: 사냥꾼, 진흙거주자, 선견자, 균열추적자 모두 해당됩니다",
		["North out of {area:271} to the Syndicate camp on the Alterac border, west of {area:272} (Horde): its Footpads and Thieves are the Syndicate Maleb wants, and the documents lie in the camp. Then back to the road and east to Arathi.\nCareful: a few Syndicate Wizards (34-35) stand among the tents and cast from range: pull them one at a time."] = "{area:271}에서 북쪽으로 나가 {area:272}(호드) 서쪽, 알터랙 경계의 비밀결사대 야영지로 가세요. 그곳의 노상강도와 도둑이 말레브가 원하는 비밀결사대이며, 문서는 야영지에 있습니다. 그다음 길로 돌아가 동쪽 아라시로 가세요.\n주의: 비밀결사대 마술사(34-35) 몇 명이 천막 사이에 서서 원거리 주문을 시전합니다. 한 번에 하나씩 끌어오세요.",
		["North-west of Watcher Biggs, {npc:255597} (level 34) waits by the road: lead him north to the {area:657}, on your way there. Stay close to him and clear what attacks him; if he falls, abandon the quest and go on."] = "감시병 빅스 북서쪽 길가에서 {npc:255597}(34레벨)이(가) 기다립니다. 가는 길에 그를 북쪽의 {area:657}(으)로 호위하세요. 곁에 붙어 그를 공격하는 적을 처치하세요. 그가 죽으면 퀘스트를 포기하고 계속 가세요.",
		["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "마른나무껍질 계곡을 나와 북서쪽으로 가세요. {npc:2712}와(과) {npc:2713}은(는) {area:314} 바로 북쪽 언덕에 진을 치고 있습니다.",
		["Off the flight, straight to the {area:271} inn. Then {npc:2276} and {npc:2277}, in the town hall, take the Syndicate camp's quests and send you north to {area:280}."] = "비행에서 내리면 곧장 {area:271} 여관으로 가세요. 그다음 마을회관의 {npc:2276}와(과) {npc:2277}이(가) 비밀결사대 야영지 퀘스트를 받고 당신을 북쪽 {area:280}(으)로 보냅니다.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "가시덤불 골짜기에서 글루글에게 펜던트를 받은 경우에만",
		["Phizzlethorpe"] = "피즐솔프",
		["South-east along the loch to the dig site."] = "호수를 따라 남동쪽으로 발굴 현장까지 가세요.",
		["South-east through the hills: {npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley.\nCareful: {npc:2793} is level 39, a caster, one or two over you here: clear the cave mouth first, then pull him alone at full health."] = "언덕을 지나 남동쪽으로 가세요. 오우거 마법사 {npc:2793}이(가) 마른나무껍질 계곡 남쪽 끝 동굴을 차지하고 있습니다.\n주의: {npc:2793}은(는) 39레벨 주문시전자로, 이 시점의 당신보다 한두 레벨 높습니다. 동굴 입구를 먼저 정리한 뒤, 생명력이 가득할 때 그만 따로 끌어오세요.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "남서쪽으로 {area:279} 서쪽 호숫가의 키린 토 야영지로 가세요. {zone:1421} 경계를 막 넘은 곳으로, {npc:269127}이(가) 그곳에 서 있습니다. 대마법사 앤자이럼은 그 남동쪽, 돔 옆에 서 있습니다.",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "{npc:2713}이(가) {area:314}에 몰래 들어갔다 나오는 동안 곁에 있으세요. 가는 길에 호드 오크가 덤벼듭니다.\n주의: 생명력이 낮아진 오크는 도망칩니다. {npc:2713}이(가) 그들을 쫓아가 몹을 더 끌어올 수 있으니, 도망치는 적은 빨리 처치하거나 느리게 하세요.",
		["Syndicate camp"] = "비밀결사대 야영지",
		["The City of Dalaran is a dungeon for a group of five at about level 28 to 33: at your level it goes quickly. Its way in is the sewer grate in the city's western wall, by the lake, 30 yards from Modera's camp.\nInside: the Seeking Remnants, Saturated Remnants and Mana Echoes are Modera's {quest:92457}; the {item:251961} for {quest:92458} drops inside too."] = "달라란 시는 약 28~33레벨 5인 파티용 던전으로, 지금 레벨이면 빠르게 끝납니다. 입구는 호숫가, 도시 서쪽 성벽의 하수구 창살로, 모데라 야영지에서 30야드 거리입니다.\n내부: Seeking Remnant, Saturated Remnant, Mana Echo는 모데라의 {quest:92457} 대상이며, {quest:92458}의 {item:251961}도 내부에서 떨어집니다.",
		["The Crushridge ogres hold the hills north of {area:280}. Careful: Nagaz (40) stands far to the north-west by a worn wooden chest, with Syndicate guards: stay with the ogres.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and drop the knucklebones too: pull one at a time, or group up."] = "산사태 오우거는 {area:280} 북쪽 언덕을 차지하고 있습니다. 주의: 나가즈(40)가 멀리 북서쪽의 낡은 나무 상자 옆에 비밀결사대 경비병들과 함께 서 있습니다. 오우거 근처에 머무르십시오.\n산사태일족 싸움꾼, 마법사, 집행자, 전쟁광(36-39)은 정예이고, 산사태 오우거와 산사태 야수(34-35)는 정예가 아니며 손가락뼈도 떨어뜨립니다. 하나씩 끌어오거나 파티를 맺으십시오.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need {skill:186} 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "마른수염 코볼트는 {area:321}(호드) 동쪽 협곡에서 땅을 팝니다. 마을은 북쪽으로 돌아가세요. 이들은 미즈라엘의 결정 파편을 떨어뜨리지만, 크라제크의 광석은 떨어뜨리지 않습니다. 저급 혈석 광맥은 {skill:186} 75가 필요합니다. 광석 4개를 캐거나, 경매장에서 사거나, 채광하는 친구에게 부탁하세요. 광석 목표는 선택 사항입니다. 구할 수 없으면 미즈라엘 퀘스트를 계속하세요. 주의: 모든 코볼트는 생명력이 낮아지면 도움을 청하러 도망가므로(코볼트는 30%, 흙점쟁이와 채굴꾼은 15%) 더 많이 끌려올 수 있습니다.",
		["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "급사는 경비병 둘과 함께 {area:314}에서 서쪽으로 고원을 가로질러 약 24,45까지 길을 걸었다가 되돌아옵니다. 그를 만날 때까지 화살표가 서쪽으로 길을 따라갑니다. 길에서 끌어내세요.",
		["The shards lie at the far end of {area:318}."] = "파편은 {area:318}의 맨 끝에 있습니다.",
		["The western swamp"] = "서쪽 늪",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:2417} walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."] = "정예 몹입니다. 파티를 맺는 것을 권장하니 함께할 사람을 찾아보세요. {npc:2417}은(는) 40레벨 정예입니다. 대부분의 직업은 42레벨에 혼자 처치할 수 있지만, 도움이 필요할 수도 있습니다. 혼자라면 건너뛰세요. 경로에서 사냥으로 경험치를 다시 채우게 됩니다.\n{npc:2417}은(는) 화살표 지점에서 폐허를 지나 북동쪽으로 약 40,47까지 걸었다가 되돌아옵니다. 화살표 지점에 없다면 그의 경로를 따라가세요.",
		["West along the road to {area:320}."] = "길을 따라 서쪽으로 {area:320}까지 가세요.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "새끼 악어, 늪그물거미, 늪지재규어가 모두 길 주변 늪을 돌아다닙니다.",
		["from {quest:1392}: he walks a path through the ruins"] = "{quest:1392}에게서: 폐허를 지나는 길을 돌아다닙니다",
		["{item:258530}, from a {npc:757}"] = "{item:258530}, {npc:757}에게서",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: 산사태 오우거",
		["{item:3659}: the {object:1760}, beside Muckrake (40, elite): get it with a group, or abandon {quest:540}; inside"] = "{item:3659}: Muckrake(40, 정예) 옆의 {object:1760}: 파티와 함께 얻거나 {quest:540}을(를) 포기하십시오; 내부",
		["{item:6071}, the blue crystals by the tents"] = "{item:6071}, 천막 옆의 푸른 수정",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, {area:17203} 길",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, 빛의 대성당",
		["{npc:1356}: for {npc:1344} in {zone:1432}, next"] = "{npc:1356}: {zone:1432}의 {npc:1344}에게, 다음 단계",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, 성채 안 왕실 도서관",
		["{npc:1776}: {npc:255597}'s escort"] = "{npc:1776}: {npc:255597} 호위",
		["{npc:1776}: {quest:93464}, for {npc:11863} in {zone:1443}, on the {zone:1443} guide at the end of 30-40"] = "{npc:1776}: {quest:93464}, {zone:1443}의 {npc:11863}에게 전달, 30-40 마지막의 {zone:1443} 가이드에서",
		["{npc:185335}, at the same circle"] = "{npc:185335}, 같은 소환진에서",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: 아라시, {zone:1443}, 가시덤불 골짜기에서 잡을 동물 세 마리",
		["{npc:2276}: the signet rings are in {area:280}"] = "{npc:2276}: 인장 반지는 {area:280}에 있습니다",
		["{npc:2434}, if you spot him"] = "{npc:2434}, 발견한 경우",
		["{npc:2712} and {npc:2713}"] = "{npc:2712}와(과) {npc:2713}",
		["{npc:2713}'s errand"] = "{npc:2713}의 심부름",
		["{npc:2789}: {npc:2793}'s cave, west past the {object:2689}"] = "{npc:2789}: {npc:2793}의 동굴, {object:2689}을(를) 지나 서쪽",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards. Careful: on the walk out the camp's Lost One Riftseekers (37-38) and their pets, with the Lost Ones around them, turn on {npc:5391}: clear the cage and the start of his path first, stay beside him and pull every attacker onto yourself. Many players lose him the first time; if he dies, abandon the quest and take it again at his cage."] = "{npc:5391}은(는) 성역 북쪽 끝에 갇혀 있습니다. 그를 풀어주고 나가는 동안 살려두세요. 그 후 그의 금고가 길가에서 기다립니다. 주의: 나가는 길에 야영지의 길 잃은 균열추적자(37-38)와 그들의 애완동물이 주변의 길 잃은 자들과 함께 {npc:5391}을(를) 공격합니다. 먼저 우리와 그가 갈 길의 시작 부분을 정리하고, 그의 곁에 머물며 모든 공격자를 자신에게 끌어오세요. 많은 플레이어가 처음에 그를 잃습니다. 그가 죽으면 퀘스트를 포기하고 그의 우리에서 다시 받으세요.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122}이(가) 인큐버스를 당신에게 귀속시킵니다",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122}은(는) {object:2101}에 있는 {object:2164}의 지하실에서 기다립니다. 그곳 소환진에서 {item:6913}을(를) 사용하고 나타나는 서큐버스를 물리치세요. {quest:65602}을(를) 받았다면 그에게 {item:190309}도 건네고, 같은 소환진에 놓은 뒤 인큐버스를 물리치세요.",
		["{quest:651} is a group quest at this level: three Cresting Exiles (38-39) guard the {object:2691} and attack together. Grouping up is encouraged, look for people to do it with. Skip it if you are alone."] = "{quest:651}은(는) 이 레벨에서 파티 퀘스트입니다. 떠도는 물의 정령(38-39) 셋이 {object:2691}을(를) 지키며 함께 공격합니다. 파티를 권장하니 함께할 사람을 찾아보세요. 혼자라면 건너뛰세요.",
		["{quest:65602}, if you took it"] = "{quest:65602}, 받았다면",
		["{quest:92457}: the remnants and echoes, inside"] = "{quest:92457}: 잔재와 메아리, 내부",
		["{zone:1455} flight master"] = "{zone:1455} 비행 조련사",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Buzzards circle the plain to the east. Careful: the Dustbelcher Maulers, Shamans and Wyrmhunters (40-43) camp far to the south-west: leave them.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nCareful: the Stonevault Bonesnappers are 39-40 and the Shamans 40-41, a level or two over you here: pull them from the camp's edge, one at a time.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "대머리수리가 동쪽 평원 위를 맴돕니다. 주의: 먼지목도리일족 싸움꾼, 주술사, 용사냥꾼(40-43)이 멀리 남서쪽에 야영하고 있으니 무시하십시오.\n부서진 해골은 바위동굴일족 트로그 야영지 가장자리에 있습니다. 아그몬드를 죽인 {quest:739}은(는) 뼈다귀싸움꾼들 사이를 돌아다닙니다.\n주의: 바위동굴일족 뼈다귀싸움꾼은 39-40, 주술사는 40-41레벨로 지금보다 한두 레벨 높습니다. 야영지 가장자리에서 하나씩 끌어오십시오.\n주의: 먼지목도리일족 우두머리는 44-45레벨입니다. {spell:5242}와(과) {spell:1160}을(를) 사용하며, 생명력이 50% 미만이 되면 15미터 내의 아군에게 도움을 청합니다. {area:340}에서 남쪽으로 약 750미터 거리에 일곱 마리가 서 있습니다.",
		["East from the {area:1877} to {area:346}: {npc:2860} takes the scrap metal."] = "{area:1877}에서 동쪽 {area:346}(으)로 가십시오. {npc:2860}이(가) 고철을 받습니다.",
		["For {npc:4454} at the {area:2240}: the {zone:1446} guide passes him at 45, keep it"] = "{area:2240}의 {npc:4454}에게: {zone:1446} 가이드가 45레벨에 그를 지나갑니다. 보관하십시오",
		["Head back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "서쪽 길로 돌아가 남쪽으로 따라가 고개를 지나 {zone:1432}에서 {zone:1418}(으)로 가십시오. {npc:2910}와(과) {npc:2860}은(는) 발굴 현장에 나란히 야영하고 있습니다.",
		["Head north to {area:1517}'s entrance, in the north of the {zone:1418}: the chest lies just inside the cave mouth. {npc:2932} and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together."] = "{zone:1418} 북부의 {area:1517} 입구로 북쪽으로 가십시오. 상자는 동굴 입구 바로 안쪽에 있습니다. {npc:2932}와(과) 흑요석 골렘(38)이 그 옆에 서 있고 어둠괴철로단 굴착꾼(35-36)이 터널에서 일하며, 모두 정예입니다. 파티와 함께 움직이십시오.",
		["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "북동쪽 버려진 발굴 현장으로 가십시오. 보급품 상자는 먼지목도리 오우거들 사이에 있습니다.",
		["Head south to {area:345}."] = "남쪽 {area:345}(으)로 가십시오.",
		["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "서쪽 {area:1878}(으)로 가십시오. {npc:2921}은(는) 그 한가운데 기계 옆에서 일합니다.",
		["Lesser Rock Elementals"] = "하급 바위 정령",
		["Rock Elementals"] = "바위 정령",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "라이돌의 다음 심부름은 {area:1517}(으)로 가니 건너뛰십시오.",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}; every rock elemental can drop {npc:1470}'s Rock Elemental Shards. The Dustbelcher Ogres (38-39) on the {area:1878}'s west side drop {npc:2860}'s scrap. Careful: a {npc:269756}, a level 42 elite, drifts about the {area:1878}: give it a wide berth.\nCareful: the Lesser Rock Elementals are 37-39 and hit hard: fight them one at a time."] = "하급 바위 정령은 {npc:2921} 서쪽의 {area:1878}을(를) 돌아다닙니다. 모든 바위 정령이 {npc:1470}의 바위 정령 파편을 떨어뜨릴 수 있습니다. {area:1878} 서쪽의 먼지목도리 오우거(38-39)가 {npc:2860}의 금속 조각을 떨어뜨립니다. 주의: 42레벨 정예인 {npc:269756}이(가) {area:1878}을(를) 떠돌아다니니 멀리 피하십시오.\n주의: 하급 바위 정령은 37-39레벨이고 강하게 때리니 하나씩 상대하십시오.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west. Careful: a {npc:269756}, a level 42 elite, drifts about the {area:1878}: give it a wide berth."] = "바위 정령은 {npc:2921}의 남동쪽을 돌아다니고, 거대한 대머리수리와 덩치큰 바위산코요테는 그 서쪽 평원에 함께 있습니다. 주의: 42레벨 정예인 {npc:269756}이(가) {area:1878}을(를) 떠돌아다니니 멀리 피하십시오.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "부서진 해골은 오우거 바로 동쪽, 바위동굴일족 트로그 야영지 가장자리에 있습니다. 주변의 바위동굴일족 뼈다귀싸움꾼과 바위동굴일족 주술사가 조각을 떨어뜨립니다. 실성한 텔두린은 더 남쪽의 폐허가 된 야영지 옆에 앉아 있습니다.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "조개는 다음 가이드의 가시덤불 골짜기 북서 해안에 있습니다. 보관하십시오",
		["The excavation crate"] = "발굴 상자",
		["The {object:126260}"] = "{object:126260}",
		["Theldurin sits by the ruined camp south of the trogg camp. His tablet lies just inside {area:1517}'s cave mouth, beside level 38 elites: a quest for a group."] = "텔두린은 트로그 야영지 남쪽의 폐허가 된 야영지 옆에 앉아 있습니다. 그의 석판은 {area:1517} 동굴 입구 바로 안쪽, 38레벨 정예 옆에 있습니다. 파티용 퀘스트입니다.",
		["To {area:2101}"] = "{area:2101}(으)로",
		["for {npc:2786} in {zone:1455}: keep it"] = "{zone:1455}의 {npc:2786}에게: 보관하십시오",
		["{item:278402}, from the Shadowforge diggers and the Bonesnappers"] = "{item:278402}, 어둠괴철로단 채굴꾼과 뼈다귀싸움꾼에게서",
		["{item:278403}, in the Shadowforge camp"] = "{item:278403}, 어둠괴철로단 야영지에 있음",
		["{item:4630}, from the Dustbelcher Ogres"] = "{item:4630}, 먼지목도리 오우거에게서",
		["{item:7847}, if you still need one: the Buzzards east of {area:345} drop it only rarely"] = "{item:7847}, 아직 필요하다면: {area:345} 동쪽의 대머리수리는 아주 드물게 떨어뜨립니다",
		["{item:7847}: the Starving Buzzards (35-37) circling the hills north of the digsite drop it most often; leave the Giant Buzzards (39-41) of the far west"] = "{item:7847}: 발굴 현장 북쪽 언덕 위를 맴도는 굶주린 대머리수리(35-37)가 가장 자주 떨어뜨립니다. 먼 서쪽의 거대한 대머리수리(39-41)는 무시하십시오",
		["{npc:269577} of the Explorers' League camps at the foot of the pass. His artifacts drop from the Shadowforge diggers at {area:346} and the Stonevault Bonesnappers at {area:345}, and the helmet lies in the Shadowforge camp."] = "탐험가 연맹의 {npc:269577}이(가) 고개 기슭에 야영하고 있습니다. 그의 유물은 {area:346}의 어둠괴철로단 채굴꾼과 {area:345}의 바위동굴일족 뼈다귀싸움꾼에게서 떨어지며, 안전모는 어둠괴철로단 야영지에 있습니다.",
		["{npc:269577}: keep it, the {item:278404} waits for the 40-50 {zone:1418} visit"] = "{npc:269577}: 보관하세요. {item:278404}은(는) 40-50레벨 {zone:1418} 방문 때 사용합니다",
		["{npc:4618} and {npc:2817} camp in the {area:1877}, on the road between {area:1517} and {area:345}."] = "{npc:4618}와(과) {npc:2817}은(는) {area:1517}와(과) {area:345} 사이 길 위의 {area:1877}에 야영하고 있습니다.",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618}와(과) {npc:2817}은(는) {zone:1418} 한가운데 {area:1877}에 함께 야영하고 있습니다.",
} end)()
t.guides["forever/alliance/30-40/06b-desolace"] = (function() return {
		["A long trip out to Kalimdor"] = "칼림도어까지 먼 여정",
		["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s {item:213565}."] = "{npc:217590}이(가) {area:596}을(를) 기어다닙니다. {npc:217412}의 {item:213565}에 든 도구로 한 마리를 잡으십시오.",
		["Back at the coven on the way west: the Mana Eaters (37-38) on its north edge and the Mage Hunters (38-39) further in drop the brains. {npc:5760} (40, elite) walks among the Mage Hunters: pull them out to you."] = "서쪽으로 가는 길에 다시 마녀단으로: 북쪽 가장자리의 마나먹는 지옥사냥개(37-38)와 더 안쪽의 마법사 사냥개(38-39)가 뇌를 떨어뜨립니다. {npc:5760}(40, 정예)이(가) 마법사 사냥개 사이를 돌아다니니 사냥개를 끌어내십시오.",
		["Fly to Theramore"] = "테라모어 섬으로 비행",
		["Fly to {area:150}"] = "{area:150}(으)로 비행",
		["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "길을 따라 북쪽 {area:608}(으)로 가십시오. {npc:5396}은(는) 남쪽 끝에, {npc:5638}은(는) 한가운데에, {npc:1182}은(는) 북쪽에 서 있습니다.",
		["Follow the road south to {area:2407}."] = "길을 따라 남쪽 {area:2407}(으)로 가십시오.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "길을 따라 서쪽으로 {zone:1443} 북부를 가로질러 {area:2405} 폐허로 가십시오. 난파선으로 가는 길, 그곳 언덕 위에 {npc:11863}의 탑이 서 있습니다.",
		["Kodo bones, demons and lost treasure in south {zone:1443}."] = "남부 {zone:1443}의 코도 뼈, 악마, 잃어버린 보물.",
		["Maraudine centaurs"] = "마라우돈일족 켄타우로스",
		["Off the boat, walk up the pier to Baldruc, the flight master by the gate of {area:514}."] = "배에서 내려 부두를 따라 {area:514} 성문 옆의 비행 조련사 발드럭에게 올라가십시오.",
		["Rackmore's chest lies just south-east of the {object:177673}."] = "랙모어의 상자는 {object:177673} 바로 남동쪽에 있습니다.",
		["Short: about one level of quests"] = "짧음: 약 1레벨 분량의 퀘스트",
		["Stays on the main route"] = "주요 경로에 머무름",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "마라우돈일족 켄타우로스가 묘지 서쪽 {area:607}을(를) 차지하고 있으며, 모든 종류가 토템을 떨어뜨립니다.",
		["The demons gather at the {area:602} in southern {zone:1443}. Nether Maidens (37-38) hold its north-west side and drop the wings; Doomwarder Captains (38) stand at the south end and drop the blood.\nCareful: Nether Sorceresses (39-40) stand beside the Doomwarder Captains, and {npc:5760}, a level 40 elite, walks the coven's middle: pull the captains away from them. Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "악마들은 {zone:1443} 남부의 {area:602}에 모여 있습니다. 황천의 요녀(37-38)가 북서쪽을 차지하고 있으며 날개를 떨어뜨리고, 파멸의경비대 부대장(38)은 남쪽 끝에 서 있으며 혈액을 떨어뜨립니다.\n주의: 파멸의경비대 부대장 옆에는 황천의 여마법사(39-40)가 서 있고, 40레벨 정예인 {npc:5760}이(가) 마녀단 한가운데를 돌아다닙니다. 부대장을 그들에게서 멀리 끌어내십시오. 이곳 몹 대부분이 순찰 경로를 돌아다니므로 다른 몹까지 끌려오기 쉽습니다.",
		["The ghost magnets"] = "유령 유인기",
		["The next guide starts in Theramore."] = "다음 가이드는 테라모어 섬에서 시작합니다.",
		["The wrecked ship's chest lies just south-west of {npc:11863}'s tower."] = "난파선의 상자는 {npc:11863}의 탑 바로 남서쪽에 있습니다.",
		["The {area:2657}"] = "{area:2657}",
		["Then on to {zone:1434}"] = "이후 {zone:1434}(으)로",
		["Theramore flight master"] = "테라모어 섬 비행 조련사",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:6134}'s magnets draw the Magrami Spectres a few yards from the Magram Necrokhans and Corpsefeeders (45, elite) in the {area:2657}. Skip it if you are alone."] = "정예 몹입니다. 파티를 권장하니 함께할 사람을 찾으십시오. {quest:6134}의 자석은 {area:2657}에서 마그람일족 강령왕과 시체먹이(45, 정예)로부터 몇 미터 떨어진 곳으로 마그라미 유령을 끌어냅니다. 혼자라면 건너뛰십시오.",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven: the arrow leads to their western edge. Careful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields further east, with Magram Necromancers (42): pull the Ravagers to you, away from them."] = "언데드 약탈자가 마그람일족 마을 남쪽, 마녀단 동쪽의 뼈 들판을 돌아다닙니다. 화살표는 들판 서쪽 가장자리로 안내합니다. 주의: 마그람일족 강령왕과 시체먹이(45, 정예)가 마그람일족 강령술사(42)와 함께 더 동쪽의 뼈 들판을 돌아다닙니다. 약탈자를 그들에게서 멀리 끌어내십시오.",
		["Underwater"] = "물속",
		["Use the {item:15848} at its arrow, on the fields' eastern side, to draw the Magrami Spectres; the Necrokhans and Corpsefeeders (45, elite) walk close by: keep the group together."] = "들판 동쪽의 화살표 위치에서 {item:15848}을(를) 사용해 마그라미 유령을 끌어내십시오. 강령왕과 시체먹이(45, 정예)가 가까이 돌아다니니 파티와 함께 움직이십시오.",
		["escort {npc:12277} back toward the graveyard"] = "{npc:12277}을(를) 묘지 쪽으로 호위",
		["for {npc:3980} in {area:271}: keep it"] = "{area:271}의 {npc:3980}에게: 보관하십시오",
		["for {npc:5637} in {zone:1455}: keep it"] = "{zone:1455}의 {npc:5637}에게: 보관하십시오",
		["{area:144} flight master"] = "{area:144} 비행 조련사",
		["{area:598}: kill these as you meet them"] = "{area:598}: 만나는 대로 처치하십시오",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, {object:177673}에 사용",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, 칼날비늘 나가에게서 획득",
		["{item:6251}, from the Nether Maidens"] = "{item:6251}, 황천의 요녀에게서 획득",
		["{item:6252}, from the Doomwarder Captains"] = "{item:6252}, 파멸의경비대 부대장에게서 획득",
		["{npc:11863}: {quest:93464}, from Magtoor in the {zone:1435}"] = "{npc:11863}: {quest:93464}, {zone:1435}의 마그투르에게서 받음",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277}은(는) 묘지 서쪽 켄타우로스 야영지에 갇혀 있습니다. 풀어 주고 나가는 동안 살려 두십시오. 그녀는 묘지 옆에서 멈춥니다.\n주의: 스크립트로 등장하는 무리는 서로 연결되어 있고 호위 중에만 나타나므로, 미리 처치하거나 하나씩 끌어올 수 없습니다. 시작하기 전에 길의 일반 켄타우로스를 처치해 두면 도움이 됩니다.",
		["{object:177787} lies beside {object:35251}, if you didn't take it on your first {zone:1443} visit. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "첫 {zone:1443} 방문 때 받지 않았다면, {object:177787}은(는) {object:35251} 옆에 있습니다. 그의 은 열쇠는 난파선 주변의 마른집게 게가 떨어뜨리고, 황금 열쇠는 다음에 갈 북서쪽 해안의 칼날비늘 나가에게서 얻습니다.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "\"말썽꾼\" 이그나츠",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40레벨에 100골드가 있으면 탈것 타기를 배울 수 있으며, 배우면 탈것도 하나 받습니다. {npc:4732}은(는) {zone:1429} 동부 {area:88}의 {npc:384}의 말 옆에서 인간에게 가르칩니다. Forever에서는 어느 종족이든 아무 탈것 상급자에게 배울 수 있을지도 모릅니다(확인되지 않음). 수집품, 탈것 · 레벨 40에 모든 색상이 나옵니다.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "40레벨에 100골드가 있으면 탈것 타기를 배울 수 있으며, 배우면 탈것도 하나 받습니다. {npc:4753}은(는) {zone:1457}의 {npc:4730}의 표범 옆에서 나이트 엘프에게 가르칩니다. {area:17203}에서 배를 타고 {area:442}(으)로 간 뒤 {area:702}(으)로 날아가세요. Forever에서는 어느 종족이든 {zone:1429} {area:88}의 {npc:4732} 같은 아무 탈것 상급자에게 배울 수 있을지도 모릅니다(확인되지 않음). 수집품, 탈것 · 레벨 40에 모든 색상이 나옵니다.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40레벨에 100골드가 있으면 탈것 타기를 배울 수 있으며, 배우면 탈것도 하나 받습니다. {npc:4772}은(는) {area:131} 동쪽, {zone:1432}(으)로 가는 길의 {area:803}에서 {npc:1261}의 산양 옆에서 드워프에게 가르칩니다. Forever에서는 어느 종족이든 아무 탈것 상급자에게 배울 수 있을지도 모릅니다(확인되지 않음). 수집품, 탈것 · 레벨 40에 모든 색상이 나옵니다.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40레벨에 100골드가 있으면 탈것 타기를 배울 수 있으며, 배우면 탈것도 하나 받습니다. {npc:7954}은(는) {area:131} 바로 동쪽 {area:189}에서 {npc:7955}의 기계타조 옆에서 노움에게 가르칩니다. Forever에서는 어느 종족이든 아무 탈것 상급자에게 배울 수 있을지도 모릅니다(확인되지 않음). 수집품, 탈것 · 레벨 40에 모든 색상이 나옵니다.",
		["Bloodsail camp"] = "붉은해적단 야영지",
		["Bloodsail pirates: kill these as you meet them"] = "붉은해적단 해적: 만나는 대로 처치하세요",
		["Boat to {area:150}"] = "배를 타고 {area:150}(으)로",
		["Boat to {area:35}"] = "배를 타고 {area:35}(으)로",
		["Corrosive Swamp Oozes"] = "부식성 늪수액괴물",
		["Defeat the challengers and {npc:6238}"] = "도전자들과 {npc:6238} 물리치기",
		["East from the stalkers' slopes to the ruins of Zul'Mamwe: the Skullsplitter Mystics (39-40) in its northern half carry {npc:739}'s fetishes. Careful: the Witch Doctors, Berserkers and Headhunters (41-44) hold the ruins' southern half: stay north. Then north-west toward the coast: the Shadowmaw Panthers (37-38) prowl the jungle west of the ruins, often stealthed."] = "추적자 비탈에서 동쪽으로 줄맘웨 폐허로 가세요. 폐허 북쪽 절반의 백골가루부족 비술사(39-40)가 {npc:739}의 우상을 가지고 있습니다. 주의: 주술사, 광전사, 사냥꾼(41-44)이 폐허 남쪽 절반을 지키니 북쪽에 머무르세요. 그다음 북서쪽 해안 쪽으로 가세요. 그림자퓨마(37-38)가 폐허 서쪽 밀림을 배회하며, 은신해 있는 경우가 많습니다.",
		["East from the {area:99} to {area:101}: {npc:218230} is caged at its western edge. The Kurzen Subchiefs (35-36) and Elites (36-37) carry his cage key; the fighter's uniform lies in a supply crate in the compound's eastern part.\nCareful: {npc:813}, an elite of 39-40, stands at the compound's north end beside three of the Subchiefs: take the key from the Subchiefs and Elites further south and leave him be."] = "{area:99}에서 동쪽으로 {area:101}까지 가세요. {npc:218230}은(는) 그 서쪽 끝에 갇혀 있습니다. 쿠르젠 부대장(35-36)과 정예병(36-37)이 우리 열쇠를 가지고 있으며, 전사 제복은 주둔지 동쪽의 보급품 상자에 있습니다.\n주의: 39-40 정예인 {npc:813}이(가) 주둔지 북쪽 끝에 부대장 셋과 함께 서 있습니다. 열쇠는 더 남쪽의 부대장과 정예병에게서 얻고 그는 건드리지 마세요.",
		["Fly to Theramore"] = "테라모어 섬으로 비행",
		["Fly to {area:35}"] = "{area:35}(으)로 날아가기",
		["Fly to {area:42}"] = "{area:42}(으)로 날아가세요",
		["Fly to {area:442}"] = "{area:442}(으)로 비행",
		["Fly to {zone:1453}"] = "{zone:1453}로 비행",
		["Follow the road east back to Theramore. The officers are in {area:514}."] = "길을 따라 동쪽으로 테라모어에 돌아가세요. 장교들은 {area:514}에 있습니다.",
		["Follow the road south to {area:35}."] = "길을 따라 남쪽으로 {area:35}까지 가세요.",
		["For {npc:218229} in {area:35}, at the end of the jungle loop"] = "정글 순환 경로 끝에 {area:35}의 {npc:218229}에게 전달",
		["Go on north-west to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "계속 북서쪽으로 북서 해안의 만까지 가세요. 바닥에 있는 대합에 진주가 들어 있습니다. {npc:2624}이(가) 그 사이를 헤엄치며 {item:4034}을(를) 떨어뜨립니다.",
		["Gorilla hills"] = "고릴라 언덕",
		["Head east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "동쪽으로 가세요. 가는 길의 덩굴늪괴물도 평론을 떨어뜨립니다. 사원 폐허가 수면 위로 드러난 {area:74} 가장자리를 찾아보세요.",
		["Head north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale."] = "네싱워리의 야영지를 지나 북동쪽으로 간 뒤 길을 따라 북쪽으로 계곡 위쪽의 야영지까지 가세요.",
		["Head south to the giant's hut in the middle of the marsh."] = "남쪽으로 습지 한가운데의 거인 오두막으로 가십시오.",
		["Jungle Stalkers"] = "줄무늬정글랩터",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks.\nCareful: the Bloodsail Mages and Warlocks here are level 40-43 and cast from range: pull one at a time and fight with your back to the open beach."] = "터널로 마을을 나가 해안을 따라 북쪽으로 가세요. 편지는 \"꽃미남\" 던컨이 걸어다니는 해변의 붉은해적단 야영지에 있습니다.\n주의: 이곳의 붉은해적단 마법사와 흑마법사는 40-43레벨이며 멀리서 주문을 겁니다. 하나씩 끌어오고 탁 트인 해변을 등지고 싸우세요.",
		["Level 40 with 100 gold later on? {npc:4732} teaches riding at {area:88} in {zone:1429}: Collectibles, Mounts · Level 40 has the trip."] = "나중에 40레벨에 100골드가 있습니까? {npc:4732}이(가) {zone:1429}의 {area:88}에서 탈것 타기를 가르칩니다. 수집품, 탈것 · 레벨 40에 가는 길이 있습니다.",
		["Mirefin murlocs"] = "진흙아가미멀록",
		["North-east from the bay toward Nesingwary's camp: {npc:729}, the great tiger (37), lairs on the hilltop just south-west of the camp."] = "만에서 북동쪽으로 네싱워리의 야영지 쪽으로 가세요. 거대한 호랑이 {npc:729}(37)은(는) 야영지 바로 남서쪽 언덕 꼭대기에 있습니다.",
		["On the way back east, the Corrosive Swamp Oozes (38-40) creep through the marsh south of the road, between the middle of the marsh and Theramore: one of them carries Jameson's training sword. Careful: Elder Daggermaws (48-49) lurk in the water among them, and the larger Bubbling Swamp Oozes (39-40) are elite: leave both alone."] = "동쪽으로 돌아가는 길에, 부식성 늪수액괴물(38-40)이 습지 한가운데와 테라모어 섬 사이, 길 남쪽 습지를 기어 다닙니다. 그중 하나가 제임슨의 훈련용 검을 지니고 있습니다. 주의: 늙은 단검턱(48-49)이 그 사이 물속에 숨어 있고, 더 큰 부글거리는 늪수액괴물(39-40)은 정예입니다. 둘 다 건드리지 마십시오.",
		["Paladin: {quest:1661}"] = "성기사: {quest:1661}",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "탈것 타기와 돌풍타조: 제프라스 섬 {area:16638}의 {area:17684}에 있는 {npc:265756}.",
		["Riding at 40"] = "40레벨 탈것 타기",
		["Seahorn's next errand goes back to Arathi: skip it."] = "시혼의 다음 심부름은 아라시로 돌아갑니다. 건너뛰세요.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "이그나츠는 오두막 서쪽, {area:504} 아래 습지에서 기다립니다. 그를 늪콩 잎사귀가 있는 곳으로 데려가며 늪의 짐승들이 그를 공격하지 못하게 막으세요.",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house. Jarl wants three {quest:1218}: if you passed {npc:4897}, buy them from her in Theramore first."] = "길을 따라 북쪽의 폐허가 된 오두막으로 가세요. 자를은 그 옆 판잣집에 살고, 흐트러진 흙은 집 모퉁이에 있습니다. 자를은 {quest:1218} 세 개를 원합니다. {npc:4897}을(를) 지나쳤다면 먼저 테라모어에서 그녀에게 사세요.",
		["The Jungle Stalkers roam the slopes west of the mine."] = "밀림 추적자가 광산 서쪽 비탈을 돌아다닙니다.",
		["The Mirefin murlocs crowd the north coast past {area:497}."] = "진흙아가미멀록은 {area:497} 너머 북쪽 해안에 모여 있습니다.",
		["The Silt Crawlers (40-41) crowd the north end of the eastern shore, and the driftwood washes up along it from there.\nCareful: the big Monstrous Crawlers (43-44) further south on the shore are over you: take the legs at the north end and pick up the driftwood without pulling them."] = "늪지게(40-41)는 동쪽 해안 북쪽 끝에 모여 있고, 유목은 거기서부터 해안을 따라 떠밀려 옵니다.\n주의: 해안 더 남쪽의 큰 괴물게(43-44)는 레벨이 높습니다. 다리는 북쪽 끝에서 모으고, 괴물게를 끌지 않도록 유목을 주우세요.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes."] = "불탄 여관은 서쪽 길, {zone:1413} 방향에 있습니다. 경비병의 휘장은 잿더미 속에 있습니다.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "탈영병들은 {npc:4503}의 오두막 서쪽, 길 남쪽에 진을 치고 있습니다.",
		["The north-west coast"] = "북서쪽 해안",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "두루마리는 빅스 북쪽 습지에 있습니다. 그 북쪽의 늪괴물이 카드가의 평론을 떨어뜨릴 수 있습니다.",
		["The sunken temple"] = "가라앉은 사원",
		["Theramore"] = "테라모어",
		["Theramore flight master"] = "테라모어 섬 비행 조련사",
		["Upstairs"] = "위층",
		["Warlock: {quest:4488}"] = "흑마법사: {quest:4488}",
		["Zul'Mamwe's Mystics and the Shadowmaw Panthers"] = "줄맘웨의 비술사와 그림자퓨마",
		["for {npc:5635} at {area:348}: keep it"] = "{area:348}의 {npc:5635}에게 줄 것: 보관하세요",
		["for {npc:770} at the {area:99}, on the northern loop"] = "북쪽 순환 경로에서 {area:99}의 {npc:770}에게",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "{item:3853}(대장장이 제작품)을 가지고 있을 때만",
		["with the spices from Theramore"] = "테라모어에서 산 향신료를 가지고",
		["{area:702} flight master"] = "{area:702} 비행 조련사",
		["{item:216616}, from the Subchiefs (or the Elites)"] = "{item:216616}, 부대장(또는 정예병)에게서 획득",
		["{item:2466}, from the Skullsplitter Mystics"] = "{item:2466}, 백골가루부족 비술사에게서 획득",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, \"늪지눈알\" 자를에게 줄 것",
		["{item:5938}, from the Silt Crawlers"] = "{item:5938}, 늪지게에게서",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141}은(는) {object:2169}에서 요리하고, {npc:5384}은(는) {object:28027}에 있습니다.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: 다른 색상, 20골드",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, {object:2117}의 왕실 도서관",
		["{npc:218230}, back at his cage on the way out"] = "{npc:218230}, 나가는 길에 그의 우리에서",
		["{npc:218230}, in his cage, if you didn't take it on the 30-40 loop"] = "{npc:218230}, 우리 안: 30-40 경로에서 수락하지 않았다면",
		["{npc:2486}'s Stranglethorn Fever ({npc:1514}) waits for the level-48 {area:35} stop: leave it for now."] = "{npc:2486}의 가시덤불 열병({npc:1514})은 48레벨 {area:35} 방문 때 처리합니다. 지금은 남겨 두세요.",
		["{npc:2487}, top floor: {quest:669}, if you did {area:327} with a group"] = "{npc:2487}, 꼭대기 층: {quest:669}, {area:327}을(를) 파티로 했다면",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624}은(는) 북쪽 순환 경로 중 북서쪽 해안 앞바다에서 헤엄칩니다",
		["{npc:271167}: {quest:98233}, from the oozes on the way back east"] = "{npc:271167}: {quest:98233}, 동쪽으로 돌아가는 길의 수액괴물에게서 획득",
		["{npc:384}: other colours, 20g"] = "{npc:384}: 다른 색상, 20골드",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, {object:2164} 안: 다음 가이드 끝에 {area:392}의 {npc:6251}이(가) 받습니다",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: 다른 색상, 20골드",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\n{npc:4967} and {npc:4968} wait beside the tower: once he yields, hand in to both on the spot."] = "{npc:4966}은(는) 탈영병 몇 명과 함께 탑을 지키고 있습니다. 그가 당신에게 덤벼드니 굴복할 때까지 때리세요.\n주의: 헨델에게는 경비병 둘이 있어 그가 적대적으로 변하면 전투에 합류합니다. 그가 항복하면 경비병들은 달아납니다.\n{npc:4967}와(과) {npc:4968}은(는) 탑 옆에서 기다립니다. 그가 굴복하면 그 자리에서 두 사람 모두에게 제출하세요.",
		["{npc:4967}, at the tower"] = "{npc:4967}, 탑에서",
		["{npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:2786} in the {object:32383}."] = "{npc:5637}은(는) {object:32356} 옆 개척자 연맹 전당에, {npc:2786}은(는) {object:32383}에 있습니다.",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, 빛의 대성당 안",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236}은(는) 다음으로 바람의감시자(1791)를 줍니다. 끝에 정예가 나오는 소용돌이 무기 퀘스트 연계는 전사 직업 가이드 소용돌이 무기에 있습니다.",
		["{npc:718}, beside him"] = "{npc:718}, 그의 옆",
		["{npc:739}: the {area:301} report bundle for {npc:2277} in {area:271}, on the {zone:1418} & {zone:1425} guide: keep it"] = "{npc:739}: {zone:1418} & {zone:1425} 가이드에서 {area:271}의 {npc:2277}에게 가져갈 {area:301} 보고서 꾸러미입니다. 보관하세요",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: {zone:1446}의 {quest:2864}에게 줄 것, 보관하세요",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: 다른 색상, 20골드",
		["{quest:1218}: {npc:4897} in Theramore, if you left without them"] = "{quest:1218}: 받지 않고 떠났다면 테라모어 섬의 {npc:4897}",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260}은(는) 여관 근처에 서 있습니다. 몇 걸음 남쪽의 거래 물품 상인 {npc:4897}이(가) 자를이 원하는 향신료를 팝니다.",
		["{zone:1453} has no shaman trainer"] = "{zone:1453}에는 주술사 상급자가 없습니다",
} end)()
t.guides["forever/alliance/40-50/01b-riverglades"] = (function() return {
		["About 90 quests in Forever's new zone, from {area:16724}: the level for its port and Western Front."] = "Forever의 새 지역에서 약 90개 퀘스트, {area:16724}에서 시작: 항구와 서부 전선을 위한 레벨입니다.",
		["Back east along the road to {area:16744}."] = "길을 따라 동쪽 {area:16744}으로 돌아가세요.",
		["Back east through the town to Elbrim's farm: the doll and the locket are in the burnt farmhouse beside it."] = "마을을 지나 다시 동쪽 엘브림의 농장으로 가십시오. 인형과 목걸이는 그 옆의 불탄 농가에 있습니다.",
		["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "해안을 따라 북쪽으로 돌아가십시오. 게들에게 가는 길에 부두에서 멀록 퀘스트와 가죽 퀘스트를 제출하십시오.",
		["Back past {area:16744} and south to the Holmsbys' farm by the river."] = "{area:16744}을(를) 다시 지나 남쪽 강가의 홈스비 농장으로 가십시오.",
		["Back south-west along the river: kill the Mudfin Warriors and Oracles on the banks for {npc:258317} (they drop {npc:256438}'s heads) and the {npc:258588} in the shallows for the shells. {npc:258935}, one of {npc:256438}'s lumberjacks, is stuck on the bank just north-west of the murlocs; {npc:259049}'s hat lies on the riverbank among them; the fresh manure is in the fields of {area:16735}, between the river and the farm. {npc:263380}, an elite (level 42), prowls the river: if he comes your way, back off and let him pass."] = "강을 따라 남서쪽으로 돌아가십시오: {npc:258317}을(를) 위해 강둑의 진흙지느러미 전사와 진흙지느러미 점쟁이를 처치하고({npc:256438}의 머리를 떨어뜨립니다), 껍데기를 얻으려면 얕은 물의 {npc:258588}을(를) 처치하십시오. {npc:256438}의 벌목꾼 중 하나인 {npc:258935}은(는) 멀록들 바로 북서쪽 강둑에 갇혀 있습니다. {npc:259049}의 모자는 멀록들 사이 강둑에 있고, 신선한 거름은 강과 농장 사이 {area:16735}의 들판에 있습니다. 정예 {npc:263380}(42레벨)이(가) 강을 배회합니다: 다가오면 물러나서 지나가게 두십시오.",
		["Back through the port"] = "항구를 거쳐 돌아가기",
		["Back to the port, from the north pier west through the docks."] = "북쪽 부두에서 서쪽으로 선착장을 지나 항구로 돌아가십시오.",
		["Back to the port."] = "항구로 돌아가십시오.",
		["Back to {area:16724}"] = "{area:16724}(으)로 귀환",
		["Coyote pelts"] = "코요테 가죽",
		["Down to the port."] = "항구로 내려가십시오.",
		["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "절벽을 따라 동쪽으로 해적 야영지 맨 끝까지 가십시오. {npc:260390}이(가) 물가에, 그 옆에 {npc:260391}이(가) 있습니다.",
		["East along the road towards {area:16724}: hand {npc:258317} his murlocs as you pass {area:16725}."] = "길을 따라 동쪽 {area:16724} 쪽으로 가십시오: {area:16725}을(를) 지나며 {npc:258317}에게 멀록을 넘겨주십시오.",
		["East down the road to {area:16727}, the goblins' harbour. {npc:255897} keeps a stall at the west end of the docks; {npc:263120}, {npc:255894} and {npc:259962} are at the inn, and {npc:259961} works the north pier. Zizplink's drink needs three things the port's traders sell: the chum from {npc:260487}, the degreaser and the old poison from {npc:260565} and {npc:260560}, by {npc:255897}'s stall."] = "길을 따라 동쪽, 고블린 항구인 {area:16727}(으)로 내려가십시오. {npc:255897}은(는) 부두 서쪽 끝에 노점을 차렸고, {npc:263120}, {npc:255894}, {npc:259962}은(는) 여관에, {npc:259961}은(는) 북쪽 부두에서 일합니다. 지즈플링크의 음료에는 항구 상인들이 파는 세 가지가 필요합니다. {npc:260487}의 미끼, 그리고 {npc:255897}의 노점 옆에 있는 {npc:260565}와(과) {npc:260560}의 탈지제와 오래된 독극물입니다.",
		["Finish the {item:268632}"] = "{item:268632} 마저 모으기",
		["Fly from {zone:1455} to {area:69} in Redridge, then follow the road north out of town and up through {area:2417}: it comes down into the western {zone:2548} by the {area:16737}."] = "{zone:1455}에서 붉은마루 산맥의 {area:69}까지 날아간 뒤, 길을 따라 마을 북쪽으로 나가 {area:2417}을 넘으세요. 길은 {area:16737} 옆 {zone:2548} 서부로 내려옵니다.",
		["Fly to {area:144}"] = "{area:144}(으)로 비행",
		["Follow the road east to {area:16744}, the Alliance outpost above the river. The gnolls you passed on the way in are Captain Dalton's job: you go back for them after the lumber camp."] = "길을 따라 동쪽으로 강 위의 얼라이언스 전초기지인 {area:16744}까지 가세요. 오는 길에 지나친 놀은 달튼 대장의 일입니다. 벌목장 다음에 처치하러 돌아옵니다.",
		["Free him, then get him out: {npc:259057} fights his way out of {area:16726}, and you keep the ogres off him. If he falls, take the quest from him again."] = "그를 풀어 준 뒤 데리고 나가십시오. {npc:259057}이(가) 싸우며 {area:16726}을(를) 빠져나가는 동안 오우거가 그를 공격하지 못하게 막으십시오. 그가 쓰러지면 퀘스트를 다시 수락하십시오.",
		["From the inn: {npc:260070} on the way in, then {npc:257558} and {npc:257591} in the keep."] = "여관에서: 들어가는 길에 {npc:260070}, 이어서 성채 안의 {npc:257558}와(과) {npc:257591}.",
		["Holmsby farm"] = "홈스비 농장",
		["Into the {zone:2548}"] = "{zone:2548}으로",
		["Leave {zone:1453}"] = "{zone:1453} 떠나기",
		["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42), Komuk (a Horde elite, 45) and {npc:263380} (elite, 42) range over the zone's wilds: take your beasts away from them."] = "{zone:2548}의 야수 대부분이 {npc:260231}에게 줄 {item:268632}을(를) 떨어뜨립니다. 이 해안의 해안 게와 해적 서쪽 능선의 멧돼지가 좋습니다.\n주의: {npc:257001}(정예, 42), 코무크(호드 정예, 45), {npc:263380}(정예, 42)이(가) 지역의 야생을 돌아다닙니다. 이들에게서 멀리 떨어져 사냥하십시오.",
		["No class trainer stands in the {zone:2548}, and the {zone:1418} & {zone:1425} guide passes none: {npc:257087} flies to {zone:1453}, where you train before you go on."] = "{zone:2548}에는 직업 상급자가 없고, {zone:1418} & {zone:1425} 가이드도 상급자를 거치지 않습니다: {npc:257087}을(를) 통해 {zone:1453}(으)로 날아가서 계속 가기 전에 수련하십시오.",
		["No class trainer stands in the {zone:2548}: train here in {zone:1453} before you fly on."] = "{zone:2548}에는 직업 상급자가 없습니다: 계속 날아가기 전에 이곳 {zone:1453}에서 수련하십시오.",
		["No flight path to {area:144} yet: go to {zone:1455} (by the {area:2257} from {zone:1453}), ride out of its gates east through {zone:1426} and the tunnel into {zone:1432}, and on along the road to {area:144}."] = "아직 {area:144}(으)로 가는 비행 경로가 없다면: {zone:1453}에서 {area:2257}을(를) 타고 {zone:1455}(으)로 간 뒤, 성문을 나와 동쪽으로 {zone:1426}을(를) 지나 터널을 통해 {zone:1432}(으)로 들어가서 길을 따라 {area:144}까지 가십시오.",
		["No shaman trainer stands in the {zone:2548} or in {zone:1453}, and the {zone:1418} & {zone:1425} guide passes none: fly to {area:1537} and train there; {area:144} is a short flight on."] = "{zone:2548}과(와) {zone:1453}에는 주술사 상급자가 없고, {zone:1418} & {zone:1425} 가이드도 상급자를 거치지 않습니다: {area:1537}(으)로 날아가서 수련하십시오. {area:144}은(는) 거기서 조금만 더 날아가면 됩니다.",
		["North along the beach from the docks: the crawlers drop the meat for {npc:259962} and the spittle for Zizplink, and their entrails count for {npc:260231}. {npc:260235}, a big crab, scuttles along the rocks east of the docks. {npc:259758}, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."] = "부두에서 해변을 따라 북쪽으로 가십시오. 게들은 {npc:259962}에게 줄 고기와 지즈플링크에게 줄 침을 떨어뜨리고, 그 내장은 {npc:260231}의 퀘스트에 포함됩니다. 큰 게인 {npc:260235}은(는) 부두 동쪽 바위를 따라 돌아다닙니다. 49레벨 희귀 정예 {npc:259758}이(가) 부두에서 해적 야영지까지 이 해안을 배회합니다. 보이면 멀리 피하십시오.",
		["North along the coast from the port: the Eastsea raiders and bombardiers have dug in on the slopes west of the buccaneers' camp, among their powder kegs. They stand close together: pull them one at a time. {npc:259758}, a rare elite of level 49, roams these cliffs and the beach below: if you see him, keep well away."] = "항구에서 해안을 따라 북쪽으로: 동해 약탈자와 폭격수가 해적 야영지 서쪽 비탈의 화약통 사이에 자리 잡고 있습니다. 서로 붙어 있으니 하나씩 끌어내십시오. 49레벨 희귀 정예 {npc:259758}이(가) 이 절벽과 아래 해변을 돌아다닙니다. 보이면 멀리 피하십시오.",
		["North of the camps the cult works ogre miners in a mine, driven by the Twilight Subjugators.\nCareful: Twilight Enforcers (elites, level 45) walk past the mine's mouth on their way through the camps. Wait for one to pass before you go in, and pull the miners and Subjugators back out to you."] = "야영지 북쪽 광산에서 교단이 황혼의 정복자를 시켜 오우거 광부들을 부리고 있습니다.\n주의: 황혼의 집행자(정예, 45레벨)가 야영지를 오가며 광산 입구를 지나갑니다. 지나간 뒤에 들어가고, 광부와 정복자는 밖으로 끌어내십시오.",
		["North past {area:16729}: fill {npc:262031}'s phial in the marsh water north-east of the tower."] = "북쪽으로 {area:16729}을(를) 지나 탑 북동쪽 습지 물에 {npc:262031}의 약병을 채우십시오.",
		["North up the long valley towards {area:16685}: {npc:258023} holds a small camp below the Twilight cult's fortress."] = "긴 골짜기를 따라 북쪽 {area:16685}(으)로 가십시오. {npc:258023}은(는) 황혼의 교단 요새 아래 작은 야영지에 있습니다.",
		["North up the road to the lumber camp."] = "길을 따라 북쪽의 벌목장으로 가십시오.",
		["North up the road to the lumber camp. {npc:256438} runs it; his third job, the saplings, comes once his plant food is in."] = "길을 따라 북쪽 벌목장으로 가세요. {npc:256438}이(가) 운영합니다. 세 번째 일인 묘목은 식물 비료를 건넨 뒤에 나옵니다.",
		["North up the track towards {area:16729}: the foreman's crate lies by the road."] = "길을 따라 북쪽 {area:16729} 방향으로: 십장의 상자가 길가에 있습니다.",
		["North-east across the fields to {area:16725}: {npc:258317} wants the Mudfin murlocs on the river thinned out, the same murlocs whose heads {npc:256438} needs, so one pass along the river does both."] = "들판을 가로질러 북동쪽 {area:16725}(으)로 가십시오: {npc:258317}은(는) 강가의 진흙지느러미 멀록 수를 줄여 달라고 합니다. {npc:256438}에게 필요한 머리도 같은 멀록에게서 나오므로, 강을 따라 한 번만 돌면 둘 다 끝납니다.",
		["North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. {npc:259758} walks the camp too: keep an eye out for him."] = "해안을 따라 북동쪽, 절벽 위 해적 야영지로 가십시오. 해적과 머스킷병이 밀수품을 지니고 있습니다. {npc:259758}도 야영지를 돌아다니니 주의하십시오.",
		["North-east of Elbrim's farm, the Horde drills its trainees in the fields north of {area:16743}. Stay north of the fort: its guards are far above your level. The supply crates lie around the drill grounds. Three elites work this ground: {npc:263071} (42) walks among the trainees, {npc:263615} (42) lurks at the north end, and Komuk (45), a Horde elite, patrols the hills to the east; give each of them room.\nCareful: Rog'mar Grunts (55) guard the fort's north wall, around 59,39 to 61,41. Leave the crates and trainees by the wall and take the ones further north, around 57-61,34-37."] = "엘브림의 농장 북동쪽, {area:16743} 북쪽 들판에서 호드가 훈련병들을 훈련시킵니다. 요새 북쪽에 머무르십시오. 요새 경비병은 당신보다 레벨이 훨씬 높습니다. 보급품 상자는 훈련장 곳곳에 있습니다. 이곳에는 정예 셋이 있습니다. {npc:263071}(42)은(는) 훈련병들 사이를 걸어 다니고, {npc:263615}(42)은(는) 북쪽 끝에 숨어 있으며, 호드 정예 코무크(45)는 동쪽 언덕을 순찰합니다. 모두 거리를 두십시오.\n주의: 로그마르 그런트(55)가 59,39에서 61,41 부근 요새 북쪽 성벽을 지킵니다. 성벽 근처의 상자와 훈련병은 두고, 더 북쪽인 57-61,34-37 부근의 것을 노리십시오.",
		["North-east to {npc:263367}'s workshop. {npc:263367}'s stress test is a fight with his G45-B4G beside the workshop: hand the quest in once it's beaten."] = "북동쪽 {npc:263367}의 작업장으로 가십시오. {npc:263367}의 스트레스 테스트는 작업장 옆의 G45-B4G와 싸우는 것입니다. 쓰러뜨리면 퀘스트를 제출하십시오.",
		["North-west to {area:16726}, the ogres' town. Its ogres side with the Horde and attack you on sight, and Clugfist on his hill in the middle is an elite (level 50): keep to the town's north-eastern edge, where {npc:259057} hides."] = "북서쪽의 오우거 마을 {area:16726}(으)로 가십시오. 이곳 오우거는 호드 편이라 보는 즉시 공격하며, 한가운데 언덕의 클러그피스트는 정예(50레벨)입니다. {npc:259057}이(가) 숨어 있는 마을 북동쪽 가장자리로 다니십시오.",
		["On east along the road to {area:16724}. {npc:257087}, the gryphon master, stands at its western gate; {npc:260070} and {npc:260080} are on the way in, {npc:263613} tends the wounded by the barracks, {npc:257558} and {npc:257591} wait in the keep at the east end, and the inn is in the south of the walls."] = "길을 따라 계속 동쪽 {area:16724}(으)로 가십시오. 그리폰 조련사 {npc:257087}은(는) 서쪽 문에 서 있고, {npc:260070}와(과) {npc:260080}은(는) 들어가는 길에 있습니다. {npc:263613}은(는) 병영 옆에서 부상자를 돌보고, {npc:257558}와(과) {npc:257591}은(는) 동쪽 끝 성채 안에서 기다립니다. 여관은 성벽 안 남쪽에 있습니다.",
		["One of Benjy's horses ran north up the river, past the farm. Give it the feed, then lead it home."] = "벤지의 말 한 마리가 농장을 지나 강을 따라 북쪽으로 달아났습니다. 먹이를 준 뒤 집으로 데려가십시오.",
		["Rotflesh Mushrooms"] = "부패살점 버섯",
		["Saplings"] = "묘목",
		["Search around the stables south of the farmhouse for the horses' tracks; the bundles of hay lie around the farm."] = "농가 남쪽 마구간 주변에서 말 발자국을 찾으십시오. 건초 더미는 농장 곳곳에 있습니다.",
		["South across the plains to {area:16724}: {npc:257591} and {npc:257558} stand together in the keep at the east end, {npc:257591} first, her news is what Brant's next orders wait on. With {area:16723} saved, {npc:263089} by the orchard and {npc:263613} by the barracks have work for you too."] = "평원을 건너 남쪽 {area:16724}(으)로 가십시오. {npc:257591}와(과) {npc:257558}은(는) 동쪽 끝 성채에 함께 있습니다. {npc:257591}부터 만나십시오. 그녀의 소식이 있어야 브랜트의 다음 명령이 나옵니다. {area:16723}을(를) 구했으니 과수원 옆의 {npc:263089}와(과) 막사 옆의 {npc:263613}도 일을 줍니다.",
		["South back to {area:16724}."] = "남쪽 {area:16724}(으)로 돌아가십시오.",
		["South-east out of the hills towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. {npc:259758} wanders down to this beach too."] = "언덕에서 남동쪽 항구 쪽으로 나가십시오. 부두 북쪽 해변의 해안 게가 내장을 가장 빨리 모으는 방법입니다. {npc:259758}도 이 해변까지 내려와 돌아다닙니다.",
		["South-east, round {area:16743}'s east side, to {npc:263367}'s workshop on the hill. Komuk and the {area:16726} ogres walk the road east of the fort: let them pass before you cross it."] = "남동쪽으로 {area:16743}의 동쪽을 돌아 언덕 위 {npc:263367}의 작업장으로 가십시오. 코무크와 {area:16726} 오우거들이 요새 동쪽 길을 걸어 다니니, 지나갈 때까지 기다렸다 길을 건너십시오.",
		["South-west across the plains to {area:16724}: {npc:257558} in the keep at the east end."] = "남서쪽으로 평원을 가로질러 {area:16724}(으)로 가십시오. {npc:257558}은(는) 동쪽 끝 성채에 있습니다.",
		["South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts {quest:95260} for {npc:260231} at the docks."] = "항구에서 해안을 따라 남서쪽으로 가십시오. 바닷물 멀록이 해변에 진을 치고 있습니다. 가는 길에 길가에 칠한 가죽이 펼쳐져 있는데, 부두의 {npc:260231}을(를) 위한 {quest:95260}이(가) 시작됩니다.",
		["South-west past {area:16744}: {npc:262399}, a prospector, has camped by the Cinderscale dragonkin's hollow."] = "{area:16744}을(를) 지나 남서쪽으로 가십시오: 탐광꾼 {npc:262399}이(가) 잿빛비늘 용족의 분지 옆에 야영하고 있습니다.",
		["The Cinderscale hollow"] = "잿빛비늘 분지",
		["The Eastsea pirates"] = "동부해 해적",
		["The Plains Coyotes roam west and south-west of the keep, towards {area:16725}."] = "평원 코요테는 성채 서쪽과 남서쪽, {area:16725} 방향으로 돌아다닙니다.",
		["The Rog'mar Poachers hunt the plains north of the tower; the Wildplains lions roam among them. A picked carcass lies in the grass east of the tower: its skull starts {quest:95983}.\nCareful: {npc:263380}, an elite (level 42), hunts along the river west of the plains: keep an eye on the riverbank."] = "로그마르 밀렵꾼은 탑 북쪽 평원에서 사냥하고, 그 사이로 들평원 사자가 돌아다닙니다. 탑 동쪽 풀밭에 뼈만 남은 사체가 있습니다: 그 두개골로 {quest:95983}이(가) 시작됩니다.\n주의: 정예(42레벨)인 {npc:263380}이(가) 평원 서쪽 강을 따라 사냥합니다: 강변을 잘 살피십시오.",
		["The Roving Tallstriders graze the meadows south-west of the workshop; further south-west the marsh bubbles with gas: fill the vials at the vents."] = "떠도는 타조는 작업장 남서쪽 초원에서 풀을 뜯습니다. 더 남서쪽 습지에는 가스가 끓어오르니, 분출구에서 약병을 채우십시오.",
		["The Stranglethorn guide leaves Dwarves and Gnomes at their riding trainer in {zone:1426}: ride back west into {zone:1455}, where the flight to {area:69} leaves from the gryphon master."] = "가시덤불 골짜기 가이드는 드워프와 노움을 {zone:1426}의 탈것 상급자에게서 끝냅니다. 서쪽으로 {zone:1455}에 돌아가면 그리폰 조련사에게서 {area:69}행 비행편을 탈 수 있습니다.",
		["The Twilight camps"] = "황혼의 야영지",
		["The Twilight cult"] = "황혼의 교단",
		["The cathedral"] = "대성당",
		["The coyote den"] = "코요테 굴",
		["The coyotes den in the hills south of the farm: {npc:258522}, the big dark one, sits at the back of it; the Plains Coyotes around it drop the pelts."] = "코요테 굴은 농장 남쪽 언덕에 있습니다: 크고 어두운 색의 {npc:258522}이(가) 굴 안쪽에 있고, 주변의 평원 코요테가 가죽을 떨어뜨립니다.",
		["The crawlers and {npc:260235}"] = "게와 {npc:260235}",
		["The cult's camps fill the valley north and west of Riftan. Free the captive Farholde Scouts as you find them, and kill a {npc:258652} for {npc:257591}: her soulstone takes it. Twilight Enforcers (elites, level 45) patrol through the camps: watch where they walk before each pull. {npc:256881} and {npc:256891} (elites, 46) hold the fortress at the valley's head: pull the cultists away from them."] = "교단의 야영지가 리프탄 북쪽과 서쪽 골짜기를 채우고 있습니다. 붙잡힌 파홀드 정찰병을 보이는 대로 풀어 주고, {npc:257591}을(를) 위해 {npc:258652}을(를) 처치하십시오. 그녀의 영혼석이 그것을 담습니다. 황혼의 집행자(정예, 45레벨)가 야영지를 순찰하니 끌어오기 전마다 이동 경로를 확인하십시오. {npc:256881}와(과) {npc:256891}(정예, 46)이(가) 골짜기 끝의 요새를 지키고 있으니 교단원을 그들에게서 떨어뜨려 끌어내십시오.",
		["The cultists fill the streets and fields of {area:16723}. Start at the ritual circles in the middle (fill Claire's catalyst there), work west through the burnt houses to the edge of town, then back north-east to the loose soil west of Elbrim's farm: bury the {item:266148} the Twilight Raiders drop there. The charms, pages and finger bones drop from the cultists.\nKeep the {item:4338} they drop: {npc:263613} in {area:16724} asks for twenty when you are back there. Now and then a cultist drops the {quest:94885}: right-click it to start the quest.\nCareful: {npc:256899}, an elite ogre (level 41), walks the western streets of {area:16723}, around 44-47,47-52. Pull the cultists out towards you and let him pass; players died here more than anywhere else in the zone.\n{npc:263380}, the river's elite (level 42), can wander up from the south-western fields: let him pass."] = "교단원들이 {area:16723}의 거리와 들판을 메우고 있습니다. 한가운데 의식의 원에서 시작해(거기서 클레어의 촉매를 채우십시오), 불탄 집들을 지나 서쪽 마을 끝까지 간 뒤, 북동쪽 엘브림 농장 서쪽의 무른 흙으로 돌아오십시오: 황혼의 약탈자가 떨어뜨리는 {item:266148}을(를) 그곳에 묻으십시오. 부적, 책장, 손가락뼈는 교단원에게서 나옵니다.\n교단원이 떨어뜨리는 {item:4338}은(는) 보관하세요: {area:16724}의 {npc:263613}이(가) 돌아가면 20개를 요구합니다. 가끔 교단원이 {quest:94885}을(를) 떨어뜨립니다: 우클릭하여 퀘스트를 시작하십시오.\n주의: 정예 오우거 {npc:256899}(41레벨)이(가) {area:16723} 서쪽 거리 44-47,47-52 부근을 돌아다닙니다. 교단원을 끌어내고 그가 지나가게 두십시오. 이 지역에서 플레이어가 가장 많이 죽은 곳입니다.\n강의 정예 {npc:263380}(42레벨)이(가) 남서쪽 들판에서 올라올 수 있습니다: 지나가게 두십시오.",
		["The lost horse"] = "잃어버린 말",
		["The meadows"] = "초원",
		["The murlocs, south-west"] = "남서쪽의 멀록",
		["The next guide starts in the {zone:1418}, south of {zone:1432}: fly to {area:144}."] = "다음 가이드는 {zone:1432} 남쪽의 {zone:1418}에서 시작합니다: {area:144}(으)로 날아가십시오.",
		["The next guide starts in the {zone:1418}, south of {zone:1432}: fly to {area:144}. {zone:1453}'s gryphon master stands in the {object:2096}."] = "다음 가이드는 {zone:1432} 남쪽의 {zone:1418}에서 시작합니다: {area:144}(으)로 날아가십시오. {zone:1453}의 그리폰 조련사는 {object:2096}에 있습니다.",
		["The ogre mine"] = "오우거 광산",
		["The pirates' second wave"] = "해적의 두 번째 무리",
		["The pirates' ships"] = "해적선",
		["The plains"] = "평원",
		["The stables"] = "마구간",
		["The tallstriders and the marsh"] = "타조와 습지",
		["The western {zone:2548}"] = "{zone:2548} 서부",
		["The whelps nest all over the hollow; the warriors (level 41-42) guard its back, by the {item:271611}. Scaldaron, a rare elite drake, can be up here too: leave him be unless you have a group."] = "새끼용은 분지 곳곳에 둥지를 틀고 있고, 전사(41-42레벨)는 분지 안쪽 {item:271611} 옆을 지킵니다. 희귀 정예 비룡 스칼다론도 이곳에 나타날 수 있습니다: 파티가 없다면 건드리지 마십시오.",
		["The {area:16737}"] = "{area:16737}",
		["The {area:16743} training grounds"] = "{area:16743} 훈련장",
		["The {npc:260244} prowls the shallows south-west of the port, below the murlocs' beaches. {npc:257001}, an elite, walks the shore close by: give him room."] = "{npc:260244}은(는) 항구 남서쪽, 멀록 해변 아래 얕은 물을 배회합니다. 정예인 {npc:257001}이(가) 근처 해안을 걸어 다니니 거리를 두십시오.",
		["The {object:628948} poster by the inn"] = "여관 옆 {object:628948} 벽보",
		["The {object:628948} poster by the inn: {npc:260235}"] = "여관 옆 {object:628948} 벽보: {npc:260235}",
		["Train before the {zone:1418}"] = "{zone:1418}에 가기 전에 수련하기",
		["Use {npc:256438}'s {item:266161} on bare ground around the camp: five saplings."] = "{npc:256438}의 {item:266161}을(를) 벌목지 주변 맨땅에 사용하십시오: 묘목 5그루.",
		["West across the river to {area:16736}: the Peasant Woodpiles around the camp give the wood bundles.\nCareful: {npc:263380}, an elite (level 42), prowls the river by the camp: if he comes your way, back off and let him pass."] = "강을 건너 서쪽 {area:16736}(으)로 가십시오. 야영지 주변의 농부 장작더미에서 나무 묶음을 얻습니다.\n주의: 정예 {npc:263380}(42레벨)이(가) 야영지 옆 강을 배회합니다. 다가오면 물러나서 지나가게 두십시오.",
		["West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."] = "북쪽 배에서 서쪽으로 능선을 오르십시오. 부패살점 버섯은 황혼의 망치 오우거 야영지 근처 바위 사이에 자랍니다. 능선의 다 자란 흰엄니도 내장을 줍니다.",
		["West into the {area:16737}: the Redridge gnolls camp on the slopes all the way from the hills west of the lumber camp to the pass you came in by. The stolen saw blades lie only in the western camps, near the pass.\nCareful: {npc:255906}, an elite gnoll (level 40), roams the south-western camps: pull the gnolls away from him."] = "서쪽 {area:16737}으로 가세요. 붉은마루 놀은 벌목장 서쪽 언덕부터 들어온 고개까지 비탈 곳곳에 진을 치고 있습니다. 도난당한 톱날은 고개 근처 서쪽 야영지에만 있습니다.\n주의: 정예 놀(40레벨) {npc:255906}이(가) 남서쪽 야영지를 돌아다닙니다. 놀들을 그에게서 떼어내 끌어오세요.",
		["West of the port, the wildflowers grow in the meadows below {npc:263367}'s workshop."] = "항구 서쪽, {npc:263367}의 작업장 아래 초원에 야생화가 자랍니다.",
		["West through the keep: {npc:263089} by the orchard, then the cathedral and {npc:259859} south of the inn if you have their errands."] = "성채를 지나 서쪽으로 가십시오. 과수원 옆의 {npc:263089}, 그다음 심부름이 있다면 대성당과 여관 남쪽의 {npc:259859}에게 들르십시오.",
		["West to {area:16725}: {npc:258317} stands by the farmhouse."] = "서쪽 {area:16725}(으)로: {npc:258317}이(가) 농가 옆에 서 있습니다.",
		["Your class trainer"] = "직업 상급자",
		["Your hearthstone is bound at {area:16724}'s inn: use it, or ride back south to the keep."] = "귀환석이 {area:16724} 여관에 지정되어 있습니다. 사용하거나 남쪽 성채로 말을 타고 돌아가십시오.",
		["fill the {item:269990} at the ritual circles"] = "의식의 원에서 {item:269990} 채우기",
		["find {npc:257250} and talk to him"] = "{npc:257250}을(를) 찾아 대화하기",
		["free five captive Farholde Scouts"] = "붙잡힌 파홀드 정찰병 다섯 명 풀어 주기",
		["go with {npc:258963} to save {npc:258935}"] = "{npc:258963}와(과) 함께 {npc:258935} 구출",
		["grind on {npc:257901}"] = "{npc:257901} 사냥",
		["help {npc:259057} break out of {area:16726}"] = "{npc:259057}이(가) {area:16726}에서 탈출하도록 돕기",
		["kill a {npc:258652}"] = "{npc:258652} 처치",
		["lead {npc:259158} out of {area:16723} to his treasure, west of the town"] = "{npc:259158}을(를) {area:16723} 밖으로 데리고 마을 서쪽의 보물까지 가십시오",
		["the middle ship"] = "가운데 배",
		["the northern ship"] = "북쪽 배",
		["the stress test: beat G45-B4G beside the workshop"] = "스트레스 테스트: 작업장 옆의 G45-B4G 쓰러뜨리기",
		["the {object:645166} poster"] = "{object:645166} 전단",
		["walk it back to {area:16725}"] = "{area:16725}까지 걸어서 데려가기",
		["{area:16724}, the west side"] = "{area:16724}, 서쪽",
		["{area:16735} and the river"] = "{area:16735}와(과) 강",
		["{item:17028}, from {npc:272437}"] = "{item:17028}, {npc:272437}에게서",
		["{item:268505}, the southern ship"] = "{item:268505}, 남쪽 배",
		["{item:268632} as you go"] = "이동하며 {item:268632} 모으기",
		["{item:269997}, on the graves"] = "무덤 위의 {item:269997}",
		["{item:271653}, from {npc:260565}"] = "{item:271653}, {npc:260565}에게서",
		["{item:271654}, from {npc:260560}"] = "{item:271654}, {npc:260560}에게서",
		["{item:271657}, from {npc:260487}"] = "{item:271657}, {npc:260487}에게서",
		["{item:272126}, on the Wounded Soldiers beside him"] = "{item:272126}, 그의 옆에 있는 부상당한 병사들에게",
		["{npc:255906} is an elite gnoll (level 40) who roams the south-western camps of the {area:16737}: grouping up is advised."] = "{npc:255906}은(는) {area:16737}의 남서쪽 야영지를 돌아다니는 정예 놀(40레벨)입니다. 파티를 권장합니다.",
		["{npc:256881} is an elite (level 46) in the fortress at the head of the valley, with the Enforcers around him: grouping up is advised."] = "{npc:256881}은(는) 골짜기 끝 요새에 있는 정예(46레벨)이며 주위에 집행자들이 있습니다. 파티를 권장합니다.",
		["{npc:256899}, the two-headed ogre, is an elite (level 41) at the western edge of {area:16723}: grouping up is advised. Claire then has the filled catalyst for {npc:257591} in {area:16724}."] = "머리 둘 달린 오우거 {npc:256899}은(는) {area:16723} 서쪽 끝의 정예(41레벨)입니다: 파티를 권장합니다. 이어서 클레어가 {area:16724}의 {npc:257591}에게 줄 채워진 촉매를 건넵니다.",
		["{npc:257001} is an elite (level 42) on the south shore: grouping up is advised."] = "{npc:257001}은(는) 남쪽 해안의 정예(42레벨)입니다. 파티를 권장합니다.",
		["{npc:257087} flies to {zone:1453}. {npc:278088} waits in the {object:2098}."] = "{npc:257087}을(를) 통해 {zone:1453}(으)로 날아갈 수 있습니다. {npc:278088}은(는) {object:2098}에서 기다리고 있습니다.",
		["{npc:257087}, at the western gate"] = "{npc:257087}, 서쪽 문",
		["{npc:257250} lies wounded among the camps at the valley's western edge.\nCareful: {npc:256881} and {npc:256891} (elites, 46) hold the fortress north of him: come at Ryan from the south."] = "{npc:257250}은(는) 골짜기 서쪽 끝 야영지 사이에 부상당한 채 쓰러져 있습니다.\n주의: {npc:256881}와(과) {npc:256891}(정예, 46)이(가) 그의 북쪽 요새를 지키고 있습니다. 라이언에게는 남쪽에서 접근하십시오.",
		["{npc:257558}, in the keep"] = "{npc:257558}, 성채 안",
		["{npc:257558}: Kilgar's head for {npc:1748} in {object:2117}"] = "{npc:257558}: 킬가르의 머리를 {object:2117}의 {npc:1748}에게",
		["{npc:257591}: {quest:94881}, for later in this guide"] = "{npc:257591}: {quest:94881}, 이 가이드 후반용",
		["{npc:257595}, at the inn"] = "{npc:257595}, 여관에서",
		["{npc:258963} stands at the camp's south end. He sets off for {npc:258935}, south-east of the camp, as soon as you take {quest:94861}: go with him and keep the attackers off, and wait if {npc:263380} is in sight. If it fails, {npc:258963} offers the quest again."] = "{npc:258963}은(는) 벌목지 남쪽 끝에 서 있습니다. {quest:94861}을(를) 수락하면 바로 벌목지 남동쪽의 {npc:258935}에게 출발합니다: 함께 가며 공격자를 막고, {npc:263380}이(가) 보이면 기다리십시오. 실패하면 {npc:258963}에게서 퀘스트를 다시 받을 수 있습니다.",
		["{npc:259051} keeps the west end of {area:16744}."] = "{npc:259051}은(는) {area:16744}의 서쪽 끝을 지킵니다.",
		["{npc:259158} wants out of {area:16723}: lead him west to his treasure at the edge of town and keep the cultists off him."] = "{npc:259158}은(는) {area:16723}을(를) 빠져나가고 싶어 합니다: 서쪽 마을 끝의 보물까지 데려가며 교단원을 막아 주십시오.",
		["{npc:259352} holds {area:16729}, the tower on the plains north-east of the crate."] = "{npc:259352}은(는) 상자 북동쪽 평원의 탑인 {area:16729}에 있습니다.",
		["{npc:259352}'s tower stands just south-west of the marsh."] = "{npc:259352}의 탑은 습지 바로 남서쪽에 있습니다.",
		["{npc:259352}'s tower."] = "{npc:259352}의 탑.",
		["{npc:259863}, by the inn: {quest:95330}, for {area:16736} later in this guide"] = "{npc:259863}, 여관 옆: {quest:95330}, 이 가이드 뒷부분의 {area:16736}용",
		["{npc:262031} keeps the old cathedral at the south-west corner of {area:16724}. The bats roost in its upper floor; {npc:272437} sells the holy candles beside it; the graves are in the chapel graveyard.\n{npc:271742}, an elite of level 53, stands in the cathedral: he leaves you be, so never attack him, and pull the bats away from him."] = "{npc:262031}은(는) {area:16724} 남서쪽 구석의 옛 대성당을 지키고 있습니다. 박쥐는 대성당 위층에 둥지를 틀고 있고, 그 옆에서 {npc:272437}이(가) 신성한 양초를 팔며, 무덤은 예배당 묘지에 있습니다.\n53레벨 정예인 {npc:271742}이(가) 대성당 안에 서 있습니다: 먼저 공격하지 않으니 절대 공격하지 말고, 박쥐는 그에게서 떨어진 곳으로 끌어내십시오.",
		["{npc:262031}, in the cathedral at the keep's south-west corner."] = "{npc:262031}, 성채 남서쪽 모퉁이의 대성당에 있습니다.",
		["{npc:263071} is an elite (level 42) at the Horde's training grounds north of {area:16743}, where this guide goes later: grouping up is advised."] = "{npc:263071}은(는) {area:16743} 북쪽 호드 훈련장에 있는 정예(42레벨)로, 이 가이드에서 나중에 갑니다: 파티를 권장합니다.",
		["{npc:263071}, the elite, walks the training grounds."] = "정예 {npc:263071}은(는) 훈련장을 걸어 다닙니다.",
		["{npc:263089} stands west of the inn, by the orchard: the apples hang on the trees around it."] = "{npc:263089}은(는) 여관 서쪽 과수원 옆에 있습니다. 사과는 주변 나무에 달려 있습니다.",
		["{npc:263315}, an elite lion (level 41), prowls the plains north of {area:16729}, on your way back north: grouping up is advised."] = "정예 사자(41레벨)인 {npc:263315}이(가) {area:16729} 북쪽 평원을 배회합니다. 북쪽으로 돌아가는 길에 있으니 파티를 권장합니다.",
		["{npc:263367}'s workshop"] = "{npc:263367}의 작업장",
		["{npc:263380} is an elite (level 42) who hunts along the river between {area:16725} and {area:16729}, on your way north later in this guide: grouping up is advised. The poster hangs by the keep; {npc:259859}, who takes the fang, stands south of the inn."] = "{npc:263380}은(는) {area:16725}와(과) {area:16729} 사이 강을 따라 사냥하는 정예(42레벨)로, 이 가이드 후반 북쪽으로 가는 길에 있습니다: 파티를 권장합니다. 현상수배 전단은 성채 옆에 걸려 있고, 송곳니를 받는 {npc:259859}은(는) 여관 남쪽에 서 있습니다.",
		["{npc:263380}, the elite, hunts along the river between {area:16725} and {area:16729}, on your way north."] = "정예인 {npc:263380}은(는) 북쪽으로 가는 길에 {area:16725}와(과) {area:16729} 사이 강을 따라 사냥합니다.",
		["{npc:263613} tends the wounded beside the barracks: bandage three of his soldiers, then he has a note for {npc:262031} in the cathedral."] = "{npc:263613}은(는) 병영 옆에서 부상병을 돌보고 있습니다. 병사 세 명에게 붕대를 감아 주면 대성당의 {npc:262031}에게 보낼 쪽지를 줍니다.",
		["{npc:263613}: twenty {item:4338}, from {area:16723}'s cultists and the pirates; hand it in when you are back"] = "{npc:263613}: {area:16723}의 광신도와 해적에게서 얻는 {item:4338} 20개. 돌아오면 제출하십시오",
		["{npc:263749} (level 44) carries the key: he paces the lanes south of {npc:259057}'s hut.\nThe {item:275043} lies just west of the lanes: its fighters (elites, 41-45) only fight in a bout, so leave them be."] = "{npc:263749}(44레벨)이(가) 열쇠를 지니고 있습니다. {npc:259057}의 오두막 남쪽 골목을 오갑니다.\n{item:275043}은(는) 골목 바로 서쪽에 있습니다. 그곳 투사들(정예, 41-45)은 시합 중에만 싸우니 내버려 두십시오.",
		["{quest:94877}: for later in this guide"] = "{quest:94877}: 이 가이드 후반용",
		["{quest:94879}, for later in this guide"] = "{quest:94879}, 이 가이드 뒷부분용",
		["{quest:94884}: for {npc:257591} in {area:16724}"] = "{quest:94884}: {area:16724}의 {npc:257591}에게",
		["{quest:94885}: only if a cultist dropped the log"] = "{quest:94885}: 교단원이 일지를 떨어뜨린 경우에만",
		["{quest:94886}: for later in this guide"] = "{quest:94886}: 이 가이드 후반에 진행합니다",
		["{quest:94887}: for later in this guide"] = "{quest:94887}: 이 가이드 후반용",
		["{quest:94891}: for {npc:257591}"] = "{quest:94891}: {npc:257591}에게",
		["{quest:94892}: for {npc:257558} in {area:16724}"] = "{quest:94892}: {area:16724}의 {npc:257558}에게",
		["{quest:94893}: for {npc:278088} in {zone:1453}"] = "{quest:94893}: {zone:1453}의 {npc:278088}에게",
		["{quest:94907}: for later in this guide"] = "{quest:94907}: 이 가이드 후반에 진행합니다",
		["{quest:94928}: for {area:16727}, keep it"] = "{quest:94928}: {area:16727}용, 보관하십시오",
		["{quest:95059}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95059}: {area:16724}의 {npc:257558}에게 줄 것이니 보관하십시오",
		["{quest:95064}: for later, at the Horde's training grounds north of {area:16743}"] = "{quest:95064}: 나중에 {area:16743} 북쪽 호드 훈련장에서 합니다",
		["{quest:95066}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95066}: {area:16724}의 {npc:257558}에게 제출하니, 보관하십시오",
		["{quest:95122}: for later in this guide"] = "{quest:95122}: 이 가이드 후반에 진행",
		["{quest:95123}: for later in this guide"] = "{quest:95123}: 이 가이드 후반에 진행",
		["{quest:95148}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95148}: {area:16724}의 {npc:257558}에게 줄 것, 보관하세요",
		["{quest:95261}: the beasts' entrails come as you go; the mushrooms are for later"] = "{quest:95261}: 짐승 내장은 진행하며 모이고, 버섯은 나중에 합니다",
		["{quest:95267}: a big beast in the shallows south-west of the port, near {npc:257001}, the elite"] = "{quest:95267}: 항구 남서쪽 얕은 물, 정예 {npc:257001} 근처의 큰 야수",
		["{quest:95293}: for {npc:260390} at the pirates' camp"] = "{quest:95293}: 해적 야영지의 {npc:260390}에게",
		["{quest:95329}: for {npc:259352} at {area:16729}, keep it"] = "{quest:95329}: {area:16729}의 {npc:259352}에게 제출하니, 보관하십시오",
		["{quest:95426}: for later, the same training grounds"] = "{quest:95426}: 나중에 같은 훈련장에서 합니다",
		["{quest:95961}: for {npc:263120} in {area:16727}, keep it"] = "{quest:95961}: {area:16727}의 {npc:263120}에게 제출하니, 보관하십시오",
		["{quest:95975}: for later, the wildflowers west of the port"] = "{quest:95975}: 나중에, 항구 서쪽의 들꽃",
		["{quest:95984}: for later, where the tallstriders graze by {npc:263367}'s workshop; keep it"] = "{quest:95984}: 나중에 {npc:263367}의 작업장 옆 타조가 풀을 뜯는 곳에서 합니다. 보관하세요",
		["{quest:96009}: for {area:16736} later in this guide"] = "{quest:96009}: 이 가이드 후반 {area:16736}에서 합니다",
		["{quest:96084}: for later in this guide"] = "{quest:96084}: 이 가이드 후반용",
		["{quest:96125}: for {npc:259057} in {area:16726}, keep it"] = "{quest:96125}: {area:16726}의 {npc:259057}에게 줄 것, 보관하세요",
		["{zone:1455} flight master"] = "{zone:1455} 비행 조련사",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Fly to {area:150}"] = "{area:150}(으)로 비행",
		["Fly to {area:271}"] = "{area:271}(으)로 날아가세요",
		["Mudsprocket"] = "진흙톱니",
		["Raleigh's next errand is in the {area:796}: skip it."] = "랄레이의 다음 심부름은 {area:796}에 있으니 건너뛰십시오.",
		["Ride back east to {area:1898}."] = "동쪽 {area:1898}(으)로 돌아가십시오.",
		["Ride back north to Ironband's camp."] = "북쪽 아이언밴드의 발굴현장으로 돌아가십시오.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "길을 따라 북동쪽으로 {area:271}을(를) 빠져나가 {zone:1425}로 가십시오. {area:348}은(는) 경계 바로 너머에 있습니다. {npc:5635}은(는) 꼭대기에, {quest:1450}은(는) 그리핀 둥지에, {npc:7884}은(는) 여관 옆에 있습니다.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "남쪽 고개를 지나 {zone:1432}에서 {zone:1418}(으)로 가십시오. {npc:2860}은(는) 발굴 현장에 야영하고 있습니다.",
		["Take the road south-west out of Theramore to Mudsprocket, the goblin camp at the edge of the {area:511}. {npc:270723} and {npc:270727} stand together in the camp."] = "테라모어에서 남서쪽 길을 따라 {area:511} 가장자리의 고블린 야영지인 진흙톱니로 가십시오. {npc:270723}와(과) {npc:270727}은(는) 야영지에 함께 있습니다.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "탈론액스의 다음 임무는 이후 {zone:1425} 가이드에서 합니다.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "화염의 새끼비룡은 {npc:2888} 동쪽 협곡에 둥지를 틀고 있습니다. 화염의 수호비룡(정예)은 건드리지 마십시오. {item:4612}은(는) 드물게 떨어지니 사냥 중에 나오면 챙기십시오.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace.\nCareful: {npc:270772} (49) and his Hexed Larvae (45) keep to the huts of the western village, around 25,64: take the necklaces from the trolls outside."] = "처음 두 우리는 {npc:5634} 남쪽 마른나무껍질 마을에 함께 있고, 세 번째는 동쪽의 다음 마을에 있습니다. 모든 마른나무껍질 트롤이 목걸이를 떨어뜨릴 수 있습니다.\n주의: {npc:270772}(49)와(과) 그의 저주받은 애벌레(45)는 서쪽 마을의 오두막, 약 25,64 근처에 머뭅니다. 목걸이는 바깥의 트롤에게서 얻으세요.",
		["The {area:1517} dig"] = "{area:1517} 발굴지",
		["The {area:511}"] = "{area:511}",
		["The {item:280092} grows in the bog east of the camp: gather it first. Then the Searing Hatchlings and Whelps (41-43) and the Firemane dragonkin nest in the bog north and west of Mudsprocket, on the way back; all of them drop the shed scales.\nCareful: the Firemane Scalebanes and Flamecallers are 43-44 and cast fire: pull them one at a time."] = "{item:280092}은(는) 야영지 동쪽 늪에서 자랍니다: 먼저 채집하십시오. 그런 다음 돌아오는 길에 진흙톱니 북쪽과 서쪽 늪에 둥지를 튼 갓 부화한 화염 새끼용과 새끼용(41-43), 화염갈기혈족 용족을 처치하십시오. 모두 허물 비늘을 떨어뜨립니다.\n주의: 화염갈기혈족 맹독전사와 화염술사는 43-44레벨이며 화염 주문을 씁니다: 하나씩 끌어오십시오.",
		["Then ride back north-east to Theramore's flight master."] = "그런 다음 북동쪽으로 돌아가 테라모어의 비행 조련사에게 가십시오.",
		["Theramore"] = "테라모어 섬",
		["Theramore flight master"] = "테라모어 섬 비행 조련사",
		["Warlock: {quest:3631}"] = "흑마법사: {quest:3631}",
		["Witherbark villages"] = "마른나무껍질 마을",
		["{area:144} flight master"] = "{area:144} 비행 조련사",
		["{npc:1470} is below ground in {area:144}, by the inn, where the flight lands. His mushrooms grow in the {area:1517} dig at the {zone:1418}' northern edge, on this guide's loop back north."] = "{npc:1470}은(는) 비행 경로가 도착하는 {area:144}의 여관 옆 지하에 있습니다. 그의 버섯은 {zone:1418} 북쪽 끝의 {area:1517} 발굴지에서 자라며, 이 가이드에서 북쪽으로 돌아오는 길에 들르게 됩니다.",
		["{npc:2277} stands in {area:271}, by the inn."] = "{npc:2277}은(는) {area:271}의 여관 옆에 있습니다.",
		["{npc:269577} camps at the foot of the pass into {zone:1432}, on the way north."] = "{npc:269577}은(는) 북쪽으로 가는 길, {zone:1432}(으)로 이어지는 고갯길 기슭에 야영하고 있습니다.",
		["{npc:269577}'s {item:278404} lies in the middle of the Stonevault trogg camp, where {quest:739} walks."] = "{npc:269577}의 {item:278404}은(는) {quest:739}이(가) 돌아다니는 돌무덤 트로그 야영지 한가운데에 있습니다.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "{npc:2817}의 다음 퀘스트는 경험치를 주지 않으니 건너뛰십시오.",
		["{npc:2817}: Blue Pearls from Stranglethorn"] = "{npc:2817}: 가시덤불 골짜기의 푸른 진주",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888}은(는) 발굴 현장 남동쪽 {area:1898}에 홀로 야영하고 있습니다.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "{npc:2888}의 다음 임무는 정예 사냥이니 건너뛰십시오.",
		["{npc:2944} does not stay at {area:342}: he walks a long loop around the {zone:1418} with his guards, from the camp in the west along the south of the zone to about 61,69, north to about 49,49 and back west to the camp. The arrow follows his loop west from here until you meet him."] = "{npc:2944}은(는) {area:342}에 머물러 있지 않습니다. 호위병들과 함께 {zone:1418}을(를) 크게 돌며, 서쪽 야영지에서 지역 남쪽을 따라 약 61,69까지, 북쪽으로 약 49,49까지 간 뒤 다시 서쪽 야영지로 돌아옵니다. 화살표는 그를 만날 때까지 여기서부터 서쪽으로 그의 경로를 따라갑니다.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634}은(는) {area:348} 동쪽 길가에 야영하고 있습니다.",
		["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}, 꼭대기의 비행 조련사 옆, 안",
		["{quest:706}: its {item:4612} is a rare drop, so the work and hand-in are optional too"] = "{quest:706}: {item:4612}은(는) 드물게 떨어지므로, 작업과 제출도 선택 사항입니다",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the coast"] = "해안으로 돌아가기",
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "{area:1117}(으)로 돌아가십시오. 그곳의 증오의갈기일족 나가는 모두 비늘을 떨어뜨릴 수 있습니다.",
		["Boats to and from the island"] = "섬을 오가는 배",
		["Careful: {npc:222286}, an elite of level 43, stands at the camp's north-east edge, around 67,39: pull the Naturalists, Raiders and Shamans away from her."] = "주의: 43레벨 정예 {npc:222286}이(가) 야영지 북동쪽 가장자리(약 67,39)에 서 있습니다. 박물학자, 약탈자, 주술사는 그녀에게서 멀리 끌어내십시오.",
		["Feathermoon's isle, ogres, yetis and the {area:1121}."] = "페더문의 섬, 오우거, 설인, 그리고 {area:1121}.",
		["From {area:489} ride west along the road to the Grimtotem camp north of it. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "{area:489}에서 길을 따라 서쪽으로, 길 북쪽의 그림토템 주둔지까지 가십시오. {npc:7956}은(는) 그 밖에서 기다립니다. 한가운데 우리에서 화살요정용을 풀어 주고, {npc:7956}과 화살요정용을 적어도 여섯 마리 살려 두십시오.",
		["Gordunni ogres"] = "골두니일족 오우거",
		["Grimtotem camp"] = "그림토템 야영지",
		["Grimtotem tauren"] = "그림토템 타우렌",
		["Grind to 45"] = "45레벨까지 사냥",
		["Hatecrest naga"] = "증오의갈기일족 나가",
		["Ironfur bears"] = "무쇠가죽곰",
		["No flight path to {area:489} yet: take the boat back to the coast and ride east along the road to {area:489}, on the {zone:1441} border."] = "아직 {area:489} 비행 경로가 없습니다. 배를 타고 해안으로 돌아가 길을 따라 동쪽으로, {zone:1441} 경계의 {area:489}까지 가십시오.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north.\nCareful: the {npc:5236} are 44-45 and the Warlocks 43-44, casters a level or two over you here: pull them one at a time from the camp's edge, and take the Brutes (42-43) on the slopes first."] = "동쪽으로 설인 골짜기 남동쪽 언덕의 골두니 야영지까지 가십시오. 골두니일족 흑마법사와 골두니일족 주술사가 야영지를 지키고, 골두니일족 투사는 주변 비탈과 더 북쪽을 돌아다닙니다.\n주의: {npc:5236}은(는) 44-45레벨, 흑마법사는 43-44레벨로, 이곳에서 당신보다 한두 레벨 높은 주문시전자입니다. 야영지 가장자리에서 하나씩 끌어내고, 비탈의 투사(42-43레벨)부터 처치하십시오.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "북쪽 설인 골짜기로 들어가십시오. 원시설인은 모두 두꺼운 설인 가죽을 떨어뜨릴 수 있습니다. {npc:5346}(48레벨)은(는) 한가운데를 배회합니다.",
		["Ride north out of {area:1105}: the Ironfur Bears (41-42) at the foot of the {area:1136} drop Rhapsody's last liver.\nCareful: Ironfur Patriarchs (48-49) and the Rage Scar yetis (46-49) roam the hills further north: stay at their edge."] = "{area:1105}에서 북쪽으로 나가십시오. {area:1136} 기슭의 무쇠가죽곰(41-42레벨)이 랩소디의 마지막 간을 떨어뜨립니다.\n주의: 더 북쪽 언덕에는 우두머리 무쇠가죽곰(48-49레벨)과 성난상처 설인(46-49레벨)이 돌아다닙니다. 가장자리에 머무르십시오.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "북동쪽으로 {zone:1441} 경계의 나이트 엘프 전초기지까지 가십시오.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "남동쪽의 덩굴발일족 놀에게 가십시오. 전령의 배낭은 남쪽 야영지에 있고, 그 안의 꾸러미로 {area:489} 배달이 시작됩니다. 바로 남쪽이 고통의 구덩이입니다: 안내원 라스칼이 갇힌 고치까지 싸우며 내려가 그를 풀어 주고, 나가는 동안 살려 두십시오.",
		["Ride to {area:489}"] = "{area:489}까지 이동",
		["Ride west into {area:1105}: its yetis are 43-45. The Rage Scar yetis in the hills to the north are 46-49: leave them. Or, with a group, run the {area:978} dungeon instead."] = "서쪽 {area:1105}(으)로 가십시오. 그곳 설인은 43-45레벨입니다. 북쪽 언덕의 성난상처 설인은 46-49레벨이니 피하십시오. 또는 파티가 있다면 대신 {area:978} 던전을 도십시오.",
		["Stays on the main route"] = "주요 경로에 머무름",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "배를 타고 {area:1108}(으)로 가서 해안을 따라 남쪽으로, 해변에 부서진 나룻배까지 가십시오.",
		["The courier's boat"] = "전령의 배",
		["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "{area:1121}은(는) {area:1120} 바로 남쪽의 섬입니다. 헤엄쳐 건너십시오. 증오의갈기일족 수호병과 증오의갈기일족 여마법사가 지키고 있으며, {npc:8136}(47레벨)은(는) 남쪽 끝 동굴에 있습니다. 경비병부터 끌어내십시오.",
		["Then on to {zone:1446}"] = "이어서 {zone:1446}(으)로",
		["Two new flight paths for later"] = "나중을 위한 새 비행 경로 2개",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "섬을 따라 남쪽의 나가 폐허로 걸어가십시오. 정자는 폐허 사이에 있습니다.",
		["You came into {zone:1444} from {zone:2652}, so {area:489}'s flight path is still to learn: take the boat back to the coast and ride east along the road; you pick up the flight path when this guide ends at {area:489}."] = "{zone:2652}에서 {zone:1444}(으)로 왔으므로 {area:489}의 비행 경로는 아직 익히지 않았습니다. 배를 타고 해안으로 돌아가 길을 따라 동쪽으로 가십시오. 이 가이드가 {area:489}에서 끝날 때 비행 경로를 익힙니다.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "{zone:1457}의 티란데 위스퍼윈드에게: 경로상 47레벨에 그곳에 갑니다",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "{zone:1444} {area:1105}에서 {npc:5292} 사냥",
		["{item:11463}, from the backpacks"] = "{item:11463}, 배낭에서",
		["{npc:3936}, beside him"] = "{npc:3936}, 그의 옆",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: 답장은 나중에 {area:702}에서 받습니다",
		["{npc:7852}'s next order, Improved Quality, wants Rage Scar hides from yetis of 46-49: skip it."] = "{npc:7852}의 다음 주문인 '품질 향상'은 46-49레벨 설인의 성난상처 가죽을 요구합니다: 건너뛰십시오.",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, 요새 꼭대기",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136}은(는) 본토를 한 바퀴 돈 뒤에 처치합니다.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Boat to {area:150}"] = "배를 타고 {area:150}(으)로",
		["Class trainer"] = "직업 상급자",
		["Fly to {area:271}"] = "{area:271}(으)로 비행",
		["Fly to {area:442}"] = "{area:442}(으)로 비행",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "해안을 따라 남쪽 해적단 소굴로 가십시오. 남쪽바다해적단이 해변과 배에 우글거립니다: 가장자리부터 하나씩 끌어내십시오. {npc:7883}은(는) 반대편에 서 있고, {npc:7881}의 도둑맞은 화물은 야영지에 있습니다.\n주의: {npc:7883} 곁에는 해적 두세 명이 서 있고, 싸움이 시작되면 마을의 해적이 훨씬 더 많이 합류합니다.",
		["For your {area:978} run, later in this guide: {quest:2864} wants scarab shells, {npc:7407}, by the water tower, his {quest:2768} back, and Trenton Lighthammer Troll Temper from the Sandfury trolls."] = "{area:978} 공략용(이 가이드 후반): {quest:2864}은(는) 풍뎅이 껍질을, 급수탑 옆의 {npc:7407}은(는) 자신의 {quest:2768}을(를), 트렌턴 라이트해머는 성난모래부족 트롤의 Troll Temper를 원합니다.",
		["From {npc:6015}, {area:977} is just west along the shore."] = "{npc:6015}에서 해안을 따라 바로 서쪽에 {area:977}이(가) 있습니다.",
		["Gives the {item:8585}"] = "{item:8585}을(를) 줍니다",
		["No flight path to {area:348} yet: ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border."] = "아직 {area:348} 비행 경로가 없다면: {area:271}에서 북동쪽 길을 따라 {zone:1425}(으)로 가십시오. {area:348}은(는) 경계 바로 너머에 있습니다.",
		["Pool by {area:979}"] = "{area:979} 옆 웅덩이",
		["Portal to {zone:1438}"] = "{zone:1438}행 차원문",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "서쪽 {area:976} 쪽으로 돌아가십시오. 가는 길의 모래언덕에는 사막유랑단 약탈자와 사막유랑단 좀도둑이 있고, 누구든 사막유랑단 물주머니를 지니고 있을 수 있습니다.\n주의: 사막유랑단 도적(43-44레벨)은 은신한 채 움직이므로 보이지 않게 다가올 수 있습니다.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "모래언덕을 건너 동쪽, 북동쪽 해안의 고블린 항구(스팀휘들 항구)로 가십시오.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool to tap it; the trolls stand close, so pull the nearest first.\nCareful: tapping the pool brings Scarabs (level 44-47) out of the sand to attack you: tap it, then step away from the trolls and fight the Scarabs one by one."] = "북서쪽 {area:979}의 성난모래부족 트롤 야영지로 가십시오. 웅덩이 가장자리에서 {item:8584}을(를) 사용해 추출하십시오. 트롤들이 가까이 있으니 가장 가까운 것부터 끌어내십시오.\n주의: 웅덩이를 추출하면 모래에서 풍뎅이(44-47레벨)가 나와 공격합니다. 추출한 뒤 트롤에게서 떨어져 풍뎅이를 하나씩 처치하십시오.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "남쪽 {area:1938}의 발굴 야영지로 가십시오. {npc:7771}이(가) 탐지 투구를 줍니다: 착용하면 {quest:3161} 흙더미가 보이며, 야영지 주변과 남서쪽 오우거 쪽 모래에 많이 있습니다.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "{area:439}에서 남동쪽 {zone:1446}(으)로 가십시오. {area:976}은(는) 경계 바로 안쪽에 있습니다.",
		["Ride south-west to the ogre compound and keep to its south end; the compound's quest waits for the Un'Goro guide.\nWhy the grind to 47: {npc:5955} waits at the edge of the {quest:3362} (mobs of 48-50). Grind it on the Dunemaul Ogres (45-46) at the compound's south end, the safer camp, not on the Brutes and Enforcers (46-48) inside."] = "남서쪽 오우거 주둔지로 가서 남쪽 끝에 머무르십시오. 주둔지 퀘스트는 운고로 가이드에서 합니다.\n47레벨까지 사냥하는 이유: {npc:5955}은(는) {quest:3362}(48-50레벨 몹) 가장자리에 있습니다. 안쪽의 투사와 집행자(46-48레벨) 말고, 더 안전한 주둔지 남쪽 끝의 모래망치 오우거(45-46레벨)를 사냥하십시오.",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "차원문을 지나 {zone:1457}(으)로 가십시오. 달의 신전은 도시 남쪽에 있습니다.",
		["Take the boat from {area:442}'s dock to {area:702}; {npc:3838}, the hippogryph master, stands on the rise just east of the landing: learn the flight path on the way up to the village."] = "{area:442} 부두에서 배를 타고 {area:702}(으)로 가십시오. 히포그리프 조련사 {npc:3838}은(는) 선착장 바로 동쪽 언덕에 서 있습니다. 마을로 올라가는 길에 비행 경로를 익히십시오.",
		["Temple of the Moon"] = "달의 신전",
		["The Wanted poster beside him"] = "그 옆의 현상수배 포스터",
		["The pool by {area:979}"] = "{area:979} 옆 웅덩이",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "같은 현상수배 전단: {npc:7847}은(는) 훨씬 나중, {area:976} 이후에 나옵니다",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "더 강한 사막유랑단 도적, 사막유랑단 어둠마법사, 사막유랑단 암살자는 {area:976} 남동쪽, 약탈자들 남쪽에 진을 치고 있습니다. 남쪽 야영지 한가운데의 {npc:7847}은(는) 나중으로 미루십시오.\n주의: 사막유랑단 도적은 전투 밖에서 은신을 유지하므로, 야영지에서 시작한 싸움에 숨어 있던 도적이 합류할 수 있습니다.",
		["The {area:1938}"] = "{area:1938}",
		["The {quest:2768}: {npc:7407}, by the water tower."] = "{quest:2768}: 급수탑 옆의 {npc:7407}.",
		["The {quest:3042}: {npc:7804}, in town."] = "{quest:3042}: 마을 안의 {npc:7804}.",
		["Your {area:978} scarab shells: {npc:7876}, on the north side of town."] = "{area:978}의 풍뎅이 껍질: 마을 북쪽의 {npc:7876}.",
		["grind on {npc:5471}, at the compound's south end"] = "주둔지 남쪽 끝에서 {npc:5471} 사냥",
		["keep it: the {area:982}'s Centipaar (48-50) wait for the Un'Goro guide's {area:976} landing at about 49.5"] = "보관하십시오: {area:982}의 센티파르(48-50레벨)는 운고로 가이드에서 약 49.5레벨에 {area:976}에 도착할 때 처치합니다",
		["the book on her table"] = "그녀의 탁자 위에 있는 책",
		["the soil comes from {zone:1449}, later"] = "흙은 나중에 {zone:1449}에서 얻습니다",
		["{area:702} flight master"] = "{area:702} 비행 조련사",
		["{area:976} flight master"] = "{area:976} 비행 조련사",
		["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the pool.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978}은(는) 5인 파티용 던전이며, 이곳의 퀘스트는 45~47레벨입니다. 입구는 웅덩이에서 북쪽으로 약 400야드 떨어져 있습니다.\n내부: 풍뎅이가 껍질을 떨어뜨리고, 모든 성난모래부족 트롤이 {quest:3042}을(를) 떨어뜨릴 수 있으며, {npc:7604}이(가) {quest:2768}을(를) 가지고 있습니다.",
		["{item:278186}, from any Dunemaul ogre"] = "{item:278186}, 모래망치 오우거 아무에게서나",
		["{npc:11758}: keep it, the {area:983} waits for the same landing"] = "{npc:11758}: 보관하십시오. {area:983}은(는) 같은 도착 때 합니다",
		["{npc:270263}, just east of the aviary: {quest:86616}, from the {area:355}'s Soothsayers"] = "그리핀 둥지 바로 동쪽의 {npc:270263}: {quest:86616}, {area:355}의 예언자들",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, 나무 꼭대기",
		["{npc:5636}: {quest:86620}, the eggs in the hills just east of {area:348}"] = "{npc:5636}: {quest:86620}, {area:348} 바로 동쪽 언덕의 알",
		["{npc:5955}'s escort"] = "{npc:5955} 호위",
		["{npc:5955}, beside her: Oasis"] = "{npc:5955}, 토르타 옆: 오아시스",
		["{npc:7407}, by the water tower"] = "{npc:7407}, 급수탑 옆",
		["{npc:7408}, next to him"] = "{npc:7408}, 그의 옆",
		["{npc:7564}: keep it for the same landing"] = "{npc:7564}: 같은 도착 때까지 보관하십시오",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: 그의 상자는 나중에 {area:702}(으)로 갑니다",
		["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}, 항구의 선술집, 안",
		["{npc:7882}: {quest:97530}, the bangles come from the ogres on your way south"] = "{npc:7882}: {quest:97530}, 팔찌는 남쪽으로 가는 길의 오우거에게서 얻습니다",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907}은(는) {npc:7916} 위층에 서 있습니다. 건물 안에서 올라가십시오. 화살표는 층을 구분하지 못합니다.",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "{npc:7907}의 다음 심부름은 {zone:1446}(으)로 이어집니다. 건너뛰십시오.",
		["{npc:7916}: the feathers lie in the {zone:1425}, next"] = "{npc:7916}: 깃털은 다음 {zone:1425}에 있습니다",
		["{quest:2768}: {npc:7604}, inside"] = "{quest:2768}: {npc:7604}, 내부",
		["{quest:2864}, north side of town"] = "{quest:2864}, 마을 북쪽",
		["{quest:2864}: keep it, the {quest:3362} waits for the Un'Goro guide's {area:976} landing"] = "{quest:2864}: 보관하십시오. {quest:3362}은(는) 운고로 가이드에서 {area:976}에 도착할 때 합니다",
		["{quest:2865}: the Scarabs, inside"] = "{quest:2865}: 풍뎅이, 내부",
		["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042}: 성난모래부족 트롤, 내부",
		["{zone:1457} first, while you are on this side of the sea: Troyas' answer, {npc:7763}'s crate, Tyrande and the soil errand, then the boat from {area:442} to {area:150} and the gryphon to {area:348}."] = "바다 이쪽에 있는 동안 {zone:1457}부터 들르십시오: 트로야스의 답신, {npc:7763}의 상자, 티란데와 흙 심부름. 그런 다음 {area:442}에서 배를 타고 {area:150}(으)로 가서 그리폰을 타고 {area:348}(으)로 가십시오.",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Class trainer"] = "직업 전문가",
		["Fly to {area:1537}"] = "{area:1537}(으)로 비행",
		["Fly to {area:35}"] = "{area:35}(으)로 날아가기",
		["Gorilla hills"] = "고릴라 언덕",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last.\nCareful: three waves of gorillas come one after another with little rest between, then {npc:1514}. Start at full health and mana, and stay near Unbagwa. Some classes find it hard alone: a friend makes it easy."] = "송곳니를 건네고 그 자리에 머무르십시오. 고릴라가 세 차례 몰려오고, 마지막에 {npc:1514}이(가) 나옵니다.\n주의: 고릴라 세 무리가 쉴 틈 없이 연달아 몰려온 뒤 {npc:1514}이(가) 나타납니다. 생명력과 마나를 가득 채우고 시작하고, 운바그와 근처에 머무르십시오. 일부 직업은 혼자 하기 어렵습니다. 친구와 함께하면 쉽습니다.",
		["Leave town by the tunnel and ride north along the coast past the Bloodsail camp: the naga comb the beaches beyond it and drop the reeds."] = "터널로 마을을 나와 붉은해적단 야영지를 지나 해안을 따라 북쪽으로 가십시오. 그 너머 해변을 뒤지는 나가가 갈대를 떨어뜨립니다.",
		["Lost Gryphon Eggs"] = "잃어버린 그리핀 알",
		["MacKinley's next task sends you after elite ogres: skip it."] = "맥킨리의 다음 임무는 정예 오우거를 잡으러 보냅니다. 건너뛰세요.",
		["Naga Explorers"] = "{npc:1907}",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the way back to {area:348}: the lost gryphon eggs lie in the hills just east of the aviary."] = "{area:348}(으)로 돌아가는 길에: 잃어버린 그리핀 알은 그리핀 둥지 바로 동쪽 언덕에 있습니다.",
		["Ride back down to town."] = "다시 마을로 내려가십시오.",
		["Ride back south-east to the Mistvale gorilla hills above {area:35}. {npc:1449} sits among the gorillas: take ten Gorilla Fangs from the Elder Mistvale Gorillas first."] = "남동쪽으로 돌아가 {area:35} 위쪽 안개계곡고릴라 언덕으로 가십시오. {npc:1449}은(는) 고릴라들 사이에 있습니다. 먼저 덩치큰 안개계곡고릴라에게서 고릴라 송곳니 10개를 모으십시오.",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "북쪽으로 {zone:1425} 한가운데의 {area:351}까지 가세요. 초록 진흙괴물과 비취 수액괴물이 그 주변 곳곳을 기어다닙니다.\n주의: 표범이 은신한 채 이 지역을 돌아다닙니다.",
		["Ride on north along the coast to Zanzil's village. Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "해안을 따라 북쪽 잔질의 마을로 계속 가십시오. 모든 잔질 추종자가 혼합물을 떨어뜨릴 수 있습니다. {npc:2537}은(는) 야영지 남쪽을 돌아다닙니다.",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "남동쪽으로 {zone:1425} 남쪽에 있는 썩은가지부족의 계단식 신전 {area:355}(으)로 가서 꼭대기까지 올라가십시오. 퀴아가와 {npc:8636}(정예, 50)이(가) 그곳에 있습니다: 꼭대기에 닿으면 곧바로 내려오십시오.\n주의: {npc:7996}와(과) {npc:8636}을(를) 포함한 정예 트롤과 썩은가지부족 점술가 여럿이 꼭대기 단을 지킵니다. 점술가는 주문을 시전하며 무리의 나머지와 연결되어 있습니다.",
		["The Bloodsail captains"] = "붉은해적단 선장들",
		["The charts and orders lie in the pirate camp on the {area:43}, just south of {area:35}; its Swashbucklers walk the shore. The Warlocks and Swashbucklers (41-43) are under you now."] = "해도와 명령서는 {area:35} 바로 남쪽 {area:43}의 해적 야영지에 있습니다. 해적 검객들이 해안을 돌아다닙니다. 흑마법사와 검객(41-43)은 이제 레벨이 낮습니다.",
		["Tram to {zone:1453}"] = "지하철을 타고 {zone:1453}(으)로",
		["Unbagwa's ritual"] = "운바그와의 의식",
		["Vilebranch Soothsayers"] = "썩은가지부족 예언자",
		["Wildkin feathers"] = "숲올빼미 깃털",
		["Zanzil's village"] = "잔질의 마을",
		["for {npc:2616} in Theramore: keep it, the Un'Goro guide lands there"] = "테라모어의 {npc:2616}에게: 간직하십시오. 운고로 가이드가 그곳에서 끝납니다",
		["{area:1537} inn"] = "{area:1537} 여관",
		["{npc:2487}, top floor"] = "{npc:2487}, 꼭대기 층",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "{npc:2498}의 다음 잔질 심부름은 {zone:1441}에서 시작합니다. 건너뛰세요.",
		["{npc:2535} and {npc:2536} stand together in the hills just north of Zanzil's village."] = "{npc:2535}와(과) {npc:2536}은(는) 잔질의 마을 바로 북쪽 언덕에 함께 서 있습니다.",
		["{npc:270263}, just east of the aviary"] = "{npc:270263}, 그리핀 둥지 바로 동쪽",
		["{npc:7916}'s Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam: pick them up as you ride between the altar and {area:351}."] = "{npc:7916}의 숲올빼미 깃털은 {zone:1425} 곳곳, 올빼미야수가 돌아다니는 {area:348} 남쪽과 동쪽 땅 위에 있습니다. 제단과 {area:351} 사이를 오가며 주우십시오.",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["Below ground"] = "지하",
		["Carry the {object:149047} south along the rim of the Cauldron and light the four Sentry Braziers, from the south-west round to the south-east."] = "{object:149047}을(를) 들고 용광로 가장자리를 따라 남쪽으로 가서, 남서쪽부터 남동쪽까지 돌며 감시용 화로 네 개에 불을 붙이십시오.",
		["Class trainer"] = "직업 전문가",
		["Dorius stands by the road beside the {area:247}. Escort him north-east to {area:1959} and keep him alive; when it is over, read the {object:175704} he leaves on the road."] = "도리우스는 {area:247} 옆 길가에 서 있습니다. 그를 북동쪽 {area:1959}까지 호위하며 살려 두십시오. 끝나면 그가 길에 남긴 {object:175704}을(를) 읽으십시오.",
		["Fly to {area:144}"] = "{area:144}(으)로 비행",
		["Fly to {area:1537}"] = "{area:1537}(으)로 비행",
		["For {npc:8256} in {zone:1455}, at the end of this guide"] = "이 가이드의 마지막에 {zone:1455}의 {npc:8256}에게",
		["Four rune rubbings in {zone:1447}: keep it"] = "{zone:1447}의 룬 탁본 네 개: 간직하십시오",
		["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {zone:1427}: the {area:247} is just inside, in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "{area:144}에서 남쪽 {zone:1418}(으)로 간 다음, 서쪽으로 호드 마을 {area:340}을(를) 지나(거리를 두십시오) 오솔길을 따라 {zone:1427}(으)로 올라가세요. {area:247}은(는) 바로 안쪽 남동쪽에 있습니다. 나무 변소 안의 죄수가 {item:4306} 15개와 그 주변 발굴지의 검은무쇠단 지질학자 8마리 처치를 원합니다. 열쇠를 찾았다면 변소를 열쇠로 열 수도 있습니다.",
		["Golems and elementals"] = "골렘과 정령",
		["Heavy War Golems patrol the floor of the Cauldron below {npc:8479}; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "{npc:8479} 아래 용광로 바닥을 육중한 전투골렘이 순찰하고, 그 사이를 용암 정령이 떠다닙니다. 기름은 골렘과 정령이, 심장은 정령이 떨어뜨립니다.",
		["Listen to {npc:8479}'s story once more."] = "{npc:8479}의 이야기를 한 번 더 들으십시오.",
		["Ride west along the north of the Gorge to {area:1446}, the scaffolded camp on the north-west rim."] = "협곡 북쪽을 따라 서쪽 {area:1446}(으)로 가십시오. 북서쪽 가장자리의 비계가 세워진 야영지입니다.",
		["Searing Lava Spiders"] = "이글거리는 용암거미",
		["Sentry Braziers"] = "감시용 화로",
		["The Grimesilt outhouse"] = "검댕가루 간이화장실",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "포로의 다음 임무인 {zone:1446}의 장부는 {zone:1435}와(과) {zone:1445}(으)로 보냅니다: 건너뛰십시오.",
		["The spiders roam the plateaus and lava pools south of {npc:8436}, on the way to {npc:8479}."] = "거미는 {npc:8436} 남쪽, {npc:8479}에게 가는 길의 고원과 용암 웅덩이를 돌아다닙니다.",
		["The {object:149502} it gives holds a {item:10575}: keep it for {npc:9459} in the {zone:1428}"] = "보상으로 받는 {object:149502}에는 {item:10575}이(가) 들어 있습니다: {zone:1428}의 {npc:9459}에게 가져갈 수 있도록 간직하십시오",
		["The {object:179827} board"] = "{object:179827} 게시판",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:8436} stands inside the Twilight camp at {area:1442}, west of {area:1446}, among Twilight Fire Guards, Idolaters and Geomancers (level 48-49 elites), with {npc:8282} (level 51, rare elite) beside him: {quest:3377} needs a group of 4. Skip it if you are alone."] = "정예 몹입니다. 파티를 맺는 것을 권장하니 함께할 사람을 찾아보십시오. {npc:8436}은(는) {area:1446} 서쪽, {area:1442}의 황혼의 망치단 야영지에서 황혼의망치단 화염경비병, 황혼의망치단 우상숭배자, 황혼의망치단 풍수사(48-49레벨 정예) 사이에 서 있고, 그 옆에는 {npc:8282}(51레벨 희귀 정예)이(가) 있습니다. {quest:3377}에는 4인 파티가 필요합니다. 혼자라면 건너뛰십시오.",
		["To {zone:1455}"] = "{zone:1455}(으)로",
		["Xiggs waits in the {object:32359}."] = "직스 퓨즈라이터는 군사 지구에서 기다립니다({object:32359}).",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443}은(는) 용광로 북쪽에 입구가 있습니다. 비밀조제법: 불꽃 융해촉진제는 위쪽 바위 턱에 있습니다. 더 안쪽 용암 웅덩이에서 인센도사우루스가 헤엄치니 가장자리로 끌어내십시오. 깊숙한 곳의 {npc:14621}와(과) 그의 정예 경비병은 피하십시오.",
		["{area:1446} flight master"] = "{area:1446}의 비행 조련사",
		["{npc:8479} stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "{npc:8479}은(는) {area:1446} 남쪽, 용광로 가장자리에 서 있습니다. 그의 이야기를 들으십시오.",
		["{npc:8509} and the dragonflight's hoard are beside {npc:8479}, on the rim south of {area:1446}."] = "{npc:8509}와(과) 용군단의 보물은 {area:1446} 남쪽 가장자리, {npc:8479} 옆에 있습니다.",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: 수액괴물은 {zone:1448}에 있으니 간직하십시오",
		["{quest:3453} lies on the ground at {npc:8479}'s feet; {quest:3462} stands beside him."] = "{quest:3453}은(는) {npc:8479}의 발치 땅바닥에 놓여 있고, {quest:3462}은(는) 그 옆에 서 있습니다.",
		["{quest:3462}: hand it in on the way back to {area:1446}"] = "{quest:3462}: {area:1446}(으)로 돌아가는 길에 완료하십시오",
		["{zone:1455} flight master"] = "{zone:1455} 비행 조련사",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Back east to {npc:9619} with the glands."] = "분비샘을 들고 동쪽 {npc:9619}에게 돌아가세요.",
		["Crystal clusters stand all over the crater. The pits' Tar Lords (53-54) and the oozes around them (50-54) are over you: take the clusters on the jungle's north-eastern edge, among the Lashers and young beasts (48-50)."] = "수정 무더기는 분화구 곳곳에 있습니다. 구덩이의 우두머리 송진괴물(53-54)과 주변의 수액괴물(50-54)은 레벨이 높습니다: 붉은꽃잎덩굴손과 어린 야수(48-50) 사이, 밀림 북동쪽 가장자리의 수정 무더기를 노리세요.",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "{zone:1452}의 {npc:9298}에게서 끝납니다: 보관하세요",
		["Fly to {area:150}"] = "{area:150}(으)로 비행",
		["Fly to {area:976}"] = "{area:976}(으)로 날아가기",
		["For {npc:7775} in {zone:1444}: keep it"] = "{zone:1444}의 {npc:7775}에게 줄 것: 보관하세요",
		["Lar'korwi Mates and the raft"] = "{npc:9683}와(과) 뗏목",
		["Ride back north-east to {area:976}: {npc:11758} stands on the east side of town."] = "북동쪽 {area:976}(으)로 돌아가세요. {npc:11758}은(는) 마을 동쪽에 서 있습니다.",
		["Ride east into the eastern jungle: Bloodpetal Lashers and Threshers (48-50) drop the petals and {quest:3764}. Crystal clusters stand all over the crater, many around the foot of {area:537}: take a few extra of each colour.\nCareful: the Living Blazes (54-55) walk the top of {area:537}, and the Bloodpetal Flayers and Trappers (51-53) hold the jungle's south: take your crystals from the ridge's foot and your petals in the north.\n{npc:9998}'s scales: the {npc:9165} (48-50) glide over the north-east of the jungle and the Young Diemetradons (49-50) graze beside them. There are only ten of those: the Diemetradons (51) on the jungle's western edge, a short way west of the Threshers, drop the scales too. They are a level over you: take them one at a time."] = "동쪽으로 동쪽 밀림에 들어가세요: 채찍줄기 붉은꽃잎덩굴손과 타작 붉은꽃잎덩굴손(48-50)이 꽃잎과 {quest:3764}을(를) 떨어뜨립니다. 수정 무더기는 분화구 곳곳에 있으며, {area:537} 기슭 주변에 많습니다: 색깔별로 몇 개씩 더 챙기세요.\n주의: 살아있는 불길(54-55)이 {area:537} 꼭대기를 돌아다니고, 칼날가시 붉은꽃잎덩굴손과 덫 붉은꽃잎덩굴손(51-53)이 밀림 남쪽을 차지하고 있습니다: 수정은 산마루 기슭에서, 꽃잎은 북쪽에서 구하세요.\n{npc:9998}의 비늘: {npc:9165}(48-50)가 밀림 북동쪽 위를 날고, 새끼 디메트로돈(49-50)이 그 옆에서 풀을 뜯습니다. 새끼 디메트로돈은 열 마리뿐입니다: 타작 덩굴손에서 조금 서쪽, 밀림 서쪽 가장자리의 디메트로돈(51)도 비늘을 떨어뜨립니다. 레벨이 하나 높으니 한 마리씩 잡으세요.",
		["Ride north-west to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every {npc:271301} and {object:157936} you pass from here on."] = "북서쪽 야영지로 가세요.\n정예 데빌사우루스와 스테고돈은 멀리 피하세요. 여기서부터 지나가는 {npc:271301}와(과) {object:157936}을(를) 모두 챙기세요.",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "남쪽으로 {area:1938}을(를) 지나 하잘리 굴인 {area:981}으로 가십시오. 슈섕크의 측량 장비는 깊숙한 곳에 있습니다.\n주의: 벌레 하나가 장비를 지킵니다. 많은 벌레가 굴을 순찰하며 일부는 50레벨이라, 싸우면 몹이 추가로 끌려오는 경우가 많습니다.",
		["Ride south to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "남쪽 오우거 주둔지로 가세요. 야수와 집행자(46-48)로 가득하고, {npc:12046}(49)이(가) 한가운데에 경비병에 둘러싸여 서 있습니다. 경비병부터 처리하세요.",
		["Ride west into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley.\nCareful: the thistleshrubs wander a lot, so you can easily pull extra mobs."] = "서쪽 {quest:3362}(으)로 가세요. 이슬 수집가가 분비샘을 떨어뜨리는데, 가득 찬 것은 일부뿐이니 가득 찬 것을 챙기세요. 옹이진 덤불나무괴물과 뿌리조각가도 골짜기에 있습니다.\n주의: 덤불나무괴물은 많이 돌아다니므로 몹을 더 끌기 쉽습니다.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "{area:976}에서 서쪽으로 나가 {zone:1449}(으)로 내려가는 긴 비탈로 가세요. {npc:9619}은(는) 분화구 남동쪽 구석, 비탈 아래에 진을 치고 있습니다.",
		["Ride west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "서쪽 모래언덕의 센티파르 벌집으로 가세요. 센티파르는 모두 곤충 부위를 떨어뜨릴 수 있습니다.\n주의: 우두머리 센티파르는 전투 중이든 아니든 {npc:4196}을(를) 시전해 작은 몹을 불러내며, 이들이 행동을 방해합니다.",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "{npc:9683}은(는) {npc:9619} 서쪽 밀림을 어슬렁거립니다. 부서진 뗏목은 그곳 호숫가에 있고, 작은 꾸러미는 그 옆 물속에 있습니다. 나침반, 지도, 열쇠는 {npc:8737}에게 주도록 보관하세요. 분화구의 어떤 야수든 {item:11116}을(를) 떨어뜨릴 수 있습니다. 오른쪽 클릭하세요.",
		["The dead Threshadon lies by the water north of {npc:9619}.\nCareful: Venomhide Ravasaurs (50-51) hunt along the water there: pull them one at a time before you loot the carcass.\nAny ravasaur may drop a {item:280459}: right-click it, {npc:9619} takes it."] = "죽은 쓰레샤돈은 {npc:9619} 북쪽 물가에 있습니다.\n주의: 맹독가죽 라바사우루스(50-51)가 그 물가를 따라 사냥합니다. 사체를 뒤지기 전에 하나씩 끌어 처리하세요.\n라바사우루스는 {item:280459}을(를) 떨어뜨릴 수 있습니다. 우클릭하면 {npc:9619}이(가) 받습니다.",
		["Theramore flight master"] = "테라모어 섬 비행 조련사",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "경로의 이전 방문 때 이것을 놓쳤습니다. 지금 이것부터 합니다. 금방 끝나며 뒤에 이어지는 퀘스트를 열어 줍니다.",
		["{area:537} and the eastern jungle"] = "{area:537}와(과) 동쪽 밀림",
		["{item:11316}, from the Lashers and Threshers"] = "{item:11316}, 붉은꽃잎덩굴손에게서 획득",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616}은(는) 배가 도착하는 부두에 있습니다.",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, 야영지 안쪽",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, 동굴 안쪽, 지하",
		["{npc:9998}: his scales come from the young beasts of the eastern jungle"] = "{npc:9998}: 비늘은 동쪽 밀림의 어린 야수에게서 얻습니다",
		["{quest:3764}, from the Threshers and the dirt piles"] = "{quest:3764}, 타작 덩굴손과 흙더미에서 획득",
		["{quest:87494}, if a ravasaur dropped the scale"] = "{quest:87494}, 라바사우루스가 비늘을 떨어뜨렸다면",
		["{zone:1455} flight master"] = "{zone:1455} 비행 조련사",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "아케소누스는 {object:171709}에서 국왕 마그니 브론즈비어드 옆에 서 있습니다.",
		["Archesonus stands beside King Magni in the {object:171709}: the relics you read in the Steppes are his."] = "아케소누스는 {object:171709}에서 국왕 마그니 브론즈비어드 옆에 서 있습니다. 불타는 평원에서 읽은 유물은 그의 것입니다.",
		["Ardalan is inside {area:1438}."] = "아달란은 {area:1438} 안에 있습니다.",
		["Back south-west to {area:3137}."] = "남서쪽 {area:3137}(으)로 돌아가세요.",
		["Back to the {zone:1419}"] = "{zone:1419}(으)로 돌아가기",
		["Below ground"] = "지하",
		["East along the road to {area:1235}"] = "길을 따라 동쪽 {area:1235}(으)로",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "{zone:1452} {area:2255}의 {quest:4808}에게서 끝납니다: 보관하세요",
		["Fly to {area:1438}"] = "{area:1438}(으)로 날아가기",
		["Fly to {area:144}"] = "{area:144}(으)로 비행",
		["Fly to {area:150}"] = "{area:150}(으)로 비행",
		["Fly to {area:1537}"] = "{area:1537}(으)로 비행",
		["Fly to {area:271}"] = "{area:271}(으)로 날아가세요",
		["Fly to {area:69}"] = "{area:69}(으)로 비행",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "길을 따라 서쪽으로 간 뒤 북쪽으로 올라가 {area:251}의 고블린 야영지로 가세요.",
		["From {area:415}, ride east along the road past {area:2358} into {zone:1447}: {area:1235} lies just over the border, in {zone:1447}'s south-west corner."] = "{area:415}에서 길을 따라 동쪽으로 {area:2358}을(를) 지나 {zone:1447}(으)로 가세요: {area:1235}은(는) 경계 바로 너머, {zone:1447} 남서쪽 구석에 있습니다.",
		["Hearth back to {zone:1455}'s inn."] = "귀환석으로 {zone:1455} 여관에 돌아가십시오.",
		["Into {zone:1447}"] = "{zone:1447}(으)로",
		["Just north-east of the shrine: {npc:239822} and {npc:240482} keep the Alliance camp at {area:3137}."] = "제단 바로 북동쪽: {npc:239822}와(과) {npc:240482}이(가) {area:3137}의 얼라이언스 야영지를 지키고 있습니다.",
		["Kum'isha waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have. Come at her hill straight from the keep, along the road, and leave by the same way.\nCareful: Felcular, {npc:7664} and Ilifar are all level 60 elites. Razelikh casts {spell:2691}, {spell:8255} and Decimate, and as its health drops it adds {object:141891}, {spell:10854} and then Enrage at 15%.\nCareful: {npc:247015}, a level 55 elite, stands by Kum'isha's hill (about 50,35) and to the west (about 39,32), and the Dreadmaul and Shadowsworn camps around it are 53-55: take the fragments from the mobs on the way from the keep, not beside him."] = "쿰이샤는 요새 남서쪽 언덕인 {area:2517}에서 기다립니다. 가는 길의 {zone:1419} 몹이 불완전한 드레니시스트 조각을 떨어뜨립니다. 가진 만큼 가져다주세요. 요새에서 길을 따라 곧장 언덕으로 가고, 같은 길로 돌아오세요.\n주의: 펠큘라, {npc:7664}, 일리파는 모두 60레벨 정예입니다. 라젤리크는 {spell:2691}, {spell:8255}, 대학살을 시전하며, 생명력이 줄어들수록 {object:141891}, {spell:10854}을(를) 더하고 15%에서 격노합니다.\n주의: 55레벨 정예인 {npc:247015}이(가) 쿰이샤의 언덕 옆(약 50,35)과 서쪽(약 39,32)에 있고, 주변의 공포망치 및 어둠맹세 야영지는 53-55레벨입니다. 조각은 그의 옆이 아니라 요새에서 오는 길의 몹에게서 얻으세요.",
		["Listen to his tale, then ride back south to Kum'isha."] = "그의 이야기를 들은 뒤 남쪽으로 쿰이샤에게 돌아가세요.",
		["Mosshoof Coursers"] = "{npc:8761}",
		["Mosshoof Runners"] = "작은 이끼발굽순록",
		["On the road back south, {npc:235903} takes the satyrs."] = "남쪽으로 돌아가는 길에 {npc:235903}에게 사티로스 퀘스트를 제출하세요.",
		["Ride back east along the road to the Vigil."] = "길을 따라 동쪽으로 감시초소에 돌아가세요.",
		["Ride back south to the camp."] = "남쪽 야영지로 돌아가세요.",
		["Ride east out of {area:69} and up the pass into the {zone:1428}: {area:2418} stands at the top."] = "{area:69}에서 동쪽으로 나가 고개를 넘어 {zone:1428}(으)로 가십시오. {area:2418}은(는) 꼭대기에 있습니다.",
		["Ride north from {area:271} into Alterac and west to the walls of {area:279}: {npc:34365} stands outside them. Her quest goes to {npc:266524} in {area:1438}, where this guide flies later."] = "{area:271}에서 북쪽으로 알터랙에 들어가 서쪽으로 {area:279}의 성벽까지 가세요. {npc:34365}은(는) 성벽 밖에 서 있습니다. 그녀의 퀘스트는 이 가이드가 나중에 날아가는 {area:1438}의 {npc:266524}에게 제출합니다.",
		["Ride north out of the {zone:1419} into the {zone:1435}: the {npc:10996} stands by the road from the {zone:1419}. Keep clear of {area:75}, the Horde town to the north-east."] = "{zone:1419}에서 북쪽으로 {zone:1435}에 들어가세요. {npc:10996}은(는) {zone:1419}에서 이어지는 길가에 서 있습니다. 북동쪽의 호드 마을인 {area:75}에는 가까이 가지 마세요.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "제단에서 북동쪽으로 가세요. {npc:8405}은(는) 길 위 언덕의 {area:1224}에 진을 치고 있습니다.",
		["Swim to the small island off the southern tip of {zone:1447}. If {npc:8392} isn't there, fire your {item:10444} to signal him, and wait for him to land."] = "{zone:1447} 남쪽 끝 앞바다의 작은 섬까지 헤엄쳐 가세요. {npc:8392}이(가) 없다면 {item:10444}을(를) 쏘아 신호를 보낸 뒤 착륙할 때까지 기다리세요.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it. {npc:222478} is held in the satyrs' camp: free her and walk her out."] = "명가 유령들이 제단 주변 폐허를 떠돌고, 할다르 사티로스가 그 바로 북쪽 야영지를 차지하고 있습니다. {npc:222478}은(는) 사티로스 야영지에 붙잡혀 있습니다: 풀어 주고 밖까지 호위하세요.",
		["The Mosshoof Runners (45-47) graze the hills north of {area:3137}, on the way to the satyrs."] = "작은 이끼발굽순록(45-47)은 사티로스에게 가는 길목인 {area:3137} 북쪽 언덕에서 풀을 뜯습니다.",
		["The Spitelash Warriors (46-47) and Screamers (47-48) hold the western shore north-east of the satyrs."] = "원한의꼬리일족 전사(46-47)와 절규자(47-48)가 사티로스 북동쪽의 서쪽 해안을 차지하고 있습니다.",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "혈법사들의 두 번째 단계는 같은 재료에 경험치 없이 강화 아이템만 줍니다: 건너뛰십시오.",
		["The relics are in the {zone:1428}: keep it"] = "유물은 {zone:1428}에 있습니다: 보관하세요",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered. Take the ones on the ruins' southern edge, nearest {area:251}.\nCareful: the ruins' War Reavers and Thaurissan Firewalkers are 53-55, and {npc:8978} (57) holds the {object:147516} camp south-west of {area:251}: take the relics at the edge of the ruins, pull one at a time, and keep away from the camp."] = "유물은 {area:251} 주변 {area:250} 곳곳에 흩어진 조각된 돌입니다. 정보를 복원할 때까지 클릭하세요. {area:251}에 가장 가까운 폐허 남쪽 가장자리의 것을 챙기세요.\n주의: 폐허의 전투절단기와 타우릿산 조사단원은 53-55레벨이며, {npc:8978}(57)이(가) {area:251} 남서쪽의 {object:147516} 야영지를 지키고 있습니다. 폐허 가장자리의 유물을 챙기고, 하나씩 끌어오며, 야영지에는 가까이 가지 마세요.",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "섀도송 제단은 {area:3137} 남쪽, {zone:1447} 남서쪽 구석에 있습니다.",
		["The western shore"] = "서쪽 해안",
		["The {area:1221}"] = "{area:1221}",
		["To {zone:1455}"] = "{zone:1455}(으)로",
		["{area:144} flight master"] = "{area:144} 비행 조련사",
		["{item:10575}, from the hoard"] = "{item:10575}, 보물에서",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: {npc:7864}, 약 10%",
		["{npc:222478}, in the camp"] = "{npc:222478}, 야영지 안",
		["{npc:235903} camps by the road north to {npc:8420}: his satyrs are in {npc:8420}'s camp."] = "{npc:235903}은(는) {npc:8420}에게 가는 북쪽 길가에 진을 치고 있습니다. 그의 사티로스는 {npc:8420}의 야영지에 있습니다.",
		["{npc:3546}: {quest:87295}, the scales come from the basilisks ahead"] = "{npc:3546}: {quest:87295}, 비늘은 앞쪽의 바실리스크에게서 얻습니다",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "{npc:8022}의 다음 임무인 {item:9471}은(는) {area:978} 퀘스트입니다: 건너뛰십시오.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him.\nCareful: the Blood Elf Surveyors are 51-52 and the Reclaimers 52-53, with {npc:6647} (53) among them: take the equipment from the camp's edge and pull the elves one at a time.\n{npc:235903}'s satyrs, rogues and hellcallers (51-53) are the Legashi around {npc:8420}'s camp; the Legashi Soulstealers, Hellraisers and Blackguards (53) further east are not part of it: stay west of them."] = "{npc:8420}은(는) 북쪽의 {area:1219}에 진을 치고 있으며, 그의 장비는 바로 남동쪽의 {area:1220} 곳곳에 흩어져 있습니다.\n주의: 블러드 엘프 감정관은 51-52레벨, 회수자는 52-53레벨이며, 그 사이에 {npc:6647}(53)이(가) 있습니다. 야영지 가장자리에서 장비를 챙기고 엘프는 하나씩 끌어오세요.\n{npc:235903}의 사티로스, 도적, 지옥소환사(51-53)는 {npc:8420}의 야영지 주변에 있는 레가쉬 일족입니다. 더 동쪽의 레가쉬 영혼강탈자, 지옥지기, 흑기사(53)는 해당되지 않으니 그 서쪽에 머무르세요.",
		["{npc:9177}' next tasks ({npc:9176}, and fifty Blackrock Medallions) send you among the Blackrock orcs of 55-58 at the foot of {area:254}: skip them."] = "{npc:9177}의 다음 임무({npc:9176}, 그리고 검은바위부족 메달 50개)는 {area:254} 기슭의 55-58레벨 검은바위부족 오크 사이로 보냅니다. 건너뛰세요.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, 요새 꼭대기",
		["{quest:3701} is a group quest at this level: its relics stand among War Reavers and Firewalkers of 53-55, with {npc:8978} (57) close by, two to five over you, and the route has no later {zone:1428} visit. Grouping up is encouraged, look for people to do it with. Skip it if you are alone."] = "{quest:3701}은(는) 이 레벨에서는 파티 퀘스트입니다. 유물은 53-55레벨의 전투절단기와 타우릿산 조사단원 사이에 있고 근처에 {npc:8978}(57)도 있어 당신보다 2~5레벨 높으며, 경로상 이후에 {zone:1428}을(를) 다시 방문하지 않습니다. 파티를 맺는 것을 권장하니 함께할 사람을 찾아보세요. 혼자라면 건너뛰세요.",
		["{zone:1455} flight master"] = "{zone:1455} 비행 조련사",
		["{zone:1455} inn"] = "{zone:1455} 여관",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Back to {npc:14637} on the dock."] = "부두의 {npc:14637}에게 돌아가세요.",
		["Below ground"] = "지하",
		["Careful: {npc:9454} (54) stands at the back of the {area:2481}, at about 32.2,67.1, with Shadowstalkers around him: clear them one at a time, then pull him alone at full health."] = "주의: {npc:9454}(54)은(는) {area:2481} 안쪽 약 32.2,67.1에 있고 주위에 어둠추적자가 있습니다. 하나씩 처리한 뒤 생명력이 가득 찬 상태에서 그만 끌어오세요.",
		["First crater"] = "첫 번째 구덩이",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them.\nCareful: an {npc:7136} (53, elite) stands among the craters: walk round it."] = "길을 따라 북쪽의 구덩이 파인 골짜기로 가서 구덩이마다 들르며, 그 사이의 혼돈의 불길과 혼돈의 소산물을 처치하세요.\n주의: 구덩이 사이에 {npc:7136}(53, 정예)이(가) 서 있습니다. 돌아서 가세요.",
		["From {area:702}, fly to {area:1116}."] = "{area:702}에서 {area:1116}(으)로 날아가세요.",
		["Portal to {zone:1438}"] = "{zone:1438}행 차원문",
		["Putrescent organs: kill these as you meet them"] = "부패한 장기: 만나는 대로 처치",
		["Ride east along the road to {area:2255}."] = "길을 따라 동쪽 {area:2255}(으)로 가세요.",
		["Ride north up the road from the Sanctuary, all the way to the cave mouth of {area:1769}; {npc:15395} guards it."] = "성소에서 길을 따라 북쪽으로 {area:1769}의 동굴 입구까지 쭉 가세요. {npc:15395}이(가) 입구를 지킵니다.",
		["Ride west into the Ravenwind Ruins: {npc:7774} hides in the small round building at the back. Open the chest beside her for {item:9189}: it lasts 15 minutes, like the quest."] = "서쪽 레이븐윈드 폐허로 가세요. {npc:7774}은(는) 안쪽의 작고 둥근 건물에 숨어 있습니다. 그녀 옆의 상자를 열어 {item:9189}을(를) 얻으세요. 퀘스트처럼 15분간 지속됩니다.",
		["Second crater"] = "두 번째 구덩이",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "{area:2618} 동쪽 {area:1767}의 굽이나무정령이 {item:11503}을(를) 가지고 있습니다.",
		["The {area:2479}"] = "{area:2479}",
		["The {item:11242} grows inside a ruined building north of {npc:7765}: climb in through the break in its wall from the ledge beside it."] = "{item:11242}은(는) {npc:7765} 북쪽의 무너진 건물 안에서 자랍니다. 옆의 바위턱에서 벽의 갈라진 틈으로 들어가세요.",
		["Third crater"] = "세 번째 구덩이",
		["{area:1763} again"] = "다시 {area:1763}",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}.\nCareful: {npc:10648} (55) stands at the valley's far end with Hellcallers (53-54) around him: clear them one at a time before you pull him."] = "{area:2618}은(는) 북서쪽의 사티로스 골짜기이며, 맨 끝에 {npc:10648}이(가) 있습니다. 그가 {quest:939}을(를) 떨어뜨리고, 비취불꽃의 사티로스는 누구나 {item:11674}을(를) 떨어뜨릴 수 있습니다.\n주의: {npc:10648}(55)은(는) 골짜기 맨 끝에 있고 주위에 지옥소환사(53-54)가 있습니다. 그를 끌어오기 전에 하나씩 처리하세요.",
		["{area:702} flight master"] = "{area:702} 비행 조련사",
		["{item:18904}, on the Wave and Deep Striders in the water"] = "{item:18904}, 물속의 파도 거인과 성큼걸이 바다거인에게 사용",
		["{item:18958}, from the Sea Sprays"] = "{item:18958}, 바다 물보라 정령에게서",
		["{npc:10920}: {quest:86577}, from the bears and wolves you meet in {zone:1448}"] = "{npc:10920}: {zone:1448}에서 만나는 곰과 늑대로 {quest:86577}",
		["{npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "펄볼그 {npc:11554}은(는) {area:2479} 바로 남쪽 길가에 서 있습니다.",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556}은(는) {area:1769} 터널의 {zone:1452} 쪽 출구, 나오는 바로 그 자리에 서 있습니다.",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395}은(는) {zone:1448} 북쪽 끝에서 기다립니다",
		["{npc:4217}, upstairs"] = "{npc:4217}, 위층",
		["{npc:7740}: {quest:162}, from {area:976}"] = "{npc:7740}: {area:976}에서 받은 {quest:162}",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907}은(는) {npc:7916} 위층에 서 있습니다. 건물 안에서 올라가십시오. 화살표는 층을 구분하지 못합니다.",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, {npc:11554} 바로 동쪽 폐허",
		["{zone:1448}'s Angerclaw bears and Felpaw wolves carry the putrescent organs {npc:10920} wants: the Bears and Wolves (47-48) of the south and the Maulers and Scavengers (49-50) along the road north of {area:1763}. Kill them as you ride between the stops."] = "{zone:1448}의 성난발톱 곰과 악령발 늑대가 {npc:10920}이(가) 원하는 부패한 장기를 지니고 있습니다. 남쪽의 곰과 늑대(47-48), 그리고 {area:1763} 북쪽 길가의 난폭곰과 청소부(49-50)입니다. 지점 사이를 이동하며 처치하세요.",
		["{zone:1455} has no druid trainer"] = "{zone:1455}에는 드루이드 상급자가 없습니다",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Below ground"] = "지하",
		["Bones and equipment"] = "뼈와 장비",
		["Careful: Ancient Irontree Walkers, level 59 elites, stand among the {quest:5086}: work the Horrors at the camp's north-east tip (about 50.6,22.4), one at a time, and look for a walker before each pull."] = "주의: 59레벨 정예 Ancient Irontree Walker가 {quest:5086} 사이에 서 있습니다. 야영지 북동쪽 끝(약 50.6,22.4)의 소산물을 하나씩 처치하고, 끌어오기 전마다 보행자가 있는지 살피십시오.",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "분화구 남쪽을 가로질러 비탈 옆의 {npc:9619}에게 가세요.",
		["Eastern Pylon and the crate"] = "동쪽 수정탑과 상자",
		["Escort {npc:9999}"] = "{npc:9999} 호위",
		["Fly to Theramore"] = "테라모어 섬으로 비행",
		["Northern Pylon"] = "북쪽 수정탑",
		["Pristine Yeti Horns"] = "온전한 설인 뿔",
		["Ride back south-east to the Sanctuary."] = "남동쪽의 성소로 돌아가세요.",
		["Ride east along the road to {area:2255}."] = "길을 따라 동쪽 {area:2255}(으)로 가세요.",
		["Ride east to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "동쪽으로 {area:1943}까지 가세요. 로봇은 고릴라들 사이에 서 있습니다. 그곳의 깊은 동굴에는 들어가지 마세요.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "동쪽으로 {area:537}까지 가서 올라간 뒤, 꼭대기 근처 용암 분출구에서 {npc:10541}을(를) 사용하세요.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "동쪽을 따라 북쪽의 고릴라 고원으로 가세요. 55레벨 고릴라 {npc:9622}은(는) 가장 깊은 동굴에 있습니다. 먼저 동굴 입구의 고릴라를 정리하세요.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "남서쪽으로 {area:1938}의 {npc:7771} 야영지로 가세요.",
		["The Gorishi hive"] = "고리쉬 벌집",
		["The Tar Beasts and Tar Lords wallow in the {area:538}, south of the refuge on the way down into the crater."] = "타르 야수와 타르 군주는 분화구로 내려가는 길에 있는 피난처 남쪽의 {area:538}에서 뒹굴고 있습니다.",
		["The crater"] = "분화구",
		["The gorillas live on {area:1943}, just east of the pylon: take the pelts for {npc:9619} now, while you are up here. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "고릴라는 수정탑 바로 동쪽의 {area:1943}에 삽니다. 여기 올라온 김에 지금 {npc:9619}에게 줄 가죽을 모으세요. 가장 깊은 동굴에는 들어가지 마세요. {npc:9622}은(는) 55레벨입니다.\n주의: 운고로 고릴라(50-51레벨)는 생명력이 25%로 떨어지면 20미터 안의 동료를 불러 도움을 요청합니다. 이 지역에는 고릴라로 가득한 동굴이 있어, 그곳에서 싸우면 많은 적이 몰려듭니다.",
		["The pelts come from the gorillas on {area:1943}"] = "가죽은 {area:1943}의 고릴라에게서 모읍니다",
		["The pylon stands on the eastern cliffs above {npc:9684}'s lair; the expedition's {item:11113} sits at the abandoned camp in the eastern jungle."] = "수정탑은 {npc:9684}의 굴 위 동쪽 절벽에 있습니다. 탐험대의 {item:11113}은(는) 동쪽 밀림의 버려진 야영지에 있습니다.",
		["The pylon stands on the western cliffs."] = "수정탑은 서쪽 절벽에 있습니다.",
		["The wooden sign beside {npc:9997}"] = "{npc:9997} 옆의 나무 표지판",
		["The {area:2479}"] = "{area:2479}",
		["The {item:280417} is a short ride west of {npc:9619}'s camp."] = "{item:280417}은(는) {npc:9619}의 야영지에서 서쪽으로 조금만 가면 있습니다.",
		["Wait a moment for {npc:9116}"] = "{npc:9116}을(를) 잠시 기다리세요",
		["West along the south of the crater: the Gorishi hive fills it. Use the Scraping Vial on a hatchery, a chamber with hanging larvae."] = "분화구 남쪽을 따라 서쪽으로 가세요. 고리시 벌집이 그곳을 채우고 있습니다. 애벌레가 매달린 방인 부화장에 긁개 유리병을 사용하세요.",
		["Western Pylon"] = "서쪽 수정탑",
		["{area:1770} braziers"] = "{area:1770} 화로",
		["{area:1943}: kill these as you meet them"] = "{area:1943}: 만나는 대로 처치하세요",
		["{area:541} flight master"] = "{area:541} 비행 조련사",
		["{area:976} flight master"] = "{area:976} 비행 조련사",
		["{npc:10301}'s camp"] = "{npc:10301}의 야영지",
		["{npc:8496}, inside"] = "{npc:8496}, 내부",
		["{npc:9299} is a ghost at the graveyard just east of town: drink a {item:11243} there, which kills you, release your spirit and talk to him as a ghost. Then run back to your body to come back to life: the gravestone stands nearby."] = "{npc:9299}은(는) 마을 바로 동쪽 묘지에 있는 유령입니다. 그곳에서 {item:11243}을(를) 마시면 죽습니다. 영혼을 해방한 뒤 유령 상태로 그에게 말을 거세요. 그런 다음 시체로 달려가 되살아나세요. 묘비는 근처에 있습니다.",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999}은(는) 분화구 한가운데 {area:537}의 남동쪽 비탈에 앉아 있습니다.",
		["{quest:4291}, if you still carry it from the first visit"] = "{quest:4291}, 첫 방문 때부터 아직 가지고 있다면",
		["{quest:87494}, if a ravasaur dropped the scale since the first visit"] = "{quest:87494}, 첫 방문 이후 라바사우루스가 비늘을 떨어뜨렸다면",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "안돌할",
		["Boat to {area:150}"] = "배를 타고 {area:150}(으)로",
		["Diseased Grizzlies"] = "오염된 불곰",
		["Fly to {area:150}"] = "{area:150}(으)로 비행",
		["Fly to {area:1537}"] = "{area:1537}(으)로 비행",
		["Fly to {area:271}"] = "{area:271}(으)로 날아가세요",
		["Fly to {area:3197}"] = "{area:3197}(으)로 비행",
		["Fly to {area:442}"] = "{area:442}(으)로 비행",
		["For {npc:11053} at {area:3197}, at the end of this guide"] = "이 가이드 마지막에 {area:3197}의 {npc:11053}에게 가져갑니다",
		["For {zone:1453}: keep it"] = "{zone:1453}용: 보관하세요",
		["Listen to his story"] = "그의 이야기를 들으세요",
		["Mark {npc:10902} with the {item:12815}"] = "{item:12815}(으)로 {npc:10902} 표시",
		["Mark {npc:10903} with the {item:12815}"] = "{item:12815}(으)로 {npc:10903} 표시",
		["Mark {npc:10904} with the {item:12815}"] = "{item:12815}(으)로 {npc:10904} 표시",
		["Mark {npc:10905} with the {item:12815}"] = "{item:12815}(으)로 {npc:10905} 표시",
		["Portal to {zone:1438}"] = "{zone:1438}행 차원문",
		["Pureheart, Dumah, Valorfist and MacDonnell stand around the middle of the camp, by the flight master."] = "퓨어하트, 두마, 밸러피스트, 맥도넬은 야영지 한가운데, 비행 조련사 옆에 서 있습니다.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "북쪽 길을 따라 북마루 벌목지로 가세요. {npc:11610}은(는) 벌목지 가장자리에 숨어 있습니다.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "북서쪽 {area:2277} 가장자리의 {area:2276}(으)로 가세요.",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones while you wear the {quest:5401} (equip it as a trinket first).\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "해골 타작꾼과 걸신들린 구울이 야영지 북쪽 들판을 돌아다닙니다. {quest:5401}을(를) 착용하고 있으면 이곳의 모든 스컬지가 스컬지석을 떨어뜨립니다(먼저 장신구로 착용하세요).\n주의: 이 언데드들은 멀리서도 알아차리며, 하나를 끌면 근처의 다른 언데드도 싸움에 합류합니다.\n주의: {npc:10411}(3곳 출현, 15분 재생성)은 전투 중이 아닐 때 투명해지며, 전투가 시작되면 바위날개 가고일을 부릅니다.",
		["The Andorhal watchtowers"] = "안돌할 감시탑",
		["The Scarlet Crusade"] = "붉은십자군",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "붉은십자군 의무병, 붉은십자군 사냥꾼, 붉은십자군 기사, 붉은십자군 마법사가 벌목지와 {area:190}(으)로 가는 길을 순찰합니다.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "인형 조각 세 개는 {area:2262}의 무너진 집들에 있습니다. 하나를 주울 때 유령이 나타날 수 있습니다. 조각을 합쳐 인형을 만드세요.",
		["Underwater"] = "물속",
		["Upstairs"] = "위층",
		["{area:190} overlook"] = "{area:190} 전망 지점",
		["{area:199} cauldron"] = "{area:199} 가마솥",
		["{area:202} cauldron"] = "{area:202} 가마솥",
		["{area:702} flight master"] = "{area:702} 비행 조련사",
		["{item:12841}: wear the {quest:5401} while you kill"] = "{item:12841}: 처치할 때 {quest:5401}을(를) 착용하세요",
		["{item:12894}, at the monument"] = "기념비의 {item:12894}",
		["{npc:10926}'s doll"] = "{npc:10926}의 인형",
		["{npc:10927}: keep it for {area:2262}"] = "{npc:10927}: {area:2262}을(를) 위해 보관하세요",
		["{npc:11063}'s next task, at {area:2264}, is among Scourge of 57-60: skip it."] = "{npc:11063}의 다음 임무는 {area:2264}의 57-60레벨 스컬지 사이에서 해야 하니 건너뛰세요.",
		["{npc:11610} hides at the lumber camp's edge."] = "{npc:11610}은(는) 벌목지 가장자리에 숨어 있습니다.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}, {object:2096} 안",
		["{npc:1852} is a level 61 elite"] = "{npc:1852}은(는) 61레벨 정예입니다",
		["{npc:332}, in SI:7"] = "{npc:332}, SI:7 안",
		["{npc:3520}, who walks the canals"] = "{npc:3520}, 운하를 걸어다님",
		["{npc:4217}, upstairs"] = "{npc:4217}, 위층",
		["{object:175924}, in the farmhouse; inside"] = "농가 안의 {object:175924}, 안",
		["{quest:5210}, at {area:2268}: keep it"] = "{area:2268}의 {quest:5210}: 보관하세요",
		["{zone:1455} flight master"] = "{zone:1455} 비행 조련사",
		["{zone:1455} has no druid trainer"] = "{zone:1455}에는 드루이드 상급자가 없습니다",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Below ground"] = "지하",
		["Bronzebeard's Encampment"] = "브론즈비어드 야영지",
		["From the hold, west into the sands: Dredge Crushers dig there; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "요새에서 서쪽 모래밭으로 가세요. 망치미늘벌레가 그곳을 파고 있으며, 돌꼬리집게전갈, 가죽벗기기전갈, 긴다리 바위거미도 같은 모래밭에서 사냥합니다.",
		["Hand him the ten texts you kept"] = "보관해 둔 문서 10개를 그에게 건네세요",
		["Havunth's camp sits just west of {area:3425}.\nCareful: Havunth is level 60: clear his camp first and fight him at full health."] = "하분스의 야영지는 {area:3425} 바로 서쪽에 있습니다.\n주의: 하분스는 60레벨입니다. 야영지를 먼저 정리하고 생명력이 가득 찬 상태에서 싸우세요.",
		["Into {zone:1451}"] = "{zone:1451}(으)로",
		["Level 60"] = "60레벨",
		["Ride back south-east to the hermit."] = "남동쪽으로 은둔자에게 돌아가세요.",
		["Ride back south-west to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "남서쪽으로 돌아가 {area:2738}의 {area:2742} 탑으로 가세요. 탑에 올라 딱딱한 실리시드 조각을 노리고 나타나는 잠복꾼을 처치하세요.",
		["Ride north along the west side to Mayna's small camp.\nCareful: Mayna is level 60: clear her camp first and fight her at full health."] = "서쪽을 따라 북쪽으로 마이나의 작은 야영지로 가세요.\n주의: 마이나는 60레벨입니다. 야영지를 먼저 정리하고 생명력이 가득 찬 상태에서 싸우세요.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand south-east of the camp, where Deathclasp, an elite scorpid, patrols: grab it while he is away."] = "남서쪽으로 남쪽 산맥 근처의 드워프 야영지에 가서 {npc:15171}와(과) {npc:15170}에게 물어보세요. {npc:15190}의 가방은 야영지 남동쪽 모래 속에 있는데, 그곳에는 정예 전갈 Deathclasp이(가) 순찰합니다. 그가 자리를 비운 사이에 챙기세요.",
		["Ten more for {quest:8323}"] = "{quest:8323}에 10개 더",
		["The hermit hides among the rocks south-east of {area:2738}."] = "은둔자는 {area:2738} 남동쪽 바위 사이에 숨어 있습니다.",
		["The {area:2742} tower"] = "{area:2742} 탑",
		["The {area:3098}"] = "{area:3098}",
		["Twilight Tablet Fragments"] = "{item:20378}",
		["Twilight's Hammer cultists"] = "황혼의 망치단 이교도",
		["{npc:15183}: the tablet fragments come from the Twilight dig"] = "{npc:15183}: 서판 조각은 황혼의 발굴지에서 얻습니다",
		["{npc:15189}, upstairs"] = "{npc:15189}, 위층",
		["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp.\nCareful: You lose the Silithyst if you mount, stealth, use {spell:642}, {spell:5384} or Vanish. Blink and {spell:17} do not drop it."] = "{npc:17080}은(는) 서쪽 벌집인 {area:2743} 바깥에 진을 치고 있습니다. 근처 붉은 간헐천에서 실리시스트를 집어 그의 야영지에 있는 얼라이언스 추출기로 가져가세요.\n주의: 탈것을 타거나, 은신하거나, {spell:642}, {spell:5384}, 소멸을 사용하면 실리시스트를 잃습니다. 점멸과 {spell:17}은(는) 떨어뜨리지 않습니다.",
		["{npc:17082}, at the Alliance tents: for {npc:17080} at {area:2743}"] = "얼라이언스 천막의 {npc:17082}: {area:2743}의 {npc:17080}에게 가져갑니다",
} end)()
t.guides["forever/alliance/dwarf/01-dun-morogh"] = (function() return {
		["Back east through {area:131}: {npc:1252} by Eric's campfire takes the {quest:287} report, and {npc:1269} the cogs and gears. The Shaman quest here waits for level 10: a Shaman still short of it finishes on the Ice Claw Bears (7-8), Snow Leopards and Large Crag Boars in the fields just south of {area:131}."] = "{area:131}을(를) 지나 동쪽으로 돌아가세요. 에릭의 모닥불 옆 {npc:1252}에게 {quest:287} 보고를, {npc:1269}에게 톱니와 기어를 제출합니다. 이곳의 주술사 퀘스트는 10레벨이 필요합니다. 아직 모자라는 주술사는 {area:131} 바로 남쪽 들판의 얼음발톱흰곰(7-8), 눈표범, 큰 멧돼지를 잡아 채우세요.",
		["Back north to {area:77} on the way to the tunnel: {npc:2756} stands by {npc:8416} at its door. Gozwin's camp is in the hills just north-west; the {npc:269075} (level 6) prowls around it."] = "터널로 가는 길에 북쪽 {area:77}으로 돌아가세요. {npc:2756}은(는) 문 앞에서 {npc:8416} 옆에 서 있습니다. 고즈윈의 야영지는 바로 북서쪽 언덕에 있으며, {npc:269075}(6레벨)이(가) 그 주변을 배회합니다.",
		["Back north to {npc:257808}'s camp above the tunnel. {npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "굴 위쪽 {npc:257808}의 야영지로 북쪽으로 돌아가세요. {npc:257808}이(가) {item:6636}을(를) 줍니다. 그의 야영지 위 봉우리로 올라가 정령석 옆에서 삽타를 마시고 {npc:5893}을(를) 물리친 뒤, 영원의 불꽃 제단 꼭대기의 {object:61934}에 {item:6655}을(를) 넣으세요.",
		["Back through the tunnel to {npc:257597}' cave above the farm, then west along the road to {zone:1455}."] = "굴을 지나 농장 위 {npc:257597}의 동굴로 돌아간 뒤, 길을 따라 서쪽 {zone:1455}(으)로 가세요.",
		["Back to the {area:136}, the wendigo cave south-west of {area:131} where {npc:271546} camps. Flintfire's shipments lie on the cave floor, {npc:278166} is missing deep inside, and {quest:98326} (level 9) keeps the {item:280426} at the back.\nCareful: Wendigos, Elder Wendigos and Wendigo Shamans (up to level 8) stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks avoids this."] = "{npc:271546}이(가) 야영하는, {area:131} 남서쪽의 웬디고 동굴 {area:136}(으)로 돌아가세요. 플린트파이어의 화물은 동굴 바닥에 있고, {npc:278166}은(는) 동굴 깊숙한 곳에서 실종되었으며, {quest:98326}(9레벨)이(가) 안쪽 끝에서 {item:280426}을(를) 지키고 있습니다.\n주의: 동굴 안에는 웬디고, 장로 웬디고, 웬디고 주술사(최대 8레벨)가 붙어 있어 여러 마리가 한꺼번에 끌려오기 쉽습니다. 원거리 공격으로 한 마리씩 끌어내면 피할 수 있습니다.",
		["Back to {area:77}"] = "{area:77}(으)로 돌아가기",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "{area:77}의 {npc:257446}에게 돌아가세요. 그가 {item:6635}을(를) 줍니다. 골짜기 남쪽에서 서쪽으로 올라가는 돌무더기 표시 길을 따라 능선의 정령석까지 가서, 그 옆에서 삽타를 마시고 {npc:5891}에게 말을 건 뒤, 그 {item:6656}을(를) 테오에게 가져가세요.",
		["Back to {npc:257597}"] = "{npc:257597}에게 돌아가기",
		["Below ground"] = "지하",
		["Brewnall: kill these as you meet them"] = "브루날: 마주치는 대로 처치하세요",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "멧돼지와 새끼 흑곰이 럼블샷의 야영지에서 북동쪽 {area:131}와(과) 정거장까지 들판을 돌아다닙니다. 돌아오는 길에 처치하세요.",
		["Druid trainer"] = "드루이드 상급자",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "그리프 와일드하트의 퀘스트마다 {item:15908}을(를) 줍니다. 그가 지정한 야수에게 사용한 뒤, {area:131} 대장간의 그에게 막대를 가져가세요. 큰 바위멧돼지, 눈표범, 얼음발톱흰곰 모두 {area:131} 바로 남쪽과 동쪽 들판을 돌아다닙니다.",
		["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats. Shamans: the Tunnel Rat Geomancers (level 12-13) here carry the {item:5026}.\nCareful: the Tunnel Rat Geomancers (12-13) cast from range in the narrow tunnels: pull them one at a time."] = "언덕을 따라 동쪽으로 호수 북쪽 끝의 광산으로 가세요. 광부 연맹 상자들이 굴 안 동굴쥐일족 사이에 있습니다. 주술사: 이곳의 동굴쥐일족 흙점쟁이(12-13레벨)가 {item:5026}을(를) 지니고 있습니다.\n주의: 동굴쥐일족 흙점쟁이(12-13)는 좁은 굴에서 원거리 주문을 시전합니다. 한 마리씩 끌어오세요.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "파르센은 서쪽에서 {area:134}을(를) 내려다보는 능선에 진을 치고 있습니다. 그에게 말을 걸어 원시를 받으세요.",
		["Feather Charms, from the Frostmane Novices"] = "깃털 부적, 서리갈기부족 견습마법사에게서",
		["Firewood"] = "장작",
		["Follow the road east past the depot to {area:138}."] = "길을 따라 동쪽으로 정거장을 지나 {area:138}까지 가세요.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "{area:131}에서 길을 따라 북동쪽으로 {zone:1455} 길 아래의 정거장까지 가세요.",
		["From the {quest:2997} she gives you"] = "그녀가 주는 {quest:2997}에서",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "{npc:706}은(는) {npc:786}의 야영지 남쪽과 동쪽 비탈에 가득합니다.",
		["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}. The den comes after {area:137}, once its level 8 Elder Wendigos and Shamans are no longer above you."] = "그레첸은 {area:131} 남서쪽의 웬디고 동굴인 {area:136} 바로 밖에 야영하고 있습니다. 이 동굴은 {area:137} 다음에, 8레벨 장로 웬디고와 주술사가 더 이상 레벨이 높지 않을 때 가세요.",
		["Heal and fortify {npc:12427}"] = "{npc:12427} 치유 및 강화하기",
		["Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake and {area:137}."] = "얼음발톱흰곰, 덩치큰 멧돼지, 눈표범이 호수와 {area:137} 주변 언덕을 돌아다닙니다.",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "{item:264356}, 야영지 위 비탈의 {npc:706}에게서",
		["Inside {area:77}"] = "{area:77} 안",
		["Leper Gnomes wander the {area:133} road north of {area:137} and carry the cogs and gears. {area:135} comes next, in the hills south-west of the village.\nCareful: the Leper Gnomes (8-10) walk the road in twos and threes, and many players died here: pull them one at a time."] = "오염된 노움은 {area:137} 북쪽 {area:133} 길을 돌아다니며 톱니와 기어를 지니고 있습니다. 다음은 마을 남서쪽 언덕의 {area:135}입니다.\n주의: 오염된 노움(8-10)은 두세 마리씩 길을 다니며 많은 플레이어가 여기서 죽었습니다. 한 마리씩 끌어오세요.",
		["Level 4 spells"] = "4레벨 주문",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "새끼 회색갈기늑대가 {area:77} 바로 남쪽 눈밭을 돌아다닙니다.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "바위턱일족 망치잡이, 바위턱일족 뼈다귀싸움꾼, 바위턱일족 잠복꾼이 채석장과 그 북쪽 비탈에 함께 있으며, 잠복꾼이 {item:268548}을(를) 떨어뜨립니다.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "바위턱트로그와 힘센 바위턱트로그가 {area:77} 남쪽 골짜기 바닥 곳곳에서 땅을 팝니다.",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "에릭의 모닥불 옆에 앉아(/sit 입력) 버프를 기다리세요. 전문 기술을 배웠다면 에릭은 해당 기술의 야영 101도 주며, 그 기술의 상급자에게 제출합니다: 대장기술은 {npc:1241}, {skill:129}은(는) {area:131}의 {npc:2326}, 채광과 기계공학은 {area:189}에서.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "작은 멧돼지가 {npc:714}의 야영지 주변과 골짜기 서쪽을 따라 풀을 뜯습니다.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "눈표범과 멧돼지가 농장과 채석장 사이 눈밭을 돌아다닙니다. 대장장이: 구리 주괴는 {item:2770}을(를) 제련하거나 직업용품 상인에게서 구합니다.",
		["South down the road past the tunnel post into {area:923}: the Stonesplinter Seers (level 13-14) stand among the troggs in its middle. Stay out of the far south end, where Shamans and Bonesnappers (level 15-16) camp, and keep clear of Headsplitter (15) on his walk. The Seers come with other troggs and cast from range: pull one at a time."] = "굴 초소를 지나 길을 따라 남쪽 {area:923}(으)로 가세요. 가루바위일족 점쟁이(13-14레벨)가 중앙의 트로그들 사이에 있습니다. 주술사와 뼈다귀분쇄자(15-16레벨)가 진을 친 남쪽 끝은 피하고, 돌아다니는 헤드스플리터(15)도 멀리하세요. 점쟁이는 다른 트로그와 함께 있고 원거리 주문을 시전합니다. 한 마리씩 끌어오세요.",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "길을 따라 남쪽으로 {area:144}까지 내려가면서 귀, 고기, 체액을 마저 모으세요. {npc:1340}은(는) 마을을 지나는 길을 걸어 다닙니다.",
		["The Fire Spirit Stone"] = "불의 정령석",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "두르난의 뜨거운 새벽주는 5분 동안 유지됩니다. 곧장 북쪽으로 {area:77} 안의 {npc:836}에게 가세요.",
		["The boars"] = "멧돼지",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "장작은 피난처 옆 얼어붙은 호수 주변 눈밭에 있습니다.",
		["The quarry troggs"] = "채석장 트로그",
		["The troggs"] = "트로그",
		["The troll cave"] = "트롤 동굴",
		["The tunnel"] = "굴",
		["The {area:133} road"] = "{area:133} 길",
		["The {area:2257}"] = "{area:2257}",
		["The {item:6652}"] = "{item:6652}",
		["The {object:269} in the basement"] = "지하실의 {object:269}",
		["Tram to {zone:1453}"] = "지하철을 타고 {zone:1453}(으)로",
		["Upstairs"] = "위층",
		["Use the {item:6866} on {npc:6177}"] = "{npc:6177}에게 {item:6866}을(를) 사용하세요",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "당신은 골짜기 북쪽 끝의 석조 전당인 {area:77} 앞에서 시작합니다. {npc:658}은(는) 문 밖에서 기다립니다.",
		["Young wolves"] = "새끼 늑대",
		["talk to the trainer"] = "상급자에게 말을 거세요",
		["{area:131} and the depot"] = "{area:131}와(과) 정거장",
		["{area:77} is on the way north from {npc:786}'s camp to the tunnel: {npc:837}, the priest trainer inside, sends priests of level 5 to {npc:1226} in {area:131}."] = "{area:77}은(는) {npc:786}의 야영지에서 굴로 가는 북쪽 길목에 있습니다. 안에 있는 사제 상급자 {npc:837}이(가) 5레벨 사제를 {area:131}의 {npc:1226}에게 보냅니다.",
		["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}, 야영지 안",
		["{item:280426}: {quest:98326}, at the back"] = "{item:280426}: 안쪽 끝의 {quest:98326}",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325}은(는) 얼어붙은 호수 옆, 얼음 정령들 사이에 있습니다.",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: 오염된 노움",
