		["{npc:1702}, beside {npc:5392}"] = "{npc:1702}, {npc:5392} 옆",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965}은(는) {area:77} 동쪽, 골짜기 밖으로 나가는 굴을 지킵니다. {npc:6782}은(는) 굴 입구에서 그 옆에 서 있습니다.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, 채석장 안",
		["{npc:2326} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:129} 숙련도가 20이 되면 {npc:2326}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:2326}, inside the distillery"] = "{npc:2326}, 양조장 안",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}, {area:77} 안",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}: {npc:5873}와(과) {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597}은(는) {area:806} 북서쪽 농장 위의 동굴에서 기다립니다. 올라가는 길은 농장 뒤에서 시작합니다.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, {item:5176}, {item:263412}",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: 남문 옆 {npc:257597}에게 제출합니다",
		["{npc:265813}: for {npc:1241}, in the cellar west of the distillery"] = "{npc:265813}: 양조장 서쪽 지하실의 {npc:1241}에게",
		["{npc:265813}: for {npc:1702} at {area:189}"] = "{npc:265813}: {area:189}의 {npc:1702}에게",
		["{npc:265813}: for {npc:2326} in the {area:2102}"] = "{npc:265813}: {area:2102}의 {npc:2326}에게",
		["{npc:265813}: for {npc:5392} at {area:189}"] = "{npc:265813}: {area:189}의 {npc:5392}에게",
		["{npc:4256} works at the {object:32372}'s north end, and {npc:1573} keeps the gryphons in the {object:32372}, where the flight from {area:144} lands."] = "{npc:4256}은(는) {object:32372} 북쪽 끝에서 일하고, {npc:1573}은(는) {area:144}에서 오는 비행편이 내리는 {object:32372}에서 그리핀을 돌봅니다.",
		["{npc:460}, inside {area:77}"] = "{npc:460}, {area:77} 안",
		["{npc:5392} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:186} 숙련도가 20이 되면 {npc:5392}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:5392}, at the depot"] = "{npc:5392}, 정거장에서",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480}은(는) {object:2100}의 오스릭 상점 근처에서 전사를 훈련시킵니다. {zone:1455}에서 오는 지하철은 그 북쪽의 {object:28027}에 도착합니다. {npc:6089}와(과) {npc:6090}은(는) 그곳 {object:2152} 옆에 함께 서 있습니다. {npc:6090}은(는) 자기 잔을 걸고 당신과 싸웁니다. {npc:5480}이(가) {quest:1638}을(를) 주지 않으면 곧장 {npc:6089}에게 가세요. 그는 그 퀘스트 없이도 {quest:1639}을(를) 줍니다.",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: {zone:1453}의 {npc:6122}에게 제출합니다",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122}은(는) {object:2101}에 있는 {object:2164}의 지하실에서 기다립니다.",
		["{npc:6179}: Redemption"] = "{npc:6179}: 구원",
		["{npc:658}: a rune for {npc:895}"] = "{npc:658}: {npc:895}에게 줄 룬",
		["{npc:658}: read the {quest:98581}"] = "{npc:658}: {quest:98581}을(를) 읽으세요",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, {npc:658} 옆",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "{npc:714}의 야영지는 골짜기 서쪽 끝에 있습니다. {item:10438}은(는) 그 남쪽 눈밭에, 펠릭스의 궤짝은 트롤 동굴 옆에, 펠릭스의 나사통은 동굴 동쪽에 있습니다. 지나가면서 챙기세요.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786}와(과) {npc:12738}은(는) 트롤 동굴 아래, 골짜기 남서쪽 가장자리에 진을 치고 있습니다.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808}은(는) {npc:786}의 야영지 동쪽 트롤 동굴 안에 있습니다. 그 위 언덕이 아닙니다. 입구로 들어가 굴을 따라 안쪽 끝까지 가세요.",
		["{npc:837}, inside {area:77}"] = "{npc:837}, {area:77} 안",
		["{npc:837}, the priest trainer"] = "{npc:837}, 사제 상급자",
		["{npc:895}, the hunter trainer"] = "{npc:895}, 사냥꾼 상급자",
		["{npc:916}, the rogue trainer"] = "{npc:916}, 도적 상급자",
		["{npc:926}, the paladin trainer"] = "{npc:926}, 성기사 상급자",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, {object:171524}의 우체통 옆",
		["{quest:1688}: her choker and The Binding are on {zone:1436}'s east-Elwynn loop"] = "{quest:1688}: 그녀의 목걸이와 '속박'은 {zone:1436} 가이드의 엘윈 동부 순회에서 처리합니다",
} end)()
t.guides["forever/alliance/gnome/01-dun-morogh"] = (function() return {
		["Back east through {area:131}: {npc:1252} by Eric's campfire takes the {quest:287} report, and {npc:1269} the cogs and gears. The Shaman quest here waits for level 10: a Shaman still short of it finishes on the Ice Claw Bears (7-8), Snow Leopards and Large Crag Boars in the fields just south of {area:131}."] = "{area:131}을(를) 지나 동쪽으로 돌아가세요. 에릭의 모닥불 옆 {npc:1252}에게 {quest:287} 보고를, {npc:1269}에게 톱니와 기어를 제출합니다. 이곳의 주술사 퀘스트는 10레벨이 필요합니다. 아직 모자라는 주술사는 {area:131} 바로 남쪽 들판의 얼음발톱흰곰(7-8), 눈표범, 큰 멧돼지를 잡아 채우세요.",
		["Back north to {area:77} on the way to the tunnel: {npc:2756} stands by {npc:8416} at its door. Gozwin's camp is in the hills just north-west; the {npc:269075} (level 6) prowls around it."] = "터널로 가는 길에 북쪽 {area:77}으로 돌아가세요. {npc:2756}은(는) 문 앞에서 {npc:8416} 옆에 서 있습니다. 고즈윈의 야영지는 바로 북서쪽 언덕에 있으며, {npc:269075}(6레벨)이(가) 그 주변을 배회합니다.",
		["Back north to {npc:257808}'s camp above the tunnel. {npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "굴 위쪽 {npc:257808}의 야영지로 북쪽으로 돌아가세요. {npc:257808}이(가) {item:6636}을(를) 줍니다. 그의 야영지 위 봉우리로 올라가 정령석 옆에서 삽타를 마시고 {npc:5893}을(를) 물리친 뒤, 영원의 불꽃 제단 꼭대기의 {object:61934}에 {item:6655}을(를) 넣으세요.",
		["Back through the tunnel to {npc:257597}' cave above the farm, then west along the road to {zone:1455}."] = "굴을 지나 농장 위 {npc:257597}의 동굴로 돌아간 뒤, 길을 따라 서쪽 {zone:1455}(으)로 가세요.",
		["Back to the {area:136}, the wendigo cave south-west of {area:131} where {npc:271546} camps. Flintfire's shipments lie on the cave floor, {npc:278166} is missing deep inside, and {quest:98326} (level 9) keeps the {item:280426} at the back.\nCareful: Wendigos, Elder Wendigos and Wendigo Shamans (up to level 8) stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks avoids this."] = "{npc:271546}이(가) 야영하는, {area:131} 남서쪽의 웬디고 동굴 {area:136}(으)로 돌아가세요. 플린트파이어의 화물은 동굴 바닥에 있고, {npc:278166}은(는) 동굴 깊숙한 곳에서 실종되었으며, {quest:98326}(9레벨)이(가) 안쪽 끝에서 {item:280426}을(를) 지키고 있습니다.\n주의: 동굴 안에는 웬디고, 장로 웬디고, 웬디고 주술사(최대 8레벨)가 붙어 있어 여러 마리가 한꺼번에 끌려오기 쉽습니다. 원거리 공격으로 한 마리씩 끌어내면 피할 수 있습니다.",
		["Back to {area:77}"] = "{area:77}(으)로 돌아가기",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "{area:77}의 {npc:257446}에게 돌아가세요. 그가 {item:6635}을(를) 줍니다. 골짜기 남쪽에서 서쪽으로 올라가는 돌무더기 표시 길을 따라 능선의 정령석까지 가서, 그 옆에서 삽타를 마시고 {npc:5891}에게 말을 건 뒤, 그 {item:6656}을(를) 테오에게 가져가세요.",
		["Back to {npc:257597}"] = "{npc:257597}에게 돌아가기",
		["Below ground"] = "지하",
		["Brewnall: kill these as you meet them"] = "브루날: 마주치는 대로 처치하세요",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "멧돼지와 새끼 흑곰이 럼블샷의 야영지에서 북동쪽 {area:131}와(과) 정거장까지 들판을 돌아다닙니다. 돌아오는 길에 처치하세요.",
		["Druid trainer"] = "드루이드 상급자",
		["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats. Shamans: the Tunnel Rat Geomancers (level 12-13) here carry the {item:5026}.\nCareful: the Tunnel Rat Geomancers (12-13) cast from range in the narrow tunnels: pull them one at a time."] = "언덕을 따라 동쪽으로 호수 북쪽 끝의 광산으로 가세요. 광부 연맹 상자들이 굴 안 동굴쥐일족 사이에 있습니다. 주술사: 이곳의 동굴쥐일족 흙점쟁이(12-13레벨)가 {item:5026}을(를) 지니고 있습니다.\n주의: 동굴쥐일족 흙점쟁이(12-13)는 좁은 굴에서 원거리 주문을 시전합니다. 한 마리씩 끌어오세요.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "파르센은 서쪽에서 {area:134}을(를) 내려다보는 능선에 진을 치고 있습니다. 그에게 말을 걸어 원시를 받으세요.",
		["Feather Charms, from the Frostmane Novices"] = "깃털 부적, 서리갈기부족 견습마법사에게서",
		["Firewood"] = "장작",
		["Follow the road east past the depot to {area:138}."] = "길을 따라 동쪽으로 정거장을 지나 {area:138}까지 가세요.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "{area:131}에서 길을 따라 북동쪽으로 {zone:1455} 길 아래의 정거장까지 가세요.",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "{npc:706}은(는) {npc:786}의 야영지 남쪽과 동쪽 비탈에 가득합니다.",
		["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}. The den comes after {area:137}, once its level 8 Elder Wendigos and Shamans are no longer above you."] = "그레첸은 {area:131} 남서쪽의 웬디고 동굴인 {area:136} 바로 밖에 야영하고 있습니다. 이 동굴은 {area:137} 다음에, 8레벨 장로 웬디고와 주술사가 더 이상 레벨이 높지 않을 때 가세요.",
		["Heal and fortify {npc:12427}"] = "{npc:12427} 치유 및 인내",
		["Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake and {area:137}."] = "얼음발톱흰곰, 덩치큰 멧돼지, 눈표범이 호수와 {area:137} 주변 언덕을 돌아다닙니다.",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "{item:264356}, 야영지 위 비탈의 {npc:706}에게서",
		["Inside {area:77}"] = "{area:77} 안",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "정문으로 {zone:1453}을(를) 나가십시오. {quest:1861} 폭포는 성문 남서쪽, 서쪽 {zone:1436}(으)로 가는 길에 있습니다. 폭포 아래에서 {item:7207}을(를) 채우십시오.",
		["Leper Gnomes wander the {area:133} road north of {area:137} and carry the cogs and gears. {area:135} comes next, in the hills south-west of the village.\nCareful: the Leper Gnomes (8-10) walk the road in twos and threes, and many players died here: pull them one at a time."] = "오염된 노움은 {area:137} 북쪽 {area:133} 길을 돌아다니며 톱니와 기어를 지니고 있습니다. 다음은 마을 남서쪽 언덕의 {area:135}입니다.\n주의: 오염된 노움(8-10)은 두세 마리씩 길을 다니며 많은 플레이어가 여기서 죽었습니다. 한 마리씩 끌어오세요.",
		["Level 4 spells"] = "4레벨 주문",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "새끼 회색갈기늑대가 {area:77} 바로 남쪽 눈밭을 돌아다닙니다.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "바위턱일족 망치잡이, 바위턱일족 뼈다귀싸움꾼, 바위턱일족 잠복꾼이 채석장과 그 북쪽 비탈에 함께 있으며, 잠복꾼이 {item:268548}을(를) 떨어뜨립니다.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "바위턱트로그와 힘센 바위턱트로그가 {area:77} 남쪽 골짜기 바닥 곳곳에서 땅을 팝니다.",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "에릭의 모닥불 옆에 앉아(/앉기 입력) 강화 효과를 기다리세요. 전문 기술을 배웠다면 에릭은 해당 기술의 야영 101도 주며, 그 기술의 전문 기술자에게 제출합니다. 대장기술은 {npc:1241}, {skill:129}은(는) {area:131}의 {npc:2326}, 채광과 기계공학은 {area:189}입니다.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "작은 멧돼지가 {npc:714}의 야영지 주변과 골짜기 서쪽을 따라 풀을 뜯습니다.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "눈표범과 멧돼지가 농장과 채석장 사이 눈밭을 돌아다닙니다. 대장장이: 구리 주괴는 {item:2770}을(를) 제련하거나 직업용품 상인에게서 구합니다.",
		["South down the road past the tunnel post into {area:923}: the Stonesplinter Seers (level 13-14) stand among the troggs in its middle. Stay out of the far south end, where Shamans and Bonesnappers (level 15-16) camp, and keep clear of Headsplitter (15) on his walk. The Seers come with other troggs and cast from range: pull one at a time."] = "굴 초소를 지나 길을 따라 남쪽 {area:923}(으)로 가세요. 가루바위일족 점쟁이(13-14레벨)가 중앙의 트로그들 사이에 있습니다. 주술사와 뼈다귀분쇄자(15-16레벨)가 진을 친 남쪽 끝은 피하고, 돌아다니는 헤드스플리터(15)도 멀리하세요. 점쟁이는 다른 트로그와 함께 있고 원거리 주문을 시전합니다. 한 마리씩 끌어오세요.",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "길을 따라 남쪽으로 {area:144}까지 내려가면서 귀, 고기, 체액을 마저 모으세요. {npc:1340}은(는) 마을을 지나는 길을 걸어 다닙니다.",
		["The Fire Spirit Stone"] = "불의 정령석",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "두르난의 뜨거운 새벽주는 5분 동안 유지됩니다. 곧장 북쪽으로 {area:77} 안의 {npc:836}에게 가세요.",
		["The boars"] = "멧돼지",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "장작은 피난처 옆 얼어붙은 호수 주변 눈밭에 있습니다.",
		["The quarry troggs"] = "채석장 트로그",
		["The troggs"] = "트로그",
		["The troll cave"] = "트롤 동굴",
		["The tunnel"] = "굴",
		["The {area:133} road"] = "{area:133} 길",
		["The {area:2257}"] = "{area:2257}",
		["The {item:6652}"] = "{item:6652}",
		["The {object:269} in the basement"] = "지하실의 {object:269}",
		["Tram to {zone:1453}"] = "지하철을 타고 {zone:1453}(으)로",
		["Upstairs"] = "위층",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "당신은 골짜기 북쪽 끝의 석조 전당인 {area:77} 앞에서 시작합니다. {npc:658}은(는) 문 밖에서 기다립니다.",
		["Young wolves"] = "새끼 늑대",
		["talk to the trainer"] = "전문 기술자에게 말 걸기",
		["{area:131} and the depot"] = "{area:131}와(과) 정거장",
		["{area:77} is on the way north from {npc:786}'s camp to the tunnel: {npc:837}, the priest trainer inside, sends priests of level 5 to {npc:1226} in {area:131}."] = "{area:77}은(는) {npc:786}의 야영지에서 북쪽으로 굴까지 가는 길에 있습니다. 그 안의 사제 상급자 {npc:837}은(는) 5레벨 사제를 {area:131}의 {npc:1226}에게 보냅니다.",
		["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}, 야영지 안",
		["{item:280426}: {quest:98326}, at the back"] = "{item:280426}: 안쪽 끝의 {quest:98326}",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325}은(는) 얼어붙은 호수 옆, 얼음 정령들 사이에 있습니다.",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: 오염된 노움",
		["{item:3084}: Leper Gnomes"] = "{item:3084}: 오염된 노움",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: 동굴쥐일족 흙점쟁이",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, 정령석 옆",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}, 정령석 옆",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}: 가루바위일족 점쟁이",
		["{npc:1226}, upstairs: {item:16605}"] = "{npc:1226}, 위층: {item:16605}",
		["{npc:1226}: heal {npc:12427} south of {area:131}"] = "{npc:1226}: {area:131} 남쪽의 {npc:12427} 치유",
		["{npc:1241} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:164} 숙련도가 20이 되면 {npc:1241}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:1241}, in the cellar west of the distillery"] = "{npc:1241}, 양조장 서쪽 지하실",
		["{npc:12427} kneels wounded on the ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer, on the walk back from Rumbleshot's camp. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12427}은(는) {area:131} 바로 남쪽, 낮은 두 담 사이 능선에 부상당한 채 무릎을 꿇고 있습니다. 사냥꾼 야수 조련사 맞은편 길 건너이며, 럼블샷의 야영지에서 돌아오는 길에 있습니다. 그에게 {spell:613}(2레벨)을 시전한 뒤 {spell:1243}을(를) 시전하세요. {spell:613} 1레벨은 인정되지 않습니다.",
		["{npc:1252} stands by Eric's campfire in front of the {area:2102}; {npc:1241} is in the cellar west of it. {npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1252}은(는) {area:2102} 앞 에릭의 모닥불 옆에 서 있고, {npc:1241}은(는) 그 서쪽 지하실에 있습니다. {npc:1373}은(는) 양조장 지하에서 {item:2686} 통을 지키고 있습니다. {npc:1247}에게서 {item:2686}을(를) 사서 지켜지는 통을 클릭한 뒤, {npc:1373}의 퀘스트 창에서 맥주를 건네세요(수락할 퀘스트는 없습니다). 그 후에는 지키는 이 없는 통에 {spell:8553}을(를) 넣을 수 있습니다.",
		["{npc:12738}, next to him"] = "{npc:12738}, 그의 옆",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: 시간 제한, 5분 안에 {area:77}의 {npc:836}에게 가야 합니다",
		["{npc:1573}, the gryphon master in the {object:32372}"] = "{npc:1573}, {object:32372}의 그리핀 조련사",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}: 대장장이만",
		["{npc:1702} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:202} 숙련도가 20이 되면 {npc:1702}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:1702}, beside {npc:5392}"] = "{npc:1702}, {npc:5392} 옆",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965}은(는) {area:77} 동쪽, 골짜기 밖으로 나가는 굴을 지킵니다. {npc:6782}은(는) 굴 입구에서 그 옆에 서 있습니다.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, 채석장 안",
		["{npc:2326} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:129} 숙련도가 20이 되면 {npc:2326}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:2326}, inside the distillery"] = "{npc:2326}, 양조장 안",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}, {area:77} 안",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}: {npc:5873}와(과) {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597}은(는) {area:806} 북서쪽 농장 위의 동굴에서 기다립니다. 올라가는 길은 농장 뒤에서 시작합니다.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, {item:5176}, {item:263412}",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: 남문 옆 {npc:257597}에게 제출합니다",
		["{npc:258785}: {quest:94817}, her own copy of the letter"] = "{npc:258785}: {quest:94817}, 그녀 자신의 편지 사본",
		["{npc:265813}: for {npc:1241}, in the cellar west of the distillery"] = "{npc:265813}: 양조장 서쪽 지하실의 {npc:1241}에게 제출",
		["{npc:265813}: for {npc:1702} at {area:189}"] = "{npc:265813}: {area:189}의 {npc:1702}에게 제출",
		["{npc:265813}: for {npc:2326} in the {area:2102}"] = "{npc:265813}: {area:2102}의 {npc:2326}에게 제출",
		["{npc:265813}: for {npc:5392} at {area:189}"] = "{npc:265813}: {area:189}의 {npc:5392}에게 제출",
		["{npc:4256} works at the {object:32372}'s north end, and {npc:1573} keeps the gryphons in the {object:32372}, where the flight from {area:144} lands."] = "{npc:4256}은(는) {object:32372} 북쪽 끝에서 일하고, {npc:1573}은(는) {area:144}에서 오는 비행편이 내리는 {object:32372}에서 그리핀을 돌봅니다.",
		["{npc:460}, inside {area:77}"] = "{npc:460}, {area:77} 안",
		["{npc:5392} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:186} 숙련도가 20이 되면 {npc:5392}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:5392}, at the depot"] = "{npc:5392}, 정거장에서",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480}은(는) 오스릭의 상점 근처 {object:2100}에서 전사를 훈련시킵니다. {zone:1455}에서 오는 지하철은 그 북쪽의 {object:28027}에 도착합니다. {npc:6089}와(과) {npc:6090}은(는) 그곳 {object:2152} 옆에 함께 서 있습니다. {npc:6090}은(는) 자기 잔을 걸고 당신과 싸웁니다. {npc:5480}이(가) {quest:1638}을(를) 주지 않으면 곧장 {npc:6089}에게 가세요. 그는 그 퀘스트 없이도 {quest:1639}을(를) 줍니다.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497}은(는) {object:2101}의 탑인 마법사의 성소에 서 있습니다. 그녀가 {quest:1861} 폭포용 플라스크를 줍니다.",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: {zone:1453}의 {npc:6122}에게 제출합니다",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122}은(는) {object:2101}에 있는 {object:2164}의 지하실에서 기다립니다.",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, {npc:658} 옆",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "{npc:714}의 야영지는 골짜기 서쪽 끝에 있습니다. {item:10438}은(는) 그 남쪽 눈밭에, 펠릭스의 궤짝은 트롤 동굴 옆에, 펠릭스의 나사통은 동굴 동쪽에 있습니다. 지나가면서 챙기세요.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786}와(과) {npc:12738}은(는) 트롤 동굴 아래, 골짜기 남서쪽 가장자리에 진을 치고 있습니다.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808}은(는) {npc:786}의 야영지 동쪽 트롤 동굴 안에 있습니다. 그 위 언덕이 아닙니다. 입구로 들어가 굴을 따라 안쪽 끝까지 가세요.",
		["{npc:837}, inside {area:77}"] = "{npc:837}, {area:77} 안",
		["{npc:837}, the priest trainer"] = "{npc:837}, 사제 상급자",
		["{npc:912}, the warrior trainer"] = "{npc:912}, 전사 상급자",
		["{npc:916}, the rogue trainer"] = "{npc:916}, 도적 상급자",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, 마법사 상급자, {area:77} 안",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, {object:171524}의 우체통 옆",
		["{quest:1688}: her choker and The Binding are on {zone:1436}'s east-Elwynn loop"] = "{quest:1688}: 그녀의 목걸이와 '속박'은 {zone:1436} 가이드의 엘윈 동부 순회에서 처리합니다",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "버니스 \"아줌마\" 스톤필드",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "{npc:6122}에게 돌아가십시오. {object:2164} 지하실의 소환진에서 {item:6928}을(를) 사용하고 소환된 공허방랑자를 쓰러뜨리십시오.",
		["Billy plays in the {area:64}, east of the mine."] = "빌리는 광산 동쪽 {area:64}에서 놀고 있습니다.",
		["Chunks of Boar Meat"] = "멧돼지 고기",
		["Class trainer"] = "직업 전문가",
		["Crystal Kelp Fronds"] = "투명한 해초 잎",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "데피아즈단 견습마술사가 {area:86} 기슭에 야영하며, 붉은 리넨 복면도 떨어뜨립니다. {object:56}은(는) 북동쪽 기슭의 멀록 마을에 있습니다.\n주의: 견습마술사는 원거리에서 주문을 쓰고, {npc:6866}(10)이(가) 함께 기슭을 돌아다닙니다. 한 마리씩 끌어오세요.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "데피아즈단원이 대성당 동쪽 빈터와 골짜기 동쪽을 따라 야영하고 있습니다.",
		["Druid trainer"] = "드루이드 상급자",
		["Follow the hills south to the tower, on the road west."] = "언덕을 따라 남쪽, 서쪽 길가의 탑으로 가십시오.",
		["Follow the hills south to the tower."] = "언덕을 따라 남쪽 탑으로 가십시오.",
		["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "길을 따라 동쪽으로 {area:91}을(를) 지나 다리로 가십시오. 다리 남쪽 강 주변의 굶주린 늑대와 새끼 숲곰을 마저 처치하십시오.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "길을 따라 북쪽으로 {area:87}에서 {zone:1453}(으)로 가십시오. {npc:5497}은(는) {object:2101}의 탑인 마법사의 성소에 있으며, {quest:1861} 폭포용 플라스크를 줍니다.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "길을 따라 북쪽으로 {area:87}에서 {zone:1453}(으)로 가십시오. {npc:6122}은(는) {object:2101} {object:2164}의 지하실에서 기다립니다.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "길을 따라 남쪽으로 {area:87}을(를) 빠져나가 {area:64}(으)로 가십시오. {npc:251}이(가) 집 옆에서 기다립니다.",
		["Fun with Elementals: {npc:248464}"] = "그림책: 정령과 놀기: {npc:248464}",
		["He stands by the river west of the farm."] = "그는 농장 서쪽 강가에 있습니다.",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "{area:87}을 통해 돌아 나와 도로를 따라 동쪽 {area:62}으로 가세요. {npc:881} (9레벨)이 농가 옆에 있습니다.",
		["Heal and fortify {npc:12423}"] = "{npc:12423} 치유 및 강화하기",
		["Inside {area:34}"] = "{area:34} 안",
		["It lies by the river north-west of the logging camp."] = "벌목장 북서쪽 강가에 있습니다.",
		["Large Candles"] = "큰 양초",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "정문으로 {zone:1453}을(를) 나가십시오. {quest:1861} 폭포는 성문 남서쪽, 서쪽 {zone:1436}(으)로 가는 길에 있습니다. 폭포 아래에서 {item:7207}을(를) 채우십시오.",
		["Lost Books: Kobold Miners and Tunnelers"] = "잃어버린 책: 코볼트 광부와 코볼트 채굴꾼",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "멀록과 멀록 길잡이가 동쪽 기슭을 차지하고 있으며, 잡동사니 더미는 그들의 야영지에 있습니다. 주의: 멀록들이 서로 가까이 붙어 있어 전투 중에 두세 마리가 한꺼번에 끌려오기 쉽습니다. 야영지 가장자리에서 한 마리씩 끌어내고, 쫓아가다 다음 무리로 들어가지 마십시오.",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "벌목장 북동쪽입니다. 데피아즈단 견습마술사가 호숫가에 야영합니다.\n주의: 견습마술사는 원거리에서 주문을 쓰고, {npc:6866}(10)이(가) 함께 기슭을 돌아다닙니다. 한 마리씩 끌어오세요.",
		["Painted Gnoll Armbands"] = "놀의 화려한 완장",
		["Red Burlap Bandanas"] = "붉은 삼베 복면",
		["Red Linen Bandanas"] = "붉은 리넨 복면",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "갈퀴발일족 심부름꾼과 갈퀴발일족 길잡이가 주둔지 남쪽, {zone:1436} 경계를 따라 언덕을 차지하고 있습니다.",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "갈퀴발일족 놀이 {area:86} 서쪽 언덕에 야영하며, {quest:91725}은(는) 그들의 야영지에 있습니다.",
		["She stands by her cart at the vineyard east of the Abbey."] = "그녀는 대성당 동쪽 포도밭의 수레 옆에 있습니다.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "윤기나는 빨간 사과, {npc:894}에게서, {quest:91736}용",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "{spell:1229451} 효과를 얻을 때까지 그의 모닥불 옆에 앉으세요(/앉기)",
		["South down the road to the {area:64}."] = "길을 따라 남쪽 {area:64}(으)로 가십시오.",
		["Subdue the voidwalker"] = "공허방랑자 제압",
		["The Defias camp"] = "데피아즈단 야영지",
		["The Fishing Traps sit along the west shore of the lake."] = "{object:694772}은(는) 호수 서쪽 기슭을 따라 놓여 있습니다.",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "스톤필드 농장은 광산 서쪽에 있습니다.\n그녀는 농가 안에 앉아 있습니다. 스톤필드 부인과 버니스 \"아줌마\"가 집 옆에 있습니다.",
		["The bridge"] = "다리",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it.\nCareful: Elmpaw, a level 12 elite gnoll, walks the woods and hills from the logging camp north to {area:86} and the gnoll camps: keep clear of him when you see him coming."] = "야영지는 다리 북동쪽에 있습니다. 나무 묶음은 야영지 주변과 그 북쪽 숲에 놓여 있습니다.\n주의: 12레벨 정예 놀인 엘름포가 벌목장에서 북쪽 {area:86}와(과) 놀 야영지까지 숲과 언덕을 돌아다닙니다. 다가오는 것이 보이면 피하세요.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "포도 상자는 데피아즈단 뒤쪽 포도밭에 있습니다. {npc:103}은(는) 골짜기 동쪽 끝 오두막 옆에서 기다립니다.",
		["The gnoll camps"] = "놀 야영지",
		["The kobold camp"] = "코볼트 야영지",
		["The lake shore"] = "호숫가",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "광산은 놀 야영지 남서쪽에 있습니다. {item:247816}은(는) 입구 근처에 있고, 터널은 코볼트 흙점쟁이가 지키고 있습니다.\n주의: {npc:471}(7-10), 굴거미(7-9), {npc:248474}(7)은(는) 광산 깊숙한 곳의 정예입니다. 입구 근처에서 코볼트를 하나씩 끌어오고, 정예가 다가오면 물러나세요. 친구와 함께하면 더 쉽습니다.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "광산은 포도밭 서쪽에 있습니다. 코볼트 광부와 코볼트 굴착꾼이 두 층 모두에 가득합니다. 이름 있는 코볼트 {npc:248464}이(가) 아래쪽 터널에서 그림책을 가지고 있습니다. {npc:248464}은(는) 정예이므로 파티를 권장합니다.",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too.\nCareful: {npc:276180}, a level 11 rare murloc, walks the river by {npc:261}' bridge, east of the Prowlers' woods: leave him be."] = "동쪽 기슭의 멀록이 해초를 떨어뜨립니다. 무두질: 회색 숲늑대가 호수와 {area:91} 사이 숲을 돌아다니며, 더 동쪽의 굶주린 늑대도 가죽을 줍니다.\n주의: 11레벨 희귀 멀록인 {npc:276180}이(가) 굶주린 늑대 숲 동쪽, {npc:261}의 다리 옆 강을 따라 돌아다닙니다. 건드리지 마세요.",
		["The vineyards and {npc:103}"] = "포도밭과 {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Young Forest Bears on the way; the Prowlers (level 9-10) wait for the walk back to {npc:261}, after the logging camp and the mine. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group; otherwise leave him: it's optional."] = "{item:247813}, 도끼, 연장통은 다리 남쪽 강에 있습니다. 큰 멧돼지인 {npc:330}은(는) 강 서쪽 {area:62}에서 {npc:390}와(과) 함께 땅을 파헤칩니다. 새끼 돼지부터 떼어 내세요. 가는 길에 새끼곰을 처치하세요. 굶주린 늑대(9-10레벨)는 벌목장과 광산을 마친 뒤 {npc:261}에게 돌아가는 길에 잡으세요. 주의: {npc:248278}은(는) 멀록 해안의 11레벨 정예입니다. 파티가 있을 때만 그의 머리를 노리세요. 아니면 건드리지 마세요. 선택 사항입니다.",
		["The {quest:91736}"] = "{quest:91736}",
		["Walk into the mine"] = "광산 안으로 걸어가기",
		["Walk through the mine"] = "광산 안을 걸어가기",
		["Wolves"] = "늑대",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "대성당 앞에서 시작합니다. {npc:823}은(는) 계단 아래에, {npc:197}은(는) 홀 안에, {npc:951}와(과) {npc:247229}은(는) 오른쪽 도서관에, {npc:196}은(는) 북서쪽 모퉁이 밖에 있습니다.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "새끼 늑대와 회색 늑대가 대성당 바로 주변 들판을 돌아다닙니다.",
		["grind on {npc:1922}"] = "{npc:1922} 사냥",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "그의 코볼트 추적기가 {area:87}(으)로 가는 길에 클릭할 코볼트를 보여 줍니다",
		["talk to the trainer"] = "상급자와 대화하기",
		["{item:247824}, from the still"] = "{item:247824}, 증류기에서",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: 돌엄니멧돼지",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: 데피아즈단 야영지의 {object:83763}",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423}은(는) {area:18} 서쪽 기슭의 낚시 덫 사이, 나무 옆에 부상을 입고 무릎 꿇고 있습니다. 그에게 {spell:613}(2레벨)을 시전한 뒤 {spell:1243}을(를) 시전하십시오. {spell:613} 1레벨은 인정되지 않습니다. 두 주문이 모두 적용되면 떠나며, 약 3분 뒤에 돌아옵니다.",
		["{npc:1632} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:165} 숙련도가 20이 되면 {npc:1632}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}, {npc:6306} 옆",
		["{npc:1651} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:356} 숙련도가 20이 되면 {npc:1651}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: {item:15908}(으)로 길들이기",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, 마법사 상급자, 대성당 안",
		["{npc:2329} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:129} 숙련도가 20이 되면 {npc:2329}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}, 사자무리 여관 안",
		["{npc:247229}, in the library; inside"] = "{npc:247229}, 도서관, 안",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242}와(과) {npc:248248}은(는) 탑 아래에 있습니다.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, 대성당 옆",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507}은(는) {area:87} 상급자들과 함께 있습니다. 퀘스트마다 {item:15908}을(를) 주니, 지정한 야수에게 사용한 뒤 막대를 그녀에게 가져가십시오. 돌가죽멧돼지와 새끼곰은 {area:64} 남쪽 언덕에, 회색 숲늑대는 {area:18} 동쪽 숲에 있습니다.",
		["{npc:253}, back in the inn"] = "{npc:253}, 다시 여관 안",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, 그녀 옆: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261}이(가) 동쪽 길의 다리를 지키며, {npc:248265}은(는) 바로 건너편에 있습니다.",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}."] = "{npc:263399}은(는) 여관 북동쪽에 야영하고 있습니다. 전문 기술을 배웠다면 해당 기술의 야영 기초 퀘스트도 주며, 이는 해당 기술 상급자가 받습니다. 무두질, 가죽세공, 낚시는 호숫가에서, {skill:129}와(과) 대장기술은 {area:87}에서 받습니다.",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}: 호숫가의 {npc:1632}에게",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}: 호숫가의 {npc:1651}에게",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}: 사자무리 여관의 {npc:2329}에게",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}: {area:87} 대장간의 {npc:514}에게",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}: 호숫가의 {npc:6306}에게",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: {zone:1453}의 {npc:5497}이(가) 받습니다",
		["{npc:375}, the priest trainer"] = "{npc:375}, 사제 상급자",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}, 사제 상급자: {area:87}의 {npc:377}이(가) 받습니다",
		["{npc:377}, upstairs"] = "{npc:377}, 위층",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}, 위층: {item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}: {area:18}에서 {npc:12423} 치유하기",
		["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377}: {zone:1453}의 {npc:376}이(가) 받습니다",
		["{npc:459}, outside the Abbey"] = "{npc:459}, 대성당 밖",
		["{npc:514} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:164} 숙련도가 20이 되면 {npc:514}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:514}, at the smithy across the road"] = "{npc:514}, 길 건너 대장간",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: {item:15908}(으)로 길들이기",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: {zone:1453}의 {npc:6122}이(가) 받습니다",
		["{npc:6306} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:393} 숙련도가 20이 되면 {npc:6306}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}, 마을 동쪽 호숫가; 실내",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}, {npc:383}, {npc:1651}은(는) 마을 동쪽 {area:18} 호숫가에 있습니다.",
		["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306}: 무두질 전용, 가죽은 무두질로 얻습니다. 안",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, 대성당 남쪽 마구간 옆",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6}이(가) 대성당 북동쪽 포도밭을 파헤치고 있습니다. 가끔 {quest:91741}을(를) 떨어뜨리니 오른쪽 클릭하십시오.",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: {item:15908}(으)로 길들이기",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, 대성당 계단으로 돌아가기",
		["{npc:911}, the warrior trainer; inside"] = "{npc:911}, 전사 상급자, 안",
		["{npc:915}, the rogue trainer"] = "{npc:915}, 도적 상급자",
		["{npc:925}, the paladin trainer"] = "{npc:925}, 성기사 상급자",
		["{npc:952}, upstairs"] = "{npc:952}, 위층",
		["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955}: {item:247824}을(를) 원합니다. 안",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}: {area:108}의 {npc:234}를 위해",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "{object:694855}은(는) 포도밭과 스톤필드 농장 주변 밭에서 자라며, 주변의 돌엄니멧돼지가 피를 줍니다.\n돌엄니멧돼지는 포도밭과 농장 사이에서 풀을 뜯습니다.",
		["{quest:76}'s entrance"] = "{quest:76} 입구",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it.\nCareful: {npc:248464} (6), a kobold deep in the mine, is elite, and {npc:79} (10, rare) walks the tunnels: pull the kobolds one at a time."] = "{quest:87}은(는) 언덕 위가 아니라 {area:57} 안에 있습니다. 입구로 들어가 왼쪽을 따라 광산 바닥 안쪽까지 가세요. 위층 계단은 오르지 마세요. 포도밭 주변의 데피아즈단 좀도둑이 가끔 {item:1972}을(를) 떨어뜨리니 오른쪽 클릭하세요.\n주의: 광산 깊은 곳의 코볼트 {npc:248464}(6)은(는) 정예이고, {npc:79}(10, 희귀)이(가) 터널을 돌아다닙니다. 코볼트를 하나씩 끌어오세요.",
		["{quest:91733} and {npc:330}"] = "{quest:91733}와(과) {npc:330}",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "{spell:1229451}을(를) 얻을 때까지 {npc:265811}의 모닥불 옆에서 /앉기 하세요",
		["Back at {area:256}"] = "{area:256}(으)로 돌아가기",
		["Back to the moonwell."] = "달샘으로 돌아가세요.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "{area:256} 꼭대기로 돌아가세요. {object:654846}은(는) 그 옆에 있습니다.",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "거미를 처치하고 {npc:272116}의 이끼를 챙겨 위층의 {npc:3567}에게 돌아가세요.",
		["Befouled Webwoods"] = "오염된 나무그물거미",
		["Below ground"] = "지하",
		["Bloodfeather harpies"] = "붉은깃털일족 하피",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn {area:493}'s flight path from {npc:10897}, south of the lake, for later trips. Then {npc:11800} in {area:2361} flies Druids straight to {area:702} from her gossip: hers is no flight path to learn. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있고, {quest:5929}은(는) 북서쪽 숲에 있습니다. 나중을 위해 호수 남쪽의 {npc:10897}에게서 {area:493} 비행 경로를 배우세요. 그다음 {area:2361}의 {npc:11800}이(가) 대화로 드루이드를 {area:702}까지 곧장 태워 줍니다. 배울 비행 경로는 아닙니다. {npc:11802}은(는) 건물 위층에 있습니다. 안에서 올라가세요. 화살표는 층을 구분하지 못합니다.",
		["Crawler Legs: the Tide Crawlers"] = "게 다리: 왕바닷게",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "다잘라의 퀘스트마다 {item:15908}을(를) 줍니다. 그가 말한 야수에게 사용한 뒤 {area:186}의 그에게 막대를 가져가세요. 나무그물 늑대거미는 마을 주변을 기어 다니고, 긴발톱 흑호와 비명소리 스트리기드 올빼미는 마을 남쪽 숲을 돌아다닙니다.",
		["East along the road to {area:186}."] = "길을 따라 동쪽 {area:186}(으)로 가세요.",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "{npc:275744}을(를) 지하굴 밖으로 호위하세요. 보고는 {area:186}의 {npc:2081}에게 하세요.",
		["Fandral in {zone:1457} takes it"] = "{zone:1457}의 판드랄 스테그헬름에게 가져가세요",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "악의 열매는 {area:186}와(과) {npc:2150} 주변 나무 아래 곳곳에 있습니다. 동쪽 길에서 주워 {npc:7234}에게 가는 길에 {npc:2150}에게 건네세요.",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "한 번 더 {area:702}(으)로 날아가 차원문을 타고 {npc:4217}에게 간 뒤, {area:442}(으)로 날아가세요.",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "{area:188}에서 남서쪽 길을 따라가세요. {npc:2150}은(는) {area:186} 바로 동쪽 길가에 앉아 있습니다.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "나무옹이일족 복병이 {area:258} 서쪽 길을 따라 숨어 있습니다.",
		["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "나무옹이일족 비술사와 {npc:7234}이(가) {area:260} 북동쪽에서 야영합니다. {npc:7234}이(가) {item:8049}을(를) 떨어뜨리니 열어서 보석을 꺼내세요.\n주의: {npc:7234}은(는) 비술사들에 둘러싸여 모닥불 근처에서 기다리므로, 다른 몹 없이 그만 끌어오기 어렵습니다.",
		["Gnarlpine Shamans"] = "나무옹이일족 주술사",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "{area:702}(으)로 다시 내려가 {area:442}(으)로 날아가세요. {object:177525}은(는) 마을 바로 동쪽 언덕에 있습니다. 그곳에서 {item:15208}을(를) 사용하고, 초승달발톱을 물리친 뒤 {npc:12144}와(과) 대화하세요.",
		["Grells (level 2-3) carry {item:3297} in the woods west of the tree, by the totems. The {npc:1989} further north are level 3-4: the Grells by the totems are enough."] = "나무 서쪽 숲, 토템 옆의 그렐(2-3레벨)이 {item:3297}을(를) 지니고 있습니다. 더 북쪽의 {npc:1989}은(는) 3-4레벨이니, 토템 옆의 그렐만으로 충분합니다.",
		["Heal and fortify {npc:12429}"] = "{npc:12429}을(를) 치유하고 인내력 강화하기",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "{area:256} 남동쪽 길로 {area:188}을(를) 떠나세요. {area:186}(으)로 가는 길로 내려가는 곳에 {npc:6780}이(가) 서 있습니다.",
		["Level 12 spells while you're in the Temple of the Moon: the priest trainers stand beside {npc:11401}."] = "달의 신전에 있는 동안 12레벨 주문: 사제 상급자는 {npc:11401} 옆에 서 있습니다.",
		["Level 12 spells while you're in the {area:1658}: the hunter, rogue and druid trainers all stand in it."] = "{area:1658}에 있는 동안 12레벨 주문: 사냥꾼, 도적, 드루이드 상급자가 모두 그 안에 서 있습니다.",
		["Level 12 spells while you're on the {area:1660}: the warrior trainers stand beside {quest:1684}."] = "{area:1660}에 있는 동안 12레벨 주문: 전사 상급자는 {quest:1684} 옆에 서 있습니다.",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "병든 흑호와 엉겅퀴멧돼지가 동굴로 가는 길인 {area:256} 북쪽에 돌아다닙니다. {npc:1994}은(는) 동굴 깊숙이 있습니다. {npc:8584}은(는) 동굴 입구 서쪽 나무 사이에서 기다립니다.",
		["Nightsabers"] = "흑호",
		["North to {area:257}"] = "북쪽 {area:257}(으)로",
		["North-east from Ursal's den, back to {area:186}. {npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in."] = "우르살의 굴에서 북동쪽으로 {area:186}에 돌아가세요. {npc:6094}은(는) 잎과 약병과 함께 {item:159}을(를) 받습니다. 마셔 버렸다면 제출하기 전에 이 여관의 {npc:6736}에게서 하나 더 사세요.",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "돌라나르 북서쪽, {area:264}(으)로 가는 길의 숲에 오염된 나무그물거미가 기어 다닙니다. {npc:272116}은(는) 그 동쪽 끝을 배회하며 {item:281023}을(를) 지니고 있습니다.\n{npc:272116}은(는) 정예(12레벨)이므로 파티를 맺는 것이 좋습니다. 먼저 주변의 거미를 처치한 뒤 그를 따로 끌어내세요.",
		["On the way back south to the glade: {npc:272046} (level 12) flies on the slopes north-west of the moonwell, among Bloodfeather Matriarchs (11). Pull the harpies around her first."] = "남쪽 숲으로 돌아가는 길에: {npc:272046}(12레벨)이(가) 달샘 북서쪽 비탈에서 붉은깃털일족 우두머리(11) 사이를 날아다닙니다. 주변 하피부터 먼저 끌어오세요.",
		["Priest trainer"] = "사제 상급자",
		["Sentinel Arynia again"] = "다시 파수꾼 아리니아 클라우드브레이크",
		["South from the glade to the road: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "숲에서 남쪽으로 길까지 가세요. 샤일라는 {area:186} 서쪽 길을 오갑니다. 숲에서 내려오는 길이 만나는 곳에서 남서쪽으로 약 38,54의 굽은 길까지 오갑니다.",
		["South of the pools. The {object:6751} grows by the Hold; the furbolgs around it drop the rest of the fangs.\nCareful: the Gnarlpine Avengers (9-10) and Augurs here stand close together and many players died at the Hold: pull them one at a time."] = "웅덩이 남쪽입니다. {object:6751}은(는) 나무옹이 요새 옆에 자랍니다. 그 주변의 펄볼그가 나머지 송곳니를 떨어뜨립니다.\n주의: 이곳의 나무옹이일족 복수자(9-10)와 점술사들이 서로 가까이 붙어 있어 많은 플레이어가 요새에서 죽었습니다. 한 마리씩 끌어오세요.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "돌라나르 남동쪽의 {npc:2080}에게 가세요. 덩굴손 묘목이 물가에서 그 주변을 돌아다닙니다.",
		["South-west from {area:259}, past the {area:478}: Ursal prowls the far south of the island.\nCareful: Gnarlpine of roughly level 9-11 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "{area:259}에서 남서쪽으로 {area:478}을(를) 지나세요. 우르살은 섬 최남단을 배회합니다.\n주의: 9-11레벨가량의 나무옹이일족이 야영지에 몰려 가까이 붙어 있어 여러 마리가 한꺼번에 끌려오기 쉽습니다. 우르살과 싸우기 전에 하나씩 처치하세요.",
		["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "별바람 마을 남서쪽, {npc:2150} 남쪽입니다. {npc:2080}은(는) 물가에서 묘목을 돌보고 있습니다. 덩굴손 묘목과 나무괴물이 그 주변을 돌아다니고, 그 사이에 {quest:919}이(가) 자랍니다.",
		["South-west of the barrow. The moonwell sits by the pools."] = "지하굴 남서쪽입니다. 달샘은 웅덩이 옆에 있습니다.",
		["Speak with the {quest:5929}"] = "{quest:5929}와(과) 대화하세요",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "다시 {area:186}에서 북서쪽 길로 가세요. 그녀는 아직 {zone:1457}(으)로 가는 길가에 누워 있습니다.",
		["The WANTED poster outside the inn"] = "여관 밖의 현상수배 포스터",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms. Its furbolgs drop Shayla's fangs.\nCareful: the barrow's Gnarlpine Defenders, Augurs and Shamans (7-9) stand in threes in the narrow tunnels: pull each group back toward the entrance before you go deeper."] = "지하굴은 길 남쪽에 있습니다. 그곳의 펄볼그가 샤일라의 송곳니를 떨어뜨립니다.\n주의: 지하굴의 나무옹이일족 수비병, 점술가, 주술사(7-9)가 좁은 터널에 셋씩 서 있습니다. 더 깊이 들어가기 전에 무리마다 입구 쪽으로 끌어내십시오. {npc:275744}이(가) 안에 갇혀 있고, {npc:7317}은(는) 가장 깊은 곳에서 잠들어 있으며, 유물 상자 4개는 아래층 방에 있습니다.",
		["The grells west of the tree"] = "나무 서쪽의 그렐",
		["The moonwell"] = "달샘",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "달샘은 숲 한가운데에 있습니다. {object:6752}은(는) 북쪽 끝에 자랍니다.",
		["The road to {zone:1457}"] = "{zone:1457}(으)로 가는 길",
		["The {area:478}"] = "{area:478}",
		["The {object:177525}"] = "{object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406}은(는) {area:257} 안쪽에 있습니다. 가운데 길로 가다가 갈림길에서 왼쪽으로 높은 바위턱까지 오르세요. {item:10639}은(는) 그렐이 떨어뜨리고, 달봉우리 백합은 {area:256} 북쪽 연못가에 자랍니다.",
		["The {object:6752} grows at the glade's north end, on the way: then north along the island's northern edge by {area:266}, {npc:7319}, a level 12 spider, lurks."] = "{object:6752}은(는) 가는 길인 숲 북쪽 끝에 자랍니다. 그다음 섬 북쪽 가장자리를 따라 북쪽으로 가면 {area:266} 옆에 12레벨 거미 {npc:7319}이(가) 숨어 있습니다.",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "왕바닷게는 마을 아래 해안을 따라 기어다니고, {quest:983}은(는) 부두 바로 남쪽 해변에 서 있습니다. 어둠의해안 트레샤돈은 얕은 물에서 헤엄칩니다. {object:175207}은(는) 마을 바로 남쪽 해안에 놓여 있습니다.",
		["Upstairs"] = "위층",
		["Use the {item:18152} at the moonwell"] = "달샘에서 {item:18152}을(를) 사용하세요",
		["Use the {item:5185} at the moonwell"] = "달샘에서 {item:5185}을(를) 사용하세요",
		["Use the {item:5619} at the moonwell"] = "달샘에서 {item:5619}을(를) 사용하세요",
		["Use the {item:5621} at the moonwell"] = "달샘에서 {item:5621}을(를) 사용하세요",
		["Walk Lynessa out and keep her alive"] = "리네사를 데리고 나오며 살려 두세요",
		["Warrior trainer"] = "전사 상급자",
		["Webwood Lurkers"] = "나무그물 늑대거미",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "길을 따라 도시 쪽 서쪽으로 가세요. 샤일라는 화살표 위치에서 남서쪽으로 약 38,54의 굽은 길까지 이 구간을 오갑니다. 화살표 위치에 없으면 길을 따라 남서쪽으로 가세요. 모든 나무옹이일족 펄볼그가 송곳니를 떨어뜨립니다. 이 길의 복병, 지하굴과 {area:261}의 펄볼그 모두 해당됩니다.",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors.\nCareful: {npc:272116}, a level 12 elite, prowls the east edge of the Befouled Webwoods north-west of {area:186}: if you are alone, keep clear of the webwoods and go round him."] = "나무그물거미 지대에서 서쪽으로 {area:265}까지 간 뒤, 강을 따라 북쪽 숲으로 가세요. 강기슭의 나무정령이 이끼 낀 종양을 떨어뜨립니다.\n주의: 12레벨 정예인 {npc:272116}이(가) {area:186} 북서쪽 더럽혀진 나무그물 거미 무리의 동쪽 끝을 배회합니다. 혼자라면 거미 지대를 피해 그를 돌아가세요.",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west."] = "전문 기술을 배웠다면 {npc:265811}에게서 야영 기초 퀘스트도 받을 수 있으며, 해당 기술의 상급자에게 가져가면 됩니다: 연금술과 약초채집은 {npc:6286} 옆, {skill:129}은(는) 여관의 {npc:6094}, 무두질과 가죽세공은 서쪽 길가의 메인위버 야영지입니다.",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "{area:188}의 거대한 나무 {area:256} 아래에서 시작합니다.",
		["Young Nightsabers and Young Thistle Boars (level 1-2) roam around {area:256}: start with them. The Gnarlpine Totems stand in the woods west of the tree, where the Grells (2-3) roam: take them once the beasts are done."] = "새끼 흑호와 새끼 엉겅퀴멧돼지(1-2레벨)가 {area:256} 주변을 돌아다닙니다. 이들부터 잡으세요. 나무옹이일족 토템은 나무 서쪽 숲에 서 있으며, 그곳에 그렐(2-3)이 돌아다닙니다. 야수를 다 잡은 뒤 처리하세요.",
		["talk to the trainer"] = "상급자와 대화하세요",
		["{area:1658} trainers"] = "{area:1658} 상급자",
		["{area:186} again"] = "다시 {area:186}",
