t.guides["forever/class/druid/bear-form"] = (function() return {
		["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "10레벨에 드루이드의 부름이 옵니다: {area:222}의 {npc:3064} 또는 {zone:1456}의 {npc:6746}({zone:1454}의 {npc:6929}이(가) 보낸 편지도 됩니다). 누구든 {zone:1456} {area:1639}의 {npc:3033}에게 보냅니다.",
		["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "10레벨이 되면 드루이드의 부름이 옵니다: {area:186}의 {npc:3602}, {zone:1457}의 데나타리온, {zone:1453}의 테리드란. 누구든 다르나서스 세나리온 자치령의 {npc:4217}에게 보냅니다.",
		["Back to {npc:255853} by the falls."] = "폭포 옆의 {npc:255853}에게 돌아가세요.",
		["Back to {npc:3033} on {area:1639}."] = "{area:1639}의 {npc:3033}에게 돌아가세요.",
		["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, in {area:2361}. Learn the {area:493} flight path while you are here ({npc:12740} for the Horde, south-west of the lake; {npc:10897} for the Alliance, south of it)."] = "{spell:18960}을(를) 시전하세요. {area:2361}에서 {npc:11802}이(가) 위층에 서 있는 건물 옆에 도착합니다. 여기 온 김에 {area:493} 비행 경로를 배우세요(호드는 호수 남서쪽의 {npc:12740}, 얼라이언스는 호수 남쪽의 {npc:10897}).",
		["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs. The {quest:5930} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {quest:5922} flight path ({npc:12740}, south-west of the lake); {npc:11798} in {area:2361} flies druids to {area:1638}."] = "{spell:18960}을(를) 시전하세요. {npc:11802}이(가) 위층에 서 있는 건물 옆에 도착합니다. {quest:5930}은(는) 북서쪽 숲에 있습니다. 말을 걸어 모든 대화를 진행하세요(무엇을 상징하는지, 육체의 힘, 마음의 힘, 그리고 축복 요청). 대화가 임무이며 전투는 없습니다. 땅에 섞여 보이고 퀘스트 표시가 없으며, 나무 세 그루 옆에서 희미한 청회색 빛을 냅니다. {area:2361}에서 북쪽 산기슭을 따라 서쪽으로, 나무와 언덕 사이 틈을 지나가세요. 돌아왔을 때 {npc:11802}이(가) 없으면 밖으로 나가 {spell:18960}을(를) 다시 시전하세요. {quest:5922} 비행 경로를 배우세요(호수 남서쪽의 {npc:12740}). {area:2361}의 {npc:11798}은(는) 드루이드를 {area:1638}(으)로 태워 줍니다.",
		["Fly back to {area:702} and take the portal up to {npc:4217}."] = "{area:702}(으)로 날아가 차원문을 타고 {npc:4217}에게 올라가세요.",
		["Skyboat from {area:279}"] = "{area:279}에서 하늘배 타기",
		["Skyboat from {zone:1456}"] = "{zone:1456}에서 하늘배 타기",
		["Skyboat to {zone:2521}"] = "하늘배로 {zone:2521}에 가기",
		["Speak with the {quest:5929}"] = "{quest:5929}와(과) 대화하세요",
		["Speak with the {quest:5930}"] = "{quest:5930}와(과) 대화하세요",
		["The {object:177525}"] = "{object:177525}",
		["Your tanking form: Forever no longer trains {spell:5487}, these quests give it. Opens {area:493} too."] = "방어 전담 변신: Forever에서는 더 이상 {spell:5487}을(를) 훈련으로 배울 수 없고, 이 퀘스트들로 얻습니다. {area:493}도 열립니다.",
		["or whichever of the three letters you carry"] = "또는 가지고 있는 세 편지 중 하나",
		["{npc:252359} stands in {area:16638}."] = "{npc:252359}은(는) {area:16638}에 있습니다.",
		["{npc:255853} and {npc:258443}"] = "{npc:255853}와(과) {npc:258443}",
		["{npc:259118} waits where the airship from {zone:2521} lands, in northern {zone:1412} beside {zone:1456}."] = "{npc:259118}은(는) {zone:2521}에서 오는 비행선이 내리는 곳, {zone:1456} 옆 {zone:1412} 북부에서 기다립니다.",
		["{npc:270459} stands beside {npc:259084} and the Skyborne Portal, west of {area:279}, where the skycutter from {zone:2521} lands. {npc:2543} offers the same quest."] = "{npc:270459}은(는) {area:279} 서쪽, {zone:2521}에서 오는 비행정이 내리는 곳에 {npc:259084}, 스카이본 차원문과 함께 있습니다. {npc:2543}도 같은 퀘스트를 줍니다.",
		["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}, {area:222}. 팔라와 그리쉬카의 편지도 같은 곳으로 안내합니다",
		["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}, {area:186}. 데나타리온과 테리드란의 편지도 같은 곳으로 안내합니다",
		["{spell:5487} and {area:493}"] = "{spell:5487}와(과) {area:493}",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of {area:17045}, north of {zone:1456}."] = "{spell:5487}은(는) {zone:2521}에서 배웁니다. 아직 섬에 있다면 건너뛰세요. 아니면 {zone:1456} 북쪽, {area:17045} 남쪽 절벽에서 하늘배를 타세요.",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the north side of {area:279}."] = "{spell:5487}은(는) {zone:2521}에서 배웁니다. 아직 섬에 있다면 건너뛰세요. 아니면 {area:279} 북쪽에서 하늘배를 타세요.",
} end)()
t.guides["forever/class/druid/bloodpetal-poison"] = (function() return {
		["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "{zone:1449} 남동쪽 구석의 {npc:9619}에게 돌아가세요.",
		["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer ({npc:3033}, {npc:4217} or Theridran in {zone:1453}) offers the same quest."] = "{spell:18960}을(를) 시전하세요. {npc:12042}은(는) {area:2361}에 서 있습니다. 직업 상급자({npc:3033}, {npc:4217} 또는 {zone:1453}의 테리드란)도 같은 퀘스트를 줍니다.",
		["Experience in Un'Goro at 50 and two healing potions; the Classic item choice may be gone in Forever."] = "50레벨에 운고로 경험치와 치유 물약 두 개. Forever에서는 클래식의 아이템 선택이 사라졌을 수 있습니다.",
		["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "{area:976}(으)로 날아가 서쪽으로 {zone:1449}(으)로 내려가는 긴 비탈까지 가세요. {npc:9619}은(는) 그 아래, 분화구 남동쪽 구석에 진을 치고 있습니다.",
		["Gorishi Stings and {item:22434}"] = "고리쉬 독침과 {item:22434}",
		["The {area:1417}"] = "{area:1417}",
} end)()
t.guides["forever/class/druid/cat-form"] = (function() return {
		["Back to {npc:11802}"] = "{npc:11802}에게 돌아가기",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. No {area:493} flight path yet? Learn it from {npc:10897}, south of the lake: the flight master in {area:2361} flies only Druids, from her gossip, and has none to learn."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있는 자기 건물 위층에 서 있습니다. 건물 안에서 올라가세요. 화살표는 층을 구분하지 못합니다. 아직 {area:493} 비행 경로가 없나요? 호수 남쪽의 {npc:10897}에게서 배우세요. {area:2361}의 비행 조련사는 대화를 통해 드루이드만 태워주며, 배울 비행 경로가 없습니다.",
		["Take the portal up to {npc:4217}, upstairs in the {area:1658}: he teaches you {spell:768}."] = "차원문을 타고 {area:1658}의 위층에 있는 {npc:4217}에게 올라가십시오. 그가 {spell:768}을(를) 가르쳐 줍니다.",
		["The relics of the Barrow Dens"] = "지하굴의 성물",
		["The {area:2363}"] = "{area:2363}",
		["Your stealth and melee form: in Forever this chain gives {spell:768} at 20, not the trainer."] = "은신과 근접 전투 변신: Forever에서는 {spell:768}을(를) 상급자가 아니라 이 연계 퀘스트로 20레벨에 얻습니다.",
		["{npc:3033} on {area:1639} teaches you {spell:768}."] = "{area:1639}의 {npc:3033}이(가) {spell:768}을(를) 가르쳐 줍니다.",
		["{npc:3033} stands in the druids' hut on {area:1639}. No {spell:1066} yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the {spell:1066} guide) is in the same {area:493}."] = "{npc:3033}은(는) {area:1639}의 드루이드 오두막에 서 있습니다. 아직 {spell:1066}이(가) 없나요? 그에게서 '꼭 배워야 할 교훈'도 받으세요. 이 퀘스트도 {npc:11802}에게 가며, 이어지는 '엘룬아라 호수의 시험'({spell:1066} 가이드)도 같은 {area:493}에 있습니다.",
		["{npc:4217} stands in the {area:1658}. Skyborne far from {zone:1457}: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No {spell:1066} yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the {spell:1066} guide) is in the same {area:493}."] = "{npc:4217}은(는) {area:1658}에 서 있습니다. {zone:1457}에서 멀리 있는 스카이본이라면 {spell:18960}을(를) 시전하고 {area:2361} 중앙에서 {npc:11800}의 비행편을 타세요(드루이드를 {area:702}까지 태워 주며, 비행 경로가 필요 없습니다). 그다음 차원문을 타고 올라가세요. 아직 {spell:1066}이(가) 없나요? 그에게서 '귀중한 교훈'도 받으세요. 이 퀘스트도 {npc:11802}에게 가며, 이어지는 '엘룬아라 호수의 시험'({spell:1066} 가이드)도 같은 {area:493}에 있습니다.",
} end)()
t.guides["forever/class/druid/cure-poison"] = (function() return {
		["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{spell:18960}을(를) 시전해 {npc:11802}을(를) 만난 뒤, {npc:11798}의 비행편으로 {area:1638}에 가세요. {npc:11802}은(는) 자기 건물 위층에 서 있습니다. 건물 안에서 올라가세요. 화살표는 층을 구분하지 못합니다.",
		["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15842}. {npc:11798} flies druids to {area:1638}; fly on to the Crossroads from there."] = "{spell:18960}을(를) 시전하세요: {npc:11802}은(는) 바로 옆 건물 위층에 서 있습니다. 그가 {item:15842}을(를) 줍니다. {npc:11798}이(가) 드루이드를 {area:1638}(으)로 태워 줍니다. 그곳에서 크로스로드로 날아가세요.",
		["Sickly Gazelles"] = "병든 가젤",
		["{item:15851} and {item:2449}"] = "{item:15851}와(과) {item:2449}",
		["{item:2449} and Kodo Horns"] = "{item:2449}와(과) 코도 뿔",
		["{item:2449}; herbalists pick it on the plains"] = "{item:2449}. 약초채집가는 평원에서 캘 수 있습니다",
		["{npc:3033} on {area:1639} teaches you {spell:8946}."] = "{area:1639}의 {npc:3033}이(가) {spell:8946}을(를) 가르쳐 줍니다.",
		["{npc:3448} stands in the Crossroads. No {skill:182}? {npc:3490}, a few steps away by the wind rider master, sells {item:2449} for 80 copper each, three at a time until he restocks."] = "{npc:3448}은(는) 크로스로드에 있습니다. {skill:182}이(가) 없다면 몇 걸음 떨어진 와이번 조련사 옆의 {npc:3490}이(가) {item:2449}을(를) 개당 80코퍼에 팝니다. 재입고될 때까지 한 번에 세 개씩입니다.",
		["{npc:4217}, upstairs in the {area:1658}, teaches you {spell:8946}."] = "{area:1658}의 위층에 있는 {npc:4217}이(가) {spell:8946}을(를) 가르쳐 줍니다.",
		["{spell:8946} is no longer trained in Forever: this chain teaches it, with a medicine bag on the way."] = "Forever에서는 더 이상 {spell:8946}을(를) 수련할 수 없습니다: 이 연계 퀘스트가 가르쳐 주며, 도중에 약초 가방도 얻습니다.",
} end)()
t.guides["forever/class/hunter/rhokdelar"] = (function() return {
		["Back to the Ancients"] = "고대정령에게 돌아가기",
		["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and talking to Vartrus once more then gave {item:18715}, at no extra cost."] = "Forever에서는 확인되지 않았습니다. 클래식에서는 {item:18724}을(를) 가방에 넣고 {item:18707}을(를) 사용하면 라크델라 - 고대수호자의 장궁이 만들어졌고, 그 뒤 고대정령 바르투스와 한 번 더 대화하면 추가 비용 없이 {item:18715}을(를) 주었습니다.",
		["Onyxia"] = "오닉시아",
		["Rhok'delar and Lok'delar"] = "라크델라와 로크델라",
		["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "사냥꾼의 영웅 활 연계 퀘스트입니다. 클래식에서는 지팡이와 힘줄이 라크델라와 로크델라가 되었습니다(Forever에서는 미확인).",
		["The {item:18703}"] = "{item:18703}",
		["from the {item:18703}"] = "{item:18703}에서",
		["{item:18704}, from {npc:6109}"] = "{item:18704}, {npc:6109}에게서",
		["{item:18705}, from Onyxia"] = "{item:18705}, 오닉시아에게서",
		["{item:18707}, by Vartrus"] = "{item:18707}, 바르투스 곁에서",
		["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}: 클래식에서는 로크델라",
		["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}: 화살통, 이 가이드의 마지막",
		["{npc:14536}, a gnome, walks around the gates of {area:3428} in the far south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. He enrages with {spell:23272} as he turns: drop a {spell:13809}, {spell:5384}, and he resets without the enrage. {spell:2974} roots him for a long time; while rooted he fears you and sends beetles ({npc:14761}): kill them fast with traps and {spell:2643} before they wear you down."] = "노움인 {npc:14536}은(는) {zone:1451} 남서쪽 끝 {area:3428}의 관문 주변을 걸어 다닙니다. 그에게 말을 걸면 {npc:14530}(으)로 변합니다. 변신하면서 {spell:23272}(으)로 격노하니, {spell:13809}을(를) 깔고 {spell:5384}을(를) 쓰면 격노 없이 초기화됩니다. {spell:2974}은(는) 그를 오랫동안 묶어 둡니다. 묶여 있는 동안 그는 공포를 걸고 딱정벌레({npc:14761})를 보냅니다. 지치기 전에 덫과 {spell:2643}(으)로 빨리 처치하세요.",
} end)()
