t.guides["forever/class/hunter/the-hunters-charm"] = (function() return {
		["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "50레벨이 되면 얼라이언스 사냥꾼 상급자 누구나 이 퀘스트를 줍니다: {zone:1453} {object:28027}의 {npc:5516}, {zone:1455} {object:32390}의 {npc:5116}, {zone:1457} 세나리온 자치령의 도리온.",
		["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "50레벨이 되면 호드 사냥꾼 상급자 누구나 이 퀘스트를 줍니다. {zone:1454} {object:172958}의 {npc:3352}, {zone:1456} {area:1641}의 {npc:3039}.",
		["Experience"] = "경험치",
		["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "50레벨에 {zone:1447}와(과) {area:1417}을(를) 통한 경험치. Forever에서는 클래식의 아이템 선택이 사라졌을 수 있습니다.",
		["Morphaz in the {area:1417}"] = "{area:1417}의 몰파즈",
		["{item:20019}, inside the {area:1417}"] = "{item:20019}, {area:1417} 안",
		["{quest:8151} (Alliance)"] = "{quest:8151} (얼라이언스)",
		["{quest:8151} (Horde)"] = "{quest:8151} (호드)",
} end)()
t.guides["forever/class/mage/arcane-refreshment"] = (function() return {
		["Back to Lydros"] = "리드로스에게 돌아가기",
		["Hydrospawn"] = "히드로스폰",
		["Hydrospawn, a level 57 elite water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool. A group of five. Frost does nothing to him, so frost mages switch to fire or arcane. {area:1758} hits everyone within 10 yards, so ranged stand back; at a quarter health he calls Hydrolings. The essence always drops; he does not come back until the instance resets."] = "57레벨 정예 물의 정령 히드로스폰은 굽이나무 지구(혈투의 전장 동쪽)에 있습니다. 임프 푸실린이 돌아서서 싸울 때까지 쫓아가고, 사티로스 방을 정리한 뒤 나선형 경사로를 따라 웅덩이로 내려가십시오. 5인 파티용입니다. 냉기는 통하지 않으니 냉기 마법사는 화염이나 비전으로 바꾸십시오. {area:1758}은(는) 10미터 안의 모두를 공격하므로 원거리 공격자는 물러서 있으십시오. 생명력이 4분의 1이 되면 작은 물의 정령을 부릅니다. 정수는 항상 떨어지며, 인스턴스가 초기화될 때까지 다시 나타나지 않습니다.",
		["Shen'dralar reputation"] = "셴드랄라 평판",
		["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "{area:2577} 도서관에서 얻는 레벨 60 {spell:10140}: 자신과 파티원을 위한 음료.",
		["{item:18299}: Hydrospawn"] = "{item:18299}: 히드로스폰",
} end)()
t.guides["forever/class/mage/astral-knot-garment"] = (function() return {
		["A robe or a blouse for Alliance mages in their late 20s."] = "20대 후반 얼라이언스 마법사를 위한 로브 또는 블라우스입니다.",
		["Back to Andromath"] = "고위마술사 안드로매스에게 돌아가기",
		["Carrion Recluses"] = "청소부그늘거미",
		["The {area:96}"] = "{area:96}",
		["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144}은(는) {zone:1455}의 {object:32362}에서 마법사를 가르칩니다. 이후 {object:171524}에서 {area:2257}을(를) 타고 {zone:1453}(으)로 가십시오.",
		["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}; the portal near the top of the spiral ramp takes you to her."] = "{npc:5497}은(는) {object:2101}의 보랏빛 탑인 마법사의 성소 꼭대기에 있습니다. 나선형 경사로 꼭대기 근처의 차원문이 그녀에게 데려다줍니다.",
} end)()
t.guides["forever/class/mage/celestial-orb"] = (function() return {
		["An off-hand orb or a staff for the late 30s, your pick."] = "30대 후반용 보조장비 구슬이나 지팡이 중 선택.",
		["At 40 the mage trainers who send you to {npc:6546} ({npc:5497}, Bink, {npc:4568}, {npc:5885}) also have {quest:2861}, a quest any class can do. {npc:6546} then wants the {quest:2846} from {npc:7795}, a level 46 elite naga in {area:978}, the troll dungeon in north-western {zone:1446}: a group of five, level 44-54. The reward window shows the {item:9527} and the {item:9531}."] = "40레벨이 되면 {npc:6546}에게 보내 주는 마법사 상급자들({npc:5497}, 빙크, {npc:4568}, {npc:5885})이 어느 직업이나 할 수 있는 {quest:2861}도 줍니다. 그다음 {npc:6546}은(는) {zone:1446} 북서쪽의 트롤 던전 {area:978}에 있는 46레벨 정예 나가 {npc:7795}의 {quest:2846}을(를) 원합니다. 5인 파티, 44-54레벨 던전입니다. 보상 창에 {item:9527}와(과) {item:9531}이(가) 표시됩니다.",
		["Back at {npc:6546}'s. Hand in the orb now; {quest:1955} waits for level 40. Kill the critters around the cottage first: they join the fight. Accepting {quest:1955} starts a 3 minute timer, and {npc:6546} calls the {npc:6549} out in her garden: a level 40 elite that resists many spells, roots and slows. Grouping up is encouraged: a mage of 40 may need help or potions, at about 45 it is soloable. You can pull it from range from the dock. The timer keeps running after it dies, so hand the quest in straight away. If time runs out, abandon the quest and take it again; she calls the demon again."] = "{npc:6546}에게 돌아가세요. 지금 보주를 제출하세요. {quest:1955}은(는) 40레벨이 될 때까지 기다립니다. 먼저 오두막 주변의 동물들을 처치하세요. 전투에 끼어듭니다. {quest:1955}을(를) 수락하면 3분 타이머가 시작되고, {npc:6546}이(가) 정원으로 {npc:6549}을(를) 불러냅니다. 많은 주문, 이동 불가, 감속에 저항하는 40레벨 정예입니다. 파티를 권장합니다. 40레벨 마법사는 도움이나 물약이 필요할 수 있고, 45레벨쯤이면 혼자 잡을 수 있습니다. 부두에서 원거리로 끌어올 수 있습니다. 처치한 뒤에도 타이머는 계속 흐르니 바로 퀘스트를 제출하세요. 시간이 다 되면 퀘스트를 포기하고 다시 받으세요. 그녀가 악마를 다시 불러냅니다.",
		["{area:1517} is a dungeon in the northern {zone:1418}: a group of five, from level 40 here. Go in by the rear entrance, a cave in {area:1898} south-east of the main entrance (elite dragons fly nearby): the {npc:7023} (level 42 elite) stands just past the first door. At 80, 60, 40 and 20 percent it breaks off an {npc:7209}, an elite too; while a shard lives, both reflect targeted spells, so use area spells and your wand on them. A solo trick: step out through the nearby zone line each time a shard appears; the Sentinel heals but keeps shrinking. It always drops the power source, and takes 2 hours to come back."] = "{area:1517}은(는) {zone:1418} 북부의 던전입니다. 5인 파티가 필요하며, 이 가이드는 40레벨부터 갑니다. 정문 남동쪽 {area:1898}의 동굴인 뒷문으로 들어가세요(근처에 정예 용이 날아다닙니다). {npc:7023}(42레벨 정예)은(는) 첫 번째 문 바로 뒤에 서 있습니다. 생명력 80, 60, 40, 20%에서 역시 정예인 {npc:7209}을(를) 떼어 냅니다. 파편이 살아 있는 동안 둘 다 대상 지정 주문을 반사하므로 광역 주문과 마법봉을 쓰세요. 혼자 하는 요령: 파편이 나타날 때마다 근처의 지역 경계 밖으로 나가세요. 파수병은 회복하지만 계속 작아집니다. 동력원은 항상 떨어지며, 다시 나타나는 데 2시간이 걸립니다.",
		["{area:978}, the troll dungeon in north-western {zone:1446}, needs a group of five; the guide waits for level 46. {npc:7795} is one of the bosses by the sacred pool, and the tiara always drops."] = "{zone:1446} 북서쪽의 트롤 던전 {area:978}은(는) 5인 파티가 필요합니다. 가이드는 46레벨까지 기다립니다. {npc:7795}은(는) 신성한 연못 옆의 우두머리 중 하나이며, 보관은 항상 떨어집니다.",
		["{item:7515} and Stave"] = "{item:7515}와(과) 천상의 지팡이",
