t.guides["forever/class/rogue/the-eye-of-bhossca"] = (function() return {
		["Back to the dead drop"] = "비밀 보관함으로 돌아가기",
		["C's dead drop"] = "C의 비밀 보관함",
		["C's next job comes by letter: once you are level 30 and have done the horn job (The {item:210183}, its payment from this {object:410369} handed in), visit any capital city and C's letter arrives in the mailbox; only then does the {object:410369} near {area:204}, in southern Silverpine just south of {area:236}, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30."] = "C의 다음 임무는 편지로 옵니다. 30레벨이 되고 뿔 임무({item:210183}, 그 보수를 이 {object:410369}에 제출)를 마친 뒤 아무 수도에 가면 우편함에 C의 편지가 도착합니다. 그래야 은빛소나무 숲 남부, {area:236} 바로 남쪽 {area:204} 근처의 {object:410369}에서 임무를 받을 수 있습니다. 퀘스트 데이터상 최소 25레벨이지만, 플레이어들은 30레벨에 편지와 임무를 받습니다.",
		["The {area:796}"] = "{area:796}",
		["The {item:277246}, C's payment for a solo job in the {area:796}, after The {item:210183}."] = "{item:277246}: {item:210183} 다음, {area:796}에서 혼자 하는 임무에 대한 C의 보수.",
		["the locked reliquary in the Library"] = "도서관의 잠긴 성물함",
} end)()
t.guides["forever/class/rogue/the-horn-of-xelthos"] = (function() return {
		["Back to the dead drop"] = "비밀 보관함으로 돌아가기",
		["C's dead drop"] = "C의 비밀 보관함",
		["The {item:277210}, C's payment for a solo job inside {area:236}."] = "{item:277210}, {area:236} 안에서 혼자 해내는 일에 대한 C의 보수입니다.",
		["The {object:410369} is a chest in a house just outside {area:204} in southern Silverpine, south of {area:236}. Open it and read C's note: the job has to be done alone, out of any group."] = "{object:410369}은(는) 은빛소나무 숲 남쪽, {area:236} 남쪽의 {area:204} 바로 바깥 집 안에 있는 상자입니다. 열어서 C의 쪽지를 읽으십시오. 이 임무는 파티 없이 혼자 해야 합니다.",
		["{item:210183}, inside {area:236}"] = "{item:210183}, {area:236} 내부",
} end)()
t.guides["forever/class/shaman/call-of-air-alliance"] = (function() return {
		["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "30레벨에 {zone:1455}의 주술사 상급자 {npc:258098}이(가) {zone:1417}의 {npc:259023}에게 보냅니다. 30레벨 바람 토템(마법 정화, {spell:10596})에는 그가 주는 {item:5178}이(가) 필요합니다.",
		["The steam pools"] = "증기 웅덩이",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "바람 토템을 놓게 해 주는 {item:5178}, 그리고 40레벨에 원하는 무기 하나.",
		["Twisted Air Totems"] = "뒤틀린 바람 토템",
		["Twisted Earth Totems"] = "뒤틀린 대지 토템",
		["Twisted Fire Totems"] = "뒤틀린 불의 토템",
		["Twisted Water Totems"] = "뒤틀린 물 토템",
		["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717}은(는) {zone:1413} 남쪽 끝의 5인 던전이며(화살표가 입구를 가리킵니다), {npc:4421}(33레벨 정예)이(가) 마지막 우두머리입니다. 그녀는 {spell:8292}, 아군에게 {spell:139}, 정화를 시전하며, {item:274463}은(는) 그녀에게서만 떨어집니다.",
		["{item:212792}, from the {npc:216474}"] = "{npc:216474}에게서 얻는 {item:212792}",
		["{item:274463}, from {npc:4421}"] = "{npc:4421}에게서 얻는 {item:274463}",
