t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s from {npc:6266}; its last parts wait for levels 37 and 39."] = "{npc:6266}이(가) 만들어 주는 30레벨대용 희귀 천 로브입니다. 마지막 재료는 37레벨과 39레벨까지 기다립니다.",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "31레벨에 {object:172960}의 {npc:3326}이(가) {area:392}의 {npc:6266}에게 보냅니다. 왕복을 줄이려면 먼저 {item:5770}와(과) {item:3577}을(를) 사십시오(다음 단계).",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "31레벨에 {object:2101} {object:2164}의 {npc:461}이(가) {area:392}의 {npc:6266}에게 보냅니다. 왕복을 줄이려면 먼저 {item:5770}와(과) {item:3577}을(를) 사십시오(다음 단계).",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "31레벨에 {zone:1455}의 {npc:5172}이(가) {area:392}의 {npc:6266}에게 보냅니다. 왕복을 줄이려면 먼저 {item:5770}와(과) {item:3577}을(를) 사십시오(다음 단계).",
		["Back to {npc:6266}"] = "{npc:6266}에게 돌아가기",
		["Back to {npc:6266} with the thread, the coals and a {item:6265}. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again."] = "실, 석탄, {item:6265}을(를) 가지고 {npc:6266}에게 돌아가십시오. 그런 다음 그녀가 로브를 만드는 동안 곁에서 기다린 뒤(공격하지 마십시오. 퀘스트 목록에는 처치로 표시됩니다) 다시 말을 거십시오.",
		["Hatefury satyrs"] = "서릿발분노 사티로스",
		["The Burning Exiles (level 38-39), fire elementals at the {area:334} in western {zone:1417}, drop the coal about one time in three. The guide waits for level 39 first: below it they hit too hard to solo. They resist fire: {spell:686} and Corruption. The Cresting Charms from the Cresting Exiles near {area:321} finish one off once you have hurt it. Make a {item:6265} with {spell:1120} on the way."] = "떠도는 불의 정령(38-39레벨)은 {zone:1417} 서쪽 {area:334}에 있는 불의 정령으로, 대략 세 번에 한 번 석탄을 떨어뜨립니다. 가이드는 먼저 39레벨까지 기다립니다. 그보다 낮으면 너무 세게 때려 혼자 잡기 어렵습니다. 화염에 저항합니다: {spell:686}와(과) 부패를 쓰세요. {area:321} 근처의 떠도는 물의 정령에게서 얻는 용마루장식 부적은 피해를 입힌 정령을 마무리합니다. 가는 길에 {spell:1120}(으)로 {item:6265}을(를) 만드세요.",
		["The Hatefury satyrs (level 31-32) hold {area:603} in the far north-east of {zone:1443}, past {area:608}: two kills in five give a vial, so plan on about 25."] = "서릿발분노 사티로스(31-32레벨)는 {area:608} 너머 {zone:1443} 북동쪽 끝의 {area:603}을(를) 차지하고 있습니다. 다섯 마리 중 두 마리꼴로 유리병을 주니 25마리쯤 잡을 생각을 하세요.",
		["The Lesser Infernals (36-37) and Demon Portal Guardians (38) of {area:602}, in the south of {zone:1443}, drop the stone half the time. The guide waits for level 39 first: at 31 they are too strong to solo. They resist fire, so use {spell:686} and Corruption."] = "{zone:1443} 남쪽 {area:602}의 하급 지옥불정령(36-37)과 악마의 차원문 수호병(38)은 절반의 확률로 돌을 떨어뜨립니다. 가이드는 먼저 39레벨까지 기다립니다. 31레벨에서는 너무 강해 혼자 잡기 어렵습니다. 화염에 저항하므로 {spell:686}와(과) 부패를 쓰세요.",
		["Vials of Hatefury Blood"] = "서릿발분노의 사티로스 피",
		["{npc:2670}: {quest:4785}, handed straight back"] = "{npc:2670}: {quest:4785}, 받자마자 바로 제출",
		["{npc:6266} again"] = "다시 {npc:6266}에게",
} end)()
t.guides["forever/class/warlock/felhunter-alliance"] = (function() return {
