} end)()
t.guides["forever/class/warlock/impsys-request"] = (function() return {
		["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "50대용 지팡이, 보조장비, 로브. {npc:14470}의 개인 심부름으로, 공포마 연계 퀘스트의 단계가 아닙니다.",
		["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "50레벨에 {object:172960}의 {npc:3326}이(가) 당신을 {item:14256} 한 조각과 함께 {zone:1448}의 {npc:14470}에게 보냅니다.",
		["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "50레벨에 {object:36082}의 {npc:4563}이(가) 당신을 {item:14256} 한 조각과 함께 {zone:1448}의 {npc:14470}에게 보냅니다.",
		["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "50레벨에 {object:2101}에 있는 {object:2164}의 {npc:461}이(가) 당신을 {item:14256} 한 조각과 함께 {zone:1448}의 {npc:14470}에게 보냅니다.",
		["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "50레벨에 {zone:1455}의 {npc:5172}이(가) 당신을 {item:14256} 한 조각과 함께 {zone:1448}의 {npc:14470}에게 보냅니다.",
		["The {area:1417}"] = "{area:1417}",
		["{item:20613} and Bloodvenom"] = "{item:20613}와(과) 피멍울",
		["{npc:14470} again"] = "다시 {npc:14470}",
} end)()
t.guides["forever/class/warlock/incubus-alliance"] = (function() return {
		["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "20레벨에 {object:2101} {object:2164} 지하실의 {npc:6122}이(가) {zone:1413}의 {npc:6244}에게 보냅니다. 얼라이언스에게는 먼 여정입니다. {area:150}에서 배를 타고 테라모어로 가서 {zone:1445}을(를) 지나 서쪽으로 가거나, {area:35}에서 배를 타고 {area:392}(으)로 가십시오.",
} end)()
t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1507} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "20레벨에 {object:172982} 아래 {object:172960}의 {npc:5875}이(가) 몇 걸음 떨어진 {npc:5909}에게 보냅니다. 이 악마들은 여기의 {npc:5875}과 {zone:1458}의 {npc:5675}, 두 상급자가 시작하며 하나만 수락할 수 있습니다. 이 가이드는 수락한 {quest:1507}을(를) 따라갑니다. {npc:5909}은(는) {zone:1454}의 두 갈래를 모두 줍니다. 둘 다 받으십시오.",
		["Corma Villard"] = "코르마 빌라드",
		["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so the guide waits for level 27 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422}은(는) {zone:1440} 남쪽, {area:431} 남서쪽에 있습니다. 호수 주변의 그늘덤불 암석늪괴물과 그늘덤불 껍질늪괴물(25-27레벨)은 대략 스무 번에 한 번 {item:190232}을(를) 떨어뜨리고, 홀로 있는 {npc:3931}(30)도 떨어뜨릴 수 있습니다. 꽤 많이 잡아야 하므로 가이드는 먼저 27레벨까지 기다립니다(Forever에서 이 퀘스트는 27레벨이 되었습니다). 서큐버스를 이미 얻었다면 {zone:1440}에서 20레벨대를 보낼 때로 미뤄도 됩니다. 5분마다 다시 나타납니다.",
		["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363}은(는) {object:172960} 동쪽 큰길가의 {object:173018}을(를) 운영합니다. {zone:1440}에 있는 짝 Krilge를 찾아 달라고 합니다.",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "{npc:5875} 대신 {npc:5675}의 {quest:1472}을(를) 수락한 흑마법사를 위한 {object:1661} 버전입니다. 20레벨에 {object:36082}의 {npc:5675}이 가까이 있는 {npc:5693}에게 보냅니다. {npc:5693}은(는) 각 사냥감의 환영을 보여 주고 두 갈래를 모두 줍니다. 둘 다 받으십시오.",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "30대 후반에 얻는 보조장비 보주 또는 지팡이입니다. 지옥사냥개 경로와 지옥불정령 경로 중 원하는 쪽을 고르십시오.",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "35레벨에 {object:172960}의 {npc:3326}이(가) {area:392}의 {npc:6266}에게 보냅니다.",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "35레벨에 {object:36082}의 {npc:4563}이(가) {area:392}의 {npc:6266}에게 보냅니다. {zone:1420}에서 출발하는 비행선은 {zone:1411}(으)로 갑니다.",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "35레벨에 {object:2101} {object:2164}의 {npc:461}이(가) {area:392}의 {npc:6266}에게 보냅니다.",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "35레벨에 {zone:1455}의 {npc:5172}이(가) {area:392}의 {npc:6266}에게 보냅니다.",
		["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "정화된 보주를 가지고 {area:392} 위 탑의 {npc:6266}에게 돌아가십시오. 지옥사냥개 경로라면 그녀의 마지막 퀘스트를 수락하고 그녀가 {item:15108}을(를) 완성할 때까지 곁에서 기다린 뒤(공격하지 마십시오. 퀘스트 목록에는 처치로 표시됩니다), 다시 대화해 보조장비 보주나 지팡이를 고르십시오.",
		["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "먼저 영혼과 보석을 가지고 {area:392} 위 탑의 {npc:6266}에게 돌아가십시오. 그다음 그녀의 보주가 이어집니다.",
		["Choose an acolyte"] = "수행사제 고르기",
		["On the infernal path, accept her last quest and wait beside {npc:6266} while she completes the {item:15107}, then speak to her again and pick the off-hand orb or the staff."] = "지옥불정령 경로라면 그녀의 마지막 퀘스트를 수락하고 {npc:6266}이(가) {item:15107}을(를) 완성할 때까지 곁에서 기다린 뒤, 다시 대화해 보조장비 보주나 지팡이를 고르십시오.",
		["Orb of Orahil"] = "오라힐의 보주",
		["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, the shadow versions; {npc:6252}'s infernal path with the Orb or {item:15105}, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back."] = "수행사제 하나를 고르십시오. 퀘스트는 한 명의 것만 수락할 수 있습니다. {npc:6254}의 지옥사냥개 경로는 보주 또는 {item:15106}(암흑 계열)(으)로, {npc:6252}의 지옥불정령 경로는 보주 또는 {item:15105}(으)로 끝나며, 후자는 화염 쪽의 거의 같은 아이템입니다. 대부분의 흑마법사는 암흑에 기울지만, 먼저 네 아이템의 툴팁을 비교하십시오. 가이드는 수락한 쪽을 따라갑니다. 루비나 에메랄드는 보관하십시오. 다시 돌려주게 됩니다.",
		["The demon's spirit"] = "악마의 영혼",
		["The {item:15107}"] = "{item:15107}",
		["The {item:15108}"] = "{item:15108}",
		["{item:12648}, from a {npc:4678}, {npc:4681} or {npc:4685}"] = "{item:12648}, {npc:4678}, {npc:4681} 또는 {npc:4685}에게서",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}, {npc:4676}에게서",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}, 불타는칼날단 소환사에게서",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252}: {item:12646}을(를) 줍니다",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254}: {item:12647}을(를) 줍니다",
		["{npc:6266} and her two acolytes stand in {npc:6251}'s tower on the hill above {area:392}."] = "{npc:6266}와(과) 두 수행사제는 {area:392} 위 언덕의 {npc:6251}의 탑 안에 있습니다.",
		["{npc:6546} lives at her farm in the middle of {zone:1445}, south of the road from the {zone:1413} and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Hand in the orb now; Cleansing waits for level 40. Before you accept it, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the {npc:6549} out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or {spell:710} and damage over time, a level 38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from {npc:6546} again."] = "{npc:6546}은(는) {zone:1445} 한가운데, {zone:1413}에서 오는 길 남쪽이자 테라모어 남서쪽의 농장에 살고 있으며, 옆에 영혼의 치유사가 있습니다. 45레벨 악어인 붉은눈늪지악어가 바로 북동쪽의 개울을 순찰합니다. 지금 보주를 제출하세요. '오라힐 보주의 정화'는 40레벨까지 기다립니다. 수락하기 전에 그녀의 우리 주변의 거미와 악어를 정리하세요. 수락하면 3분 타이머가 시작되고, 그녀가 우리로 걸어가 {npc:6549}을(를) 풀어놓습니다. 정예(40레벨)이므로 파티를 권장합니다. 40레벨쯤의 흑마법사는 공포나 {spell:710}와(과) 지속 피해로 혼자 잡을 수 있고, 38레벨이라면 친구를 데려가세요. 처치한 뒤에도 타이머는 계속 흐르니 바로 제출하세요. 시간이 다 되면 퀘스트를 포기하고 {npc:6546}에게서 다시 받으세요.",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
		["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "20레벨대를 위한 희귀 보조장비 보주 또는 지팡이. 두 던전에서 얻는 조각과 교환합니다.",
		["Back to {npc:6247}"] = "{npc:6247}에게 돌아가기",
		["Soran'ruk Fragments, from the Twilight Acolytes inside"] = "황혼의망치단 수행사제에게서 얻는 소란룩 조각, 내부",
		["{item:6915}, from the Shadowfang Darksouls inside"] = "그림자송곳니일족 검은영혼에게서 얻는 {item:6915}, 내부",
} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "{zone:1448}의 {npc:14469}와(과) {npc:14470}이(가) 주는 50레벨대 희귀 보조장비입니다. 임프의 부탁도 주는 곳입니다.",
		["Back to {npc:14469}"] = "{npc:14469}에게 돌아가기",
		["{area:1763} lies just south of {area:1997}, west of the road. The guide waits for level 54 first: its Legionnaires are 55. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763}은(는) {area:1997} 바로 남쪽, 길 서쪽에 있습니다. 가이드는 먼저 54레벨까지 기다립니다. 그곳의 부대원은 55레벨입니다. 두 동굴 중 {area:1770}은(는) 언덕 위쪽에 있는 북쪽 동굴이며, 다른 동굴에는 부대원이 없습니다. {area:1770}의 터널은 언덕 아래로 북쪽으로 뻗어 있고, 자에데나르 부대원(55레벨)은 첫 번째 경사로부터 {npc:9516}의 방까지 더 깊은 방들에 서 있습니다. 근접한 상대에게 올려치기를 씁니다. 네 마리 중 세 마리꼴로 정수를 주지만 11마리 정도만 나타납니다. 길을 뚫고 들어가고, 필요하면 5분 재생성을 기다리세요. {area:1763}와(과) {area:1770}의 이교도는 모두 적대적입니다.",
		["{item:18626}, at {object:179677}"] = "{item:18626}, {object:179677}에서",
} end)()
t.guides["forever/class/warlock/tome-of-sacrifice"] = (function() return {
		["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "60레벨 희귀 보조장비. {zone:1419}에서 {npc:12396}을(를) 포획한 대가로 {npc:14463}이(가) 줍니다.",
		["Back to {npc:14463}"] = "{npc:14463}에게 돌아가기",
		["{item:18601}, on a {npc:12396}"] = "{item:18601}, {npc:12396}에게",
} end)()
t.guides["forever/class/warrior/brutal-armor"] = (function() return {
		["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "20레벨에 {zone:1456}의 전사 상급자 {npc:3041}이(가) 당신을 {area:378}의 {npc:6394}에게 보냅니다.",
		["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "20레벨에 {object:172958}의 {npc:3354}이(가) 당신을 {area:378}의 {npc:6394}에게 보냅니다.",
		["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "20레벨에 {zone:1458}의 전사 상급자 {npc:4595}이(가) 당신을 {area:378}의 {npc:6394}에게 보냅니다.",
		["Back to {npc:5878} on {area:1699}. {quest:1848} is the first piece; he then sends you to three crafters, one per piece: take all three."] = "{area:1699}의 {npc:5878}에게 돌아가세요. {quest:1848}이(가) 첫 번째 부위이며, 그 후 부위마다 한 명씩 장인 세 명에게 보냅니다. 셋 다 받으세요.",
		["Hillsbrad Miners"] = "{npc:2269}",
		["Iron Bars"] = "철 주괴",
		["Iron Bars: {npc:8673}"] = "철 주괴: {npc:8673}",
		["Roogug in {area:1717}"] = "{area:1717}의 루구그",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 30 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "루구그는 {zone:1413} 남쪽 끝의 던전 {area:1717} 안에 있는 정예 가시멧돼지(28레벨)입니다. 5인 던전이라 5인 파티가 필요하며, 그의 경비병도 함께 덤빕니다. 가이드는 먼저 30레벨까지 기다립니다. 안에서 첫 갈림길에서 왼쪽 길로 가서 돼지우리 위의 덩굴 다리를 건너고, 큰 가마솥이 있는 방을 지나가세요. 그는 오른쪽 방에서 기다립니다. {spell:403}을(를) 시전하고 바위 정령을 부릅니다. 약병은 항상 떨어집니다.",
		["Starts now at 20 at your trainer; four armor pieces at 30 (hauberk, helm, gauntlets, legguards), a shield on the way."] = "지금 20레벨에 상급자에게서 시작합니다. 30레벨에 방어구 네 부위(사슬 갑옷, 투구, 건틀릿, 다리보호구), 도중에 방패도 얻습니다.",
		["Take the zeppelin from {zone:1454} to {zone:1420}; {npc:6411} works in the {zone:1458}'s {object:36078}. She wants 8 Sturdy Dragonmaw Shinbones."] = "{zone:1454}에서 비행선을 타고 {zone:1420}(으)로 가세요. {npc:6411}은(는) {zone:1458}의 {object:36078}에서 일합니다. 그녀는 튼튼한 용아귀부족 정강이뼈 8개를 원합니다.",
		["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). With {quest:1846} from {npc:6411} in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131} (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "용아귀부족 오크(레벨 26-30)는 {zone:1437} 한가운데에 진을 치고 있습니다. 아라시의 {area:321}에서 남쪽으로 {area:881}를 건너가세요({area:150}은(는) 얼라이언스 지역입니다). {npc:6411}의 {quest:1846} 퀘스트를 목록에 갖고 있으면 약탈자, 늪길잡이, 백인대장, 어둠보초병, 해골감시자가 모두 {item:7131}을(를) 떨어뜨립니다(퀘스트가 없으면 떨어뜨리지 않습니다). 오른쪽 클릭으로 시험해 보면 약 4개 중 1개가 튼튼한 정강이뼈가 되고 나머지는 부서지므로, 8개를 얻으려면 30마리 이상 처치할 각오를 하세요. 이동하거나 싸우는 중에도 시험할 수 있습니다. 오크는 생명력이 15%가 되면 도움을 청하러 달아납니다. 약탈자는 그물을 던지고, 백인대장은 방패 가격을 쓰며, 어둠보초병은 {spell:686}을(를) 시전하고, 해골감시자는 해골을 일으킵니다.",
		["You need 10 Iron Bars. Miners smelt them from {item:2772} (one ore a bar, {spell:3307} at {skill:186} 125); everyone else buys them at the auction house in {zone:1454}."] = "철 주괴 10개가 필요합니다. 채광사는 {item:2772}을(를) 제련해 만들고(광석 하나에 주괴 하나, {skill:186} 125에 {spell:3307}), 그 외에는 {zone:1454} 경매장에서 사세요.",
		["You need 10 {item:7127}. The guide waits for level 30 first ({quest:1838} is a level 30 quest). The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "{item:7127} 10개가 필요합니다. 가이드는 먼저 30레벨까지 기다립니다({quest:1838}은(는) 30레벨 퀘스트입니다). 힐스브래드 광부(26-27레벨)는 {area:271} 서쪽 언덕의 광산에서 일하며, 다섯 마리 중 네 마리꼴로 남동석을 떨어뜨립니다. {spell:71}(으)로 싸우며, 방어도를 깎고 생명력 30%에서 도움을 청하러 도망갑니다. {area:272}(으)로 날아가서 남서쪽으로 가세요.",
		["{item:6840}, from the {npc:6167}"] = "{npc:6167}에게서 {item:6840}",
		["{item:6841}, from Roogug"] = "{item:6841}, 루구그에게서",
		["{item:7119}, from the silithid"] = "{item:7119}, 실리시드에게서",
		["{item:7126}, from the Windshear kobolds"] = "{item:7126}, 칼바람 코볼트에게서",
		["{item:7127}, from the Hillsbrad Miners"] = "{item:7127}, 힐스브래드 광부에게서",
		["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads: climb the broad ridge on the north or east side. {quest:1838} is a level 30 quest, so the guide waits for level 29 before you take it. {item:7587} list where each material comes from."] = "{npc:5878}의 오두막은 크로스로드 동쪽 {area:1699} 꼭대기에 있습니다. 북쪽이나 동쪽의 넓은 능선으로 올라가세요. {quest:1838}은(는) 30레벨 퀘스트이므로 가이드는 29레벨까지 기다린 뒤 수락합니다. {item:7587}에 각 재료를 어디서 얻는지 적혀 있습니다.",
		["{npc:6408} is in {area:367} on the {zone:1411} coast. He wants 7 Uncloven Satyr Hooves."] = "{npc:6408}은(는) {zone:1411} 해안의 {area:367}에 있습니다. 그는 갈라지지 않은 사티로스 발굽 7개를 원합니다.",
} end)()
t.guides["forever/class/warrior/fire-hardened-armor"] = (function() return {
		["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "20레벨에 {zone:1455}의 전사 상급자 {npc:5113}이(가) 붉은마루 산맥의 {quest:1698}에게 보냅니다.",
		["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "20레벨에 {object:2100} 전사 상급자 건물의 {npc:5480} 옆에 있는 {npc:5479}이(가) 붉은마루 산맥의 {quest:1698}에게 보냅니다.",
		["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "20레벨에 {zone:1457}의 전사 상급자 {npc:7315}이(가) 붉은마루 산맥의 {quest:1698}에게 보냅니다.",
		["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "사슬 갑옷을 위해 {object:28027}의 {npc:5413}에게 돌아가십시오. 그다음 그가 당신 종족의 대장장이에게 보냅니다. 다른 두 대장장이의 부위도 받을 수 있으니 직접 말을 거십시오.",
		["Charred and Galvanized Horns"] = "까맣게 탄 뿔과 번개 뿔",
		["Enter the {area:98} and come back; below ground, at the first fork"] = "{area:98}에 들어갔다가 돌아오기. 지하의 첫 번째 갈림길",
		["Fire Hardened Armor"] = "불에 달궈 만든 갑옷",
		["Roogug in {area:1717}"] = "{area:1717}의 루구그",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. The guide waits for level 28 first. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "루구그는 {zone:1413} 남쪽 끝의 던전 {area:1717} 안에 있는 정예 가시멧돼지(28레벨)입니다. 5인 던전이라 5인 파티가 필요하며, 그의 경비병도 함께 덤빕니다. 가이드는 먼저 28레벨까지 기다립니다. 안에서 첫 갈림길에서 왼쪽 길로 가서 뿌리 다리를 건너고, 비어 있는 큰 가마솥을 지나가세요. 그는 오른쪽 막다른 곳에 있으며, 가는 길에 정예가 10마리쯤 있습니다. {spell:403}을(를) 시전하고 바위 정령을 부릅니다. 약병은 항상 떨어집니다.",
		["Scorched Spider Fangs"] = "그을린 거미 송곳니",
		["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five; the guide waits for level 28 first. The Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "{area:42} 남쪽과 서쪽에 있는 {zone:1431}의 파멸의어둠일족 늑대인간(암흑길잡이, 송곳니투사, 흑마술사, 늑대인간, 타락전사, 26-31레벨)은 다섯 마리 중 네 마리꼴로 {quest:1705}을(를) 떨어뜨립니다. 가이드는 먼저 28레벨까지 기다립니다. 타락전사는 독을 쓰고 울부짖으며, 송곳니투사는 {spell:3427}을(를) 겁니다.",
		["The chimaeras live south-west of {area:460} in the {area:465}; the guide waits for level 28 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "키메라는 {area:460} 남서쪽의 {area:465}에 삽니다. 가이드는 먼저 28레벨까지 기다립니다. 어린 키메라(25-27레벨)와 새끼 키메라(23-25)에게서 까맣게 탄 뿔 12개가 필요하며 다섯 마리 중 네 마리꼴로 떨어지고, {npc:6167}(28, 큰 녀석)에게서 {item:6840}도 필요한데 역시 다섯 번에 네 번 떨어집니다. 그곳에는 어린 키메라 세 마리, 새끼 두 마리, 우두머리 한 마리만 살며 각각 5분 뒤에 다시 나타나므로 기다릴 각오를 하세요. 어린 키메라와 우두머리는 {spell:3396}을(를) 뱉고, 새끼는 {spell:403}을(를) 시전합니다. 얼라이언스: {area:467}(으)로 날아가서 남쪽으로 가세요.",
		["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once: the guide waits for level 30 first."] = "껍질은 {zone:1441} 서쪽 {area:482}의 협곡 안쪽, 와이번 둥지 아래 땅에 놓여 있습니다. 9개뿐이고 하나를 주우면 3분 뒤에 다시 생기므로 기다리게 됩니다. 껍질처럼 보여도 주울 수 없는 것도 있습니다. 마루둥지 와이번(28-31레벨)이 지키고 있고 가끔 여러 마리가 한꺼번에 오므로, 가이드는 먼저 30레벨까지 기다립니다.",
		["The {area:98}"] = "{area:98}",
		["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang, but the Highland Horrors and Lurkers (elites, 28-29) roam the same ground, so the guide waits for level 28. The spiders poison; back in 5 minutes."] = "송곳니 50개가 필요합니다. 긴다리흡혈거미와 긴다리동굴거미(21-22레벨)는 {area:836} 북쪽, {zone:1437} 한가운데를 기어다닙니다. 모두 송곳니를 떨어뜨리지만, 고원 공포와 잠복꾼(정예, 28-29)이 같은 곳을 돌아다니므로 가이드는 28레벨까지 기다립니다. 거미는 독을 씁니다. 5분 뒤 다시 나타납니다.",
		["{item:6839}, from the young chimaeras"] = "{item:6839}, 새끼 키메라에게서",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}, {npc:6167}에게서",
		["{item:6841}, from Roogug"] = "{item:6841}, 루구그에게서",
		["{item:6845}, from {npc:6170}"] = "{item:6845}, {npc:6170}에게서",
		["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield."] = "{npc:5413}은(는) 스톰윈드 드워프 지구에서 일합니다. 그가 {item:6843}을(를) 받고(잃어버렸다면 퀘스트를 포기하면 {npc:6166}이(가) 새것을 줍니다) 방패인 {item:6970}을(를) 줍니다.",
		["{npc:5413}'s next task, {quest:1701}, is a level 28 quest: its chimaeras and Roogug are level 28, so the guide waits for level 27 before you take it. Come back to {npc:5413} in the {object:28027} then; {item:6842} list what it needs."] = "{npc:5413}의 다음 임무인 {quest:1701}은(는) 28레벨 퀘스트입니다. 키메라와 루구그가 28레벨이므로 가이드는 27레벨까지 기다린 뒤 수락합니다. 그때 {object:28027}의 {npc:5413}에게 돌아오세요. {item:6842}에 필요한 것이 적혀 있습니다.",
		["{npc:6170} (level 32, not elite) carries the {item:6845}, four kills in five; the guide waits for level 32 first. He walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. He poisons and howls."] = "{npc:6170}(32레벨, 정예 아님)은(는) {item:6845}을(를) 지니고 있으며 다섯 번에 네 번꼴로 떨어뜨립니다. 가이드는 먼저 32레벨까지 기다립니다. 그는 {area:42} 남동쪽 {area:2161} 광산의 안쪽과 입구 사이를 오가므로, 입구에서 기다렸다가 밖으로 끌어내세요. 독을 쓰고 울부짖습니다.",
		["{quest:1698} sits in the inn at {area:69}. His test is timed, and it is a level 22 quest, so the guide waits for level 21 before you take it: before that, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698}은(는) {area:69}의 여관에 있습니다. 그의 시험은 시간제한이 있고 22레벨 퀘스트이므로, 가이드는 21레벨까지 기다린 뒤 수락합니다. 그 전에 {area:69} 북서쪽 언덕의 {area:98}(으)로 가는 길에 있는 붉은마루 놀을 정리하세요. 동굴 입구 옆 바위 위의 두 마리도 포함입니다(바위 오른쪽으로 올라가세요).",
		["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}, 파멸의어둠일족 늑대인간에게서",
} end)()
t.guides["forever/class/warrior/haggards-weapons"] = (function() return {
