t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "{npc:261366} 돕기: {npc:261367}와(과) {area:21} 해병이 능선을 올라오면 그의 곁에 있으세요",
		["At the {area:2362}"] = "{area:2362}에서",
		["Back east over the bridge and up the trail to {npc:5900}'s shrine again. {npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "다리를 건너 다시 동쪽으로 가서 오솔길을 따라 {npc:5900}의 제단으로 올라가세요. {npc:5900}이(가) 타르와 주머니로 {item:6636}을(를) 만들어 줍니다. 그 옆의 화로 곁에서 사용해 {npc:5893}을(를) 드러내고, 처치해 {item:6655}을(를) 얻은 뒤 잉걸불을 화로에 넣으세요.",
		["Back north along the beach to {area:392}."] = "해변을 따라 북쪽의 {area:392}(으)로 돌아가세요.",
		["Back north into {area:378} before the antennae fade: {npc:6394} is inside."] = "더듬이가 사라지기 전에 북쪽 {area:378}(으)로 돌아가십시오. {npc:6394}은(는) 안에 있습니다.",
		["Back out of the caverns and up to the cave above the entrance."] = "동굴에서 나와 입구 위의 동굴로 올라가십시오.",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them. Careful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near {npc:3438} and the supply crates, and {npc:267307} (20, elite) lies in the cave under {area:1699} beside them: pull {npc:3438} and the quilboar away from them one at a time, and leave the cave alone unless you are in a group."] = "서슬갈기일족 야영지로 돌아가세요. 흙점쟁이와 파수병이 동쪽 절반을 차지하고 있고, {npc:3438}은(는) 그들 사이를 걸어 다닙니다. 주의: 서슬갈기일족 살점먹보와 광전사(18-19)는 야영지 북동쪽, {npc:3438}와(과) 보급품 상자 근처에 있는 정예이고, 그 옆 {area:1699} 아래 동굴에는 {npc:267307}(20, 정예)이(가) 있습니다. {npc:3438}와(과) 가시멧돼지를 그들에게서 하나씩 떼어 끌어오고, 파티가 아니라면 동굴은 건드리지 마세요.",
		["Bristleback Geomancers"] = "뾰족털일족 흙점쟁이",
		["Bristleback camps"] = "뾰족털일족 야영지",
		["Crossroads flight master"] = "크로스로드 비행 조련사",
		["Dogran is chained up in the quilboar camp west of the road."] = "도그란은 길 서쪽 가시멧돼지 야영지에 사슬로 묶여 있습니다.",
		["Down the {area:458} to {area:378} again."] = "{area:458}을(를) 따라 다시 {area:378}(으)로 내려가십시오.",
		["East from {npc:261366} toward the {area:382}: {npc:9316} stands at the camp on the road north of the Crossroads."] = "{npc:261366}에게서 동쪽 {area:382} 방향으로 가세요. {npc:9316}은(는) 크로스로드 북쪽 길가 야영지에 있습니다.",
		["East to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, and {npc:3467} (16) stands beside them."] = "동쪽으로 해적 야영지 남쪽 끝의 해변으로 가세요. 장화 상자와 렌즈가 든 깨지기 쉬운 상자가 그곳에 있고, {npc:3467}(16)이(가) 그 옆에 서 있습니다.",
		["Fill the {item:7766} at the quilboar watering hole"] = "가시멧돼지 물웅덩이에서 {item:7766} 채우기",
		["Fly from the Crossroads to {area:1638}. {quest:853} waits in the {area:2197}, the cave under {area:1640}: hand in the spores there first, while their time runs. Then {npc:3033} trains you on {area:1639}."] = "크로스로드에서 {area:1638}(으)로 날아가세요. {quest:853}은(는) {area:1640} 아래 동굴인 {area:2197}에서 기다립니다. 제한 시간이 흐르는 동안 먼저 그곳에 포자를 제출하세요. 그다음 {area:1639}에서 {npc:3033}이(가) 훈련해 줍니다.",
		["Fly from {zone:1456} straight on to {area:392}."] = "{zone:1456}에서 곧장 {area:392}(으)로 비행하십시오.",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Follow the {area:458} south to {area:378}."] = "{area:458}을(를) 따라 남쪽 {area:378}(으)로 가십시오.",
		["For your {area:718} run: {npc:3446}'s next errand, {quest:1491}."] = "{area:718} 공략용: {npc:3446}의 다음 심부름인 {quest:1491}.",
		["For your {area:718} run: {npc:5767} and {npc:5768} stand in a hidden cave in the rocks above the entrance, at the north end of the oasis' west shore: climb up from the west side. Follow the arrow up."] = "{area:718} 공략용: {npc:5767}와(과) {npc:5768}은(는) 오아시스 서쪽 기슭 북쪽 끝, 입구 위 바위 속 숨겨진 동굴에 서 있습니다. 서쪽에서 올라가십시오. 화살표를 따라 올라가십시오.",
		["Grimtotem camp"] = "그림토템 야영지",
		["He gives you the {item:15826}"] = "그가 {item:15826}을(를) 줍니다",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "다음으로 {quest:1838}(1838, 30레벨)을(를) 줍니다. {area:1717}이(가) 필요하며 칼림도어와 동부 왕국 곳곳을 돌아다니게 합니다. 전사 직업 가이드 {quest:1838}에서 다룹니다.",
		["In from the north gate: {npc:3464} first, {npc:3338} by the inn, then up to {npc:3449} and {npc:3429} on the tower platform, where the flight master stands."] = "북문으로 들어가서 먼저 {npc:3464}, 여관 옆의 {npc:3338}을(를) 찾은 다음, 비행 조련사가 있는 탑 승강장으로 올라가 {npc:3449}와(과) {npc:3429}을(를) 찾으세요.",
		["In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "야영지에서는 풍수사와 가시마술사가 서쪽 절반을, 사냥꾼이 가운데를 차지하고, 보급품 상자는 동쪽 끝에 있습니다.\n여기 초원타조도 부리 수집에 포함됩니다.\n주의: 서슬갈기일족 살점먹보와 광전사(18-19)는 정예이며, 야영지 북동쪽 보급품 상자 옆에 서 있습니다. 가시멧돼지를 그들에게서 하나씩 떼어 끌어오세요.",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "보관하십시오: 다음 가이드의 {zone:1440}에 있는 {npc:12696}",
		["Keep {npc:3446}'s {quest:865} and {npc:3467} for the next {area:392} stop, at 18: Scytheclaws you meet on the plains before then drop the horns too."] = "{npc:3446}의 {quest:865}와(과) {npc:3467}은(는) 18레벨에 다음 {area:392} 방문 때까지 남겨 두세요. 그 전에 평원에서 만나는 갈퀴발톱 열대초원랩터도 뿔을 떨어뜨립니다.",
		["Kolkar camp"] = "콜카르일족 야영지",
		["Leave {zone:1454} by the main gate and follow the road south through {zone:1411}, then west over the {area:814} bridge: {npc:5810} stands at {area:379} just above it, on the road to the Crossroads."] = "정문으로 {zone:1454}을(를) 나가 길을 따라 남쪽 {zone:1411}을(를) 지난 뒤, 서쪽으로 {area:814} 다리를 건너십시오. {npc:5810}은(는) 다리 바로 위 {area:379}, 크로스로드로 가는 길에 서 있습니다.",
		["Level 20"] = "20레벨",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate."] = "{area:458}을(를) 따라 북쪽의 크로스로드로 가세요. {npc:3448}은(는) 남문에, {npc:3432}은(는) 여관 옆에, {npc:3428}은(는) 북문 서쪽에 있습니다.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate. Keep the {item:5075}: {npc:3430} takes it on the next stop in {area:378}."] = "{area:458}을(를) 따라 북쪽 십자로로 가십시오. {npc:3448}은(는) 남문에, {npc:3432}은(는) 여관 옆에, {npc:3428}은(는) 북문 서쪽에 있습니다. {item:5075}은(는) 보관하십시오. 다음에 {area:378}에 들를 때 {npc:3430}에게 줍니다.",
		["On the way back down the {area:1076}, {npc:11856} is held in {npc:11858}'s hut at the bend in the road. Once you take her quest she walks straight off south-east to {area:2538}, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly."] = "{area:1076}을(를) 따라 다시 내려가는 길에, {npc:11856}은(는) 길 굽이의 {npc:11858} 오두막에 갇혀 있습니다. 퀘스트를 받으면 그녀는 기다리지 않고 곧장 남동쪽의 불탄 마을 {area:2538}(으)로 걸어갑니다. 가까이 있으십시오. 그렇지 않으면 퀘스트가 실패합니다.\n주의: 불탄 마을에서 그림토템 셋이 매복해 있다가 당신이 아닌 그녀를 공격합니다. 그녀에게서 떼어내고 주문시전자를 빨리 처치하십시오.",
		["Raptor nests"] = "랩터 둥지",
		["Razormane camp"] = "서슬갈기일족 야영지",
		["South along the beach past the pirate camp to {area:385}, on the coast. The Theramore Marines and Preservers (15-16) drop the medals; {npc:3393} (20) and the two cannoneers (19) stand in the keep and on its walls.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier."] = "해변을 따라 해적 야영지를 지나 남쪽 해안의 {area:385}(으)로 가세요. 테라모어 해병과 보호자(15-16)가 훈장을 떨어뜨립니다. {npc:3393}(20)와(과) 포수 두 명(19)은 요새 안과 성벽 위에 있습니다.\n주의: 이름 있는 대상마다 치유사와 경비병이 연결되어 있고, 페어마운트에게는 해병 세 명이 더 붙어 있습니다. 치유사를 먼저 처치하면 전투가 쉬워집니다.",
		["South-west from {area:392} across the plains to the {area:1697}: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them. Each nest needs a {item:5165}: kill Sunscale raptors (most drop one) until you have three, then use a feather at each nest."] = "{area:392}에서 남서쪽으로 평원을 가로질러 {area:1697}(으)로 가세요. 둥지 세 개는 오아시스 남서쪽에 모여 있으며, 갈퀴발톱 열대초원랩터가 지키고 있습니다. 둥지마다 {item:5165}이(가) 필요합니다. 열대초원랩터를 처치해(대부분 하나씩 떨어뜨립니다) 세 개를 모은 뒤, 각 둥지에서 깃털을 사용하세요.",
		["Sunscale Scytheclaws hunt the plains around the {area:1697}; they drop the horns. {npc:3446} takes them back in {area:392}; any still missing come with {npc:3682}'s hills later.\nSouth-east toward the coast: the stolen silver lies in a raptor nest north-west of {area:385}."] = "갈퀴발톱 열대초원랩터는 {area:1697} 주변 평원에서 사냥하며 뿔을 떨어뜨립니다. {npc:3446}이(가) {area:392}에서 받습니다. 모자라는 것은 나중에 {npc:3682}의 언덕에서 채웁니다.\n남동쪽 해안으로 가세요. 도둑맞은 은은 {area:385} 북서쪽의 랩터 둥지에 있습니다.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. Careful: the spirits are Territorial Terrans (level 60) that kill whoever they see: stay off their paths, and click the statue again before the stealth runs out."] = "타우렌: {npc:11957}은(는) 다리 위 남쪽 언덕에서 기다립니다. 스카이본: {npc:272054}은(는) 쌍둥이 다리 남쪽에 있습니다. 그다음 호수 동쪽 굴로 가십시오. 변신을 풀고, 입구의 석상을 클릭해 5분간 은신하고, 안의 혼령을 피해 유물을 하나씩 가져가십시오. {item:280680}은(는) 흰 살쾡이 석상 아래에 있습니다. 주의: 혼령은 눈에 띄는 자를 모두 죽이는 영역 수호 테란(60레벨)입니다. 그들의 이동 경로를 피하고, 은신이 끝나기 전에 석상을 다시 클릭하십시오.",
		["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. {npc:3432}'s wife lies at their north edge, on your way south. Leave the quilboar for now: {npc:3430} in {area:378} wants the same camps cleared. {quest:883}, a grey kodo (level 22), sometimes wanders here: his hoof starts a quest. Leave him alone below level 21."] = "뾰족털일족 멧돼지인간 야영지는 {area:378} 북쪽 평원, {area:458} 양쪽에 퍼져 있습니다. {npc:3432}의 아내는 그 북쪽 끝, 남쪽으로 가는 길에 쓰러져 있습니다. 멧돼지인간은 지금은 놔두세요. {area:378}의 {npc:3430}이(가) 같은 야영지 소탕을 원합니다. 회색 코도인 {quest:883}(22레벨)이(가) 가끔 이곳을 돌아다니며, 그의 발굽으로 퀘스트가 시작됩니다. 21레벨 미만이면 건드리지 마세요.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "지역 북동쪽 구석 광산의 투자개발회사 감독과 투자개발회사 집행자가 {item:5097}을(를) 떨어뜨립니다.",
		["The antennae vanish fifteen minutes after they drop: kill the Silithid Swarmers and Creepers at the Silithid Mounds in the {area:390}, south of {area:378}, until you have five, then take them straight to {npc:6394} in {area:378}, before the thunderhawks. Careful: Silithid Swarmers (level 21-22) cast {npc:4196} both in and out of combat, which brings several small adds; Silithid Creepers (level 20-21) periodically cast {npc:5781} in combat, which spawns extra adds. A {npc:3253} (24, rare) also wanders the mounds: leave it."] = "더듬이는 떨어진 지 15분 뒤에 사라집니다. {area:378} 남쪽 {area:390}의 실리시드 흙더미에서 우두머리 실리시드와 독침 실리시드를 다섯 개가 될 때까지 처치한 뒤, 천둥매보다 먼저 곧장 {area:378}의 {npc:6394}에게 가져가십시오. 주의: 우두머리 실리시드(21-22레벨)는 전투 중에도 전투 밖에서도 {npc:4196}을(를) 시전해 작은 몹 여럿을 불러오고, 독침 실리시드(20-21레벨)는 전투 중 주기적으로 {npc:5781}을(를) 시전해 몹을 추가로 불러냅니다. {npc:3253}(24, 희귀)도 흙더미를 돌아다닙니다. 건드리지 마십시오.",
		["The pirates camp on the beach south of {area:392}: the piles of complicated parts lie in the sand among them. {npc:3467} (16) stands at the camp's southern end: leave him for the next {area:392} stop."] = "해적들은 {area:392} 남쪽 해변에 야영하고 있습니다. 복잡한 부품 더미는 그들 사이의 모래밭에 있습니다. {npc:3467}(16)은(는) 야영지 남쪽 끝에 서 있으니 다음 {area:392} 방문 때까지 남겨 두세요.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. {npc:3394} stands in the Kolkar camp west of the pools."] = "웅덩이는 {npc:3389} 바로 북쪽에 있습니다. 물에 들어가 탐험하세요. 헬브림에게 줄 숙성한 버섯은 그 주변에 자랍니다. 지나가며 만나는 콜카르일족은 모두 처치해 손목보호대를 얻으세요. {npc:3394}은(는) 웅덩이 서쪽의 콜카르일족 야영지에 서 있습니다.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "길은 {area:1076}(이)라는 이름으로 북쪽으로 올라갑니다. {quest:1483}의 오두막은 길이 동쪽 {area:461}(으)로 갈라지는 곳에 있습니다.",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}."] = "민달팽이가 든 공구 양동이는 {area:382}의 투자개발회사 시추 현장 주변에 있습니다.",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960}은(는) {object:172982} 아래 협곡입니다.",
		["The {object:177794} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177794}은(는) {area:382} 북쪽 가장자리, 투자개발회사 탑 옆에 있습니다. {quest:30}용 {item:15883}이(가) 들어 있습니다.",
		["The {object:4141} stands at the Venture Co. research site west of the {area:382}. Close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471} beside it.\nCareful: Several guards stand within aggro range of the valves, respawn in under about 3 minutes, and run at low health to bring back help; nearby mobs also join if you use a valve while they are close."] = "{object:4141}은(는) {area:382} 서쪽의 투자개발회사 연구 현장에 있습니다. 시추기 주변의 밸브 세 개를 잠그고 제어판을 다시 사용한 뒤, 그 옆의 {npc:3471}에게서 {item:5089}을(를) 얻으세요.\n주의: 여러 경비병이 밸브 근처 감지 범위 안에 서 있고, 약 3분 안에 다시 나타나며, 생명력이 낮아지면 도망쳐 도움을 불러옵니다. 근처 몹이 가까이 있을 때 밸브를 사용하면 그들도 합류합니다.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:209797} (level 20 elite) needs a group of 2. Skip it if you are alone."] = "정예 몬스터입니다. 파티를 권장하니 함께할 사람을 찾으세요. {npc:209797}(20레벨 정예)은(는) 2인 파티가 필요합니다. 혼자라면 건너뛰세요.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:267307} (level 20 elite) needs a group of 3 and sits deep in the cave under {area:1699}, past the Razormane Flesheaters and Berserkers (18-19, elite). Skip it if you are alone."] = "정예 몹입니다. 파티를 권장하니 함께할 사람을 찾아보십시오. {npc:267307}(20레벨 정예)은(는) 3인 파티가 필요하며, 서슬갈기일족 살점먹보와 광전사(18-19, 정예)를 지나 {area:1699} 아래 동굴 깊숙이 있습니다. 혼자라면 건너뛰십시오.",
		["Thunderhawk Cloudscrapers circle over the plains south of the camp."] = "비단천둥매가 야영지 남쪽 평원 위를 맴돕니다.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard (level 24), roams among them: his Tailspike starts a quest. Leave him alone below level 23."] = "천둥꼬리도마뱀이 {area:378} 바로 남쪽 평원에서 풀을 뜯습니다. 파란 천둥꼬리도마뱀 {quest:884}(24레벨)이(가) 그 사이를 돌아다니며, 그 꼬리가시로 퀘스트가 시작됩니다. 23레벨 미만이면 건드리지 마세요.",
		["Twitching Antennae"] = "꿈틀거리는 더듬이",
		["Twitching Antennae from the silithid"] = "실리시드에게서 꿈틀거리는 더듬이",
		["Underwater"] = "물속",
		["Upstairs"] = "위층",
		["Warriors: take {quest:1824} from {npc:6394} now: it runs for 30 minutes from the accept. The antennae come first, at the Silithid Mounds south of the camp, then straight back to {npc:6394}; the thunderhawks after."] = "전사: 지금 {npc:6394}에게서 {quest:1824}을(를) 받으십시오. 수락한 때부터 30분 동안 진행됩니다. 야영지 남쪽의 실리시드 흙더미에서 더듬이를 먼저 모은 뒤 곧장 {npc:6394}에게 돌아가고, 천둥매는 그다음입니다.",
		["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "불탄 마을에서 서쪽 {area:2539}(으)로 가십시오. {npc:12816}은(는) 마을 바로 바깥, 마을 앞에 있습니다.",
		["West to the {area:383}. Any Witchwing harpy drops a talon: keep to the eastern slopes, where the Witchwing Harpies and Roguefeathers (14-15) nest; the Slayers and Windcallers (16-17) hold the western hills. Savannah Prowlers hunt the plains between {npc:3389} and the hills: take their claws on the way.\nCareful: There are 2 Witchwing Ambushers (level 17-18). They stay stealthed with Sneak while out of combat."] = "서쪽의 {area:383}(으)로 가세요. 칼날바람일족 하피는 모두 발톱을 떨어뜨립니다. 칼날바람일족 하피와 칼날바람일족 도적깃털(14-15)이 둥지를 튼 동쪽 비탈에 머무르세요. 학살자와 바람술사(16-17)는 서쪽 언덕에 있습니다. 굶주린 사바나 사자는 {npc:3389}와(과) 언덕 사이 평원에서 사냥하니 가는 길에 발톱을 모으세요.\n주의: 칼날바람일족 복병(17-18레벨)이 2마리 있습니다. 전투 중이 아닐 때는 은신 상태로 있습니다.",
		["West to {npc:3389}'s watch post on the Kolkar border."] = "서쪽으로 콜카르일족 경계의 {npc:3389} 감시 초소로 가세요.",
		["While you are in the camp: {npc:3429}'s Water Seekers and Thornweavers in its western half, the Hunters in the middle, the supply crates at its eastern end.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "야영지에 있는 동안: {npc:3429}의 풍수사와 가시마술사는 서쪽 절반에, 사냥꾼은 가운데에, 보급품 상자는 동쪽 끝에 있습니다.\n주의: 서슬갈기일족 살점먹보와 광전사(18-19)는 정예이며, 야영지 북동쪽 보급품 상자 옆에 서 있습니다. 가시멧돼지를 그들에게서 하나씩 떼어 끌어오세요.",
		["grind on {npc:3263}"] = "{npc:3263} 사냥",
		["{area:392}: {area:718} quests"] = "{area:392}: {area:718} 퀘스트",
		["{area:718} is a dungeon for a group of five, about levels 17 to 24, and a full run takes about an hour. Its mouth is just north of {npc:3396}'s shore, at the north end of {area:387}, under {npc:5767}'s cave.\nIn the caves before the portal: {npc:3655}, stealthed, with the {item:5334} (he moves between a few spots and comes back slowly: leave him if he's gone). Inside: the Deviates for {npc:5768}, and their hides for {npc:5767} (they drop rarely: one run may not be enough, so leave the rest for another run), {item:6464} from the Ectoplasms. After the four Fanglords, the {npc:3678} at the entrance leads you to Naralex: {npc:3654} drops the {item:10441}: its quest (someone in {area:392}, then {npc:8418} above the caverns) is not on this route; the Dungeons page's hand-in guide takes it."] = "{area:718}은(는) 약 17~24레벨 5인 파티용 던전이며, 전체 공략에 약 1시간이 걸립니다. 입구는 {npc:3396}의 기슭 바로 북쪽, {area:387} 북쪽 끝의 {npc:5767} 동굴 아래에 있습니다.\n차원문 앞 동굴: 은신한 {npc:3655}이(가) {item:5334}을(를) 가지고 있습니다(몇몇 장소를 옮겨 다니며 천천히 돌아옵니다. 없으면 두십시오). 내부: {npc:5768}을(를) 위한 돌연변이, {npc:5767}을(를) 위한 그들의 가죽(드물게 떨어지므로 한 번으로는 부족할 수 있습니다. 나머지는 다음 공략에 맡기십시오), 엑토플라즘에게서 얻는 {item:6464}. 송곳니 군주 넷을 처치한 뒤 입구의 {npc:3678}이(가) 나랄렉스에게 안내합니다. {npc:3654}이(가) {item:10441}을(를) 떨어뜨립니다. 그 퀘스트({area:392}의 누군가, 그다음 동굴 위의 {npc:8418})는 이 경로에 없으며, 던전 페이지의 제출 가이드에서 다룹니다.",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, 호수 안의 {object:177785}에서",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{npc:3490}에게서 {item:2449}. 약초채집가는 평원에서 채집하십시오",
		["{item:6464}: the Ectoplasms"] = "{item:6464}: 엑토플라즘",
		["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}의 {npc:11798}이(가) 드루이드를 그곳으로 태워 줍니다",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, {area:2362}에서",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: {npc:3033}이(가) 보낸 환영 인사",
		["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}, {npc:11858}의 오두막 안",
		["{npc:11857}: keep it, {npc:11864} at {area:460} in the {zone:1413} & Stonetalon guide"] = "{npc:11857}: 보관하십시오. {zone:1413} & 돌발톱 산맥 가이드의 {area:460}에 있는 {npc:11864}",
		["{npc:16227}, beside {npc:3442}"] = "{npc:3442} 옆의 {npc:16227}",
		["{npc:267310} stands on the north-east side of the Crossroads. {quest:97003} is a group quest: {npc:267307} is a level 20 elite boar in the Razormane's {area:1699} cave, east of the town, where the route goes back for {npc:3438} later."] = "{npc:267310}은(는) 크로스로드 북동쪽에 서 있습니다. {quest:97003}은(는) 파티 퀘스트입니다. {npc:267307}은(는) 마을 동쪽, 서슬갈기일족의 {area:1699} 동굴에 있는 20레벨 정예 멧돼지이며, 경로는 나중에 {npc:3438} 때문에 그곳으로 돌아갑니다.",
		["{npc:3338} by the inn first, then Helbrim by the north gate, {npc:3429} and {npc:3449} on the tower platform, {npc:3432} by the inn, and {npc:3448} at the south gate last. His seed test waits for the {npc:3395} pass at the {area:388}: go straight on north-west to the {area:383}. After the spores Helbrim offers {quest:853}, a delivery to {zone:1456} within 45 minutes: this route doesn't go there, so leave it (Druids take it on the next Crossroads stop, right before their flight to {zone:1456})."] = "먼저 여관 옆의 {npc:3338}, 그다음 북문 옆의 헬브림, 탑 승강장의 {npc:3429}와(과) {npc:3449}, 여관 옆의 {npc:3432}, 마지막으로 남문의 {npc:3448}을(를) 찾아가세요. 그의 씨앗 시험은 {area:388}의 {npc:3395}에게 가는 길까지 기다립니다. 지금은 곧장 북서쪽의 {area:383}(으)로 가세요. 포자를 제출하면 헬브림이 {quest:853}을(를) 주는데, 45분 안에 {zone:1456}까지 배달하는 퀘스트입니다. 이 경로는 그곳에 가지 않으니 받지 마세요(드루이드는 다음 크로스로드 방문 때, {zone:1456}(으)로 날아가기 직전에 받습니다).",
		["{npc:3389}: {npc:3395} comes out when you kill the Kolkar at the {area:388}, later"] = "{npc:3389}: {npc:3395}은(는) 나중에 {area:388}에서 콜카르일족을 잡으면 나타납니다",
		["{npc:3390}: 45 minutes, for Zamah on the {zone:1456} step next"] = "{npc:3390}: 45분, 바로 다음 {zone:1456} 단계의 자마에게",
		["{npc:3391}, upstairs"] = "{npc:3391}, 위층",
		["{npc:3391}: the crates lie at the south end of the beach camp, on the next {area:392} stop at 18"] = "{npc:3391}: 상자는 해변 야영지 남쪽 끝에 있으며, 18레벨에 다음 {area:392} 방문 때 합니다",
		["{npc:3395} doesn't wander on his own: he comes out when you kill the Kolkar centaurs at the {area:388}, south-east of the Crossroads. Keep killing them around the oasis until he appears. Test {npc:3448}'s seeds at the bubbling fissure on the oasis' east bank while you are there."] = "{npc:3395}은(는) 스스로 돌아다니지 않습니다. 크로스로드 남동쪽 {area:388}에서 콜카르일족 켄타우로스를 잡으면 나타납니다. 나타날 때까지 오아시스 주변에서 계속 잡으세요. 그곳에 있는 동안 오아시스 동쪽 기슭의 부글거리는 균열에서 {npc:3448}의 씨앗을 시험하세요.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to {npc:3389} on your last Crossroads stop. Oasis Snapjaws crawl in the oasis' water there: their shells are for {npc:3448}."] = "{npc:3396}은(는) {npc:3389}의 남쪽, {area:387} 서쪽 기슭에서 콜카르일족을 이끕니다. 그는 북쪽 46,36부터 남쪽 46,42까지 그 기슭을 걸어 다닙니다. 화살표 위치에 없으면 만날 때까지 기슭을 따라가세요. 마지막 크로스로드 방문 때 그의 머리를 {npc:3389}에게 주세요. 그곳 오아시스 물속에는 오아시스 무쇠턱거북이 기어 다닙니다. 그 껍질은 {npc:3448}에게 줄 것입니다.",
		["{npc:3428}'s {quest:868} waits for this guide's last Crossroads stop: its eggs come on the next {zone:1413} guide's walk south, at about 25."] = "{npc:3428}의 {quest:868}은(는) 이 가이드의 마지막 크로스로드 방문까지 기다립니다. 알은 다음 {zone:1413} 가이드에서 25레벨쯤 남쪽으로 내려갈 때 모읍니다.",
		["{npc:3428}, west of the north gate: keep {quest:868}, its eggs lie on the next {zone:1413} guide's walk south from {area:378}, at about 25"] = "북문 서쪽의 {npc:3428}: {quest:868}은(는) 그대로 두세요. 알은 다음 {zone:1413} 가이드에서 25레벨쯤 {area:378}에서 남쪽으로 내려갈 때 모읍니다",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, 탑 꼭대기",
		["{npc:3430}, in the cage"] = "{npc:3430}, 우리 안",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{quest:4921}을(를) 제출하면 {npc:3432}이(가) {quest:95774}을(를) 줍니다",
		["{npc:3442} in {area:392}: on the next {area:392} stop"] = "{area:392}의 {npc:3442}: 다음 {area:392} 방문 때",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: 제어판은 나중에 {area:382}에서 처리합니다",
		["{npc:3448}: the Oasis Snapjaws at {area:387}, with {npc:3396} after the {zone:1454} trip"] = "{npc:3448}: {area:387}의 오아시스 무쇠턱거북, {zone:1454}에 다녀온 뒤 {npc:3396}와(과) 함께",
		["{npc:3448}: the bubbling fissure at the {area:388}, on the {npc:3395} pass"] = "{npc:3448}: {npc:3395}에게 가는 길에 {area:388}의 거품이 이는 균열",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}: 하피는 나중에 {area:383}에서 처리합니다",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465}은(는) 요새 안에 사슬로 묶여 있습니다. 대화해 호위를 시작하고 가까이 있으십시오. 나가는 길에 테라모어 병사가 공격합니다. 그가 {area:392}까지 함께 걸어갑니다.",
		["{npc:4049}: {quest:1063}, Magatha in {zone:1456}, on the next guide's way back from Zoram'gar"] = "{npc:4049}: {quest:1063}, {zone:1456}의 마가타. 다음 가이드에서 조람가르에서 돌아오는 길에",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197}은(는) {npc:3389}에서 서쪽으로 가는 길 끝, 돌발톱 산맥 입구의 트롤 마을 {area:2539}에 삽니다.",
		["{npc:4201}, inside"] = "{npc:4201}, 내부",
		["{npc:4201}: for {npc:3442}, beside {area:392}'s flight master at the end of the {zone:1413} & Stonetalon guide"] = "{npc:4201}: {zone:1413} & 돌발톱 산맥 가이드 마지막에 {area:392} 비행 조련사 옆의 {npc:3442}에게",
		["{npc:5767} and {npc:5768}"] = "{npc:5767}와(과) {npc:5768}",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878}은(는) {area:392}(으)로 가는 동쪽 길 옆에 진을 치고 있습니다.",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901}은(는) 북쪽으로 가는 길, {area:392} 남쪽 언덕에서 기다립니다.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, {item:5176}, {item:263412}",
		["{npc:5909}, a few steps away"] = "{npc:5909}, 몇 걸음 떨어진 곳",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018}은(는) 도시 서쪽의 {object:172961}에 서 있습니다.",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018}은(는) 도시 서쪽 {object:172961}에 있습니다.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}: 두 가이드 뒤 {zone:1458}의 {npc:4606}",
		["{quest:1483}, inside"] = "{quest:1483}, 내부",
		["{quest:1492}, on the dock"] = "부두의 {quest:1492}",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, 다음 가이드",
		["{quest:809}, beside {npc:3337}: from {npc:3216} in {zone:1454}"] = "{npc:3337} 옆의 {quest:809}: {zone:1454}의 {npc:3216}에게서",
		["{quest:853}, in the {area:2197}"] = "{area:2197}의 {quest:853}",
		["{zone:1454} class quests"] = "{zone:1454} 직업 퀘스트",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
		["{zone:1454}'s level 20 class quests come right after the Crossroads, and they are offered only from 20. Still short of 20? The Bristleback Geomancers (19-20) hold {area:1700} around you: kill them until level 20. Or, with a group, run the {area:718} dungeon instead."] = "{zone:1454}의 20레벨 직업 퀘스트는 크로스로드 바로 다음이며, 20레벨부터만 받을 수 있습니다. 아직 20레벨이 안 되었나요? 주변 {area:1700}에 뾰족털일족 흙점쟁이(19-20)가 있으니 20레벨까지 잡으세요. 또는 파티가 있으면 대신 {area:718} 던전을 도세요.",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Allister's Ambermill Investigations is for the ride through Silverpine at 22; leave it."] = "앨리스터의 앰버밀 조사는 22레벨에 은빛소나무 숲을 지날 때 하니 받지 마세요.",
		["Back out through the portal: {npc:3216} stands beside it."] = "차원문으로 다시 나가십시오. {npc:3216}은(는) 그 옆에 서 있습니다.",
		["Class trainer"] = "직업 전문가",
		["Follow the lake shore south from the murlocs: the {object:1593} lies at the ferry landing."] = "멀록이 있는 곳에서 호숫가를 따라 남쪽으로 가세요. {object:1593}은(는) 나루터에 있습니다.",
		["Follow the lake shore south-east from the Yoricks' house: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "요릭 가족의 집에서 호숫가를 따라 남동쪽으로 가세요. 그 길의 썩은지느러미멀록 갈퀴잡이와 썩은지느러미멀록 바다사냥꾼이 멀록 눈알을 떨어뜨립니다.",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "길을 따라 북동쪽으로 {area:238}의 요릭 가족 집까지 가세요.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood. Careful: Dalaran Apprentices (13) stand around the crate: pull them one at a time before you open it."] = "길을 따라 남쪽으로 가세요. {object:1627}은(는) 장작나무 마을 북쪽 길가에 있습니다. 주의: 달라란 견습생(13)이 상자 주위에 서 있습니다. 상자를 열기 전에 하나씩 끌어내세요.",
		["For your {area:2437} run: the {object:172960} is the canyon under the {object:172982}; {npc:3216} stands at its far end, next to the {area:2437} portal."] = "{area:2437} 공략용: {object:172960}은(는) {object:172982} 아래의 협곡입니다. {npc:3216}은(는) 그 맨 끝, {area:2437} 차원문 옆에 서 있습니다.",
		["From the ferry back west up the road to the {area:228}."] = "나루터에서 길을 따라 다시 서쪽 {area:228}까지 올라가세요.",
		["Mottled Worgs"] = "점박이 검은늑대",
		["Mottled Worgs prowl the hills around the house."] = "점박이 검은늑대가 집 주변 언덕을 배회합니다.",
		["North again to the Yoricks' house."] = "다시 북쪽으로 요릭 가족 집에 가세요.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field. Careful: {npc:1983} (14) rises once you have killed rot hide gnolls in the field: fight her with full health."] = "{area:228} 북쪽입니다. {npc:1983}이(가) {area:240}에 출몰합니다. 처치한 뒤 들판을 가로지르세요. 주의: 들판에서 썩은가죽 놀을 처치하면 {npc:1983}(14)이(가) 나타납니다. 생명력이 가득 찬 상태로 싸우세요.",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "{object:36126}의 {npc:10181}와(과) 대화하세요: {quest:93739}",
		["Speak with {npc:10540}, in Grommash Hold"] = "{npc:10540}에게 말을 거세요, 그롬마쉬 요새 안",
		["Speak with {npc:3230}, in Grommash Hold"] = "{npc:3230}에게 말을 거세요, 그롬마쉬 요새 안",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "{zone:1420} 방향으로 길을 따라 북쪽으로 가세요. {area:238}의 요릭 가족 집이 가는 길에 있습니다. {quest:425}은(는) 그 서쪽으로 조금 걸어간 곳에 숨어 있습니다.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "부들과 창풀은 골목길 동쪽, {object:172958}의 물가를 따라 자랍니다.",
		["The {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "{object:172960}은(는) {object:172982} 아래의 협곡입니다. {quest:829}은(는) 그 맨 끝에 서 있습니다.",
		["Vile Fin murlocs"] = "썩은지느러미멀록",
		["Walk in by the main gate. {npc:3310}, the wind rider master, stands on the tower in the {object:172982}; {npc:6929} keeps the inn below it, {npc:268701} stands by the bank. Bind here: the Hearthstone brings you back from {zone:1421} beside the zeppelin towers and the road to the {zone:1413}."] = "정문으로 들어가십시오. 와이번 조련사 {npc:3310}은(는) {object:172982}의 탑 위에 서 있고, {npc:6929}은(는) 그 아래 여관을 운영하며, {npc:268701}은(는) 은행 옆에 서 있습니다. 이곳에 귀환 지점을 정하십시오. 귀환석이 {zone:1421}에서 비행선 탑과 {zone:1413}(으)로 가는 길 옆으로 데려다줍니다.",
		["Walk in through the main gate. {npc:268701} stands in the {object:172982}."] = "정문으로 들어가세요. {npc:268701}은(는) {object:172982}에 서 있습니다.",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["Zeppelin to {zone:1458}"] = "{zone:1458}행 비행선",
		["{area:159} is a short walk north up the road from the zeppelin towers; {npc:1499} is in the town hall."] = "{area:159}은(는) 비행선 탑에서 길을 따라 북쪽으로 조금 걸어가면 나옵니다. {npc:1499}은(는) 마을 회관에 있습니다.",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228}은(는) 숲 한가운데에 있는 포세이큰의 지하묘지 마을입니다. 필요한 사람은 모두 지하묘지 입구 주변에 서 있습니다. 박쥐 조련사 {npc:2226}은(는) 그 바로 동쪽에 있습니다.",
		["{npc:11044}, in the Apothecarium"] = "연금술 실험실의 {npc:11044}",
		["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "연금술 상급자 {npc:11046}은(는) {npc:3348}의 옆집에 서 있습니다.",
		["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046}: 야영 기초, {zone:1411}의 브락의 모닥불에서",
		["{npc:11066}, the enchanting trainer, works in the Drag."] = "마법부여 상급자 {npc:11066}은(는) 골목길에서 일합니다.",
		["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066}: 야영 기초, {zone:1411}의 브락의 모닥불에서",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}: 퀸을 위해, 마지막에 북쪽 길에서",
		["{npc:1952}, below ground"] = "{npc:1952}, 지하",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978}은(는) 집 북동쪽에서 기다립니다. 그를 {npc:1950}에게 호위하세요. 가는 길에 늑대가 공격합니다.",
		["{npc:2226}: {npc:4556} in the {zone:1458}, at the end of this guide; no need to buy the flight"] = "{npc:2226}: 이 가이드 마지막에 {zone:1458}의 {npc:4556}에게, 비행 경로는 구입할 필요 없음",
		["{npc:246152}, in {area:159}"] = "{npc:246152}, {area:159}",
		["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "재봉술 상급자 {npc:2855}은(는) {object:172958}에 있습니다.",
		["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855}: 야영 기초, {zone:1411}의 브락의 모닥불에서",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348}와(과) {npc:3347}은(는) 골목길의 연금술 상점을 운영합니다. {npc:11046}은(는) 그 옆집에 있습니다.",
		["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "가죽세공 상급자 {npc:3365}은(는) {object:172958}에서 일합니다.",
		["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365}: 야영 기초, {zone:1411}의 브락의 모닥불에서",
		["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "약초채집 상급자 {npc:3404}은(는) 골목길에서 상점을 운영합니다.",
		["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404}: 야영 기초, {zone:1411}의 브락의 모닥불에서",
		["{npc:4551}, the bat handler"] = "박쥐 조련사 {npc:4551}",
		["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551}: {item:16210}은(는) 보관하세요. 22레벨에 다음 경유지인 {area:228}에서 포드리그가 받습니다",
		["{npc:4556}, the weapon merchant beside the bat handler"] = "박쥐 조련사 옆의 무기 상인 {npc:4556}",
		["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "기계공학 상급자 {npc:4586}은(는) {zone:1458}에서 일합니다.",
		["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586}: 야영 기초, 티리스팔의 {npc:265812}의 모닥불에서",
		["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "채광 상급자 {npc:4598}은(는) {zone:1458}에서 일합니다.",
		["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598}: 야영 기초, 티리스팔의 {npc:265812}의 모닥불에서",
		["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "대장기술 상급자 {npc:4605}은(는) {zone:1458}에서 일합니다.",
		["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605}: 야영 기초, 티리스팔의 {npc:265812}의 모닥불에서",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, 그롬마쉬 요새 안",
		["{npc:4949}: keep it, Thork at the Crossroads in the {zone:1413} guide"] = "{npc:4949}: 보관하세요. {zone:1413} 가이드의 크로스로드에 있는 톨크",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, 호드 지도자 순방",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "무두질 상급자 {npc:7088}은(는) {object:172958}에 서 있습니다.",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088}: 야영 기초, {zone:1411}의 브락의 모닥불에서",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264}은(는) 사람이 아니라 지하묘지 입구 바로 남쪽의 무덤 {object:24776}에서 완료합니다.",
		["{quest:829}: {quest:809} stands at {area:379}, on the next guide's road to the Crossroads"] = "{quest:829}: {quest:809}은(는) 다음 가이드에서 크로스로드로 가는 길의 {area:379}에 서 있습니다",
		["{quest:829}: {quest:832}, from the {item:4903} in {zone:1411}"] = "{quest:829}: {zone:1411}의 {item:4903}에서 시작한 {quest:832}",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Back down the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "{area:1076}을(를) 따라 {npc:4201}의 오두막으로 내려간 뒤, 길을 따라 동쪽 {area:461} 방향으로 가세요. {npc:4074}은(는) 갈림길 바로 동쪽 길을, {npc:4073}은(는) 더 북동쪽의 바위산 아래 비탈을 순찰합니다. 둘 다 홀로 다니는 벌목기 로봇이며 돌아다니니, 만날 때까지 길을 따라가세요.",
		["Back west to {npc:4201}' hut, on the way down to {area:2539}."] = "{area:2539}(으)로 내려가는 길에 서쪽 {npc:4201}의 오두막으로 돌아가십시오.",
		["Bael'dun fortress"] = "바엘던 요새",
		["Crossroads flight master"] = "크로스로드 비행 조련사",
		["East along the road from {area:2539} to {npc:4049}'s camp."] = "{area:2539}에서 길을 따라 동쪽으로 {npc:4049}의 야영지까지 가세요.",
		["Fly to {area:1638}"] = "{area:1638}(으)로 비행",
		["Fly to {area:1638} (without its flight path the arrow goes by {area:378} and {zone:1412}): two of its elders give quests worked on this guide's and the next guide's walks, and {npc:3419} takes Lydon's toxin."] = "{area:1638}(으)로 비행하세요(그곳 비행 경로가 없으면 화살표가 {area:378}와(과) {zone:1412}을(를) 거쳐 안내합니다). 그곳의 장로 두 명이 이 가이드와 다음 가이드의 여정에서 진행할 퀘스트를 주고, {npc:3419}에게 라이던의 독소를 제출합니다.",
		["Fly to {area:378}"] = "{area:378}(으)로 비행",
		["Fly to {area:378}: {npc:2995} on {zone:1456}'s central rise, or the Crossroads' wind rider master if you start this guide there."] = "{area:378}(으)로 비행하세요. {zone:1456} 중앙 언덕의 {npc:2995}, 또는 이 가이드를 크로스로드에서 시작한다면 크로스로드의 와이번 조련사입니다.",
		["Fly to {area:392}"] = "{area:392}(으)로 비행",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "길을 따라 북쪽의 {area:467}(으)로 가세요. 가는 길에 순록이 풀을 뜯고, 수액괴물, 황혼의 흑표범, 마룡은 봉우리 아래 숲을 돌아다니며, 세나리온 드루이드가 그곳 숲을 차지하고 있습니다.",
		["Follow the road on west past {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "길을 따라 계속 서쪽으로 {npc:4049}의 야영지를 지나 돌발톱 산맥으로 들어가세요. {npc:3995}은(는) {area:1076} 아래쪽, {area:2539}의 지하에서 기다립니다.",
		["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "길을 따라 서쪽으로 레그타르의 벙커를 지나가세요. {npc:4049}은(는) 돌발톱 산맥 가장자리의 길가에 야영하고 있습니다.",
		["Gaea Dirt Mounds"] = "가이아 흙더미",
		["Gaea Seeds"] = "가이아 씨앗",
		["Keep {npc:4202} (27) and {npc:4049}'s robots: {area:461} comes in one trip on the way back down from Sun Rock."] = "{npc:4202}(27)와(과) {npc:4049}의 로봇은 그대로 두세요. {area:461}은(는) 태양바위 은신처에서 내려오는 길에 한 번에 처리합니다.",
		["North up the road to {area:378}: your hearthstone takes you there if it is ready."] = "길을 따라 북쪽 {area:378}(으)로 가십시오. 귀환석이 준비되었다면 그곳으로 데려다줍니다.",
		["On down the {area:1076} to {area:2539}."] = "{area:1076}을(를) 따라 계속 {area:2539}(으)로 내려가십시오.",
		["On east to {area:461}, past where {npc:4073} roams: {quest:1096} (27) stands at the top of the Venture Co. tower. Clear the Venture Co. on the way up. His Mechanical Arm is for Ziz."] = "{npc:4073}이(가) 돌아다니는 곳을 지나 동쪽 {area:461}(으)로 계속 가세요. {quest:1096}(27)은(는) 투자개발회사 탑 꼭대기에 서 있습니다. 올라가는 길의 투자개발회사 일꾼들을 처치하십시오. 그의 기계 팔은 지즈에게 가져갑니다.",
		["On up the {area:1076} from {npc:4201}' hut to {area:460}."] = "{npc:4201}의 오두막에서 {area:1076}을(를) 따라 {area:460}까지 계속 올라가세요.",
		["Place the {item:5638} on the {object:19594}"] = "{object:19594}에 {item:5638} 놓기",
		["South of Camp Taurajo, on the road to {npc:3341}, the Silithid Mounds dot the {area:390}; the eggs lie in them, and Silithid Swarmers come out to defend them.\nCareful: Silithid Swarmers in the area release many tiny adds that interrupt spells; damage shields such as Thorns kill them in one hit."] = "타우라조 야영지 남쪽, {npc:3341}에게 가는 길의 {area:390}에 실리시드 흙더미가 흩어져 있습니다. 알은 그 안에 있으며, 우두머리 실리시드가 나와 지킵니다.\n주의: 이 지역의 우두머리 실리시드는 주문을 방해하는 작은 몹을 여럿 풀어놓습니다. 가시 같은 피해 보호막이면 한 방에 죽습니다.",
		["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight."] = "갠 남쪽 {area:359}에서 바엘던 드워프들이 발굴하고 있습니다. 바엘던 발굴인부와 현장감독이 구덩이에서 일하며, {npc:3392}(26)이(가) 일지를 가지고 있으니 그만 따로 끌어오십시오.\n주의: 발굴인부(21-22레벨)와 현장감독(22-23레벨)은 생명력이 15%로 떨어지면 도움을 청하러 달아나므로 드워프가 더 합류할 수 있습니다.",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south. Careful: the Burning Destroyers, Scorched Basilisks and Bloodfury Storm Witches here are level 27 and the valley floor is crowded: pull one at a time and keep to its edges."] = "해바위 야영지 남서쪽에 불타 버린 {area:465}이(가) 있습니다. 골짜기 바닥의 흙더미에 가이아 씨앗을 심으세요. 불의 정령은 {item:16312}을(를) 떨어뜨립니다. 혈폭풍하피와 복병은 북쪽에, 암살자와 약탈자는 남쪽에 둥지를 틀고 있습니다. 주의: 이곳의 불타는 파괴자, 그을린 바실리스크, 혈폭풍 폭풍마녀는 27레벨이고 골짜기 바닥은 붐빕니다. 하나씩 끌어오고 가장자리로 다니세요.",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "드워프의 비행 기계는 발굴 현장 안 발판 위에 있습니다. {npc:3341}이(가) 준 {item:5021}을(를) 그 위에 사용하세요.",
		["The flight lands at {area:378}'s wind rider master. {npc:3433} stands at the north edge of the camp, {npc:3387} and {npc:3430} (in the cage) in the middle."] = "비행편은 {area:378}의 와이번 조련사에게 도착합니다. {npc:3433}은(는) 야영지 북쪽 가장자리에, {npc:3387}와(과) {npc:3430}(우리 안)은(는) 한가운데에 있습니다.",
		["The flying machine"] = "비행 기계",
		["The next guide flies to {area:2897}: hearth to {area:378} if your hearthstone is ready, or walk on east to the Crossroads' flight master."] = "다음 가이드는 {area:2897}(으)로 비행합니다. 귀환석이 준비되었다면 {area:378}(으)로 귀환하고, 아니면 동쪽 크로스로드의 비행 조련사까지 걸어가십시오.",
		["The road west past {npc:4049}'s camp"] = "{npc:4049}의 야영지를 지나 서쪽으로 가는 길",
		["The {object:19594} is the platform just south-east of {npc:4202}'s tower: place Zamah's {item:5638} on it. Zamah takes it back on the next guide's {zone:1456} stop."] = "{object:19594}은(는) {npc:4202}의 탑 바로 남동쪽에 있는 발판입니다. 자마의 {item:5638}을(를) 그 위에 놓으세요. 자마의 퀘스트는 다음 가이드에서 {zone:1456}에 들를 때 제출합니다.",
		["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "{object:667362}은(는) 같은 남쪽 기슭 앞, {area:464} 바닥에서 자랍니다. 물속으로 들어가 식물과 마른 수렁풀 더미를 찾으세요. 둘 다 꼬투리를 줍니다. 호흡에 주의하세요.",
		["Up the {area:1076} to {npc:4201}' hut, where the road forks east to {area:461}: {npc:3442}'s orders are for him."] = "{area:1076}을(를) 따라 {npc:4201}의 오두막으로 올라가십시오. 그곳에서 길이 동쪽 {area:461}(으)로 갈라집니다. {npc:3442}의 지시는 그에게 가는 것입니다.",
		["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with {spell:1752}, so they can join a fight without warning."] = "갠 서쪽의 {area:1701}은(는) 서슬갈기일족이 차지하고 있습니다. {npc:3436}은(는) 동쪽에, {npc:3434}은(는) 남쪽에, {npc:3435}은(는) 서쪽 끝에 있습니다. 로크(25)와 서슬갈기일족 광전사(24-25)는 몇 레벨 높습니다. 희귀 정예 {npc:5859}이(가) 가끔 능선을 걸으니 피하십시오. 서슬갈기일족 길잡이와 정찰꾼이 기습용 단검을, 점쟁이가 마법봉을, 광전사가 전투용 방패를 떨어뜨립니다. 희귀한 붉은 바람뱀 {quest:885}이(가) 능선 위를 날며, 그 깃털로 퀘스트가 시작됩니다.\n주의: 서슬갈기일족 정찰꾼은 은신한 채 돌아다니며 {spell:1752}(으)로 공격하므로, 예고 없이 싸움에 합류할 수 있습니다.",
		["{area:718} quests still in your log: {npc:3446} stands beside the WANTED poster, Bigglefuzz on the dock by the flight master."] = "아직 퀘스트 목록에 있는 {area:718} 퀘스트: {npc:3446}은(는) 현상수배 전단 옆에, 비글퍼즈는 비행 조련사 옆 부두에 서 있습니다.",
		["{item:277936}, from any Bloodfury harpy"] = "혈폭풍하피 누구에게서나 얻는 {item:277936}",
		["{item:5736}, from {quest:1096}"] = "{item:5736}: {quest:1096}에게서",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: 혈폭풍하피에게서 얻는 {item:277936}",
		["{npc:11860}: Grish is at the {area:1718}, on the next guide's way into {zone:1441}"] = "{npc:11860}: 그리쉬는 다음 가이드에서 {zone:1441}(으)로 가는 길의 {area:1718}에 있습니다",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11862} 옆의 {npc:11861}",
		["{npc:11862}, up on the ledge"] = "바위 턱 위의 {npc:11862}",
		["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864}은(는) 해바위 야영지 안의 모닥불 옆에 있습니다. 카야가 살아 있다는 마카바의 소식은 그녀에게 전할 것입니다.",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, {npc:3341} 바로 동쪽 나무 위",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "와이번 조련사 {npc:2995}은(는) 중앙 언덕에 있습니다. 비행 경로가 없다면 얻으세요. {npc:3024}와(과) {npc:4721}은(는) 그의 동쪽으로 조금 걸어간 곳에 있습니다.",
		["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024}: {object:667362}은(는) 해바위 야영지 옆 {area:464}에서 자랍니다",
		["{npc:3419} stands in the {area:2197}, the caves under {area:1640}, west of {npc:2995}."] = "{npc:3419}은(는) {area:1640} 아래 동굴인 {area:2197}, {npc:2995} 서쪽에 있습니다.",
		["{npc:3419}: the {item:5638} goes on the {object:19594} at {area:461}, on this guide's Windshear trip"] = "{npc:3419}: {item:5638}은(는) 이 가이드의 바람가름 바위산 방문 때 {area:461}의 {object:19594}에 사용합니다",
		["{npc:3428}, west of the north gate"] = "북문 서쪽의 {npc:3428}",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, 탑 꼭대기",
		["{npc:3430}, in the cage"] = "{npc:3430}, 우리 안",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, 야영지 북쪽 가장자리",
		["{npc:3442} stands beside the flight master you land at. His new orders go back to {npc:4201} on the {area:1076}, later in this guide."] = "{npc:3442}은(는) 착륙하는 곳의 비행 조련사 옆에 있습니다. 그의 새 명령서는 이 가이드 후반에 {area:1076}의 {npc:4201}에게 다시 가져갑니다.",
		["{npc:3442}: for {npc:4201}, on the way up the {area:1076}"] = "{npc:3442}: {area:1076}을(를) 오르는 길의 {npc:4201}에게",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}: {npc:4201}에게서 받은 {quest:1094}",
		["{npc:3665}, on the dock"] = "부두의 {npc:3665}",
		["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way back down from Sun Rock"] = "{npc:4049}: {npc:4074}와(과) {npc:4073}은(는) {npc:4201} 동쪽을 돌아다닙니다. 태양바위 은신처에서 내려오는 길에",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "{npc:4198}의 다음 퀘스트인 오르다누스는 {zone:1440}의 얼라이언스 지역에 있습니다. 건너뛰세요.",
		["{npc:4198}, outside the gate"] = "정문 밖의 {npc:4198}",
		["{npc:4201}, inside"] = "{npc:4201}, 내부",
		["{npc:4201}: {npc:4202}, at the top of the Venture Co. tower on {area:461}"] = "{npc:4201}: {area:461}의 투자개발회사 탑 꼭대기에 있는 {npc:4202}",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}: 약병은 다음 가이드에서 {zone:1440}에서 얻습니다",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "{npc:5899}의 오두막은 {area:378} 남쪽, {area:359}(으)로 가는 길에 있는 가시멧돼지 물웅덩이 위 능선에 있습니다.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: 파란 물주머니는 다음 가이드에서 {zone:1440}에서 채웁니다",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: {area:272}에서 채운 빨간 물주머니",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "큰 쓰레샤돈인 {quest:873}은(는) {npc:3388} 동쪽, {area:391} 앞바다 얕은 곳에서 헤엄칩니다.",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "다시 길을 따라 남쪽으로 가세요. 길이 동쪽 {area:287}(으)로 꺾이는 곳의 {area:285}에서 {npc:2214}이(가) 기다립니다.",
		["Back to the outpost."] = "전초기지로 돌아가세요.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "북쪽 토막나무 주둔지로 가는 길가의 벌목기지에 있는 {npc:12867}에게 돌아가세요.",
		["Back up to {npc:2995} on the central rise and fly to {area:1637}."] = "중앙 언덕의 {npc:2995}에게 다시 올라가 {area:1637}(으)로 비행하세요.",
		["Below ground"] = "지하",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177844}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "길을 따라 은빛소나무 숲을 지나 {area:228}(으)로 가세요. 비행선 탑에서 출발한다면 티리스팔을 지나 남쪽으로, {object:177844}에서 출발한다면 해안에서 남동쪽으로 길까지 가세요. {npc:2121}와(과) {npc:1937}은(는) 지하 묘지 입구 옆에 서 있습니다.",
		["Druid trainer"] = "드루이드 상급자",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "전초기지 북쪽 해안을 따라 있는 성난지느러미일족 나가는 모두 머리를 떨어뜨립니다.",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Fly to {area:1637} from the {area:2897} flight master."] = "{area:2897}의 비행 조련사에게서 {area:1637}(으)로 비행하세요.",
		["Fly to {area:378}"] = "{area:378}(으)로 비행",
		["For your {area:153} run: the zeppelin lands beside the ruins. Walk into the {zone:1458} through them and down to the {object:36126}: {npc:266484} stands there, near {npc:10181}."] = "{area:153} 공략용: 비행선은 폐허 옆에 내립니다. 폐허를 지나 {zone:1458}(으)로 걸어 들어가 {object:36126}까지 내려가십시오. {npc:266484}은(는) 그곳 {npc:10181} 근처에 서 있습니다.",
		["For your {area:236} run, at the end of the {area:287} guide: {npc:1952} stands below ground in the crypt."] = "{area:236} 공략용({area:287} 가이드 마지막): {npc:1952}은(는) 지하 묘지 안 지하에 서 있습니다.",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "세레스의 야영지에서 북동쪽으로 {zone:1413}을(를) 가로질러 크로스로드 북쪽의 길로 가세요. 피줄의 탑에서 오는 도적은 서쪽으로 가서 그 길에 합류하세요. {npc:8582}은(는) 길이 {zone:1440}(으)로 들어가는 {area:1703}의 감시탑 위에 서 있습니다.",
		["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "{area:378}에서 길을 따라 서쪽 관문을 지나 {zone:1412}(으)로 들어간 뒤, 북쪽으로 {area:222}을(를) 지나 {zone:1456}(으)로 가세요. 절벽 아래의 승강기를 타면 위로 올라갑니다.",
		["Head west along the main road across {zone:1440}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west: {npc:12719} and {npc:12717} stand around it, the {npc:12863} beside the flight master. Its other quests, Thistlefur's among them, are for the next visit, at 26."] = "큰길을 따라 서쪽으로 {zone:1440}을(를) 가로질러 {area:415}(얼라이언스: 길에서 벗어나지 마세요)을(를) 지나 해안까지 가세요. {area:2897}은(는) 북서쪽 {area:414}에 있습니다. {npc:12719}와(과) {npc:12717}이(가) 그 주변에, {npc:12863}이(가) 비행 조련사 옆에 서 있습니다. 엉겅퀴털 퀘스트를 비롯한 그곳의 다른 퀘스트는 26레벨에 다음으로 올 때 처리합니다.",
		["Naga brazier"] = "나가 화로",
		["Naga heads"] = "나가 머리",
		["On the roads around {area:233}, step into the town's outskirts: Protectors guard them and Mages the town; both drop pendants. Careful: each Mage (15) fights with a {npc:2540} (15) beside it: pull one Mage at a time from the outskirts. Stay out of the middle, where {npc:2120} (22) stands."] = "{area:233} 주변 길에서 마을 외곽으로 들어가세요. 외곽은 수호병이, 마을은 마법사가 지키며 둘 다 펜던트를 떨어뜨립니다. 주의: 마법사(15)는 각각 {npc:2540}(15)과(와) 함께 싸우니, 외곽에서 마법사를 하나씩 끌어오세요. {npc:2120}(22)이(가) 있는 마을 한가운데는 피하세요.",
		["On the way west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "서쪽으로 가는 길에, {npc:267214}이(가) {area:415} 남동쪽, 큰길 남쪽의 협곡에 갇혀 있습니다. 검은뿔순록과 잿빛골짜기곰이 주변 숲을 돌아다닙니다.",
		["Out of the ruins, take the road south through Tirisfal into {zone:1421} and on to the {area:228}."] = "폐허에서 나와 길을 따라 남쪽으로 티리스팔을 지나 {zone:1421}에 들어간 뒤 {area:228}까지 가십시오.",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "{npc:267214}의 {npc:271181}을(를) 조종해 4분 안에 협곡에서 큰길까지 데려가세요. 정신 집중이 끊기면 {npc:267214}에게 다시 부탁하세요.",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "나이트 엘프 {quest:6503}(23-24)이(가) 벌목기지 남쪽과 남동쪽 숲에 숨어 다닙니다. 은신하므로 주의하세요.",
		["The quest hands you a {item:210713}: use it beside the {object:645153} to offer your blood, then kill the elite spirit that answers.\n{quest:95883} is elite: grouping up is advised."] = "퀘스트에서 {item:210713}을(를) 줍니다. {object:645153} 옆에서 사용해 피를 바친 뒤, 응답하는 정예 영혼을 처치하세요.\n{quest:95883}은(는) 정예 퀘스트입니다. 파티를 권장합니다.",
		["The {area:153} is a dungeon for a group of five, about levels 15 to 22, in the ruined city above the {zone:1458}: its portal is in the ruins you walked through.\nInside: every undead can drop {item:268580} for {npc:266484}, so clear as you go. {npc:250660} can drop an {item:280438}, which starts a quest for {npc:2055}, and a {npc:256102} found inside starts one for {npc:7825}: both are in the {zone:1458}, on this route's next stop there."] = "{area:153}은(는) {zone:1458} 위 폐허가 된 도시에 있는 약 15~22레벨 5인 파티용 던전입니다. 차원문은 지나온 폐허 안에 있습니다.\n내부: 모든 언데드가 {npc:266484}에게 줄 {item:268580}을(를) 떨어뜨릴 수 있으니 처치하며 나아가십시오. {npc:250660}은(는) {npc:2055}에게 가는 퀘스트를 시작하는 {item:280438}을(를) 떨어뜨릴 수 있고, 내부에서 찾은 {npc:256102}은(는) {npc:7825}에게 가는 퀘스트를 시작합니다. 둘 다 {zone:1458}에 있으며, 이 경로가 다음에 그곳에 들를 때 처리합니다.",
		["To {zone:1456}"] = "{zone:1456}(으)로",
		["Warsong lumber camp"] = "전쟁노래부족 벌목기지",
		["Zeppelin to {zone:1458}"] = "{zone:1458}행 비행선",
		["{item:15882}, from the {object:177844}"] = "{item:15882}: {object:177844}에서",
		["{item:271343}, from a {npc:1973}"] = "{npc:1973}에게서 얻는 {item:271343}",
		["{item:271350}, from the Tortured Souls among the ruins; below ground"] = "폐허의 괴로워하는 영혼에게서 얻는 {item:271350}, 지하",
		["{npc:12696}'s hunt targets Ursangous and Shadumbra are for the next {zone:1440} visit, at 26; Sharptalon (31) only from level 30."] = "{npc:12696}의 사냥 대상인 우르산고우스와 샤둠브라는 26레벨에 다음으로 {zone:1440}에 올 때 처리합니다. 뾰족발톱(31)은 30레벨부터 처리하세요.",
		["{npc:1952}, below ground"] = "{npc:1952}, 지하",
		["{npc:2121}: {area:233}'s pendants, on the same roads"] = "{npc:2121}: {area:233}의 펜던트, 같은 길에서",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: {area:272}의 다르탈리아",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{area:272}의 {npc:2391}이(가) 독 조제를 가르칩니다: 보관하세요",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152}은(는) 비행선 탑에서 길을 따라 북쪽으로 조금 걸어가면 나오는 {area:159}에서 성기사를 훈련시킵니다. 은빛소나무 숲으로 가려면 같은 길로 다시 내려오세요.",
		["{npc:271181}, on the road"] = "길 위의 {npc:271181}",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:4046} stands on {area:1639} to the east; {npc:3419} in the {area:2197}, the caves under {area:1640} to the west."] = "와이번 조련사 {npc:2995}은(는) 중앙 언덕에 있습니다. 비행 경로가 없다면 얻으세요. {npc:4046}은(는) 동쪽 {area:1639}에, {npc:3419}은(는) 서쪽 {area:1640} 아래 동굴인 {area:2197}에 있습니다.",
		["{npc:3419}: her note is for {npc:2216} in {area:272}, next guide"] = "{npc:3419}: 그녀의 쪽지는 다음 가이드에서 {area:272}의 {npc:2216}에게",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875}은(는) {object:172960}에 있습니다. 그곳 소환진에서 {item:6626}을(를) 사용하고 서큐버스를 쓰러뜨려 속박하십시오.",
		["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389}은(는) 지하 묘지 입구 바로 서쪽에 서 있습니다. {zone:1458}에서 가져온 {item:16210}을(를) 그에게 건네주세요.",
		["{quest:1063} first: fly to {area:1638} from the {area:2897} flight master. {npc:4046} and {npc:3419} send you to {npc:2216} in {area:272}, the next guide's base, and {area:1638}'s flight path takes you on to {zone:1454}."] = "먼저 {quest:1063}: {area:2897}의 비행 조련사에게서 {area:1638}(으)로 비행하세요. {npc:4046}와(과) {npc:3419}이(가) 다음 가이드의 거점인 {area:272}의 {npc:2216}에게 보내며, {area:1638}의 비행 경로로 {zone:1454}까지 이어서 갈 수 있습니다.",
		["{quest:1063} first: fly to {area:378} from the {area:2897} flight master and walk on to {zone:1456}. {npc:4046} and {npc:3419} send you to {npc:2216} in {area:272}, the next guide's base, and {zone:1456}'s flight path takes you on to {zone:1454}."] = "먼저 {quest:1063}: {area:2897}의 비행 조련사에게서 {area:378}(으)로 비행한 뒤 {zone:1456}까지 걸어가세요. {npc:4046}와(과) {npc:3419}이(가) 다음 가이드의 거점인 {area:272}의 {npc:2216}에게 보내며, {zone:1456}의 비행 경로로 {zone:1454}까지 이어서 갈 수 있습니다.",
		["{quest:92421}: the {item:268580}, inside"] = "{quest:92421}: {item:268580}, 내부",
		["{zone:1456}'s central rise"] = "{zone:1456}의 중앙 언덕",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Back north up the road to the {area:228}: {npc:1938} stands just north of Allister."] = "길을 따라 북쪽 {area:228}(으)로 돌아가십시오. {npc:1938}은(는) 알리스터 바로 북쪽에 서 있습니다.",
		["Bears, creepers and lions"] = "곰, 거미, 사자",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues, Watchmen and Shadow Mages hold the camps along the way; the Shadow Mages carry Lydon's Vials of Innocent Blood."] = "드럴과 {npc:2238}은(는) {area:275} 안뜰 건물 안에 사슬로 묶여 있습니다. 자물쇠를 열려면 열쇠가 필요합니다. {npc:2427}이(가) {item:3467}을(를), {npc:2428}이(가) {item:3499}을(를) 가지고 있으며, 둘 다 요새 안에 있습니다. 이들을 처치한 뒤 자물쇠 두 개를 모두 여세요.\n{area:272}에서 남동쪽으로 {area:275}(으)로 가는 길의 언덕으로 가세요. 길목의 야영지에는 비밀결사대 도적, 비밀결사대 경비병, 비밀결사대 어둠마법사가 있습니다. 비밀결사대 어둠마법사가 라이던의 순결한 피가 든 유리병을 가지고 있습니다.",
		["Drull's ball and chain"] = "드럴의 족쇄",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "여관 옆의 {object:107045}에서 {item:7768}을(를) 채우세요",
		["For your {area:236} run: {npc:1952} stands below ground in the crypt, {npc:1938} just north of Allister."] = "{area:236} 공략용: {npc:1952}은(는) 지하 묘지 안 지하에, {npc:1938}은(는) 알리스터 바로 북쪽에 서 있습니다.",
		["From {area:272} fly to the {area:228}: {npc:2121} stands by the crypt entrance."] = "{area:272}에서 {area:228}(으)로 비행하세요. {npc:2121}은(는) 지하 묘지 입구 옆에 서 있습니다.",
		["Hadrec and {npc:1938}"] = "하드렉과 {npc:1938}",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms. Careful: Kirin Tor Guards (55) stand north of the farms, on the road up toward Alterac: keep to the fields."] = "{area:287} 마을 동쪽의 농장입니다. {npc:232}은(는) 북쪽 농가 옆 밭에서, {npc:2403}은(는) 더 남동쪽 밭에서 일합니다. 힐스브래드 농노와 힐스브래드 농부는 곳곳에 있습니다. {npc:2451}은(는) 농장 남쪽 밭을 돌봅니다. 주의: 키린 토 경비병(55)이 농장 북쪽, 알터랙으로 올라가는 길에 서 있습니다. 밭을 벗어나지 마세요.",
		["The {item:280438} from the {area:153}: Faranell takes it here."] = "{area:153}에서 얻은 {item:280438}: 파라넬이 이곳에서 받습니다.",
		["The {quest:95204} from your {area:153} run: {npc:7825} takes it."] = "{area:153} 공략에서 얻은 {quest:95204}: {npc:7825}이(가) 받습니다.",
		["Train and restock in the {zone:1458} before the zeppelin."] = "비행선을 타기 전에 {zone:1458}에서 기술을 배우고 보급품을 채우세요.",
		["Train before you fly on: the next guide flies from here."] = "다시 날아가기 전에 기술을 배우세요. 다음 가이드는 이곳에서 비행으로 시작합니다.",
		["Train with {npc:3033}. {npc:3419}, in the {area:2197} under {area:1640}, takes Lydon's toxin if you carry it. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "{npc:3033}에게 기술을 배우세요. {area:1640} 아래 {area:2197}에 있는 {npc:3419}에게 라이던의 독을 가지고 있다면 전달하세요. 다시 날아가기 전에, 와이번 조련사에서 동쪽으로 조금 걸어가면 있는 {npc:3024}와(과) {npc:4721}에게서 다음 가이드들의 이동 경로에서 진행할 퀘스트 두 개를 받으세요. 그런 다음 다음 가이드가 시작되는 크로스로드로 날아가세요.",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "타렌 밀농장 서쪽, 농장으로 내려가는 길의 언덕에 회색곰, 숲이끼거미, 굶주린 산사자가 돌아다닙니다. 숲이끼거미는 {item:3477}을(를) 드물게 떨어뜨리며, 하나만 있으면 됩니다.",
		["Your {area:153} limbs: {npc:266484} stands in the {object:36126}, just past the Apothecarium."] = "{area:153}에서 얻은 팔다리: {npc:266484}은(는) 연금술 실험실 바로 너머 {object:36126}에 서 있습니다.",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["{area:236} is a dungeon for a group of five, about levels 20 to 30, and a full run takes about an hour. Follow the road south from the {area:228}: the keep stands on the hill above {area:204}, its gate at the top of the path.\nInside: Rethilgore first; the Deathstalker freed from the cells after him opens the courtyard door, and {npc:4444} lies just inside the courtyard, to the right: hand {quest:1098} in to him there. Then {npc:3886}, {npc:3887}, {npc:4278}, {npc:4279}, {npc:4274} and {npc:3927}; {npc:4275} at the top drops his head for {npc:1938}."] = "{area:236}은(는) 약 20~30레벨 5인 파티용 던전이며, 전체 공략에 약 1시간이 걸립니다. {area:228}에서 길을 따라 남쪽으로 가십시오. 성채는 {area:204} 위 언덕에 있으며, 입구는 길 꼭대기에 있습니다.\n내부: 먼저 레실고어를 처치하십시오. 그 뒤 감옥에서 풀려난 죽음의 추적자가 안뜰 문을 열어 주며, {npc:4444}은(는) 안뜰 바로 안쪽 오른편에 쓰러져 있습니다. 그곳에서 그에게 {quest:1098}을(를) 제출하십시오. 그다음 {npc:3886}, {npc:3887}, {npc:4278}, {npc:4279}, {npc:4274}, {npc:3927} 순이며, 꼭대기의 {npc:4275}이(가) {npc:1938}에게 줄 머리를 떨어뜨립니다.",
		["{area:272} is your base for this guide: you come back here between each loop. Everyone stands around the town square."] = "{area:272}은(는) 이 가이드의 거점입니다. 매 순환 사이에 이곳으로 돌아옵니다. 모두 마을 광장 주변에 있습니다.",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: {area:2362}에서 조각을 사용하십시오",
		["{item:5620}, from the Syndicate Shadow Mages"] = "{item:5620}: 비밀결사대 어둠마법사에게서 얻습니다",
		["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}의 {npc:11798}이(가) 드루이드를 그곳으로 태워 줍니다",
		["{npc:1952}, below ground"] = "{npc:1952}, 지하",
		["{npc:2055}, in the Apothecarium"] = "연금술 실험실의 {npc:2055}",
		["{npc:2121}: {area:233}'s pendants"] = "{npc:2121}: {area:233}의 펜던트",
		["{npc:2216}: Zamah's note"] = "{npc:2216}: 자마의 쪽지",
		["{npc:2216}: his toxin is for {npc:3419}, on the {zone:1413} & Stonetalon guide's {zone:1456} stop"] = "{npc:2216}: 그의 독은 {zone:1413} & 돌발톱 가이드의 {zone:1456} 구간에서 {npc:3419}에게 전달합니다",
		["{npc:2216}: the vials come from the Syndicate Shadow Mages on the way to Durnholde"] = "{npc:2216}: 약병은 듀른홀드로 가는 길의 비밀결사대 어둠마법사에게서 얻습니다",
		["{npc:2230}, next to Lydon; inside"] = "라이던 옆의 {npc:2230}, 안",
		["{npc:2238}'s ball and chain"] = "{npc:2238}의 족쇄",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274}은(는) {npc:232}의 개로, {area:286}의 북쪽 농가에 있습니다.",
		["{npc:2391}: Poisons"] = "{npc:2391}: 독 조제",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}: {quest:97538}, 태양바위 근처 {area:464}의 어둠잡초",
		["{npc:3419}: the {item:5638}, for {area:461} in the next guide"] = "{npc:3419}: {item:5638}, 다음 가이드의 {area:461}용",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606}은(는) {object:36070}에 서 있습니다.",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}: {quest:1195}, {zone:1440}의 웃음짓는 자매에게서 얻는 약병",
		["{quest:1014}: the {item:5442}"] = "{quest:1014}: {item:5442}",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "갈라크일족 야영지에서 북쪽으로 조금 걸어가면 {area:1557}의 동굴이 가장 깊은 방까지 이어지며, 그곳에서 {object:20807}이(가) 타오르고 있습니다. 화로에 {item:5868}을(를) 사용한 뒤 곧바로 {item:5869}을(를) 획득하세요. 불꽃은 잠깐만 꺼져 있으며, 다시 붙으면 유리병은 사라집니다. 그런 다음 동쪽의 {npc:2986}이(가) 있는 고원으로 가세요.\n주의: 화로 옆에 갈라크일족 화염 경비병(30) 둘이 서 있고 켄타우로스 경비병 하나가 동굴을 순찰합니다. 불꽃을 끄기 전에 하나씩 끌어내 처치하세요.",
		["Back east to {area:484}."] = "동쪽의 {area:484}(으)로 돌아가세요.",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "남쪽 야영지로 돌아간 뒤, {zone:1456}에 올라가 {area:378}(으)로 날아가세요.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "북쪽 토막나무 주둔지로 가는 길가의 벌목기지에 있는 {npc:12867}에게 돌아가세요.",
		["Back west to Zoram'gar from Thistlefur before heading east for good."] = "완전히 동쪽으로 떠나기 전에 엉겅퀴가죽 소굴에서 서쪽 조람가르로 돌아가세요.",
		["Befouled Water Elementals drift around the lake's shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "타락한 물의 정령이 호숫가를 떠다닙니다. 정자는 얼라이언스 전초기지가 내려다보이는 섬에 있습니다.",
		["Below ground"] = "지하",
		["Class trainer"] = "직업 전문가",
		["Crossroads flight master"] = "크로스로드 비행 조련사",
		["East along the road from Seereth's camp to the Crossroads' wind rider master, and fly to {area:2897}. If your hearthstone is ready, hearth to {area:378} and fly from there instead."] = "세레스의 야영지에서 길을 따라 동쪽 크로스로드의 와이번 조련사로 가서 {area:2897}(으)로 비행하세요. 귀환석을 사용할 수 있다면 {area:378}(으)로 귀환한 뒤 그곳에서 비행하세요.",
		["Felmusk satyrs"] = "검은유혹의 사티로스",
		["Fly to {area:1638}"] = "{area:1638}(으)로 날아가기",
		["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "조람가르에서 {area:1638}(으)로 날아가세요. 비행 경로를 모른다면 {area:378}(으)로 날아가 {zone:1412}을(를) 지나 북쪽으로 걸어가세요.",
		["Fly to {area:378}"] = "{area:378}(으)로 날아가기",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "큰길을 따라 동쪽으로 {area:415}을(를) 지나가세요(얼라이언스: 길에서 벗어나지 마세요). 커다란 회색곰 {npc:12678}은(는) 길 남쪽, {area:421} 서쪽의 {area:418}을(를) 돌아다닙니다. 그의 발이 다음 사냥 퀘스트를 시작합니다.",
		["For your {area:2797} run, in the same tunnels as the Sapphires: {npc:12736}'s ruins errand. Look for a group now if you have none yet."] = "{area:2797} 공략용(사파이어와 같은 터널): {npc:12736}의 폐허 심부름. 아직 파티가 없다면 지금 구하십시오.",
		["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "{area:2360}에서 북동쪽으로, 길가의 전쟁노래부족 벌목기지로 가세요. {npc:12867}이(가) 그곳에 서 있습니다.",
		["Galak centaurs"] = "갈라크일족 켄타우로스",
		["Gazebo"] = "정자",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "{npc:264096}에게서 얻는 {item:273001}",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "길을 따라 계속 동쪽으로 가세요. {npc:12858}은(는) 전쟁노래부족 벌목기지 남서쪽에서 기다립니다. 그와 그의 부하들이 {area:2360}을(를) 습격합니다. 그들이 어그로를 끌게 하고 {npc:12860}이(가) 죽을 때까지 {npc:12858} 곁에 있으세요.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "{npc:10638}을(를) 노리고 오는 {npc:10720}을(를) 처치하세요",
		["Laughing Sisters"] = "웃는 자매",
		["Level 28"] = "28레벨",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} (30, elite) sits at the north end: leave her unless you do {quest:96261} with a group; her {item:273658} starts {quest:96294}."] = "야영지 북쪽에서 거미들이 {area:17044}의 매장지를 뒤덮고 있습니다. 갉아먹힌 시체에 {npc:264074}의 {item:273015}을(를) 사용하세요. 거미들은 {item:273181}을(를) 떨어뜨립니다. {npc:264082}(30, 정예)은(는) 북쪽 끝에 있습니다. 파티와 함께 {quest:96261}을(를) 하는 게 아니라면 건드리지 마세요. 그녀의 {item:273658}이(가) {quest:96294}을(를) 시작합니다.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns. Careful: Felmusk Rogues and Shadowstalkers move in stealth and join fights without warning."] = "토막나무 주둔지 북서쪽 숲에 검은유혹의 사티로스가 야영하고 있습니다. 사티로스는 누구나 뿔을 떨어뜨릴 수 있습니다. 주의: 검은유혹 도적과 그림자추적자는 은신한 채 움직이며 예고 없이 전투에 끼어듭니다.",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest. Careful: {npc:12676} is a level 31 nightsaber and hits hard: pull her alone, away from the Outrunners."] = "북동쪽의 토막나무 주둔지로 돌아가는 길: {npc:12676}은(는) 전쟁노래 벌목지 남동쪽 숲을 돌아다닙니다. 그녀의 발톱이 다음 사냥 퀘스트를 시작합니다. 주의: {npc:12676}은(는) 31레벨 밤호랑이로 강하게 공격합니다. 정찰병들에게서 떨어진 곳으로 혼자 끌어내세요.",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "{npc:10617}이(가) 음모 문서를 떨어뜨린 경우에만: {npc:10638}은(는) {area:2237}에 있습니다.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "승강기를 타고 내려가 길을 따라 동쪽으로 협곡을 지나 고원 꼭대기의 타우렌 마을인 {area:484}(으)로 가세요. 그곳 승강기는 북쪽에 있습니다.",
		["Sapphires of Aku'Mai"] = "아쿠마이의 사파이어",
		["Short of 28? The Grimtotem around these camps (25-28) are the right level: kill a few more before the climb to {npc:10646}. Past it, this step skips itself. Or, with a group, run the {area:2797} dungeon instead."] = "28레벨이 안 되나요? 이 야영지 주변의 그림토템부족(25-28)이 적정 레벨입니다. {npc:10646}에게 올라가기 전에 몇 마리 더 처치하세요. 28레벨이 넘으면 이 단계는 자동으로 건너뜁니다. 파티가 있다면 대신 {area:2797} 던전을 도세요.",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "레인우드 은신처에서 남쪽으로 가면, 달샘은 강 서쪽의 움푹한 곳에 있어 길에서는 잘 보이지 않습니다. {area:421}은(는) 그 서쪽에 있습니다. 달샘에서 {item:5867}을(를) 사용해 채우세요.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "{area:1638}의 {npc:3057}와(과) 대화하세요: {quest:93739}",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "승강기를 타고 내려가세요. 알은 협곡 바닥의 둥지에 있으며, 위치는 세 곳 중 하나입니다: 고원 남동쪽(52.3,55.2), 동쪽(56.4,50.4), 남서쪽(37.6,56.1).",
		["The Earthen Ring"] = "대지 고리회",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "썩은나무일족 털보숭이는 {area:421} 동쪽, 길 남쪽의 숲을 차지하고 있습니다. {object:178206}에 {item:16972}을(를) 놓고 지키세요. 털보숭이들이 깃발을 쓰러뜨리러 옵니다. {npc:12918}은(는) 마지막에 오며, 그의 토템은 바구니에 떨어집니다.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks a long path between the camps: if you meet him, kill him, his note starts a quest for {area:2237}. Don't wait for him. Careful: storm elementals roam the canyon floor around the camps: Stormheart (30), the Ravaging Tempests (40) and {npc:216463} (38), all elite. Keep clear of them."] = "갈라크일족 야영지가 높새바람 봉우리 북쪽 협곡을 가득 메우고 있으며, 모든 야영지에 척후병, 사냥꾼, 바람전사가 함께 있습니다. 홀로 다니는 {npc:10617}이(가) 야영지 사이의 긴 길을 오갑니다. 마주치면 처치하세요. 그의 쪽지가 {area:2237} 퀘스트를 시작합니다. 그를 기다리지는 마세요. 주의: 폭풍의 정령들이 야영지 주변 협곡 바닥을 돌아다닙니다. Stormheart(30), 파괴의 폭풍(40), {npc:216463}(38)이며 모두 정예입니다. 가까이 가지 마세요.",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "드라이어드인 웃는 자매들은 {npc:12677}의 숲 주변 {area:426}을(를) 돌아다닙니다. 그중 하나가 {npc:4721}의 {item:5867}을(를) 떨어뜨리며, 여러 마리를 처치해야 할 수도 있습니다.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "사파이어는 {area:2797} 차원문으로 이어지는 터널 벽에 박힌 푸른 수정으로, 인스턴스 밖 지하에 있습니다. 구덩이에서 헤엄쳐 내려가 벽 아래를 지나 동굴로 들어가세요. 터널의 사티로스와 나가는 정예입니다. 파티를 권장합니다. 수정은 빨리 다시 생기므로 깊이 들어갈 필요는 없습니다.",
		["The Wanted poster beside {npc:10537}"] = "{npc:10537} 옆의 현상수배 게시판",
		["The fountain stands in the middle of the {area:418}, where {npc:12678} roams: use the {item:7767} there."] = "분수는 {area:418} 한가운데에 있으며, {npc:12678}이(가) 그곳을 돌아다닙니다. 그곳에서 {item:7767}을(를) 사용하세요.",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "나이트 엘프 {quest:6503}(23-24)이(가) 벌목기지 남쪽과 남동쪽 숲에 숨어 다닙니다. 은신하므로 주의하세요.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "사파이어로 가는 길은 해안 북쪽 끝의 가라앉은 폐허를 지납니다. 계단을 내려가 구덩이로 들어가세요.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:10992} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone."] = "정예 몬스터입니다. 파티를 권장하니 함께할 사람을 찾아보세요. {npc:10992}은(는) 30레벨 정예입니다. 대부분의 직업은 32레벨에 혼자 처치할 수 있지만 도움이 필요할 수도 있습니다. 혼자라면 건너뛰세요.",
		["Thistlefur Hold"] = "엉겅퀴일족 소굴",
		["Underwater"] = "물속",
		["Warsong lumber camp"] = "전쟁노래부족 벌목기지",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "높새바람 봉우리 서쪽, {area:2097} 아래에 그림토템부족 야영지가 있습니다. 비밀 쪽지는 남동쪽, 남서쪽, 북서쪽 야영지의 {object:176344}에 있습니다.",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "미스트랄 호수 서쪽에서 커다란 회색곰 {npc:12678}이(가) {area:418}을(를) 돌아다닙니다. 이제 그의 발이 떨어집니다.",
		["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom. Highperch Patriarchs (30-31) and the rare Heartrazor (32) nest here too: pull around them."] = "백사장 야영지 서쪽, {area:482} 절벽에 와이번이 둥지를 틀고 있으며, 알은 둥지에 있습니다. {npc:10427}은(는) 둥지 동쪽에서 기다립니다. 풀어 주고 {area:2237}(으)로 돌아가는 동안 살려 두세요.\n주의: 28-29레벨 와이번이 머리 위를 날아다녀 예고 없이 끌려올 수 있습니다. 아래쪽 첫 번째 기둥을 지나면 와이번 셋이 기습할 수 있습니다. 우두머리 마루둥지 와이번(30-31)과 희귀 몹 심장칼날(32)도 이곳에 둥지를 틀고 있으니 피해서 끌어오세요.",
		["for {npc:5901}, south of {area:392}: next guide"] = "{area:392} 남쪽의 {npc:5901}에게: 다음 가이드",
		["{area:2797} is a dungeon for a group of five, about levels 22 to 30, and a full run takes about an hour. Its portal is a little further along the tunnels you are in, past the Sapphires.\nInside: the {object:177964} lies under the water of the Moonshrine Ruins' pool, beneath the walkway (clear the crabs first): open it for the {item:16762}, and {quest:6922} comes; open the {item:16782} he drops for a quest for {npc:12736}. The Tide Priestesses sometimes drop a {item:16790}: open it for another quest for {npc:12736}. {npc:4787}, by a campfire in an underwater side room off Ghamoo-ra's room, offers Blackfathom Villainy ({npc:4832}' head, for {npc:9087} on {zone:1456}'s {area:1639})."] = "{area:2797}은(는) 약 22~30레벨 5인 파티용 던전이며, 전체 공략에 약 1시간이 걸립니다. 차원문은 지금 있는 터널을 따라 사파이어를 지나 조금 더 가면 있습니다.\n내부: {object:177964}은(는) 달의 제단 폐허 웅덩이의 물속, 통로 아래에 있습니다(먼저 게를 처치하십시오). 열어서 {item:16762}을(를) 얻으면 {quest:6922}이(가) 나타납니다. 그가 떨어뜨리는 {item:16782}을(를) 열면 {npc:12736}에게 가는 퀘스트가 시작됩니다. 파도 여사제는 가끔 {item:16790}을(를) 떨어뜨립니다. 열면 {npc:12736}에게 가는 퀘스트가 하나 더 시작됩니다. 가무라의 방에서 이어지는 수중 곁방의 모닥불 옆에 있는 {npc:4787}은(는) '검은심연의 악당'을 줍니다({npc:4832}의 머리, {zone:1456} {area:1639}의 {npc:9087}에게).",
		["{area:2797} ruins"] = "{area:2797} 폐허",
		["{area:418} fountain"] = "{area:418} 분수",
		["{area:485} detour warning: the arrow may miss the path up {area:2097}. If you are on the canyon floor, follow the path and rope bridges up {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "{area:485} 우회 주의: 화살표가 {area:2097}(으)로 올라가는 길을 놓칠 수 있습니다. 협곡 바닥에 있다면 길과 밧줄 다리를 따라 {area:2097}(으)로 올라가세요. {npc:10646}은(는) {npc:10896}(29) 옆에 붙잡혀 있습니다. 먼저 경비병과 {npc:10896}을(를) 처치한 뒤 그녀를 풀어 주고, 내려가는 동안 보호하세요. 가는 길에 그림토템부족 복병이 덤벼듭니다.",
		["{item:273181}, from Gloomrise Spinners"] = "{npc:264081}에게서 얻는 {item:273181}",
		["{item:273658}, from {npc:264082}: it does not drop for everyone"] = "{npc:264082}에게서 얻는 {item:273658}: 모두에게 떨어지지는 않습니다",
		["{item:5867}, at the {object:20806}"] = "{object:20806}에서 사용하는 {item:5867}",
		["{item:5867}, from a {npc:4054}"] = "{npc:4054}에게서 얻는 {item:5867}",
		["{item:5868}, at the {object:20807}"] = "{object:20807}에서 사용하는 {item:5868}",
		["{item:5869}, from the {object:20807}"] = "{object:20807}에서 얻는 {item:5869}",
		["{npc:10079}, at the top of the lift: {npc:10537} at {area:484}"] = "승강기 꼭대기의 {npc:10079}: {area:484}의 {npc:10537}에게",
		["{npc:10377}, by the wind rider master"] = "윈드라이더 조련사 옆의 {npc:10377}",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{npc:10617}의 {quest:4881}, 만나면",
		["{npc:12576} and {npc:10079} wait at the top of the {area:485}: Maggran's letter is for {npc:12576}, and Moonhorn's message goes down to {area:484} with you."] = "{npc:12576}와(과) {npc:10079}은(는) {area:485} 꼭대기에서 기다립니다. 마그란의 편지는 {npc:12576}에게 가는 것이며, 문혼의 전갈은 당신과 함께 {area:484}(으)로 내려갑니다.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "그림자 표범 {npc:12677}은(는) 검은유혹의 사티로스 야영지 서쪽, {area:426} 주변 숲에 숨어 있습니다. 그녀의 머리가 다음 사냥 퀘스트를 시작합니다.",
		["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696}은(는) 비행 조련사 옆, {area:428}에서 사냥 게시판을 관리합니다. {quest:6383}을(를) 받아 바로 완료하세요. 그 뒤에야 {npc:12678}, {npc:12676}, {npc:12677}이(가) 전리품을 떨어뜨립니다.",
		["{npc:12696}: {quest:247}, once {quest:2} is in"] = "{npc:12696}: {quest:2}을(를) 제출한 뒤 {quest:247}",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: 교본 쪽지를 가지고 있을 때만",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "다음으로 {npc:12736}이(가) {area:2797} 퀘스트를 줍니다. 파티가 없다면 두세요.",
		["{npc:12736} then offers the next part, {quest:6564}: it is for a second run, so leave it."] = "이어서 {npc:12736}이(가) 다음 단계인 {quest:6564}을(를) 주지만, 두 번째 공략용이므로 받지 마십시오.",
		["{npc:12736}, {npc:12757} and {npc:12721} stand in the outpost."] = "{npc:12736}, {npc:12757}, {npc:12721}은(는) 전초기지 안에 있습니다.",
		["{npc:12757}: a banner defence in the Foulweald, east of {area:421}: furbolg waves, then {npc:12918}"] = "{npc:12757}: {area:421} 동쪽 Foulweald에서 깃발 방어. 펄볼그 무리 다음 {npc:12918}",
		["{npc:2986}: {npc:4490}, in the harpy den west of the post"] = "{npc:2986}: 거점 서쪽 하피 소굴의 {npc:4490}",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024}은(는) {npc:2995} 동쪽, {npc:4721} 옆에 있습니다.",
		["{npc:3419} stands in the {area:2197}, the caves under {area:1640}, west of {npc:2995}."] = "{npc:3419}은(는) {area:1640} 아래 동굴인 {area:2197}, {npc:2995} 서쪽에 있습니다.",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721}은(는) {npc:2995}에게서 동쪽으로 조금 걸어간 곳에 있습니다.",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721}: 이 가이드 후반부, {area:484}의 {npc:4722}에게",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722}은(는) {area:484}에 있습니다. {npc:4721}의 채워진 약병은 그에게 전합니다.",
		["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722}: 갈라크일족 야영지 사이, {area:1557}의 {object:20807}",
		["{npc:4877}, inside the inn"] = "여관 안의 {npc:4877}",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole south of {area:378}, on the road to the {area:485}."] = "{npc:5899}의 오두막은 {area:378} 남쪽, {area:485}(으)로 가는 길가의 가시멧돼지 물웅덩이 위 능선에 있습니다.",
		["{object:176344}, north-west camp"] = "{object:176344}, 북서쪽 야영지",
		["{object:176344}, south-east camp"] = "{object:176344}, 남동쪽 야영지",
		["{object:176344}, south-west camp"] = "{object:176344}, 남서쪽 야영지",
		["{quest:1150} ({npc:4490}, 31) waits for the next Freewind visit, at about 30: keep it."] = "{quest:1150}({npc:4490}, 31)은(는) 약 30레벨에 높새바람 봉우리를 다시 방문할 때 진행합니다. 버리지 마세요.",
		["{quest:6921}: the {item:16762}, from the {object:177964}"] = "{quest:6921}: {object:177964}에서 얻는 {item:16762}",
		["{zone:1456}'s central rise"] = "{zone:1456}의 중앙 언덕",
} end)()
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = (function() return {
		["Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping."] = "다시 밭으로 가세요. 소작농은 농가 남쪽에서 일합니다. 주의: 도망치는 소작농이 마을 회관에 닿으면 적을 더 데려올 수 있습니다. 감속이나 이동 불가 효과로 도망가지 못하게 하세요.",
		["Back to {area:272}."] = "{area:272}(으)로 돌아가세요.",
		["City of Dalaran"] = "달라란 시",
		["Crossroads flight master"] = "크로스로드 비행 조련사",
		["Drull's ball and chain"] = "드럴의 족쇄",
		["Faranell's next {quest:513} needs a {item:3388} ({skill:171}) and the {area:287} coast: leave it."] = "파라넬의 다음 퀘스트인 {quest:513}에는 {item:3388}({skill:171})과(와) {area:287} 해안이 필요합니다. 그냥 두세요.",
		["Finish the {item:3712}"] = "{item:3712} 마저 모으기",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Fly to {area:272}"] = "{area:272}(으)로 날아가기",
		["For characters of 29 to 31: the {quest:527}, {area:272}'s errands and the gnolls of the foothills, all at or under your level."] = "29~31레벨 캐릭터용: {quest:527}, {area:272}의 심부름, 구릉지의 놀, 모두 자신의 레벨 이하입니다.",
		["For your City of Dalaran run, later in this guide: {npc:2278} stands in {area:272}, a short walk east of {npc:2410}."] = "달라란 시 공략용(이 가이드 후반): {npc:2278}은(는) {area:272}에서 {npc:2410} 동쪽으로 조금 걸어가면 서 있습니다.",
		["From the blossoms, back north along the river and then west to {area:287} town, well north of {area:271} (its guards are 55)."] = "꽃이 있는 곳에서 강을 따라 다시 북쪽으로 간 뒤, 서쪽의 {area:287} 마을로 가세요. {area:271}에서 한참 북쪽에 있습니다(경비병은 55레벨).",
		["Hillsbrad Peasants"] = "힐스브래드 소작농",
		["Keep Infiltration in your log: its Syndicate (32-35) are over you now, and the 38-39 guide (Alterac and Arathi) works it on its first {area:272} loop."] = "'Infiltration'은 퀘스트 목록에 남겨 두세요. 신디케이트(32-35)는 지금 레벨보다 높으며, 38-39레벨 가이드(알터랙과 아라시)의 첫 {area:272} 순회에서 진행합니다.",
		["Keep these in your log: their camps are two to four levels over you now, and the 38-39 guide works them on its first {area:272} loop and in {area:321}."] = "이 퀘스트들은 퀘스트 목록에 남겨 두세요. 해당 진영은 지금 레벨보다 2~4레벨 높으며, 38-39 가이드의 첫 {area:272} 순회와 {area:321}에서 처리합니다.",
		["North of Southshore"] = "사우스쇼어 북쪽",
		["North-east back to {area:272}, passing well north of {area:271} (its guards are 55)."] = "북동쪽 {area:272}(으)로 돌아가십시오. {area:271}의 경비병은 55레벨이니 그 북쪽으로 멀찍이 돌아서 가십시오.",
		["Snapjaws"] = "무쇠턱거북",
		["South of the river's bend, the Mudsnout gnolls (26-28) camp in the hills above {area:290}; the blossoms grow among their tents. The Shamans heal and call their friends: pull them first."] = "강이 굽어지는 곳 남쪽, {area:290} 위 언덕에 진흙주둥이 놀(26-28)이 야영하고 있으며, 꽃은 그들의 천막 사이에서 자랍니다. 주술사는 치유하고 동료를 부르니 먼저 끌어내세요.",
		["Thaivand's next errand, the flames, sends you among the Mountain and Giant Yetis (32-34) and to Helcular's grave inside {area:271}: leave it."] = "사이반드의 다음 심부름인 불꽃 퀘스트는 산악 설인과 거대한 설인(32-34) 사이와 {area:271} 안의 헬쿨라 무덤으로 보냅니다. 받지 마세요.",
		["The City of Dalaran is a dungeon for a group of five, about levels 28 to 33, under the violet dome. Without the {item:277507}, go in through the sewer pipe north-west of the crater: the arrow leads there.\nInside: {npc:247126} is {npc:2278}'s. {npc:268743}, in the sewer, gives Opportunistic Education and takes it back there."] = "달라란 시는 보랏빛 돔 아래에 있는 약 28~33레벨 5인 파티용 던전입니다. {item:277507}이(가) 없다면 분화구 북서쪽의 하수관으로 들어가십시오. 화살표가 그곳으로 안내합니다.\n내부: {npc:247126}은(는) {npc:2278}의 퀘스트 대상입니다. 하수도의 {npc:268743}이(가) 'Opportunistic Education'을 주며, 그곳에서 다시 받습니다.",
		["The river south of {area:272}: kill these as you meet them"] = "{area:272} 남쪽 강: 마주치는 대로 처치하세요",
		["The smithy"] = "대장간",
		["The {quest:567} poster hangs by the inn; {npc:2216} stands inside it. {npc:2393}, the cook by the inn, wants turtle meat and sells the spices for it."] = "{quest:567} 게시물은 여관 옆에 걸려 있고, {npc:2216}은(는) 여관 안에 있습니다. 여관 옆의 요리사 {npc:2393}은(는) 거북이 고기를 원하며, 그에 필요한 양념을 팝니다.",
		["Town hall"] = "마을 회관",
		["Train"] = "기술 배우기",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "{zone:1458}에 있는 동안 기술을 배우세요. 상급자는 {object:36070}, {object:36073}, {object:36082}에 있습니다(성기사: {npc:260093}).",
		["Train your new spells."] = "새 주문을 배우세요.",
		["Voidglare, Bel'varil and {npc:2770}"] = "보이드글레어, 벨바릴, {npc:2770}",
		["West of Tarren Mill, the Cave and Ferocious Yetis (30-32) fill the {area:277} in the hills; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but they hit hard and come in pairs."] = "타렌 밀농장 서쪽, 언덕의 {area:277}에는 동굴 설인과 사나운 설인(30-32)이 가득합니다. 열여섯 마리 중 한 마리꼴로 마법봉을 지니고 있습니다. 이 동굴에만 머무르세요. 더 북쪽 동굴의 산악 설인과 거대한 설인(32-34)도 마법봉을 지니지만, 세게 때리고 짝을 지어 다닙니다.",
		["West past the hills to the farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere.\nCareful: Kirin Tor Guards (55) patrol {area:287}'s fields and roads and attack the Horde: keep an eye out for them and stay out of their way."] = "언덕을 지나 서쪽으로, {area:287} 마을 동쪽의 농장으로 가세요. {npc:232}은(는) 북쪽 농가 옆 밭에서, {npc:2403}은(는) 더 남동쪽 밭에서 일합니다. 농노와 농부는 곳곳에 있습니다.\n주의: 키린 토 경비병(55)이 {area:287}의 밭과 길을 순찰하며 호드를 공격합니다. 잘 살피고 그들의 길을 피하세요.",
		["Zeppelin to {zone:1458}"] = "{zone:1458}행 비행선",
		["for {npc:2055}, on the {zone:1458} stop at the end of this guide"] = "이 가이드 마지막의 {zone:1458} 방문 때 {npc:2055}에게 제출합니다",
		["{item:3712}, from the Snapjaws"] = "무쇠턱거북에게서 얻는 {item:3712}",
		["{item:3713}, from {npc:2393}"] = "{npc:2393}에게서 사는 {item:3713}",
		["{npc:2055} stands in the Apothecarium, in the {object:36126}."] = "{npc:2055}은(는) {object:36126}의 연금술 실험실에 서 있습니다.",
		["{npc:2215}: her next {quest:539}, and {npc:2419}'s sword, are elite group quests at {area:290}: take them only with a group"] = "{npc:2215}: 그녀의 다음 퀘스트인 {quest:539}와(과) {npc:2419}의 검은 {area:290}의 정예 파티 퀘스트입니다. 파티가 있을 때만 받으십시오",
		["{npc:2229} wants his two scouts freed from {area:275}."] = "{npc:2229}은(는) {area:275}에서 정찰병 두 명을 풀어 주기를 원합니다.",
		["{npc:2229}, inside: Infiltration, worked on the 38-39 visit (its Syndicate are 32-35)"] = "{npc:2229}, 내부: 'Infiltration', 38-39레벨 방문 때 진행합니다(신디케이트는 32-35레벨)",
		["{npc:2238}'s ball and chain"] = "{npc:2238}의 족쇄",
		["{npc:2393}: {quest:7321}, the Snapjaws of the river south of town"] = "{npc:2393}: {quest:7321}, 마을 남쪽 강의 무쇠턱거북",
		["{npc:2410} and {npc:2437} are inside the inn, {npc:2770} just outside it. Their quests are offered from level 30; below it, the 38-39 guide's first {area:272} stop takes them."] = "{npc:2410}와(과) {npc:2437}은(는) 여관 안에, {npc:2770}은(는) 여관 바로 밖에 있습니다. 이들의 퀘스트는 30레벨부터 받을 수 있으며, 그보다 낮다면 38-39레벨 가이드의 첫 {area:272} 방문 때 받습니다.",
		["{npc:2410}, inside: {quest:544}, for the 38-39 visit (the {area:279} crater's traitors are 33-35)"] = "{npc:2410}, 내부: {quest:544}, 38-39레벨 방문 때 진행({area:279} 분화구의 배신자는 33-35레벨)",
		["{npc:2410}: {quest:93680}, with {quest:544} on the 38-39 visit"] = "{npc:2410}: {quest:93680}, 38-39레벨 방문 때 {quest:544}와(과) 함께 진행",
		["{npc:2429}, in the town: {item:3708}, from the yetis on the way to the town hall"] = "마을의 {npc:2429}: {item:3708}, 마을 회관으로 가는 길의 설인에게서 얻습니다",
		["{npc:2437}, inside: {quest:556}, with the crater on the 38-39 visit"] = "{npc:2437}, 내부: {quest:556}, 38-39레벨 방문 때 분화구와 함께 진행",
		["{npc:270038} stands in the Apothecarium. His {quest:97985} is for Stormheart, a level 30 elite who walks the canyon east of {area:484}, on the next guide's way to the {area:439}."] = "{npc:270038}은(는) 연금술 실험실에 서 있습니다. 그의 {quest:97985}은(는) Stormheart가 대상입니다. 30레벨 정예로, 다음 가이드에서 {area:439}(으)로 가는 길, {area:484} 동쪽 협곡을 걸어 다닙니다.",
		["{npc:270038}: back to him on the next {zone:1458} stop, at about 38"] = "{npc:270038}: 다음 {zone:1458} 방문 때(약 38레벨) 그에게 돌아갑니다",
		["{npc:2770}, outside the inn: the Boulderfist ogres (32-34) on the 38-39 Arathi visit"] = "여관 밖의 {npc:2770}: 바위주먹 오우거(32-34), 38-39레벨 아라시 방문 때 진행",
		["{npc:4949}, Grommash Hold, if you carry it"] = "그롬마쉬 요새의 {npc:4949}, 가지고 있다면",
		["{quest:567}, the poster by the inn"] = "여관 옆 게시물의 {quest:567}",
		["{quest:96986} from your City of Dalaran run: {npc:2278}, a short walk east of {npc:2410}."] = "달라란 시 공략에서 얻은 {quest:96986}: {npc:2410}에서 동쪽으로 조금 걸어가면 있는 {npc:2278}.",
		["{zone:1458} trainers"] = "{zone:1458} 상급자",
} end)()
t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Back across to {npc:2986}'s mesa north-east of the post, then take the lift down to the canyon floor. {npc:2986}'s next test, {npc:4499}, is an elite: leave it."] = "다시 건너가 거점 북동쪽에 있는 {npc:2986}의 고원으로 간 뒤, 승강기를 타고 협곡 바닥으로 내려가세요. {npc:2986}의 다음 시험인 {npc:4499}은(는) 정예입니다. 그냥 두세요.",
		["Back east to {area:484}."] = "동쪽의 {area:484}(으)로 돌아가세요.",
		["Clam beds"] = "조개 서식지",
		["Crossroads flight master"] = "크로스로드 비행 조련사",
		["East to the raceway, on the way south to {area:976}."] = "남쪽 {area:976}(으)로 가는 길에 동쪽 경주장으로 가세요.",
		["Fly to {area:460}"] = "{area:460}(으)로 날아가기",
		["Fly to {area:484}"] = "{area:484}(으)로 날아가기",
		["Head east to {area:599}. Beat a Burning Blade cultist down, then use the {item:6436} on it before it dies to fill one {item:6435}. The {npc:13019} stands on the fortress's top floor with the Sceptre. The cultists also drop a {item:20310} now and then (1-5%); if one drops, read it. Leave the red {object:176581} for now: its {npc:11876} is 37, and the second {zone:1443} visit comes back for it."] = "동쪽 {area:599}(으)로 가세요. 불타는칼날단 사교도를 빈사 상태로 만든 뒤 죽기 전에 {item:6436}을(를) 사용해 {item:6435}을(를) 하나씩 채우세요. {npc:13019}은(는) 요새 꼭대기 층에서 홀을 가지고 있습니다. 사교도는 가끔(1-5%) {item:20310}도 떨어뜨리니, 얻으면 읽어 보세요. 붉은 {object:176581}은(는) 지금은 두세요. {npc:11876}이(가) 37레벨이라 두 번째 {zone:1443} 방문 때 다시 옵니다.",
		["Level 32"] = "32레벨",
		["North-east of the raceway onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it, and the Sparkleshell Tortoises (30-31) wander among them on the western flats; the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low. The Sparkleshell Snappers (34-35) crowd round a half-buried ship in the north-east and are over you here: the Tortoises of the western flats drop the shells just as often, so stay with them. Take the venom from the Reavers (31-32) of the north half and leave the Scorpid Terrors (33-34) further south."] = "경주장 북동쪽의 평원으로 가세요. 소금바위 바실리스크(30-31)가 그 북서쪽에서 햇볕을 쬐고, 소금껍질거북(30-31)이 서쪽 평원에서 그 사이를 돌아다닙니다. 소금 평원 청소부독수리와 대머리수리는 동쪽 평원을 맴돕니다. 대머리수리는 모두 뼈를 떨어뜨리고, 거북은 약 세 마리 중 한 마리가 등껍질을 떨어뜨립니다.\n주의: 청소부독수리와 대머리수리는 생명력이 낮을 때 마무리 일격을 사용합니다. 무쇠턱 소금껍질거북(34-35)은 북동쪽의 반쯤 묻힌 배 주변에 몰려 있으며 레벨이 높습니다. 서쪽 평원의 소금껍질거북도 등껍질을 똑같이 자주 떨어뜨리니 그쪽에 머무르세요. 독은 북쪽의 붉은독전갈(31-32)에게서 얻고, 더 남쪽의 점박이독전갈(33-34)은 피하세요.",
		["Scorpid Reavers"] = "붉은독전갈",
		["South from the raceway over the {zone:1446} border to {area:976}, the walled goblin town: learn its flight path and fly back to {area:484} from there, which is quicker than the walk west across the flats, and the next guides fly straight to {area:976}."] = "경주장에서 남쪽으로 {zone:1446} 경계를 넘어 성벽으로 둘러싸인 고블린 마을 {area:976}(으)로 가십시오. 비행 경로를 익히고 그곳에서 {area:484}(으)로 날아 돌아가십시오. 평원을 가로질러 서쪽으로 걷는 것보다 빠르며, 다음 가이드들은 {area:976}(으)로 곧장 비행합니다.",
		["South of the raceway, the Saltstone Crystalhides (32-33) and Gazers (34-35) roam the far end of the flats.\nCareful: the level 35 Gazers can still be two over you: pull them one at a time from the camp's edge, never two together."] = "경주장 남쪽, 평원 끝에는 소금바위 수정바실리스크(32-33)와 응시자 바실리스크(34-35)가 돌아다닙니다.\n주의: 35레벨 응시자 바실리스크는 아직 2레벨 높을 수 있습니다. 무리 가장자리에서 한 마리씩 끌어오고, 절대 두 마리를 함께 끌지 마세요.",
		["Swim out to {area:2406} off the far northern tip: {object:177786} stands on the shore beside the {object:177673}. Open it with both keys; leave the statue alone."] = "북쪽 끝에서 헤엄쳐 {area:2406}(으)로 가세요. {object:177786}은(는) 해안의 {object:177673} 옆에 있습니다. 두 열쇠로 여세요. 석상은 건드리지 마세요.",
		["The flats' south and the silithid dig are 32-35, {zone:1443}'s quests 32-38. Still below 32 after the raceway's hand-ins? Back north on the flats, the Scorpid Reavers (31-32) roam among the basilisks and tortoises: kill them until level 32; leave the Sparkleshell Snappers (34-35) and the Scorpid Terrors (33-34) alone. Or, with a group, run the {area:1717} dungeon instead."] = "평원 남쪽과 실리시드 발굴지는 32-35레벨, {zone:1443}의 퀘스트는 32-38레벨입니다. 경주장 퀘스트를 제출한 뒤에도 32레벨이 안 되었나요? 평원 북쪽으로 돌아가면 붉은독전갈(31-32)이 바실리스크와 거북 사이를 돌아다닙니다. 32레벨까지 처치하세요. 무쇠턱 소금껍질거북(34-35)과 점박이독전갈(33-34)은 건드리지 마세요. 또는 파티가 있다면 대신 {area:1717} 던전을 도세요.",
		["The zeppelin lands at the tower outside {zone:1454}'s main gate. {npc:5639} walks the Drag: if he isn't at the arrow, look along its streets to the south-west. {npc:5640} stands in the {object:172961} on the west side of the city."] = "비행선은 {zone:1454} 정문 밖의 탑에 도착합니다. {npc:5639}은(는) 골목길을 돌아다닙니다. 화살표 위치에 없다면 남서쪽 거리를 따라 찾아보세요. {npc:5640}은(는) 도시 서쪽의 {object:172961}에 서 있습니다.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:270094} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:270094} walks the canyon road east of {area:484}'s lift, on the way to the salt flats: kill him for his heart."] = "정예 몹입니다. 파티를 권장하니 함께할 사람을 찾아보십시오. {npc:270094}은(는) 30레벨 정예입니다. 대부분의 직업은 32레벨에 혼자 처치할 수 있지만, 도움이 필요할 수도 있습니다. 혼자라면 건너뛰십시오. 경로에서 사냥으로 경험치를 다시 채우게 됩니다.\n{npc:270094}은(는) 소금 평원으로 가는 길, {area:484} 승강기 동쪽의 협곡 길을 걸어 다닙니다. 처치해서 심장을 얻으십시오.",
		["Underwater"] = "물속",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time. Careful: leave the kodo skulls on the ground alone: opening one raises a {npc:11521} (37-38) that hits hard."] = "묘지의 늙은 코도, 죽어가는 코도 또는 {npc:4702}에게 {npc:11596}의 {item:13892}을(를) 사용한 뒤, 길들인 코도를 {npc:11596}에게 데려가세요. 야영지에서 코도에게 말을 걸면 집계되고 다음 코도를 길들일 수 있습니다. 한 번에 한 마리씩 총 다섯 마리입니다. 주의: 땅에 있는 코도 해골은 건드리지 마세요. 열면 강하게 때리는 {npc:11521}(37-38)이(가) 나타납니다.",
		["West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a {item:5877}: open it.\nCareful: Hive Drones call for help when they fall to 20% health, and the {npc:4132} (37, rare) walks the dig: take the Searchers and Drones (32-34) outside first, then pull the Invaders (34-35) one at a time from the cave mouth."] = "그 서쪽에서는 실리시드가 발굴지에 떼지어 있습니다. 탐색꾼과 벌집 일벌레는 흙더미 사이를 돌아다니고, 침략자(34-35)는 벌집 동굴 안에 머뭅니다. 처음 처치한 실리시드에게서 {item:5877}이(가) 떨어지니 열어 보세요.\n주의: 벌집 일벌레는 생명력이 20%가 되면 도움을 요청하고, {npc:4132}(37, 희귀)가 발굴지를 돌아다닙니다. 먼저 바깥의 탐색꾼과 일벌레(32-34)를 처치한 뒤, 동굴 입구에서 침략자(34-35)를 하나씩 끌어내세요.",
		["West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a {item:15874}. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry {item:15878}, about one in seven."] = "서쪽 해안으로 가세요. 얕은 물에는 거대 물렁조개가 있고, 해변에는 성난 산호초 게가 돌아다닙니다. 해저에서 여는 조개마다, 그리고 일부 게에게서 {item:15874}을(를) 얻습니다. 가방에서 하나씩 열어 조갯살을 꺼내세요.\n같은 해변의 마른집게 게와 마른집게 집게발은 약 7마리 중 1마리꼴로 {item:15878}을(를) 지니고 있습니다.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.\n{npc:2986} waits on the mesa just north-east of {area:484}, across the rope bridges.\nFor the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "경로의 이전 방문 때 이것을 놓쳤습니다. 지금 이것부터 합니다. 금방 끝나며 뒤에 이어지는 퀘스트를 열어 줍니다.\n{npc:2986}은(는) 밧줄 다리를 건너 {area:484} 바로 북동쪽의 고원에서 기다립니다.\n{quest:1149}에서는 그 옆 널빤지 끝에서 걸어 떨어지세요. 안전하게 착지합니다.",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["for {npc:4483} in the {area:439}, later in this guide"] = "이 가이드 후반, {area:439}의 {npc:4483}용",
		["grind on {npc:4140}"] = "{npc:4140} 사냥",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}, 마른집게 게에게서 획득",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, 칼날비늘 나가에게서 획득",
		["{item:279186}, from {npc:270094}"] = "{item:279186}: {npc:270094}에게서",
		["{item:5795}, from the Sparkleshell Tortoises of the western flats"] = "{item:5795}, 서쪽 평원의 소금껍질거북에게서 획득",
		["{item:5843}, from {npc:4490}"] = "{item:5843}, {npc:4490}에게서 획득",
		["{npc:11863}'s next errand, the {item:15803}, needs {npc:12369} (38) out on {area:2406}: leave it, he is over your level."] = "{npc:11863}의 다음 심부름인 {item:15803}에는 {area:2406}의 {npc:12369}(38)이(가) 필요합니다. 레벨이 높으니 건너뛰세요.",
		["{npc:2986} waits on the mesa just north-east of {area:484}, across the rope bridges."] = "{npc:2986}은(는) 밧줄 다리를 건너 {area:484} 바로 북동쪽의 고원에서 기다립니다.",
		["{npc:2986}: {npc:4490}, in the harpy den west of the post"] = "{npc:2986}: 거점 서쪽 하피 소굴의 {npc:4490}",
		["{npc:3428}'s {quest:1145} needed level 29 on the last guide's Crossroads stop: take it now, on a short flight to the Crossroads and back."] = "{npc:3428}의 {quest:1145}은(는) 지난 가이드에서 크로스로드에 들렀을 때 29레벨이 필요했습니다. 크로스로드까지 잠깐 날아갔다 돌아오며 지금 받으세요.",
		["{npc:4877}, inside the inn"] = "여관 안의 {npc:4877}",
		["{npc:4877}: the Screeching harpies of {area:487}"] = "{npc:4877}: {area:487}의 날카로운울음 하피",
		["{npc:5641} and {npc:4498}"] = "{npc:5641}와(과) {npc:4498}",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892}은(는) {object:172957}에 서 있습니다.",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527}와(과) {item:5177}",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905}은(는) 폭풍의 무기로 이어지는 33-40 연계 퀘스트인 정기의 도움({area:1717})도 줍니다: forever/class/shaman/call-of-air-horde.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: {item:5178}",
		["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787}은(는) {npc:11863}의 탑 바로 남서쪽, 해안으로 내려가는 길의 땅바닥에 놓여 있습니다. 읽어 보세요. 두 열쇠는 퀘스트를 받은 상태에서만 떨어집니다.",
		["{object:19868}, all over the northern flats: pick it on the western flats, away from the Snappers"] = "{object:19868}, 북쪽 평원 곳곳: 무쇠턱 소금껍질거북을 피해 서쪽 평원에서 주우세요",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "북쪽의 야영지로 돌아가세요.",
		["Back to {object:3202}."] = "{object:3202}(으)로 돌아가세요.",
		["Boat to {area:35}"] = "{area:35}행 배",
		["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "디지위그의 부품은 경로에서 벗어난 {area:439}의 크라벨에게 돌아가야 하니 받지 마세요.",
		["East of the Mosh'Ogg hills, Shadowmaw Panthers (37-38) stalk the jungle towards the lake; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}. Careful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them; the 38s can be two over you: pull them one at a time and leave the Elders alone."] = "모쉬오그 언덕 동쪽, 호수 쪽 정글에 그림자퓨마(37-38)가 돌아다닙니다. 같은 곳의 가시덤불 암호랑이는 가끔 완벽한 송곳니를 떨어뜨립니다. 무쇠턱 악어는 정글 바로 서쪽 강가에 있습니다. 가죽은 {npc:2495}에게 줄 테니 보관하세요. 주의: 그림자퓨마(37-38 레벨)와 덩치큰 그림자퓨마(42-43 레벨)는 비전투 중 은신을 사용하므로 가까이 가기 전까지 보이지 않습니다. 38 레벨은 나보다 2레벨 높을 수 있으니 한 마리씩 끌어오고, 덩치큰 그림자퓨마는 건드리지 마세요.",
		["Escort {npc:268992} out of the ruins and keep him alive: Lozgil takes the news once he is safe."] = "{npc:268992}을(를) 폐허 밖으로 호위하며 살려 두세요. 안전해지면 로즈길이 소식을 받습니다.",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Fly to {area:35}"] = "{area:35}(으)로 날아가기",
		["Fly to {area:392}"] = "{area:392}(으)로 날아가기",
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. {npc:773} wants it investigated: walk among its tents. From here on, keep every page of The {item:2755} you loot: {npc:716} takes them on your next Stranglethorn visit."] = "길을 따라 {object:3202}에서 북쪽으로 나가세요. 네싱워리의 사냥 야영지는 강 북동쪽 언덕에 있습니다. {npc:773}이(가) 조사를 원하니 천막 사이를 걸어 다니세요. 지금부터 얻는 {item:2755}의 모든 쪽은 보관하세요. 다음에 가시덤불 골짜기에 올 때 {npc:716}이(가) 받습니다.",
		["Leave {area:35} through the tunnel and follow the road north to {object:3202}, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level."] = "터널을 통해 {area:35}을(를) 나와 길을 따라 북쪽으로 골짜기 서쪽의 오크 주둔지 {object:3202}(으)로 가세요. 길에서 벗어나지 마세요. 길 옆 정글은 레벨이 더 높습니다.",
		["Mosh'Ogg camp"] = "모쉬오그일족 야영지",
		["Nesingwary's camp"] = "네싱워리의 야영지",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "그롬골 북서쪽 해안 앞바다 물속에 {area:104}이(가) 있습니다. {item:4094}은(는) 가라앉은 폐허 옆 바닥에 있습니다. 숨과 멀록을 조심하세요.",
		["On the walk west from Nesingwary's camp, a pile of {object:661516} lies by the path: it starts {quest:97328}, whose Stolen Shipments lie in the {area:102} on the coast ahead."] = "네싱워리 야영지에서 서쪽으로 가는 길가에 {object:661516} 더미가 있습니다. {quest:97328}을(를) 시작하며, 도난당한 화물은 앞쪽 해안의 {area:102}에 있습니다.",
		["On your way back south to {object:3202}, the Lashtail Raptors (35-36) hunt the jungle between the camp and {object:3202}: they count for Hemet and for {npc:2464}. Careful: the 36s can be two over you: pull them one at a time. Carnivorous Weeds (36-38) are rooted in the jungle south of the raptors: walk around them."] = "{object:3202}(으)로 남쪽으로 돌아가는 길에, 야영지와 {object:3202} 사이 정글에서 채찍꼬리랩터(35-36)가 사냥합니다. 헤메트와 {npc:2464} 퀘스트 모두에 집계됩니다. 주의: 36레벨은 2레벨 높을 수 있으니 하나씩 끌어내세요. 식충 덩굴(36-38)이 랩터 남쪽 정글에 뿌리박고 있으니 돌아가세요.",
		["River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "민물악어는 야영지 아래 강을 따라 있습니다. 어린 가시덤불호랑이는 야영지 서쪽, 어린 표범은 동쪽에 돌아다닙니다. 야영지를 지나 서쪽으로 가세요. 가시덤불랩터(33-34)는 빈터에서 사냥하고, 붉은머리부족 트롤은 해안의 폐허를 차지하고 있습니다. 붉은머리부족은 모두 엄니를 떨어뜨릴 수 있습니다. 이들에게서 {item:4614}이(가) 매우 드물게 떨어지니, 얻으면 읽어 보세요. 주의: 트롤 야영지에는 순찰하는 몹이 많아 다른 트롤이 자주 전투에 끼어듭니다.",
		["Snapjaw Crocolisks"] = "{npc:1152}",
		["Stolen Shipments, in the ruins"] = "도난당한 화물, 폐허에서",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads. Careful: the 37s can be two over you: pull them one at a time from the village's edge, never into the middle with the Witch Doctors.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of The {item:2755}."] = "해안 마을의 붉은머리부족 인간사냥꾼(36-37)이 쪼그라든 머리를 가지고 있습니다. 주의: 37 레벨은 나보다 2레벨 높을 수 있습니다. 마을 가장자리에서 한 마리씩 끌어오고, 주술사가 있는 마을 한가운데로는 절대 들어가지 마세요.\n붉은머리부족 트롤은 산호초 북쪽 해안의 폐허와 그 너머 마을을 차지하고 있습니다. 모두 {item:3915}을(를) 떨어뜨릴 수 있습니다. {item:2755}의 쪽도 계속 모으세요.",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}, on your way back. Kill 10 Brutes and 5 Witch Doctors (36-37); pull them one at a time. Careful: the 37s can be two over you: take them from the camp's western edge, never two together."] = "모쉬오그일족 오우거는 돌아가는 길, {object:3202} 바로 동쪽 언덕에 야영하고 있습니다. 모쉬오그일족 투사 10마리와 모쉬오그일족 의술사 5마리(36-37)를 처치하세요. 한 마리씩 끌어오세요. 주의: 37 레벨은 나보다 2레벨 높을 수 있습니다. 야영지 서쪽 가장자리에서 잡고, 절대 두 마리를 한꺼번에 상대하지 마세요.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "그림자퓨마는 훨씬 나중에 {object:3202} 근처에서 나옵니다",
		["Tumbled Crystals, from the geologists of the eastern camps"] = "연마된 수정, 동쪽 야영지의 지질학자에게서 획득",
		["Underwater"] = "물속",
		["{area:2408} flight master"] = "{area:2408} 비행 조련사",
		["{area:35} first: the goblins' boat sails there from {area:392}, and every {area:35} quest is for the north of the vale, which you then walk up into."] = "먼저 {area:35}부터 갑니다. 고블린의 배가 {area:392}에서 그곳으로 운항하며, {area:35}의 퀘스트는 모두 골짜기 북쪽에서 진행하므로 이후 걸어서 올라갑니다.",
		["{item:277957}, from the Bloodscalp Scouts, Hunters and Mystics"] = "{item:277957}, 붉은머리부족 정찰병, 사냥꾼, 신비술사에게서 획득",
		["{npc:2464} stands in the middle of {object:3202}, {npc:2497} near the zeppelin tower, {npc:2465} beside the flight master."] = "{npc:2464}은(는) {object:3202} 한가운데, {npc:2497}은(는) 비행선 탑 근처, {npc:2465}은(는) 비행 조련사 옆에 있습니다.",
		["{npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs beside the flight master. {npc:4631} stands on the pier."] = "{npc:2495}의 상점은 여관 동쪽 건물에 있고, {npc:2498}은(는) 여관 1층, {npc:2496}, {npc:737}, {npc:773}은(는) 위층 비행 조련사 옆에 있습니다. {npc:4631}은(는) 부두에 서 있습니다.",
		["{npc:2496}, upstairs"] = "{npc:2496}, 위층",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: 경로 후반의 아라시 고원용",
		["{npc:268992} is held at the east edge of the {area:102}; the Stolen Shipments lie among the ruins around him. The Bloodscalp Scouts, Hunters and Mystics (34-35) there carry his {item:277957}. Then lead him out of the ruins: {npc:4631} in {area:35} takes the news and the shipments.\nCareful: Bloodscalp Berserkers and Headhunters (36-37) and Witch Doctors (37, casters) hold the ruins north and west of {npc:268992}, close to the northern shipments (around 24.9,9.6): pick the shipments in the southern ruins by {npc:268992} first, and pull one at a time if you go north."] = "{npc:268992}은(는) {area:102} 동쪽 끝에 붙잡혀 있고, 도난당한 화물은 그 주변 폐허에 있습니다. 그곳의 붉은머리부족 정찰병, 사냥꾼, 신비술사(34-35)가 {item:277957}을(를) 지니고 있습니다. 그런 다음 그를 폐허 밖으로 데리고 나가세요. {area:35}의 {npc:4631}이(가) 소식과 화물을 받습니다.\n주의: 붉은머리부족 광전사와 머리사냥꾼(36-37), 주술사(37, 시전자)가 {npc:268992} 북쪽과 서쪽 폐허, 북쪽 화물(약 24.9,9.6) 근처를 차지하고 있습니다. 먼저 {npc:268992} 옆 남쪽 폐허의 화물을 줍고, 북쪽으로 가면 하나씩 끌어내세요.",
		["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391}은(는) 비행 조련사 옆 건물 위층에 있고, {quest:1111}은(는) 부두의 배 옆에 서 있습니다.",
		["{npc:3391}, upstairs"] = "{npc:3391}, 위층",
		["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391}: 배가 향하는 {area:35}의 {npc:4631}에게 전달",
		["{npc:4631} stands on the pier where the boat docks. {npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs, {npc:2858} the flight master on the upper deck."] = "{npc:4631}은(는) 배가 정박하는 부두에 서 있습니다. {npc:2495}의 상점은 여관 동쪽 건물에 있고, {npc:2498}은(는) 여관 1층, {npc:2496}, {npc:737}, {npc:773}은(는) 위층, 비행 조련사 {npc:2858}은(는) 위층 갑판에 있습니다.",
		["{npc:4631}, on the pier"] = "{npc:4631}, 부두",
		["{npc:4631}, on the pier: the Stolen Shipments"] = "{npc:4631}, 부두: 도난당한 화물",
		["{npc:4631}: {npc:268992} is safe"] = "{npc:4631}: {npc:268992} 무사함",
		["{quest:1111}, on the docks"] = "{quest:1111}, 부두",
		["{quest:629}'s and Zul'Kunda's quests are next, with Bloodscalp Headhunters of 36-37. Still below 35 after {area:35}'s hand-ins? The Elder Stranglethorn Tigers (34-35) roam the hills north of {object:3202}, below Nesingwary's camp: kill them until level 35. The Lashtail Raptors (35-36) beside them are a level higher."] = "다음은 {quest:629}와 줄쿤다 퀘스트로, 36-37 레벨의 붉은머리부족 인간사냥꾼이 나옵니다. {area:35}에서 퀘스트를 제출하고도 35 레벨이 안 되나요? 덩치큰 가시덤불 호랑이(34-35)가 {object:3202} 북쪽, 네싱워리 야영지 아래 언덕을 돌아다닙니다. 35 레벨까지 처치하세요. 그 옆의 채찍꼬리랩터(35-36)는 한 레벨 더 높습니다.",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Back north along the coast to {area:392}'s flight master."] = "해안을 따라 북쪽으로 {area:392}의 비행 조련사에게 돌아가세요.",
		["Crossroads flight master"] = "크로스로드 비행 조련사",
		["Drywallow Crocolisks"] = "늪지악어",
		["East along the road to {area:597}; {npc:5412} stands beside {npc:5395}."] = "길을 따라 동쪽의 {area:597}(으)로 가세요. {npc:5412}은(는) {npc:5395} 옆에 서 있습니다.",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Fly to {area:2408} from the flight master you are next to: {area:392}'s, or Brackenwall's if you had no errand in {area:392}."] = "지금 옆에 있는 비행 조련사에게서 {area:2408}(으)로 날아가세요. {area:392}의 비행 조련사, {area:392}에 볼일이 없었다면 담쟁이 마을의 비행 조련사입니다.",
		["Fly to {area:378}"] = "{area:378}(으)로 날아가기",
		["Head back west to Brackenwall with the head: {npc:4503} stands at the south edge of the village where the road comes in, {npc:4791} and {npc:4926} in the village."] = "머리를 가지고 서쪽 담쟁이 마을로 돌아가세요. {npc:4503}은(는) 길이 들어오는 마을 남쪽 가장자리에, {npc:4791}와(과) {npc:4926}은(는) 마을 안에 있습니다.",
		["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "{area:378}에서 길을 따라 동쪽으로 늪지대에 들어가세요. 불타 버린 {area:403}은(는) 경계를 막 지난 길가에 있습니다. 방패, 휘장, 발굽 자국은 폐허 안과 옆에 있습니다.",
		["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "북쪽의 {area:502}(으)로 가세요. 이그나츠는 언덕 기슭에 서 있습니다. 그 바로 남쪽에서 진흙콩 잎을 모으는 동안 그를 호위하세요.",
		["Head west back across the marsh. The Darkfang Lurkers (36-37) and Venomspitters (37-38) on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes. Work its outer edge, where the Spiders and Recluses (35-37) stand: the Lurkers and Silkspinners (37-39) deeper in are two or three over you.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "늪지대를 가로질러 서쪽으로 돌아가세요. 담쟁이 마을 북쪽 능선의 검은송곳니 늑대거미(36-37)와 독침거미(37-38)가 독주머니를 떨어뜨립니다. 같은 숲에 테라모어 첩보원(35-36)이 숨어 다니니 잘 살펴보세요.\n담쟁이 마을 북서쪽 동굴 입구에 암흑안개 거미가 득실거립니다. 모든 종류가 눈을 떨어뜨립니다. 거미와 은둔거미(35-37)가 있는 바깥쪽에서 잡으세요. 안쪽의 늑대거미와 비단거미(37-39)는 나보다 2-3레벨 높습니다.\n주의: 검은송곳니 늑대거미(36-37 레벨)는 비전투 중 은신하고 전투가 시작되면 독을 사용합니다.\n주의: 같은 지역의 은신한 거미는 보는 즉시 공격합니다.\n주의: 암흑안개 늑대거미는 은신한 채 돌아다니며 전투 중 독을 사용합니다. 거미들이 가까이 붙어 있어 추가로 끌려오기 쉬우니, 바깥쪽에서 한 마리씩 끌어오세요.",
		["Hearth to Shadowprey: your hearthstone is still bound there."] = "그림자약탈 마을로 귀환석을 사용하세요. 귀환석은 아직 그곳에 설정되어 있습니다.",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "자를은 {area:502} 남동쪽의 {area:497}에 삽니다.",
		["Mirefin murlocs"] = "진흙아가미멀록",
		["North up the road to {area:599}. Clear the middle of the largest building, then use the {item:14523} on the red {object:176581} there. A {npc:11876} (37) comes out: kill it for the {item:13542}. The Burning Blade around it are well under you now."] = "길을 따라 북쪽의 {area:599}(으)로 가세요. 가장 큰 건물 가운데를 정리한 뒤, 그곳의 붉은 {object:176581}에 {item:14523}을(를) 사용하세요. {npc:11876}(37)이(가) 나타납니다. 처치하고 {item:13542}을(를) 얻으세요. 주변의 불타는 칼날단은 이제 당신보다 훨씬 낮습니다.",
		["North-west to the goblin camp on the west side of the {area:596}, back past {area:602}: keep west of the Magram's village."] = "{area:602}을(를) 다시 지나 북서쪽으로 {area:596} 서쪽의 고블린 야영지로 가세요. 마그람 마을 서쪽으로 지나가세요.",
		["On east to the {area:497}."] = "계속 동쪽의 {area:497}(으)로 가세요.",
		["On the way east, {npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out: {npc:5045} and Theramore Skirmishers (36) join it."] = "동쪽으로 가는 길에 {npc:4983}이(가) 마을 동쪽 {area:2302}에서 기다립니다. 그를 따라 리테에게 가서, 벌어지는 싸움에서 그를 살려 두세요. {npc:5045}와(과) 테라모어 척후병(36)이 싸움에 끼어듭니다.",
		["South-east from the manor to {area:513}: the {object:20925} lies on the sea floor off the docks on the isle's east side. Swim in and out and keep off the piers and the town: Theramore's guards are level 53-57, and a death here is a long run back from the spirit healer. Young Murk Threshers (40-41) circle in the water around the docks: grab the footlocker and swim straight out."] = "저택에서 남동쪽으로 {area:513}까지 가세요. {object:20925}은(는) 섬 동쪽 부두 앞바다 해저에 있습니다. 헤엄쳐 들어갔다 나오고 부두와 마을은 피하세요. 테라모어 경비병은 53-57 레벨이며, 여기서 죽으면 영혼의 치유사에게서 먼 길을 달려와야 합니다. 새끼 늪지트레샤돈(40-41)이 부두 주변 물속을 돌고 있으니 사물함을 챙기고 곧장 헤엄쳐 나오세요.",
		["South-east of the coven, the bone fields of the {area:2657}, where Undead Ravagers roam, at {zone:1443}'s southern edge: keep south of the Magram's village on the way. Use the {item:15848} at the arrow to draw the Magrami Spectres (38-39): they come in numbers, so fight them with your back to the valley's edge. They drop the ghost-o-plasm.\nCareful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields just west of the arrow, well above you: use the crate at the arrow, on the valley's eastern side, and pull the spectres away from them."] = "집회장 남동쪽, {zone:1443} 남쪽 끝에 언데드 약탈자가 배회하는 {area:2657}의 뼈 들판이 있습니다. 가는 길에 마그람 마을 남쪽으로 지나가세요. 화살표 지점에서 {item:15848}을(를) 사용해 마그라미 망령(38-39)을 끌어내세요. 여러 마리가 몰려오니 골짜기 가장자리를 등지고 싸우세요. 망령이 유령 원형질을 떨어뜨립니다.\n주의: 마그람 강령칸과 시체먹이(45, 정예)가 화살표 바로 서쪽 뼈 들판을 돌아다니며, 당신보다 훨씬 강합니다. 골짜기 동쪽의 화살표 지점에서 상자를 사용하고 망령을 그들에게서 떨어진 곳으로 끌어오세요.",
		["Stinky Ignatz"] = "말썽꾼 이그나츠",
		["Swamp Eye Jarl"] = "늪지눈알 자를",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "갈림길에서 북쪽 길로 가서 오우거 마을인 담쟁이 마을로 가세요.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "진흙아가미멀록은 {area:502} 동쪽과 북동쪽 해안에 몰려 있습니다. 모든 종류가 머리를 떨어뜨립니다.",
		["The {area:2657}"] = "{area:2657}",
		["Underwater"] = "물속",
		["West of the post, the Maraudine centaurs hold the {area:607}; every Maraudine can drop a {item:254432} and an ear for {npc:5395}'s {quest:1366}. Stay with the Scouts and Wranglers (36-38) at the valley's eastern edge; the Maulers and Windchasers (38-39) a little further in are up to two over you at 37: pull them one at a time.\nCareful: {npc:5402} and the Rock Worms (41-42, elite) hold the valley's north-western end with the Khan Guards and Marauders (39-40), and the Magram's village in the south-east has Necromancers (42-43): keep east of the arrow."] = "초소 서쪽의 {area:607}은(는) 마라우딘 켄타우로스가 차지하고 있습니다. 모든 마라우딘이 {item:254432}와(과) {npc:5395}의 {quest:1366}에 쓸 귀를 떨어뜨릴 수 있습니다. 골짜기 동쪽 가장자리의 정찰병과 조련사(36-38)만 상대하세요. 조금 더 안쪽의 난폭꾼과 바람추적자(38-39)는 37레벨인 당신보다 최대 2레벨 높습니다. 한 번에 한 마리씩 끌어오세요.\n주의: {npc:5402}와(과) 바위미늘벌레(41-42, 정예)가 칸 경비병, 약탈자(39-40)와 함께 골짜기 북서쪽 끝을 차지하고 있으며, 남동쪽의 마그람 마을에는 강령술사(42-43)가 있습니다. 화살표 동쪽에 머무르세요.",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["grind on {npc:4341}"] = "{npc:4341} 사냥",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "{item:3853}을(를) 가지고 있을 때만({skill:164} 또는 경매장)",
		["{area:2408} flight master"] = "{area:2408} 비행 조련사",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, \"늪지눈알\" 자를에게 줄 것",
		["{npc:11624} and {npc:12340} stand in the village."] = "{npc:11624}와(과) {npc:12340}은(는) 마을 안에 있습니다.",
		["{npc:11624}: the {quest:5381}, at {area:599} later on this visit"] = "{npc:11624}: {quest:5381}, 이번 방문 중 나중에 {area:599}에서",
		["{npc:12340}: the Slitherblade of Sar'theris Strand, on the way back from {area:599}"] = "{npc:12340}: 살테리스 해안의 미끈비늘, {area:599}에서 돌아오는 길에",
		["{npc:3446} stands below Gazlowe's house by the flight master, towards the docks."] = "{npc:3446}은(는) 비행 조련사 옆 가즐로의 집 아래, 부두 쪽에 서 있습니다.",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "길이 들어오는 마을 남쪽 끝의 {npc:4503}",
		["{npc:5395}: his {quest:1366}, from the same Maraudine as Gurda's totems"] = "{npc:5395}: 구르다의 토템과 같은 마라우딘에게서 얻는 그의 {quest:1366}",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019}은(는) {area:596} 서쪽의 고블린 야영지에서 기다립니다.",
		["{npc:6019}: the ghost-o-plasm, after {area:602} at the end of this visit"] = "{npc:6019}: 이번 방문 마지막에 {area:602}을(를) 마친 뒤 유령 원형질",
		["{object:20985}, beside the manor"] = "저택 옆의 {object:20985}",
		["{object:20985}, now that {npc:4791} has read the report"] = "{npc:4791}이(가) 보고서를 읽은 뒤의 {object:20985}",
		["{zone:1443}'s last quests are 36-39. Still below 36 after Brackenwall's hand-ins? The Drywallow Crocolisks (35-36) along the river east of the village are the closest at your level: kill them until level 36."] = "{zone:1443}의 마지막 퀘스트는 36-39 레벨입니다. 담쟁이 마을에서 퀘스트를 제출하고도 36 레벨이 안 되나요? 마을 동쪽 강가의 늪지악어(35-36)가 가장 가까운 적정 레벨 몹입니다. 36 레벨까지 처치하세요.",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
} end)()
t.guides["forever/horde/30-40/05-arathi-highlands"] = (function() return {
		["Back east along the foothills to {area:272}: everything from the first loop is handed in inside the inn."] = "산기슭을 따라 다시 동쪽의 {area:272}(으)로 가세요. 첫 번째 경로의 퀘스트는 모두 여관 안에서 제출합니다.",
		["Back north to {area:321}: the doctor stands at the south gate."] = "북쪽 {area:321}(으)로 돌아가세요. 의사는 남쪽 관문에 서 있습니다.",
		["Back to {area:272}"] = "{area:272}(으)로 돌아가기",
		["Back to {area:321}"] = "{area:321}(으)로 돌아가기",
		["Below ground"] = "지하",
		["Boulderfist camp"] = "돌주먹일족 야영지",
		["Fleshstalker raptors"] = "식인 고원랩터",
		["Fly to {area:272}"] = "{area:272}(으)로 날아가기",
		["Follow the road north out of {area:272} into the Alterac foothills: {quest:535} waits by the Syndicate camp. He offers his errand only while you carry {npc:2229}'s Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes {quest:535}."] = "{area:272}에서 길을 따라 북쪽으로 알터랙 산기슭에 들어가세요. {quest:535}은(는) 비밀결사 야영지 옆에서 기다립니다. 그는 {npc:2229}의 잠입 퀘스트를 가지고 있을 때만 심부름을 줍니다. 곧바로 흑맥주를 건네면 그 보상이 크루스크가 원하는 비밀결사 명령서입니다. 이곳 비밀결사에게서 얻은 명령서도 마찬가지입니다. 가방에 하나 있으면 가이드가 {quest:535}을(를) 건너뜁니다.",
		["From the south, walk up into the camp below the violet dome of {area:279}. {npc:2411}, {npc:2412} and {npc:2413} (33-34) stand together in the camp, {npc:2414} (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-33) around them drop the Worn Stone Tokens: the ones on the camp's west side are furthest from the Guard's road.\nCareful: Kirin Tor Guards (55) attack the Horde on sight, and one of them patrols the road that comes down into the camp from the north-east and walks right up to the traitors: he has killed many players here. Watch for him, let him walk back up the road, then pull the traitors. Many of the camp's guards stand in linked pairs and others patrol alone. Arcane Sentries (55, elite) and Kirin Tor Enforcers (55) stand around the violet dome itself: keep to the camp below the rim."] = "남쪽에서 {area:279}의 보랏빛 돔 아래 야영지로 올라가세요. {npc:2411}, {npc:2412}, {npc:2413}(33-34)은(는) 야영지에 함께 서 있고, {npc:2414}(35)은(는) 그 조금 서쪽에 있습니다. 각자 혈석 조각을 하나씩 가지고 있습니다. 주변의 방패 경비병과 마법사(31-33)는 닳아해진 징표의 돌을 떨어뜨립니다. 야영지 서쪽의 것들이 경비병의 길에서 가장 멉니다.\n주의: 키린 토 경비병(55)은 호드를 보자마자 공격하며, 그중 하나는 북동쪽에서 야영지로 내려오는 길을 순찰하다가 배신자들 바로 앞까지 옵니다. 이곳에서 많은 플레이어를 죽였습니다. 그를 주시하다가 길을 따라 다시 올라가면 배신자들을 끌어오세요. 야영지 경비병 중 다수는 짝지어 서 있고 일부는 혼자 순찰합니다. 비전 파수병(55, 정예)과 키린 토 집행자(55)는 보랏빛 돔 주위에 서 있습니다. 가장자리 아래 야영지에 머무르세요.",
		["From {area:280} follow the road south-west to {area:1357} and on west to the ruins north of the {area:279} crater, along the lake shore. The Dalaran Summoners lead Elemental Slaves; the bracers drop from the slaves. Careful: Arcane Sentries (55, elite) and Kirin Tor Guards (55) guard the dome itself and attack the Horde: work the ruins' outer edge and don't go up to the dome."] = "{area:280}에서 길을 따라 남서쪽으로 {area:1357}까지 간 뒤, 호숫가를 따라 계속 서쪽으로 {area:279} 분화구 북쪽 폐허까지 가세요. 달라란 소환사가 노예 바위 정령을 이끌며, 팔보호구는 노예 바위 정령이 떨어뜨립니다. 주의: 비전 파수병(55, 정예)과 키린 토 경비병(55)이 돔을 지키며 호드를 공격합니다. 폐허 바깥쪽에서만 사냥하고 돔으로 올라가지 마세요.",
		["Head north up the road past {quest:535}'s camp to {area:280}, the Syndicate-held village (35-37). {npc:2431} carries the {item:3704}; {quest:503} sits in a cage in the house on the north side.\nCareful: Stealthed Syndicate spies roam {area:280}, and the buildings hold many Syndicate mobs, mages among them."] = "{quest:535}의 야영지를 지나 길을 따라 북쪽으로 비밀결사가 점령한 마을 {area:280}(35-37)(으)로 가세요. {npc:2431}이(가) {item:3704}을(를) 가지고 있고, {quest:503}은(는) 북쪽 집의 우리에 갇혀 있습니다.\n주의: {area:280}에는 은신한 비밀결사 첩자가 돌아다니며, 건물 안에는 마법사를 포함한 비밀결사 몹이 많습니다.",
		["Hearth back to {area:272} (your hearthstone is bound there), or walk back south-east along the road out of Alterac."] = "귀환석으로 {area:272}(으)로 돌아가거나(귀환석이 그곳에 귀속되어 있습니다), 알터랙에서 나가는 길을 따라 남동쪽으로 걸어서 돌아가세요.",
		["Hearth back to {area:272}: your hearthstone is bound there."] = "귀환석으로 {area:272}(으)로 돌아가세요. 귀환석이 그곳에 귀속되어 있습니다.",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "식인 고원랩터(36-37)는 고원 남부에서 사냥합니다. 한 무리는 {area:316} 북쪽에, 다른 무리는 그 서쪽 평원에 있습니다. 한 번에 한 마리씩 끌어오세요.",
		["Only if {quest:535}'s missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one."] = "{quest:535}의 명령서를 얻지 못한 경우에만: 길 서쪽 야영지 주변의 비밀결사대 노상강도와 도둑(32-34)도 명령서를 가지고 있습니다. 약 3마리 중 1마리가 떨어뜨립니다.",
		["South of the {area:279} crater's camp"] = "{area:279} 분화구 야영지 남쪽",
		["Syndicate missives"] = "비밀결사대 서신",
		["The Boulderfist Brutes camp outside the ogres' hall, far south-west of {area:321}; the Magus stand among them. Pull them one at a time."] = "돌주먹일족 투사는 {area:321} 남서쪽 멀리 있는 오우거 전당 밖에 야영하고 있으며, 사제가 그들 사이에 있습니다. 한 번에 하나씩 끌어오세요.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "안쪽 결속의 원은 서쪽 결속의 원 남쪽, 스트롬가드 동쪽에 있습니다.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701}은(는) 골짜기 맨 끝에 있습니다.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "{zone:1458}에 있는 동안 기술을 배우세요. 상급자는 {object:36070}, {object:36073}, {object:36082}에 있습니다(성기사: {npc:260093}).",
		["Underwater"] = "물속",
		["West along the foot of the hills, south of the road: a {npc:246848} (55) walks that road from the north-east down into the traitors' camp."] = "길 남쪽, 언덕 기슭을 따라 서쪽으로 가세요. {npc:246848}(55)이(가) 북동쪽에서 그 길을 따라 배신자 야영지로 내려옵니다.",
		["West of the inner circle, Stromgarde's ruins: the Syndicate hold the east half (the Sigil drops from their Conjurors, Prowlers and Magi), the Boulderfist the west half by the {area:325} ({npc:2773} waits in one of the roofless houses beside it)."] = "안쪽 성벽 서쪽은 스트롬가드 폐허입니다. 동쪽 절반은 신디케이트가 차지하고 있으며(인장은 신디케이트 요술사, 배회자, 마법사가 떨어뜨립니다), 서쪽 절반은 {area:325} 옆으로 돌주먹일족이 차지하고 있습니다({npc:2773}은(는) 그 옆 지붕 없는 집 중 하나에서 기다립니다).",
		["Worn Stone Tokens, from the Shield Guards and Theurgists on the camp's west side"] = "야영지 서쪽의 방패 경비병과 마법사에게서 얻는 닳아해진 징표의 돌",
		["Zeppelin to {zone:1458}"] = "{zone:1458}행 비행선",
		["{item:3703}, for {npc:2333}"] = "{npc:2333}에게 줄 {item:3703}",
		["{npc:12920}, at the south gate. If he won't take the silk, another player may be running Triage: wait a few minutes and talk to him again."] = "{npc:12920}, 남쪽 관문. 비단을 받지 않으면 다른 플레이어가 '환자 분류'를 진행 중일 수 있습니다. 몇 분 기다렸다가 다시 말을 거세요.",
		["{npc:12920}, at the south gate. If {npc:12920} offers nothing, another player may be running his {skill:129} quest Triage: he can be busy for a few minutes. Wait, then talk to him again."] = "{npc:12920}, 남쪽 관문. {npc:12920}이(가) 아무것도 주지 않으면 다른 플레이어가 {skill:129} 퀘스트 '환자 분류'를 진행 중일 수 있으며, 몇 분간 바쁠 수 있습니다. 기다렸다가 다시 말을 거세요.",
		["{npc:2229} will offer {npc:2423} (41, in his manor far up {area:1339}) for this: leave it, he is over your level."] = "{npc:2229}이(가) 이 퀘스트 후 {npc:2423}(41, {area:1339} 위쪽 멀리 있는 저택)을(를) 줍니다. 레벨이 너무 높으니 받지 마세요.",
		["{npc:2229}, {npc:2410} and {npc:2437} are inside the inn; {npc:2770} stands outside it."] = "{npc:2229}, {npc:2410}, {npc:2437}은(는) 여관 안에 있고, {npc:2770}은(는) 여관 밖에 서 있습니다.",
		["{npc:270038} stands in the Apothecarium."] = "{npc:270038}은(는) 연금술 실험실에 서 있습니다.",
		["{npc:270038}: Stormheart's heart from {zone:1441}"] = "{npc:270038}: {zone:1441}에서 얻은 Stormheart의 심장",
		["{npc:2770}: for {npc:2771} in {area:321}, later in this guide"] = "{npc:2770}: 이 가이드 후반에 {area:321}의 {npc:2771}에게 줄 것",
		["{npc:2792}, by the gate"] = "{npc:2792}, 성문 옆",
		["{zone:1458} trainers"] = "{zone:1458} 상급자",
} end)()
t.guides["forever/horde/30-40/06-badlands"] = (function() return {
		["Below ground"] = "지하",
		["Into the {zone:1418}"] = "{zone:1418}(으)로",
		["Keep north on the road to {area:1517}'s entrance, in the north of the {zone:1418}: the chest lies just inside the cave mouth. {npc:2932} and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together."] = "길을 따라 계속 북쪽으로 {zone:1418} 북부의 {area:1517} 입구까지 가십시오. 상자는 동굴 입구 바로 안쪽에 있습니다. {npc:2932}와(과) 흑요석 골렘(38)이 그 옆에 서 있고 어둠괴철로단 굴착꾼(35-36)이 터널에서 일하며, 모두 정예입니다. 파티와 함께 움직이십시오.",
		["Lesser Rock Elementals"] = "하급 바위 정령",
		["Rock Elementals"] = "바위 정령",
		["Stonevault troggs"] = "바위동굴일족 트로그",
		["for Helgrum in {area:75}, around level 42"] = "42레벨쯤 {area:75}의 헬그럼에게",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}: {area:439}에서 받은 피즐의 편지",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Draenethyst crystals"] = "드레니시스트 수정",
		["Felsteed: Zevrost in {zone:1454}, then {npc:6251} in {area:392}, on the {zone:1444} guide's {zone:1454} stop."] = "지옥마: {zone:1444} 가이드의 {zone:1454} 방문 때 {zone:1454}의 제브로스트, 그다음 {area:392}의 {npc:6251}.",
		["Fly back to {object:3202}: Zul'Mamwe's Skullsplitters are just east of it."] = "{object:3202}(으)로 다시 비행하세요. 줄맘웨의 해골망치부족은 바로 동쪽에 있습니다.",
		["Fly to the {area:1497}"] = "{area:1497}(으)로 비행",
		["Fly to {area:35}"] = "{area:35}(으)로 날아가기",
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["Follow the road east from {zone:1431} through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp just off the road where it comes in from {zone:1430}."] = "길을 따라 {zone:1431}에서 동쪽으로 {zone:1430}을(를) 지나 늪으로 가세요. {npc:1776}은(는) {zone:1430}에서 들어오는 길 바로 옆의 드레나이 야영지인 {area:657}에서 기다립니다.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "더 북쪽, 길 동쪽 광산에서 투자개발회사 고블린이 채굴하고 있습니다. 광부, 현장감독, 감시관, 땜장이 모두 수정을 떨어뜨립니다.\n주의: 은신한 그림자아귀 표범과 가시덤불 암호랑이가 야영지 주변을 돌아다닙니다.",
		["Gringer, the flight master, waits on {area:35}'s upper deck. The quest givers stand on the boardwalks around the harbour and in the inn."] = "비행 조련사 그링거는 {area:35}의 위쪽 갑판에서 기다립니다. 퀘스트 제공자는 항구 주변 판자길과 여관에 있습니다.",
		["Head east to {area:75}, in the reeds south of the road."] = "동쪽으로 길 남쪽 갈대밭의 {area:75}(으)로 가세요.",
		["Head north up the road to the hunters' camp."] = "길을 따라 북쪽의 사냥꾼 야영지로 가세요.",
		["Head north up the road; the hunters camp on the hill above the river."] = "길을 따라 북쪽으로 가세요. 사냥꾼들은 강 위쪽 언덕에 야영하고 있습니다.",
		["Head north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "북동쪽의 {area:76}(으)로 가세요. 수정은 {npc:5391}의 우리로 올라가는 길을 따라 있습니다.",
		["Head south to {area:35}. Shaky Phillipe waits on the docks."] = "남쪽의 {area:35}(으)로 가세요. 겁쟁이 필립이 부두에서 기다립니다.",
		["Head west to {object:3202}."] = "서쪽의 {object:3202}(으)로 가세요.",
		["His strongbox waits at his old camp north of {area:75}, on the way back west."] = "그의 금고는 서쪽으로 돌아가는 길, {area:75} 북쪽의 옛 야영지에 있습니다.",
		["Into the {zone:1435}"] = "{zone:1435}(으)로",
		["Jungle Stalkers"] = "줄무늬정글랩터",
		["Jungle stalkers"] = "줄무늬정글랩터",
		["Keep {quest:571}, {quest:621} and {npc:737}'s tusks: the Skullsplitter chief, Zanzil's camps, the naga coast and {area:35} come on your Stranglethorn stop at about 45, after the {zone:2548}."] = "{quest:571}, {quest:621}, {npc:737}의 엄니는 가지고 있으세요. 해골망치 족장, 잔질의 야영지, 나가 해안, {area:35}은(는) {zone:2548} 이후 45레벨쯤 가시덤불 방문 때 갑니다.",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "터널로 마을을 나가세요. 쪽지는 {area:35} 바로 북쪽의 해적 만에 있습니다.",
		["MacKinley: keep it, the ghost pirates (43-44) wait for your Stranglethorn stop at about 45"] = "맥킨리: 가지고 있으세요. 유령 해적(43-44)은 45레벨쯤 가시덤불 방문 때 처리합니다",
		["Mistvale gorillas"] = "안개계곡고릴라",
		["Nesingwary's camp"] = "네싱워리의 야영지",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "노보루는 {area:76} 남서쪽 빈터를 돌아다닙니다. 그의 곤봉이 퀘스트를 시작합니다.",
		["Riding at 40"] = "40레벨 탈것 타기",
		["Riding needs level 40 and costs 100 gold; learning it gives you a Galestrider, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454} and fly to {zone:1456}: the skyboat to {zone:2521} leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes, and {npc:265756} teaches Skyborne at the {area:17684} in {area:16638}. Then back to {zone:1454} for the {object:3202} zeppelin. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "탈것 타기는 40레벨이 필요하고 100골드가 듭니다. 배우면 질풍걸음을 얻으며, 가시덤불 골짜기 다음의 {zone:2548}은(는) 탈것 없이는 먼 길입니다. {object:3202} 탑에서 비행선을 타고 {zone:1454}(으)로 간 뒤 {zone:1456}(으)로 날아가세요. {zone:2521}행 하늘배는 {zone:1456} 북쪽, {area:17045} 남쪽 절벽에서 약 5분마다 출발하며, {npc:265756}이(가) {area:16638}의 {area:17684}에서 하늘태생에게 가르칩니다. 그 후 {zone:1454}(으)로 돌아가 {object:3202}행 비행선을 타세요. 골드가 부족하면 이 단계를 건너뛰세요. {zone:1444} 가이드에서 약 45레벨에 {zone:1454}을(를) 다시 지납니다.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454} and go south down the {zone:1411} road to {area:367}: {npc:7953} teaches Trolls there, with Zjolnir's raptors (20 gold each). Then back to the zeppelin for {object:3202}. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "탈것 타기는 40레벨이 필요하고 100골드가 듭니다. 배우면 탈것을 얻으며, 가시덤불 골짜기 다음의 {zone:2548}은(는) 탈것 없이는 먼 길입니다. {object:3202} 탑에서 비행선을 타고 {zone:1454}(으)로 간 뒤 {zone:1411} 길을 따라 남쪽 {area:367}(으)로 가세요. {npc:7953}이(가) 그곳에서 트롤에게 가르치며, 즐니르의 랩터(각 20골드)도 있습니다. 그 후 비행선으로 돌아가 {object:3202}(으)로 가세요. 골드가 부족하면 이 단계를 건너뛰세요. {zone:1444} 가이드에서 약 45레벨에 {zone:1454}을(를) 다시 지납니다.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454}, fly to {zone:1456} and ride down to {area:222}: {npc:3690} teaches Tauren there, with {npc:3685}'s kodos (20 gold each). Then fly back to {zone:1454} for the {object:3202} zeppelin. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1456} again at about 45."] = "탈것 타기는 40레벨이 필요하고 100골드가 듭니다. 배우면 탈것을 얻으며, 가시덤불 골짜기 다음의 {zone:2548}은(는) 탈것 없이는 먼 길입니다. {object:3202} 탑에서 비행선을 타고 {zone:1454}(으)로 가서, {zone:1456}(으)로 날아간 뒤 {area:222}(으)로 내려가세요. {npc:3690}이(가) 그곳에서 타우렌에게 가르치며, {npc:3685}의 코도(각 20골드)도 있습니다. 그 후 {zone:1454}(으)로 날아가 {object:3202}행 비행선을 타세요. 골드가 부족하면 이 단계를 건너뛰세요. {zone:1444} 가이드에서 약 45레벨에 {zone:1456}을(를) 다시 지납니다.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454}: {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel (wolves 20 gold each). Then the zeppelin back to {object:3202}. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "탈것 타기는 40레벨이 필요하고 100골드가 듭니다. 배우면 탈것을 얻으며, 가시덤불 골짜기 다음의 {zone:2548}은(는) 탈것 없이는 먼 길입니다. {object:3202} 탑에서 비행선을 타고 {zone:1454}(으)로 가세요. {npc:4752}이(가) {object:172958}의 {npc:3362} 늑대 우리 옆에서 오크에게 가르칩니다(늑대 각 20골드). 그 후 비행선을 타고 {object:3202}(으)로 돌아오세요. 골드가 부족하면 이 단계를 건너뛰세요. {zone:1444} 가이드에서 약 45레벨에 {zone:1454}을(를) 다시 지납니다.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, a short ride north of the zeppelin towers, with {npc:4731}'s skeletal horses (20 gold each) beside her. Ride back to the towers for the {object:3202} zeppelin."] = "탈것 타기는 40레벨이 필요하며 100골드가 듭니다. 배우면 탈것도 하나 받습니다. 각 종족은 자기 종족의 상급자에게서 배웁니다. 당신의 상급자는 비행선 탑에서 북쪽으로 조금 가면 나오는 {area:159}의 {npc:4773}이며, 그 옆에 {npc:4731}의 해골마(각 20골드)가 있습니다. {object:3202}행 비행선을 타려면 탑으로 돌아가십시오.",
		["Sawtooth crocolisks"] = "톱니악어",
		["Sawtooth snappers"] = "무쇠턱 톱니악어",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "해골마: {area:159}의 {npc:4773} 옆에 있는 {npc:4731}.",
		["The Bloodsail ships"] = "붉은해적단 배",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights.\nCareful: {npc:730}, a level 43 elite raptor, roams among the stalkers: leave him for {quest:195}'s group step."] = "줄무늬정글랩터(40-41)는 {object:3202} 남쪽 해안에서 사냥합니다. 레벨이 훨씬 높으니 한 마리씩 끌어오고 전투 사이에 쉬세요.\n주의: 43레벨 정예 랩터 {npc:730}이(가) 랩터들 사이를 돌아다닙니다. {quest:195}의 파티 단계를 위해 남겨 두세요.",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "악어는 {npc:5391}의 야영지 주변 웅덩이와 남쪽 {area:75} 쪽에서 뒹굴고 있습니다. 네 마리 중 한 마리 정도가 옆구리살을 떨어뜨립니다.",
		["The naga explorers on the coast south of here (43-44) are for Bloads and Mok'thardin: keep both quests for your Stranglethorn stop at about 45."] = "이 남쪽 해안의 나가 탐험가(43-44)는 블로즈와 모크타르딘의 퀘스트용입니다. 두 퀘스트 모두 45레벨쯤 가시덤불 방문 때까지 가지고 있으세요.",
		["The scroll, {quest:624}, lies on the decks of the three ships off the {area:43}, crewed by pirates of 42-45 who come in pairs, with captains of 45-48: take it with a group. Its chain runs on through the {zone:1435}, {zone:1445} and the {zone:1425}."] = "두루마리 {quest:624}은(는) {area:43} 앞바다 배 세 척의 갑판에 있습니다. 42-45 해적이 둘씩 다니고 선장은 45-48이니 파티와 함께 가세요. 이어지는 퀘스트는 {zone:1435}, {zone:1445}, {zone:1425}(으)로 이어집니다.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast.\nCareful: the Jungle Stalkers (40-41) are thick here: pull one at a time and rest between fights."] = "랩터는 {object:3202} 남쪽 정글에서 서쪽 해안 쪽으로 사냥합니다.\n주의: 이곳엔 줄무늬정글랩터(40-41)가 많습니다. 하나씩 끌고 전투 사이에 쉬세요.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone."] = "정예 몹입니다. 파티를 권장하니 함께할 사람을 찾으세요. {npc:728}은(는) 40레벨 정예입니다. 대부분의 직업은 42레벨에 혼자 잡지만 도움이 필요할 수 있습니다. 혼자라면 건너뛰세요.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone."] = "정예 몹입니다. 파티를 권장하니 함께할 사람을 찾으세요. {npc:730}은(는) 43레벨 정예입니다. 대부분의 직업은 45레벨에 혼자 잡지만 도움이 필요할 수 있습니다. 혼자라면 건너뛰세요.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "정예 몹입니다. 파티를 권장하니 함께할 사람을 찾으세요. {npc:731}은(는) 43레벨 정예입니다. 대부분의 직업은 45레벨에 혼자 잡지만 도움이 필요할 수 있습니다. 혼자라면 건너뛰세요.\n주의: 호랑이와 은신한 그림자아귀 표범이 그 근처를 돌아다닙니다. 끌기 전에 정리하세요. {npc:731}은(는) 전투가 시작되면 20미터 안의 생물을 불러 도움을 청합니다.",
		["Venture Co. mine"] = "투자개발회사 광산",
		["Warlocks don't buy riding: your mount is the Felsteed, from your class quest. Zevrost in {zone:1454}'s {object:172960} starts it and {npc:6251} in {area:392} teaches it, both on the {zone:1444} guide's {zone:1454} stop at about 45."] = "흑마법사는 탈것 타기를 사지 않습니다. 탈것은 직업 퀘스트로 얻는 지옥마입니다. {zone:1454} {object:172960}의 제브로스트에게서 시작하고 {area:392}의 {npc:6251}에게서 배우며, 둘 다 45레벨쯤 {zone:1444} 가이드의 {zone:1454} 방문 때 합니다.",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them.\nOn the coast between Zul'Kunda and {object:3202} an {npc:2635} (level 38 elite) shares the spawns of the ordinary crocolisks: kill it if it is up and take its skin for {npc:2495}."] = "원정대 서쪽, 줄쿤다의 폐허에 붉은머리부족 족장 {npc:1061}와(과) {npc:1062}이(가) 함께 서 있습니다. 먼저 호위병을 처치한 뒤 끌어오세요.\n줄쿤다와 {object:3202} 사이 해안에서는 {npc:2635}(38레벨 정예)이(가) 일반 악어와 같은 자리에 나타납니다. 나타나 있다면 처치하고 {npc:2495}에게 줄 가죽을 챙기세요.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "경로의 이전 방문 때 이것을 놓쳤습니다. 지금 이것부터 합니다. 금방 끝나며 뒤에 이어지는 퀘스트를 열어 줍니다.",
		["Your level 40 training is in the {area:1497}: fly there from {area:340}, train, and take the zeppelin from the towers outside the city to {object:3202}."] = "40레벨 훈련은 {area:1497}에서 합니다. {area:340}에서 그곳으로 날아가 훈련한 뒤, 도시 밖 탑에서 비행선을 타고 {object:3202}(으)로 가십시오.",
		["Your mount at 40"] = "40레벨 탈것",
		["Zeppelin to {object:3202}"] = "{object:3202}행 비행선",
		["Zul'Kunda"] = "줄쿤다",
		["Zul'Mamwe"] = "줄맘웨",
		["for a later stop in the {zone:1435}"] = "나중에 {zone:1435}에 들를 때",
		["the {area:16550}'s entrance, underwater"] = "물속에 있는 {area:16550}의 입구",
		["the {object:2076}, beside {npc:2497}"] = "{npc:2497} 옆의 {object:2076}",
		["{area:340} flight master"] = "{area:340} 비행 조련사",
		["{npc:2464}: for {npc:256418} in {area:16743}, the {zone:2548}' Horde fort, in the next guide"] = "{npc:2464}: 다음 가이드에서 {zone:2548}의 호드 요새 {area:16743}의 {npc:256418}에게",
		["{npc:2487}: keep it for the {area:43} at about 45"] = "{npc:2487}: 45레벨쯤 {area:43}을(를) 위해 가지고 있으세요",
		["{npc:2488}, on the top floor: keep it for the {area:43} at about 45"] = "{npc:2488}, 꼭대기 층: 45레벨쯤 {area:43}을(를) 위해 가지고 있으세요",
		["{npc:2493}: keep it for the {area:43} at about 45"] = "{npc:2493}: 45레벨쯤 {area:43}을(를) 위해 가지고 있으세요",
		["{npc:2495}, inside: the {item:4105}"] = "{npc:2495}, 안쪽: {item:4105}",
		["{npc:2495}: the {npc:2635} suns on the coast between Zul'Kunda and {object:3202}, later on this loop"] = "{npc:2495}: {npc:2635}은(는) 줄쿤다와 {object:3202} 사이 해안에서 햇볕을 쬐고 있습니다. 이 경로 후반에 들릅니다",
		["{npc:2496}, on the balcony beside MacKinley"] = "{npc:2496}, 맥킨리 옆 발코니",
		["{npc:2519}: the cavern entrance under the {area:104}, west of the camp"] = "{npc:2519}: 야영지 서쪽, {area:104} 아래의 동굴 입구",
		["{npc:265756}, riding trainer, at the {area:17684} in {area:16638}"] = "{npc:265756}, 탈것 상급자, {area:16638}의 {area:17684}",
		["{npc:4631}, on the docks: Gazlowe's letter, if you carry it"] = "{npc:4631}, 부두: 가즐로가 보낸 편지를 가지고 있다면",
		["{npc:4631}: {quest:97332}, after Zimmix's rescue; the package goes to {npc:259961} at {area:16727}, in the {zone:2548} guide"] = "{npc:4631}: 짐믹스 구출 후 {quest:97332}. 꾸러미는 {zone:2548} 가이드에서 {area:16727}의 {npc:259961}에게 전달합니다",
		["{npc:4773}, riding trainer"] = "{npc:4773}, 탈것 상급자",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391}은(는) 늪 북동쪽 {area:76}에 붙잡혀 있습니다. 풀어 주고 따라가며 그를 쫓는 늪 생물을 물리치세요.",
		["{npc:716} collects the pages of {quest:338}: the trolls of the vale drop them now and then. Take his quest; each chapter he takes once you have all its pages."] = "{npc:716}은(는) {quest:338}의 책장을 모읍니다. 골짜기의 트롤이 가끔 떨어뜨립니다. 그의 퀘스트를 받으십시오. 각 장은 모든 책장을 모으면 그가 받습니다.",
		["{npc:716}: every page of chapter I is in your bags"] = "{npc:716}: 1장의 모든 책장이 가방에 있음",
		["{npc:716}: every page of chapter II is in your bags"] = "{npc:716}: 2장의 모든 책장이 가방에 있음",
		["{npc:716}: every page of chapter III is in your bags"] = "{npc:716}: 3장의 모든 책장이 가방에 있음",
		["{npc:716}: every page of chapter IV is in your bags"] = "{npc:716}: 4장의 모든 책장이 가방에 있음",
		["{npc:716}: the four chapters"] = "{npc:716}: 네 개의 장",
		["{npc:729}, the tiger {npc:717} sent you after on your last visit, prowls the hilltop just south-west of the camp."] = "지난번 방문 때 {npc:717}이(가) 쫓으라고 보낸 호랑이 {npc:729}은(는) 야영지 바로 남서쪽 언덕 꼭대기를 배회합니다.",
		["{npc:737}, upstairs, has his next errand now: the Skullsplitter tusks come from the trolls of Zul'Mamwe, later on this loop."] = "위층의 {npc:737}이(가) 이제 다음 심부름을 줍니다. 백골가루부족 엄니는 이 경로 후반에 줄맘웨의 트롤에게서 얻습니다.",
		["{quest:95770}: west of {object:3202}, swim out over the {area:104} and dive to the cavern entrance in the reef; the quest completes as you find it. Leave the cavern for now: the jungle stalkers are south along the coast."] = "{quest:95770}: {object:3202} 서쪽으로 {area:104} 위를 헤엄쳐 나가 암초 속 동굴 입구로 잠수하세요. 입구를 찾으면 퀘스트가 완료됩니다. 동굴은 일단 그냥 두세요. 줄무늬정글랩터는 해안을 따라 남쪽에 있습니다.",
		["{zone:1458} trainers"] = "{zone:1458} 상급자",
} end)()
t.guides["forever/horde/40-50/01b-riverglades"] = (function() return {
		["About 70 quests in Forever's new zone, from the fort of {area:16743}."] = "Forever의 새 지역에서 {area:16743} 요새를 거점으로 하는 약 70개의 퀘스트.",
		["Across the {area:3} to {area:340}, the Horde fortress built into the cliffs at the zone's western edge: its flight master stands at the foot of the fortress."] = "{area:3}을(를) 가로질러 지역 서쪽 끝 절벽에 지어진 호드 요새 {area:340}(으)로 가세요. 비행 조련사는 요새 아래에 있습니다.",
		["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "해안을 따라 북쪽으로 돌아가십시오. 게들에게 가는 길에 부두에서 멀록 퀘스트와 가죽 퀘스트를 제출하십시오.",
		["Back through the port"] = "항구를 거쳐 돌아가기",
		["Back to the port, from the north pier west through the docks."] = "북쪽 부두에서 서쪽으로 선착장을 지나 항구로 돌아가십시오.",
		["Back to the port."] = "항구로 돌아가십시오.",
		["Back to {area:16743}, where your Hearthstone is set: {npc:263190} on the fort's west side first, then {npc:256418}, {npc:256655} by the cook fire, {npc:256657} and {npc:258031} on your way east through the fort."] = "귀환석이 설정된 {area:16743}(으)로 돌아가세요. 먼저 요새 서쪽의 {npc:263190}, 그다음 요새를 지나 동쪽으로 가며 {npc:256418}, 화톳불 옆의 {npc:256655}, {npc:256657}, {npc:258031}에게 가세요.",
		["Back to {npc:255829} on his hill. {npc:257062} runs the {quest:94668} just below it."] = "언덕 위의 {npc:255829}에게 돌아가세요. 바로 아래에서 {npc:257062}이(가) {quest:94668}을(를) 운영합니다.",
		["Bonegnaw"] = "뼈갉이",
		["Down to the port."] = "항구로 내려가십시오.",
		["Each bout is a fight in the ring below {npc:255829}'s hill against an elite: Buzzbeak (41), Kronk and Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) and {npc:257059} (45). Come in rested, with full health and mana; if a bout goes wrong, {npc:257062} offers it again."] = "각 시합은 {npc:255829}의 언덕 아래 투기장에서 정예와 싸우는 것입니다: 윙윙부리(41), 크롱크와 뼈갉이(42), {npc:258626}(43), 킁킁코(44), {npc:257059}(45). 휴식 경험치 상태로 생명력과 마나를 가득 채우고 들어가세요. 시합에 실패하면 {npc:257062}이(가) 다시 제안합니다.",
		["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "절벽을 따라 동쪽으로 해적 야영지 맨 끝까지 가십시오. {npc:260390}이(가) 물가에, 그 옆에 {npc:260391}이(가) 있습니다.",
		["East back to {area:16743}."] = "동쪽 {area:16743}(으)로 돌아가세요.",
		["East back to {area:16743}: {npc:260931}'s word goes to {npc:256710}, and {npc:256710}'s to {npc:255829}, the ogres' chieftain."] = "동쪽 {area:16743}(으)로 돌아가세요. {npc:260931}의 소식은 {npc:256710}에게, {npc:256710}의 소식은 오우거 족장 {npc:255829}에게 전해집니다.",
		["East of Rog'mar, on the hill above the road to {area:16727}: {npc:263367} has his workshop there. The gas vents are in the marsh south-west of it, on your first hunt for {npc:258031}."] = "로그마르 동쪽, {area:16727}(으)로 가는 길 위 언덕에 {npc:263367}의 작업장이 있습니다. 가스 분출구는 그 남서쪽 습지에 있으며, {npc:258031}의 첫 사냥 때 들릅니다.",
		["East to {area:16735}, the Alliance farm by the river: the farmhands work the fields and the feed satchels lie by the barns. {area:16744}, the Alliance outpost on the road, has guards: pass south of it.\nCareful: {npc:263380}, an elite (level 42), hunts along the river by the farm: keep an eye on the riverbank."] = "동쪽으로 강가의 얼라이언스 농장 {area:16735}(으)로 가세요. 농장 일꾼이 밭에서 일하고 사료 가방은 헛간 옆에 있습니다. 길가의 얼라이언스 전초기지 {area:16744}에는 경비병이 있으니 남쪽으로 지나가세요.\n주의: 정예인 {npc:263380}(42레벨)이(가) 농장 옆 강을 따라 사냥합니다. 강가를 잘 살피세요.",
		["Finish the {item:268632}"] = "{item:268632} 마저 모으기",
		["Fly to {area:484}"] = "{area:484}(으)로 날아가기",
		["Frazzlespark's crate from the port goes to {npc:256418}, in the middle of the fort."] = "항구에서 받은 프라즐스파크의 상자는 요새 중앙의 {npc:256418}에게 가져가세요.",
		["Into the {area:16591}"] = "{area:16591}(으)로",
		["Kronk"] = "크롱크",
		["Learn {area:976}'s flight path: it saves the ride next time."] = "{area:976}의 비행 경로를 익히세요. 다음에 이동 시간을 아낄 수 있습니다.",
		["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42) wanders the shore and {npc:263380} (elite, 42) the river: take your beasts away from them."] = "{zone:2548}의 야수 대부분이 {npc:260231}에게 줄 {item:268632}을(를) 떨어뜨립니다. 이 해안의 해안 기어다니는 놈들과 해적 서쪽 능선의 멧돼지가 좋습니다.\n주의: {npc:257001}(정예, 42)이(가) 해안을, {npc:263380}(정예, 42)이(가) 강을 돌아다니니 야수를 그들에게서 멀리 끌어내 잡으세요.",
		["New in Forever: if a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\n{npc:255897} keeps a stall at the west end of the docks. The port's other jobs are for later in this guide: this crate goes to the Horde's fort."] = "Forever 신규 지역: 잘못된 단계가 있으면 Polestar의 Discord나 GitHub에 단계 이름과 함께 알려 주세요.\n{npc:255897}은(는) 부두 서쪽 끝에서 노점을 운영합니다. 항구의 다른 일은 이 가이드 후반에 합니다. 이 상자는 호드 요새로 가져갑니다.",
		["New in Forever: this guide follows what players did in the {area:16591}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nFrom {area:340}, ride south-east across the {area:3} to the zone's southern edge: the pass of {area:16685} leads down into the {area:16591}. {area:16743}, the Horde's fort, stands in the middle of the zone, east along the valley."] = "Forever 신규 지역: 이 가이드는 플레이어들이 {area:16591}에서 진행한 내용을 따릅니다. 잘못된 단계가 있으면 Polestar의 Discord나 GitHub에 단계 이름과 함께 알려 주세요.\n{area:340}에서 남동쪽으로 {area:3}을(를) 가로질러 지역 남쪽 끝으로 가세요. {area:16685} 고개를 따라 {area:16591}(으)로 내려갑니다. 호드 요새 {area:16743}은(는) 골짜기를 따라 동쪽, 지역 한가운데에 있습니다.",
		["New in Forever: this guide follows what players did in the {zone:2548}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nThe {zone:2548} lie across the sea from {zone:1446}: a goblin boat sails from {area:977}, north-east of {area:976}, to {area:16727}. Fly to {area:484} in {zone:1441} and head south-east through the {area:439} to {area:976}. (If you already know {area:340} in the {area:3}, the way in through {area:16685} works too.)"] = "Forever 신규 지역: 이 가이드는 플레이어들이 {zone:2548}에서 진행한 내용을 따릅니다. 잘못된 단계가 있으면 Polestar의 Discord나 GitHub에 단계 이름과 함께 알려 주세요.\n{zone:2548}은(는) {zone:1446}에서 바다 건너편에 있습니다. {area:976} 북동쪽 {area:977}에서 고블린 배가 {area:16727}(으)로 갑니다. {zone:1441}의 {area:484}(으)로 날아가 남동쪽으로 {area:439}을(를) 지나 {area:976}(으)로 가세요. ({area:3}의 {area:340} 비행 경로가 이미 있다면 {area:16685}(으)로 들어가는 길도 됩니다.)",
		["North along the beach from the docks: the crawlers drop the meat for {npc:259962}, and their entrails count for {npc:260231}. {npc:260235}, a big crab, scuttles along the rocks east of the docks. {npc:259758}, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."] = "부두에서 해변을 따라 북쪽으로 가세요. 기어다니는 놈들이 {npc:259962}에게 줄 고기를 떨어뜨리고, 내장은 {npc:260231}의 퀘스트에 포함됩니다. 큰 게인 {npc:260235}은(는) 부두 동쪽 바위를 따라 돌아다닙니다. 49레벨 희귀 정예인 {npc:259758}이(가) 부두부터 해적 야영지까지 이 해안을 배회하니, 보이면 멀리 피하세요.",
		["North along the coast from the port: the Eastsea raiders and bombardiers have dug in on the slopes west of the buccaneers' camp, among their powder kegs. Watch for {npc:259758} on these cliffs.\nCareful: the Eastsea Raiders are level 44-45, a level or two over you here: pull them one at a time from the edge of the slopes and keep clear of the camp behind them."] = "항구에서 해안을 따라 북쪽으로 가세요. 동쪽바다 약탈자와 폭격수들이 해적 야영지 서쪽 비탈의 화약통 사이에 진을 쳤습니다. 이 절벽에서 {npc:259758}을(를) 조심하세요.\n주의: 동쪽바다 약탈자는 44-45레벨로 여러분보다 한두 레벨 높습니다. 비탈 가장자리에서 하나씩 끌어내고 뒤쪽 야영지에는 접근하지 마세요.",
		["North of the camps the cult works ogre miners in a mine: talk five of them into rising up against their masters.\nCareful: Twilight Enforcers (elites, level 45) walk past the mine's mouth on their way through the camps. Wait for one to pass before you go in."] = "야영지 북쪽 광산에서 교단이 오우거 광부를 부리고 있습니다. 그중 다섯 명을 설득해 주인에게 맞서게 하세요.\n주의: 황혼의 집행자(정예, 45레벨)가 야영지를 오가며 광산 입구를 지나갑니다. 지나갈 때까지 기다렸다가 들어가세요.",
		["North of the fort the Rog'mar Trainees drill: use {npc:256655}'s {item:265066} on them.\nCareful: {npc:263380}, an elite (level 42), can come up from the river south of the fort: let him pass."] = "요새 북쪽에서 로그마르 훈련병들이 훈련하고 있습니다. 그들에게 {npc:256655}의 {item:265066}을(를) 사용하세요.\n주의: 정예(42레벨)인 {npc:263380}이(가) 요새 남쪽 강에서 올라올 수 있습니다. 지나갈 때까지 기다리세요.",
		["North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. {npc:259758} walks the camp too: keep an eye out for him."] = "해안을 따라 북동쪽, 절벽 위 해적 야영지로 가십시오. 해적과 머스킷병이 밀수품을 지니고 있습니다. {npc:259758}도 야영지를 돌아다니니 주의하십시오.",
		["North-east from {area:16743} up into the hills: {npc:256728} watches the Paletusk boars from his camp."] = "{area:16743}에서 북동쪽 언덕으로 올라가세요. {npc:256728}이(가) 야영지에서 창백엄니 멧돼지들을 지켜보고 있습니다.",
		["North-east to the workshop. {npc:263367}'s stress test is a fight with his G45-B4G beside the workshop: hand the quest in once it's beaten."] = "북동쪽 작업장으로 가세요. {npc:263367}의 스트레스 테스트는 작업장 옆 G45-B4G와의 전투입니다. 물리치면 퀘스트를 제출하세요.",
		["North-west to {area:16726}, the ogres' town. {npc:255829}, its chieftain, sits on the hill. The ogres are friendly while you leave them alone."] = "북서쪽의 오우거 마을 {area:16726}(으)로 가세요. 족장 {npc:255829}이(가) 언덕 위에 앉아 있습니다. 건드리지 않는 한 오우거들은 우호적입니다.",
		["Rotflesh Mushrooms"] = "부패살점 버섯",
		["Snufflesnout (44)"] = "킁킁주둥이 (44)",
		["South down the hills, round the west side of the Alliance scouts' camp: tap the Young Paletusks with {npc:256728}'s staff to send them home; the Mature Paletusks around the hills drop the boar meat."] = "언덕을 따라 남쪽으로 내려가 얼라이언스 정찰병 야영지 서쪽을 돌아가세요. 어린 창백엄니에게 {npc:256728}의 지팡이를 사용해 집으로 돌려보내고, 언덕 주변의 다 자란 창백엄니에게서 멧돼지 고기를 얻으세요.",
		["South-east back towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. {npc:259758} wanders down to this beach too."] = "남동쪽으로 항구 쪽으로 돌아가세요. 부두 북쪽 해변의 해안 기어다니는 놈들이 내장을 모으기 가장 빠릅니다. {npc:259758}은(는) 이 해변까지도 내려옵니다.",
		["South-east down out of the hills to {area:16727}, the goblins' harbour on the coast. {npc:255897} keeps a stall at the west end of the docks, {npc:259962} cooks by the inn, and {npc:259961} works the north pier."] = "언덕을 내려와 남동쪽으로 해안의 고블린 항구인 {area:16727}(으)로 가세요. {npc:255897}은(는) 부두 서쪽 끝에서 노점을 열고 있고, {npc:259962}은(는) 여관 옆에서 요리하며, {npc:259961}은(는) 북쪽 부두에서 일합니다.",
		["South-east of Rog'mar the plains run down to {area:16729}. The Low Plains Buzzards circle everywhere; a picked carcass lies in the grass (its skull starts {quest:96103}), and the marsh vents are just past it."] = "로그마르 남동쪽으로 평원이 {area:16729}까지 이어집니다. 저지대 대머리수리가 곳곳을 맴돌고, 풀밭에 뜯어먹힌 사체가 있으며(두개골로 {quest:96103} 시작), 습지 분출구는 그 바로 너머에 있습니다.",
		["South-east out of the hills: {npc:262399}, a prospector who deals with both sides, has camped by the Cinderscale dragonkin's hollow."] = "언덕을 나와 남동쪽으로 가세요. 양쪽 진영과 거래하는 탐광꾼 {npc:262399}이(가) 잿빛비늘 용족의 분지 옆에 야영하고 있습니다.",
		["South-west across the river to the Alliance lumber camp. The lumberjacks carry the axes. Loot Wood Bundles from the Peasant Woodpiles around the camp and use them to fletch Makeshift Stickin' Spears. {npc:263380}, an elite (level 42), prowls the river by the camp: if he comes your way, back off and let him pass."] = "남서쪽으로 강을 건너 얼라이언스 벌목장으로 가세요. 벌목꾼이 도끼를 지니고 있습니다. 벌목장 주변의 농부 장작더미에서 목재 묶음을 얻어 급조한 찌르기 창을 만드세요. 정예인 {npc:263380}(42레벨)이(가) 벌목장 옆 강을 배회합니다. 다가오면 물러나서 지나가게 두세요.",
		["South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts {quest:95260} for {npc:260231} at the docks."] = "항구에서 해안을 따라 남서쪽으로 가십시오. 바닷물 멀록이 해변에 진을 치고 있습니다. 가는 길에 길가에 칠한 가죽이 펼쳐져 있는데, 부두의 {npc:260231}을(를) 위한 {quest:95260}이(가) 시작됩니다.",
		["South-west of Rog'mar the river runs between the farms: impale the Freshwater Crocolisks with {npc:263190}'s spears. The Alliance trains its scouts and priests at a camp on the far bank. {npc:257079}, the Alliance elite, rides the road just east of the camp: pull the scouts and priests away from it.\nCareful: {npc:263380}, an elite (level 42), hunts along this river: if he comes your way, back off and let him pass."] = "로그마르 남서쪽에서 강이 농장 사이를 흐릅니다. {npc:263190}의 창으로 민물 악어를 꿰뚫으세요. 얼라이언스는 건너편 강둑의 야영지에서 정찰병과 사제를 훈련합니다. 얼라이언스 정예인 {npc:257079}이(가) 야영지 바로 동쪽 길을 순찰합니다. 정찰병과 사제를 그에게서 떼어 끌어오세요.\n주의: 정예(42레벨)인 {npc:263380}이(가) 이 강을 따라 사냥합니다. 다가오면 물러나서 지나가게 두세요.",
		["The Cinderscale hollow"] = "잿빛비늘 분지",
		["The Eastsea pirates"] = "동부해 해적",
		["The Glade Vipers hide in the long grass south-east of town; the Roving Tallstriders graze beside them. {npc:257079}, an Alliance elite (level 45), rides the road from {area:16729} to {area:16725} along the grass's south-west edge: keep clear of him."] = "숲속 독사는 마을 남동쪽의 긴 풀숲에 숨어 있고, 떠도는 타조가 그 옆에서 풀을 뜯습니다. 얼라이언스 정예인 {npc:257079}(45레벨)이(가) 풀숲 남서쪽 가장자리를 따라 {area:16729}에서 {area:16725}까지 길을 달립니다. 가까이 가지 마세요.",
		["The Twilight Maulers and Firecallers camp on the ridge east of {npc:256728}. {npc:260973}, who carries the {item:269257}, stands among them. Just south of the ogres, {npc:260211} (an Alliance elite, level 42) and his Farholde Ambushers hold the scouts' camp: keep north of it unless you came with a group for him."] = "황혼의 난타꾼과 황혼의 불소환사들이 {npc:256728} 동쪽 산등성이에 진을 치고 있습니다. {item:269257}을(를) 지닌 {npc:260973}이(가) 그들 사이에 있습니다. 오우거 바로 남쪽에는 {npc:260211}(얼라이언스 정예, 42레벨)와(과) 파홀드 매복병들이 정찰병 야영지를 지키고 있습니다. 그를 잡을 파티가 없다면 야영지 북쪽으로 다니세요.",
		["The Twilight camps"] = "황혼의 야영지",
		["The Twilight ogres' camp"] = "황혼의 오우거 야영지",
		["The Wildplains lions roam the plains just south of {area:16743}.\nCareful: {npc:263315}, an elite lion (level 41), prowls the same plains around 59.6,53.2: keep an eye out for him and pull the lions away from where he walks."] = "야생평원 사자는 {area:16743} 바로 남쪽 평원을 돌아다닙니다.\n주의: 정예 사자 {npc:263315}(41레벨)이(가) 같은 평원의 59.6,53.2 부근을 배회합니다. 잘 살피고 사자를 그가 다니는 곳에서 멀리 끌어내세요.",
		["The crawlers and {npc:260235}"] = "게와 {npc:260235}",
		["The cultists fill the streets and fields; the Shadowmancers on the town's northern side carry the missives. The finger bones drop from all of them.\nCareful: {npc:256899}, an elite ogre (level 41), walks the western streets of {area:16723}, around 44-47,47-52. Pull the cultists out towards you and let him pass."] = "신도들이 거리와 들판을 가득 메우고 있습니다. 마을 북쪽의 어둠술사가 서신을 지니고 있습니다. 손가락뼈는 모두에게서 떨어집니다.\n주의: 정예 오우거(41레벨)인 {npc:256899}이(가) {area:16723} 서쪽 거리, 44-47,47-52 주변을 돌아다닙니다. 신도들을 끌어오고 그는 지나가게 두세요.",
		["The lions"] = "사자",
		["The murlocs, south-west"] = "남서쪽의 멀록",
		["The ogre mine"] = "오우거 광산",
		["The paletusks"] = "창백엄니 멧돼지",
		["The pirates' second wave"] = "해적의 두 번째 무리",
		["The pirates' ships"] = "해적선",
		["The plains and the marsh"] = "평원과 습지",
		["The ritual grounds"] = "의식의 터",
		["The ritualists and their empowered brutes gather at the ritual circles in the middle of {area:16723}: wreck five of the circles.\nCareful: {npc:256899}, the elite ogre (level 41), walks through here from the western streets: watch for him before each pull."] = "의식술사와 강화된 난폭자들이 {area:16723} 한가운데의 의식 법진에 모여 있습니다. 법진 다섯 개를 파괴하세요.\n주의: 정예 오우거(41레벨)인 {npc:256899}이(가) 서쪽 거리에서 이곳을 지나다닙니다. 매번 끌어오기 전에 살피세요.",
		["The river and the Farholde camp"] = "강과 파홀드 야영지",
		["The training grounds"] = "훈련장",
		["The vipers and the tallstriders"] = "독사와 타조",
		["The whelps nest all over the hollow; the warriors guard its back, by the {item:271611}. The warriors are level 41-42: pull them one at a time. Scaldaron, a rare elite drake, can be up here too: leave him be unless you have a group."] = "새끼용은 분지 곳곳에 둥지를 틀고 있고, 전사는 분지 안쪽 {item:271611} 옆을 지킵니다. 전사는 41-42레벨이니 하나씩 끌어내세요. 희귀 정예 비룡 스칼다론도 여기 있을 수 있습니다. 파티가 없으면 건드리지 마세요.",
		["The {area:16737}"] = "{area:16737}",
		["The {npc:260244} prowls the shallows south-west of the port, below the murlocs' beaches. {npc:257001}, an elite, walks the shore close by: give him room."] = "{npc:260244}은(는) 항구 남서쪽, 멀록 해변 아래 얕은 물을 배회합니다. 정예인 {npc:257001}이(가) 근처 해안을 걸어 다니니 거리를 두십시오.",
		["The {object:628948} poster by the inn"] = "여관 옆 {object:628948} 벽보",
		["The {object:628948} poster by the inn: {npc:260235}"] = "여관 옆 {object:628948} 벽보: {npc:260235}",
		["The {quest:94670}: Buzzbeak"] = "{quest:94670}: 윙윙부리",
		["The {quest:94670}: Kronk and Bonegnaw"] = "{quest:94670}: 크롱크와 뼈갉이",
		["The {quest:94962}: {npc:258626}"] = "{quest:94962}: {npc:258626}",
		["West back to {area:16743}'s east side."] = "서쪽으로 {area:16743}의 동쪽으로 돌아가세요.",
		["West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."] = "북쪽 배에서 서쪽으로 능선을 오르십시오. 부패살점 버섯은 황혼의 망치 오우거 야영지 근처 바위 사이에 자랍니다. 능선의 다 자란 흰엄니도 내장을 줍니다.",
		["West from {area:16743} through {area:16723} and on up the valley towards {area:16685}: {npc:258570}, {npc:256418}'s wayward warrior, keeps a camp in the hills below the Twilight cult's fortress."] = "{area:16743}에서 서쪽으로 {area:16723}을(를) 지나 계곡을 따라 {area:16685} 쪽으로 올라가세요. {npc:256418}의 길 잃은 전사 {npc:258570}이(가) 황혼 교단 요새 아래 언덕에 야영지를 차리고 있습니다.",
		["West into the {area:16737}: the Redridge gnolls camp along the slopes and carry the stolen ore. Work south-west through their camps.\nCareful: {npc:255906}, an elite gnoll (level 40), roams the south-western camps: pull the gnolls away from him."] = "서쪽 {area:16737}(으)로 가세요. 붉은마루 놈놀이 비탈을 따라 야영하며 훔친 광석을 지니고 있습니다. 야영지를 거치며 남서쪽으로 가세요.\n주의: 정예 놈놀 {npc:255906}(40레벨)이(가) 남서쪽 야영지를 돌아다닙니다. 놈놀을 그에게서 멀리 끌어내세요.",
		["West to {area:16723} again: {npc:260931}, a Twilight miner who wants out, waits at the town's eastern edge. Talk him round, then hand {npc:256710}'s quest in; one of the missing ogres stands a few steps west."] = "다시 서쪽 {area:16723}(으)로 가세요. 빠져나가고 싶어 하는 황혼의 망치단 광부 {npc:260931}이(가) 마을 동쪽 끝에서 기다립니다. 그를 설득한 뒤 {npc:256710}의 퀘스트를 제출하세요. 실종된 오우거 중 하나가 조금 서쪽에 있습니다.",
		["West to {area:16743}, the Horde's fort in the middle of the zone. {npc:258031} stands on its east side, {npc:256657} and {npc:256418} in the middle with {npc:255993}, the wind rider master; {npc:256675} and {npc:263190} on the west side."] = "서쪽으로 지역 한가운데의 호드 요새 {area:16743}(으)로 가세요. {npc:258031}은(는) 동쪽에, {npc:256657}와(과) {npc:256418}은(는) 와이번 조련사 {npc:255993}와(과) 함께 중앙에, {npc:256675}와(과) {npc:263190}은(는) 서쪽에 있습니다.",
		["West up the road from the port: {npc:263367} has his workshop on the hill. The gas vents are in the marsh south-west of it, on your first hunt for {npc:258031}."] = "항구에서 길을 따라 서쪽으로 올라가세요. {npc:263367}의 작업장이 언덕 위에 있습니다. 가스 분출구는 그 남서쪽 습지에 있으며, {npc:258031}의 첫 사냥 때 들릅니다.",
		["beat Buzzbeak"] = "윙윙부리 처치",
		["destroy 5 Twilight Ritual Circles"] = "황혼의 의식 법진 5개 파괴",
		["free five captive Rog'mar Scouts"] = "붙잡힌 로그마르 정찰병 5명 풀어 주기",
		["help {npc:258048} reach {area:16726}"] = "{npc:258048}이(가) {area:16726}에 도착하도록 돕기",
		["lead {npc:259158} out of {area:16723} to his treasure, west of the town"] = "{npc:259158}을(를) {area:16723} 밖으로 데리고 마을 서쪽의 보물까지 가십시오",
		["recruit five Ogre Miners"] = "오우거 광부 5명 포섭하기",
		["talk {npc:260931} round"] = "{npc:260931} 설득",
		["the middle ship"] = "가운데 배",
		["the northern ship"] = "북쪽 배",
		["the stress test: beat G45-B4G beside the workshop"] = "스트레스 테스트: 작업장 옆의 G45-B4G 쓰러뜨리기",
		["the {object:645164} poster"] = "{object:645164} 벽보",
		["{area:977} is on the coast north-east of {area:976}: wait on the pier for the goblin boat to {area:16727}."] = "{area:977}은(는) {area:976} 북동쪽 해안에 있습니다. 부두에서 {area:16727}행 고블린 배를 기다리세요.",
		["{item:268505}, the southern ship"] = "{item:268505}, 남쪽 배",
		["{item:268521}, on the Young Paletusks"] = "어린 창백엄니에게 {item:268521} 사용",
		["{item:268632} as you go"] = "이동하며 {item:268632} 모으기",
		["{item:269257}, from {npc:260973}"] = "{npc:260973}에게서 얻는 {item:269257}",
		["{item:271629}, from the Peasant Woodpiles"] = "농부 장작더미에서 얻는 {item:271629}",
		["{item:271629}: fletch it into Makeshift Stickin' Spears"] = "{item:271629}: 급조한 찌르기 창으로 만드세요",
		["{item:769}, from the Mature Paletusks"] = "다 자란 창백엄니에게서 얻는 {item:769}",
		["{npc:255829}, on the hill"] = "언덕 위의 {npc:255829}",
		["{npc:255897}: {quest:95296}, for {npc:260405} at {area:977} in the {zone:1444} & {zone:1446} guide"] = "{npc:255897}: {quest:95296}, {zone:1444} & {zone:1446} 가이드의 {area:977}에 있는 {npc:260405}에게",
		["{npc:255906} is an elite gnoll (level 40) who roams the south-western camps of the {area:16737}: grouping up is advised."] = "{npc:255906}은(는) {area:16737}의 남서쪽 야영지를 돌아다니는 정예 놀(40레벨)입니다. 파티를 권장합니다.",
		["{npc:255993}, in the middle of the fort"] = "요새 중앙의 {npc:255993}",
		["{npc:256418}: Aggro'gosh's report from {object:3202}, if you carry it"] = "{npc:256418}: {object:3202}에서 받은 아그로고쉬의 보고서(가지고 있다면)",
		["{npc:256655}, by the cook fire"] = "화톳불 옆의 {npc:256655}",
		["{npc:256710} stands beside {npc:256418} in the middle of {area:16743}: now that the Farholde camp has had its lesson, he has work in {area:16723}."] = "{npc:256710}은(는) {area:16743} 한가운데 {npc:256418} 옆에 있습니다. 파홀드 야영지가 본때를 맛봤으니, 이제 {area:16723}에서 할 일을 줍니다.",
		["{npc:256728}'s camp"] = "{npc:256728}의 야영지",
		["{npc:256881} is an elite (level 46) in the fortress at the head of the valley, with the Enforcers around him: grouping up is advised."] = "{npc:256881}은(는) 골짜기 끝 요새에 있는 정예(46레벨)이며 주위에 집행자들이 있습니다. 파티를 권장합니다.",
		["{npc:257001} is an elite (level 42) on the south shore: grouping up is advised."] = "{npc:257001}은(는) 남쪽 해안의 정예(42레벨)입니다. 파티를 권장합니다.",
		["{npc:258031}'s elites"] = "{npc:258031}의 정예",
		["{npc:259158} wants out of {area:16723}: lead him west to his treasure at the edge of town and keep the cultists off him."] = "{npc:259158}은(는) {area:16723}을(를) 빠져나가고 싶어 합니다: 서쪽 마을 끝의 보물까지 데려가며 교단원을 막아 주십시오.",
		["{npc:259961} on the north pier takes Lozgil's {item:277974}."] = "북쪽 부두의 {npc:259961}에게 로즈길의 {item:277974}을(를) 전달하세요.",
		["{npc:260211} is an elite (level 42) at the Alliance scouts' camp in the hills south-east of {npc:256728}, where you go next: grouping up is advised. The poster hangs in the middle of the fort; {npc:258031} takes the eye, later in this guide."] = "{npc:260211}은(는) 다음 목적지인 {npc:256728} 남동쪽 언덕의 얼라이언스 정찰병 야영지에 있는 정예(42레벨)입니다. 파티를 권장합니다. 현상 수배 전단은 요새 한가운데 걸려 있으며, 눈은 이 가이드 후반에 {npc:258031}에게 제출합니다.",
		["{npc:260993}, a {area:16726} ogre, hides in the cave west of {npc:258570}'s camp."] = "{area:16726} 오우거인 {npc:260993}은(는) {npc:258570}의 야영지 서쪽 동굴에 숨어 있습니다.",
		["{npc:261208}, a few steps west"] = "{npc:261208}, 조금 서쪽",
		["{npc:263190}: {quest:95033}, for {npc:8115} at {area:1099} in the {zone:1444} guide"] = "{npc:263190}: {quest:95033}, {zone:1444} 가이드에서 {area:1099}의 {npc:8115}에게",
		["{npc:263315}, an elite lion (level 41), prowls the plains south of {area:16743}, where the lions are: grouping up is advised."] = "정예 사자 {npc:263315}(41레벨)이(가) 사자들이 있는 {area:16743} 남쪽 평원을 배회합니다. 파티를 권장합니다.",
		["{npc:263367}'s workshop"] = "{npc:263367}의 작업장",
		["{npc:263380} is an elite (level 42) who hunts along the river south-west of {area:16743}, by the Farholde camp you go to next: grouping up is advised. The poster hangs in the middle of the fort."] = "{npc:263380}은(는) 다음에 갈 파홀드 야영지 옆, {area:16743} 남서쪽 강을 따라 사냥하는 정예(42레벨)입니다. 파티를 권장합니다. 벽보는 요새 한가운데에 걸려 있습니다.",
		["{quest:93976}: for {npc:255897} in {area:16727}, keep it"] = "{quest:93976}: {area:16727}의 {npc:255897}에게 가져갈 것이니 보관하세요",
		["{quest:94669}: the Ring's bouts, one-on-one fights with elites (41-45); a deposit first"] = "{quest:94669}: 투기장 시합, 정예와의 1대1 대결(41-45). 먼저 보증금 필요",
		["{quest:94670}: Buzzbeak"] = "{quest:94670}: 윙윙부리",
		["{quest:94727}: for {npc:260931} in {area:16723}"] = "{quest:94727}: {area:16723}의 {npc:260931}용",
		["{quest:94744}: for {npc:258570}, west of {area:16723}"] = "{quest:94744}: {area:16723} 서쪽의 {npc:258570}에게",
		["{quest:95062}: for {npc:256418} in {area:16743}"] = "{quest:95062}: {area:16743}의 {npc:256418}에게",
		["{quest:95261}: the beasts' entrails come as you go; the mushrooms grow on the ridge west of the pirates"] = "{quest:95261}: 야수 내장은 진행하면서 모이고, 버섯은 해적 서쪽 능선에서 자람",
		["{quest:95267}: a big beast in the shallows south-west of the port, near {npc:257001}, the elite"] = "{quest:95267}: 항구 남서쪽 얕은 물, 정예 {npc:257001} 근처의 큰 야수",
		["{quest:95293}: for {npc:260390} at the pirates' camp"] = "{quest:95293}: 해적 야영지의 {npc:260390}에게",
		["{quest:95418}: for {npc:256710} in {area:16743}"] = "{quest:95418}: {area:16743}의 {npc:256710}용",
		["{quest:95420}: for {npc:255829} in {area:16726}"] = "{quest:95420}: {area:16726}의 {npc:255829}용",
		["{quest:95428}: for {npc:256418} in {area:16743}, later in this guide"] = "{quest:95428}: 이 가이드 후반에 {area:16743}의 {npc:256418}에게 제출",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "{area:75}을(를) 지나 동쪽으로 돌아가세요. 아탈라이 유물은 {quest:1424}의 물속과 기슭에 있습니다.",
		["Back west to {object:3202}."] = "서쪽의 {object:3202}(으)로 돌아가세요.",
		["Below ground"] = "지하",
		["Coming from the {zone:2548}: {area:340}'s flight master stands at the foot of the fortress."] = "{zone:2548}에서 오는 경우: {area:340}의 비행 조련사는 요새 아래에 서 있습니다.",
		["Flown in: {area:976}'s quests first, by the flight master, then the {area:2240} is a short ride north over the {zone:1446} border."] = "비행으로 도착: 먼저 비행 조련사 옆에서 {area:976}의 퀘스트를 처리하십시오. 그다음 {area:2240}은(는) 북쪽으로 {zone:1446} 경계를 넘어 조금만 가면 됩니다.",
		["Fly to {area:1638}"] = "{area:1638}(으)로 날아가기",
		["Fly to {area:484}"] = "{area:484}(으)로 날아가기",
		["Fly to {area:75}"] = "{area:75}(으)로 날아가기",
		["Fly to {area:976}"] = "{area:976}(으)로 비행",
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["For your {area:978} run, in the next guide: {quest:2864} wants scarab shells, and {npc:7804}, a short walk from the flight master, {quest:3042} from the Sandfury trolls."] = "{area:978} 공략용(다음 가이드): {quest:2864}은(는) 풍뎅이 껍질을, 비행 조련사에게서 조금 떨어진 {npc:7804}은(는) 성난모래부족 트롤의 {quest:3042}을(를) 원합니다.",
		["Grimtotem camp"] = "그림토템부족 야영지",
		["Ironjaw Basilisks"] = "무쇠턱 바실리스크",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "코도: {area:222}의 {npc:3690} 옆의 {npc:3685}",
		["Murlocs of the Misty Reed"] = "안개갈대 멀록",
		["Pirate ghosts and Zanzil's camps"] = "해적 유령과 잔질의 야영지",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "랩터: {area:367}의 {npc:7953} 옆의 졸니르",
		["Ride east to the Skullsplitter ruins east of the Venture Co. mine. The headhunters, berserkers and hunters roam the ruins.\n{npc:1059} (45) carries the Broken Armor for {quest:586}: he walks the south-western ruins with two guards and sometimes stands in a small cave there. Pull the guards first.\nCareful: {npc:1060}, an elite troll (level 44), stands in the southern ruins around 47.7,44.3: pull the headhunters and berserkers away from him."] = "동쪽으로 가서 투자개발회사 광산 동쪽의 해골망치부족 폐허로 가세요. 머리사냥꾼, 광전사, 사냥꾼이 폐허를 돌아다닙니다.\n{npc:1059}(45)이(가) {quest:586}에 필요한 부서진 갑옷을 지니고 있습니다. 경비병 둘과 함께 남서쪽 폐허를 돌아다니며, 가끔 그곳의 작은 동굴에 서 있습니다. 경비병부터 끌어내세요.\n주의: 정예 트롤 {npc:1060}(44레벨)이(가) 남쪽 폐허 47.7,44.3 부근에 서 있습니다. 머리사냥꾼과 광전사를 그에게서 떨어진 곳으로 끌어내세요.",
		["Ride north-east to the goblin harbour on the coast."] = "북동쪽 해안의 고블린 항구로 가세요.",
		["Ride south along the road towards {area:35}; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "길을 따라 남쪽 {area:35} 방향으로 가세요. 바실리스크는 정글 한가운데 길 동쪽 바위 위에서 햇볕을 쬐고 있습니다. 파편을 자주 떨어뜨립니다.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "길을 따라 서쪽으로 가세요. 두루마리는 늪 맨 서쪽의 물가에 있습니다.",
		["Ride west from the hive to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb.\nCareful: the Mage-Lords (45-46) and the Shamans cast from range and the ruins are packed: pull one at a time from the edge."] = "벌집에서 서쪽으로 {area:1105} 아래의 오우거 폐허로 가세요. 주술사, 흑마법사, 싸움꾼이 가득하며, 남쪽 끝의 대마법사가 구슬을 지니고 있습니다.\n주의: 대마법사(45-46)와 주술사는 원거리에서 주문을 쓰고 폐허는 빽빽하니, 가장자리에서 하나씩 끌어오세요.",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "탈것 타기와 돌풍타조: 제프라스 섬 {area:16638}의 {area:17684}에 있는 {npc:265756}",
		["Riding at 40"] = "40레벨 탈것 타기",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:3690} in {area:222}, with {npc:3685}'s kodos (20 gold each) beside him. Ride back up to {zone:1456}'s flight master afterwards."] = "탈것 타기는 40레벨이 필요하고 100골드가 듭니다. 배우면 탈것을 하나 받습니다. 각 종족은 자기 종족의 상급자에게서 배웁니다. 당신의 상급자는 {area:222}의 {npc:3690}이며, 그 옆에서 {npc:3685}이(가) 코도(각 20골드)를 팝니다. 그 뒤에 {zone:1456}의 비행 조련사에게 다시 올라가세요.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel. Skyborne learn it from {npc:265756} at the {area:17684} in {area:16638} on Zephras Isle, with a Galestrider: the skyboat to the isle leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "탈것 타기는 40레벨이 필요하고 100골드가 듭니다. 배우면 탈것을 하나 받습니다. {npc:4752}은(는) {object:172958}의 {npc:3362} 우리 옆에서 오크에게 가르칩니다. 스카이본은 제프라스 섬 {area:16638}의 {area:17684}에 있는 {npc:265756}에게서 돌풍타조와 함께 배웁니다. 섬으로 가는 하늘배는 {zone:1456} 북쪽, {area:17045} 남쪽 절벽에서 약 5분마다 출발합니다. 종족의 다른 탈것은 각각 20골드입니다: 수집품, 탈것 · 40레벨에 각각의 가이드가 있습니다.",
		["Rogue Vale screechers"] = "도적의 골짜기 날카로운비명",
		["Sawtooth crocolisks"] = "톱니악어",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns.\nCareful: {npc:222286} (level 43, elite) stands in the camp: pull the raiders and shamans away from her."] = "그림토템부족 타우렌은 화살요정용의 숲 옆에 야영하고 있습니다. 침략자, 식물학자, 주술사 모두 뿔을 지니고 있습니다.\n주의: 야영지에 {npc:222286}(43레벨 정예)이(가) 있습니다. 침략자와 주술사를 그녀에게서 떼어 끌어오세요.",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "늪지멀록은 주둔지 남쪽 해변에 삽니다. 먹물쟁이는 주둔지 동쪽 해안을 따라 있고, 청소부는 더 서쪽, 서쪽 해안의 오두막 주변에 있습니다.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane.\nCareful: Every Woodpaw gnoll except the Alpha runs off for help at 15% health, which can pull more gnolls into the fight."] = "덩굴발일족 놀은 모자케 야영지 바로 북서쪽 언덕에 야영하고 있습니다. 누구나 갈기를 떨어뜨릴 수 있습니다.\n주의: 우두머리를 제외한 모든 덩굴발일족 놀은 생명력이 15%가 되면 도움을 청하러 달아나 놀을 더 끌어올 수 있습니다.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber.\nCareful: {quest:7731} is level 47: clear the hive around him and pull him alone at full health."] = "주크애쉬 벌집은 야영지 남동쪽 언덕 속으로 파고들어 있습니다. {quest:7731}은(는) 가장 깊은 방에서 기다립니다.\n주의: {quest:7731}은(는) 47레벨입니다. 주변 벌집을 정리하고 생명력이 가득 찬 상태에서 혼자 끌어오세요.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "전투 지도는 모자케 야영지 남쪽의 덩굴발일족 야영지에 있습니다.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.\nCareful: Most Alphas sit in small tent camps with 2-4 other gnolls that join the fight, and other gnolls patrol between the camps."] = "화살요정용은 모자케 야영지 바로 서쪽 숲 위를 날아다닙니다. 거의 모두 날개를 떨어뜨립니다. 덩굴발일족 우두머리는 그 남서쪽 야영지를 이끌고 있습니다. 한 시간 안에 처치하세요.\n주의: 우두머리 대부분은 작은 천막 야영지에 다른 놀 2-4마리와 함께 있어 함께 싸우며, 다른 놀이 야영지 사이를 순찰합니다.",
		["The {area:43}"] = "{area:43}",
		["To {area:75}"] = "{area:75}(으)로",
		["Underwater"] = "물속",
		["Upstairs"] = "위층",
		["West into Mistvale: {npc:1449} sits among the gorillas. Any gorilla can drop a fang: hand him ten and stay by him, he calls three waves of gorillas, then {npc:1514}.\nCareful: three waves of gorillas come one after another with little rest between, then {npc:1514}. Start at full health and mana, and stay near Unbagwa. Some classes find it hard alone: a friend makes it easy."] = "서쪽 안개골짜기로 가세요. {npc:1449}이(가) 고릴라들 사이에 앉아 있습니다. 모든 고릴라가 송곳니를 떨어뜨릴 수 있습니다. 열 개를 건네고 곁에 있으면 고릴라 세 무리를 불러낸 뒤 {npc:1514}을(를) 부릅니다.\n주의: 고릴라 세 무리가 쉴 틈 없이 연달아 나온 뒤 {npc:1514}이(가) 나옵니다. 생명력과 마나를 가득 채우고 시작하고, 운바그와 가까이 있으세요. 일부 직업은 혼자 하기 어렵습니다. 동료가 있으면 쉽습니다.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "늑대: {npc:4752} 옆의 {npc:3362}",
		["Woodpaw battle map"] = "덩굴발일족 전투 지도",
		["Woodpaw north camp"] = "덩굴발일족 북쪽 야영지",
		["Your trainer is in {zone:1456}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins)."] = "직업 상급자는 {zone:1456}에 있습니다: {area:1639}의 {npc:3033}(드루이드), {npc:246344}(성기사).",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["Zul'Mamwe"] = "줄맘웨",
		["for {area:35}, around level 51 (40-50/06)"] = "51레벨쯤 {area:35}에서 (40-50/06)",
		["for {zone:1454}, after {zone:2652}"] = "{zone:2652} 이후 {zone:1454}에서",
		["the {object:2076}"] = "{object:2076}",
		["the {object:2076}: {quest:586}"] = "{object:2076}: {quest:586}",
		["{area:340} flight master"] = "{area:340} 비행 조련사",
		["{area:392} for the Felsteed"] = "지옥마를 위해 {area:392}(으)로",
		["{area:976} flight master"] = "{area:976} 비행 조련사",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976}은(는) {zone:1446} 경계를 막 지나서 있는 담장 두른 고블린 마을입니다.",
		["{npc:2519}: the basilisks bask beside the road south, on the ride to {area:35}"] = "{npc:2519}: 바실리스크는 {area:35}(으)로 가는 남쪽 길가에서 햇볕을 쬐고 있습니다",
		["{npc:260405}, on the pier: Friz's errand from the {zone:2548}, if you carry it"] = "부두의 {npc:260405}: {zone:2548}에서 받은 프리즈의 심부름이 있다면",
		["{npc:2934}, on the way back to Zinge"] = "징에에게 돌아가는 길의 {npc:2934}",
		["{npc:3690}, riding trainer"] = "탈것 타기 상급자 {npc:3690}",
		["{npc:4706}, beside {npc:4630}"] = "{npc:4630} 옆의 {npc:4706}",
		["{npc:4752}, riding trainer"] = "탈것 타기 상급자 {npc:4752}",
		["{npc:773}, upstairs: for {quest:2864} in {area:976}, later in this guide"] = "위층의 {npc:773}: 이 가이드 후반 {area:976}의 {quest:2864}용",
		["{npc:7825}, the {object:36126}"] = "{object:36126}의 {npc:7825}",
		["{npc:7953}, riding trainer"] = "{npc:7953}, 탈것 상급자",
		["{npc:8115}: {npc:263190}'s errand from the {zone:2548}, if you carry it"] = "{npc:8115}: {zone:2548}에서 받은 {npc:263190}의 심부름이 있다면",
		["{quest:2863}: one hour from now"] = "{quest:2863}: 지금부터 한 시간",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
		["{zone:2652} is next, a ride north from {area:1099} into {zone:1443}: keep your {zone:1454} hand-ins (Neeru, Zilzibin, {npc:4485}, {npc:7311}) for the flight there after it."] = "다음은 {zone:2652}입니다. {area:1099}에서 북쪽으로 {zone:1443}까지 가면 됩니다. {zone:1454} 제출 퀘스트(니루, 질지빈, {npc:4485}, {npc:7311})는 그 뒤 그곳으로 비행할 때를 위해 남겨 두세요.",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Below ground"] = "지하",
		["Fly to {area:1099}"] = "{area:1099}(으)로 날아가기",
		["From the flight master: the {object:172960}, then the Drag, then the {object:172958}."] = "비행 조련사에서: {object:172960}, 그다음 골목길, 그다음 {object:172958}.",
		["Level 45.37"] = "45.37레벨",
		["Onyxia's eggs"] = "오닉시아의 알",
		["Ride back north to Brackenwall."] = "북쪽의 담쟁이 마을로 돌아가세요.",
		["Stays on the main route"] = "주요 경로에 머무름",
		["Takes you to level 47"] = "47레벨까지 진행",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "오닉시아의 알은 {area:511} 남동쪽의 용 동굴에 있으며, 맹독전사가 지키고 있습니다. 다섯 개를 깨부수세요.",
		["Then on to {zone:1446}"] = "이어서 {zone:1446}(으)로",
		["the {object:2555}"] = "{object:2555}",
		["{area:1099} flight master"] = "{area:1099}의 비행 조련사",
		["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon instead."] = "담쟁이 마을로 돌아가서 하는 {npc:4500}의 도전에는 3인 파티가 필요합니다. 혼자라면 북쪽으로 돌아가기 전에 이곳 {area:511} 북쪽 가장자리의 화염갈기혈족 정찰병을 사냥해 45.37레벨까지 올리세요. 그러면 다시 내려올 필요가 없습니다. 파티가 있다면 대신 {area:978} 던전을 도세요.",
		["{npc:6986}, the Drag"] = "골목길의 {npc:6986}",
		["{npc:7010}, the Drag"] = "{npc:7010}, 골목길",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Below ground"] = "지하",
		["Below ground: the plans, on the {area:1443}'s upper ledge"] = "지하: {area:1443} 위쪽 바위턱의 설계도",
		["Dark Iron Lookouts"] = "검은무쇠단 망꾼",
		["Fly to {area:976}"] = "{area:976}(으)로 날아가기",
		["For your {area:978} run, after {area:979}: {npc:7407}, by the water tower, wants his {quest:2768} back; {quest:2864} his scarab shells and Trenton Lighthammer Troll Temper, if you have not taken those yet."] = "{area:978} 공략용({area:979} 다음): 급수탑 옆의 {npc:7407}은(는) 자신의 {quest:2768}을(를) 돌려받기를 원합니다. 아직 받지 않았다면 {quest:2864}은(는) 풍뎅이 껍질을, 트렌턴 라이트해머는 Troll Temper를 원합니다.",
		["Heavy War Golems patrol the Cauldron below {npc:8479} and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it.\nThe Searing Lava Spiders roam the plateaus and lava pools in the south-west of the gorge.\n{area:1443} opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee. The biggest Incendosaurs and Lava Spiders are 49: pull them one at a time."] = "육중한 전투골렘은 {npc:8479} 아래 용광로를 순찰하며 기름을 떨어뜨리고, 그 사이를 떠도는 용암 정령과 이글거리는 정령은 심장을 떨어뜨립니다. 검은무쇠단 감독관과 노예상인이 길에서 노예를 부립니다. 노예상인이 {item:11818}을(를) 떨어뜨릴 수 있으니 보관하세요.\n거대한 용암거미는 협곡 남서쪽의 고원과 용암 웅덩이를 돌아다닙니다.\n{area:1443}은(는) 용광로 북쪽에 있습니다. 인센도사우루스가 용암 웅덩이에서 헤엄치니 가장자리로 끌어내세요. 비밀 설계도는 구덩이 위쪽 바위턱에 있습니다.\n주의: 검은무쇠단 노예상인(45-46레벨)은 공격받으면 15미터 내 동료를 부르고, 15미터 거리에서 그물을 던지며, 근접전에서 찢어발기기를 씁니다. 가장 큰 인센도사우루스와 용암거미는 49레벨이니 하나씩 끌어오세요.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "그의 다음 요청에는 정예 이교도가 지닌 {item:10552}이(가) 필요합니다. 받지 마세요.",
		["Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts {quest:654}, a two-hour timer, so use it on the way back north from Scrimshank's hive."] = "빌지위즐이 준 4711-FTZ형 동력원은 버리지 말고 보관하세요. 2시간 제한이 있는 {quest:654} 퀘스트를 시작하므로, 스크림섕크의 벌집에서 북쪽으로 돌아오는 길에 사용하세요.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to {area:977}; its reward waits with Oglethorpe in {area:35}.\nCareful: The escort has two ambushes. Three level 47 scorpids attack near the start. Near the end, by the beach, three Wastewander humans attack: one mage and two assassins, around level 44."] = "조난 탐지기가 있을 때만: OOX-17/TN은 스크림섕크의 벌집 남동쪽에 있습니다. 북쪽 {area:977}까지 호위하세요. 보상은 {area:35}의 오글소프에게서 받습니다.\n주의: 호위 중 두 번 매복이 있습니다. 시작 근처에서 47레벨 전갈 셋이 공격합니다. 끝 무렵 해변 근처에서는 사막유랑단 인간 셋(마법사 하나와 암살자 둘, 44레벨 정도)이 공격합니다.",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "{item:11818}이(가) 있을 때만: 동쪽 발굴지의 {object:173265}(으)로 돌아가세요.",
		["Ride back north to {area:1446}, just past {npc:8479}."] = "{npc:8479}을(를) 막 지나 북쪽의 {area:1446}(으)로 돌아가세요.",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "북서쪽으로 협곡을 가로지르세요. {area:1446}은(는) 북서쪽의 비계를 두른 야영지입니다.",
		["Ride south from {area:1446} into the Cauldron: the Dark Iron Taskmasters and Slavers drive the slaves on the paths, and the Heavy War Golems patrol the floor below {npc:8479}. Careful: the biggest golems are 49: pull them one at a time."] = "{area:1446}에서 남쪽으로 용광로에 들어가세요. 검은무쇠단 감독관과 노예상인이 길에서 노예를 부리고, 육중한 전투골렘이 {npc:8479} 아래 바닥을 순찰합니다. 주의: 가장 큰 골렘은 49레벨이니 하나씩 끌어오세요.",
		["Scrimshank's gear"] = "스크림섕크의 장비",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "검은무쇠단 망꾼은 용광로 남쪽 감시탑 주변 능선에 서 있습니다. 열 명 중 한 명 정도가 {item:18960}을(를) 지니고 있습니다.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "검은무쇠단 증기기술자는 용광로 한가운데의 화로에서 일합니다. 절반은 {item:10551}을(를), 열 명 중 한 명은 {item:18959}을(를) 지니고 있습니다. 노예, 노예상인, 감독관도 단검을 지니고 있습니다.",
		["The Steamsmiths' furnaces"] = "증기기술자의 용광로",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "{object:179827} 게시판",
		["The {quest:2768}: {npc:7407}, by the water tower."] = "{quest:2768}: 급수탑 옆의 {npc:7407}.",
		["The {quest:3042}: {npc:7804}, a short walk from the flight master."] = "{quest:3042}: 비행 조련사에게서 조금 떨어진 {npc:7804}.",
		["Use the {item:8524}"] = "{item:8524} 사용하기",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "길을 따라 서쪽으로, 남쪽 방향으로 가세요. {npc:7771}은(는) {area:1938}의 폐허 옆에 야영하고 있습니다. 그의 {item:9978}을(를) 착용하면 이곳과 {area:983} 주변에 묻힌 장식품이 보입니다.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "가젯잔 서쪽, 트롤 야영지의 물웅덩이 옆에서 {item:8584}을(를) 사용하세요.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you. The Sandreavers are 49-50: take the Workers and Tunnelers."] = "서쪽에서는 센티파르 곤충이 벌집 주변에 몰려 있습니다. 어느 것이든 부품을 떨어뜨립니다.\n주의: 우두머리 센티파르는 전투 중이든 아니든 {npc:4196}을(를) 시전해 작은 쫄을 불러내며, 이들이 시전을 방해합니다. 모래약탈자는 49-50레벨이니 일꾼과 굴착꾼을 잡으세요.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "경로의 이전 방문 때 이것을 놓쳤습니다. 지금 이것부터 합니다. 금방 끝나며 뒤에 이어지는 퀘스트를 열어 줍니다.",
		["Your {area:978} scarab shells: {npc:7876}, beside the wind rider master."] = "{area:978}의 풍뎅이 껍질: 와이번 조련사 옆의 {npc:7876}.",
		["for {npc:7010} in {zone:1454}, around level 50"] = "50레벨쯤 {zone:1454}의 {npc:7010}에게",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526}은(는) 48레벨쯤 {zone:1425}에서 자랍니다",
		["the {object:173265}"] = "{object:173265}",
		["{area:1099} flight master"] = "{area:1099}의 비행 조련사",
		["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the troll camp's water hole.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978}은(는) 5인 파티용 던전이며, 이곳의 퀘스트는 45~47레벨입니다. 입구는 트롤 야영지의 물웅덩이에서 북쪽으로 약 400야드 떨어져 있습니다.\n내부: 풍뎅이가 껍질을 떨어뜨리고, 모든 성난모래부족 트롤이 {quest:3042}을(를) 떨어뜨릴 수 있으며, {npc:7604}이(가) {quest:2768}을(를) 가지고 있습니다.",
		["{item:11818}, a rare drop"] = "드물게 떨어지는 {item:11818}",
		["{item:8623}, a rare drop"] = "드물게 떨어지는 {item:8623}",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955}은(는) 골짜기에서 기다립니다. 사막을 가로질러 북동쪽 {area:977}에 있는 그의 아내 {npc:6015}에게까지 데려가세요. 가까이 붙어 그의 속도에 맞추고, 그를 공격하는 적을 물리치세요. 그에게서 멀리 떨어진 채 탈것에 오르거나 귀환석을 쓰지 마세요. {npc:8579}도 항구에 있습니다.",
		["{npc:5955}'s escort"] = "{npc:5955} 호위",
		["{npc:7876}, beside the wind rider master"] = "윈드라이더 조련사 옆의 {npc:7876}",
		["{npc:8479} stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "{npc:8479}은(는) {area:1446} 남쪽, 용광로 가장자리에 홀로 서 있습니다. 그의 이야기를 들으세요.",
		["{quest:2768}: {npc:7604}, inside"] = "{quest:2768}: {npc:7604}, 내부",
		["{quest:2865}: the Scarabs, inside"] = "{quest:2865}: 풍뎅이, 내부",
		["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042}: 성난모래부족 트롤, 내부",
		["{quest:3161} ornaments"] = "{quest:3161} 장신구",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "서쪽의 {area:350}(으)로 돌아가세요. 순찰대와 명사수는 산장 근처에, 정찰대와 길잡이는 그 남쪽 비탈에 있습니다.",
		["East of the village, the violet flower grows in the hills."] = "마을 동쪽 언덕에 보라색 꽃이 자랍니다.",
		["Fly to {area:272}"] = "{area:272}(으)로 날아가기",
		["Fly to {area:75}"] = "{area:75}(으)로 날아가기",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "길을 따라 동쪽으로 {zone:1425}을(를) 가로질러 동쪽 해안의 트롤 마을로 가세요.",
		["Highvale"] = "깊은골짜기",
		["His next request, going on to the {area:355}, is for a group."] = "그의 다음 요청인 {area:355} 진입은 파티용입니다.",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. The trolls inside are elite: stay with your group and keep to the paths."] = "사냥꾼 마코르의 해골은 썩은가지부족 폐허 아래 더미에, 뼈는 {area:354} 기슭의 더미에 있습니다. 오염된 피가 담긴 용기는 아래쪽 계단식 단에 있고, {npc:14757}은(는) 꼭대기에 갇혀 있습니다. 안쪽의 트롤은 정예입니다. 파티와 함께 다니며 길에서 벗어나지 마세요.",
		["No flight path to {area:75} yet: the arrow takes the quickest way there (by the {object:3202} flight and the road through {zone:1431} and {zone:1430}). Learn {area:75}'s flight path when you arrive."] = "아직 {area:75} 비행 경로가 없다면: 화살표가 가장 빠른 길로 안내합니다({object:3202} 비행편과 {zone:1431}, {zone:1430}을(를) 지나는 길). 도착하면 {area:75}의 비행 경로를 익히십시오.",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "해안을 따라 북쪽으로 가면 작은 섬에 {npc:14731}의 소풍 바구니가 있습니다. {npc:14748}이(가) 지키고 있습니다.",
		["OOX-09/HL"] = "OOX-09/HL",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "서쪽 끝까지 가서 와일드해머 마을 {area:348}에 들어가 중앙 우물 옆에 전갈을 놓으세요. 마을에는 얼라이언스 경비병이 가득합니다. 들어가서 놓고 바로 나오세요.",
		["Ride back north to the bloodmages."] = "북쪽의 피의 마법사에게 돌아가세요.",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "{area:272}에서 북동쪽 {zone:1425}로 들어가 길을 따라 동쪽으로 가세요. {npc:7801}은(는) 엘프의 {area:350} 남쪽 언덕에 야영하고 있습니다.",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "{area:75}에서 서쪽으로 나가 협곡을 지나 남쪽 {zone:1419}(으)로 가세요. 피의 마법사 둘은 들어가자마자 길가에 서 있습니다.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "산장 남쪽에서 마른나무껍질부족 트롤이 마을을 차지하고 있습니다. 모두 해골을 지니고 있습니다. 스무 개를 모아 {item:15002}을(를) 사용해 님보야의 무거운 창을 만든 뒤 마을 안에 꽂으세요.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "다시 남서쪽으로 가면 추방자가 {area:353} 폐허 옆에 숨어 있습니다.",
		["South-west of the lake, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "호수 남서쪽, 중앙 언덕 남쪽의 트롤 사원인 {area:355}을(를) 썩은가지부족 예언자가 차지하고 있습니다. 퀴아가와 {npc:8636}(정예, 50)은(는) 꼭대기에 있습니다. 아래 계단의 예언자를 상대하세요.\n남서쪽에서는 은빛갈기 울음늑대가 마른나무껍질 마을 동쪽 언덕을 돌아다닙니다.",
		["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way.\nCareful: Groups of about three elves ambush the escort, usually twice."] = "깊은골짜기 엘프는 {area:350} 주변에 야영하고 있습니다. 그들의 야영지에서 보고서, 쪽지, 기록을 불태우세요. {npc:7780}은(는) 산장 안에 갇혀 있습니다. 밖으로 데리고 나오며 도중의 매복을 물리치세요.\n주의: 엘프 셋 정도가 무리 지어 호위를 습격하며, 대개 두 번입니다.",
		["The big turtles crawl along the beaches north of the village, and {npc:2491}'s bottles of port lie on the same beaches, from the village up to the {area:307}: pick them up as you go. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it.\nCareful: the biggest Saltwater Snapjaws are 50: pull them one at a time."] = "큰 거북은 마을 북쪽 해변을 기어다니며, {npc:2491}의 포트와인 병도 같은 해변, 마을에서 {area:307}까지 있습니다. 지나가며 주우세요. 무쇠턱바다거북이 드물게 OOX-09/HL 조난 탐지기를 떨어뜨릴 수 있습니다. 보관하세요.\n주의: 가장 큰 무쇠턱바다거북은 50레벨이니 하나씩 끌어오세요.",
		["The bloodmages"] = "피의 마법사",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "{item:8684} 상자는 {area:351}의 버려진 호드 야영지 주변, 수액괴물 사이에 있습니다.",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills.\nEast of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south.\nCareful: Scorpok Stingers (50-51) use {spell:5416}; {npc:8301} adds Knockdown. Pull the Stingers one at a time."] = "퀘스트 다섯 개가 같은 재료를 요구합니다. 한 번에 모두 모으세요. 길 서쪽 언덕에는 {npc:5982}, 굶주린 칼송곳니하이에나, 스콜포크 독침전갈, 죽음의 눈 바실리스크가 함께 있습니다.\n길 동쪽에서는 잿빛갈기 멧돼지와 잿빛갈기 꿀꿀이가 붉은돌 바실리스크 옆 비탈에서 땅을 파헤칩니다. 더 남쪽의 52레벨 지옥멧돼지는 피하세요.\n주의: 스콜포크 독침전갈(50-51)은 {spell:5416}을(를) 사용하고, {npc:8301}은(는) 넘어뜨리기도 사용합니다. 독침전갈은 하나씩 끌어오세요.",
		["The secret lies on the {area:307}, above the beach."] = "비밀은 해변 위쪽 {area:307}에 있습니다.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "후속 퀘스트는 강화 아이템을 위해 같은 재료를 다시 요구하며 경험치를 주지 않습니다. 받지 마세요.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "이들은 정예 몹입니다. 파티를 권장하니 함께할 사람을 찾아보세요. {npc:7977}은(는) 48레벨 정예입니다. 50레벨이면 대부분의 직업이 혼자 처치할 수 있지만 도움이 필요할 수도 있습니다. 혼자라면 건너뛰세요. 경로에서 경험치를 사냥으로 다시 채웁니다.\n{npc:7977}은(는) {area:307} 아래 해안을 걸어 다니며, 화살표에서 남쪽으로 약 75,66, 북쪽으로 약 82,52까지 이동합니다. 화살표 위치에 없다면 해안을 따라가세요.",
		["To {area:75}"] = "{area:75}(으)로",
		["Underwater"] = "물속",
		["for {npc:6986} in {zone:1454}, around level 50"] = "50레벨쯤 {zone:1454}의 {npc:6986}에게",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "50레벨쯤 {zone:1458}의 {npc:7825}에게",
		["{area:1446} flight master"] = "{area:1446}의 비행 조련사",
		["{area:348} well"] = "{area:348} 우물",
		["{item:8704}, a rare drop"] = "드물게 떨어지는 {item:8704}",
		["{npc:14731}'s lunch"] = "{npc:14731}의 점심",
		["{npc:14757}, at the top of {area:354}"] = "{area:354} 꼭대기의 {npc:14757}",
		["{npc:7801}'s camp"] = "{npc:7801}의 야영지",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor: Stoley's shipment from {zone:1446}"] = "꼭대기 층의 \"바다늑대\" 매킨리: {zone:1446}에서 온 스톨리의 화물",
		["Back to {area:1099}"] = "{area:1099}(으)로 돌아가기",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "제단의 {npc:11548}에게 돌아가세요. {area:3137} 경비병의 서쪽으로 다니세요.",
		["Back to {object:3202}"] = "{object:3202}(으)로 돌아가기",
		["Below ground"] = "지하",
		["Fly to {area:1099}"] = "{area:1099}(으)로 날아가기",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Fly to {area:1638}"] = "{area:1638}(으)로 날아가기",
		["Fly to {area:35}"] = "{area:35}(으)로 날아가기",
		["Fly to {area:976}"] = "{area:976}(으)로 날아가기",
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["Fly to {zone:1456}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and Magatha are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "{zone:1456}(으)로 날아가세요. {area:1099}(으)로 가는 길목입니다. 아직 비행 경로가 없다면 {area:378}(으)로 날아가 {zone:1412}을(를) 지나 서쪽으로 가세요. 하뮬과 마가사는 {area:1639}에 있습니다. 드루이드와 성기사는 여기서 기술을 배웁니다({npc:3033}, {npc:246344}).",
		["Follow the road north to {area:1237}, the Horde camp."] = "길을 따라 북쪽의 호드 야영지 {area:1237}(으)로 가세요.",
		["Frayfeather Hippogryphs"] = "공작날개 히포그리프",
		["Hippogryph nests"] = "히포그리프 둥지",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "{quest:3444}은(는) 보관하세요. {npc:7771}의 상자는 나중에 다시 와서 엽니다.",
		["Northspring harpies"] = "바람계곡일족 하피",
		["On the way through {zone:1454} to the flight master, step into the Drag: {npc:7010} takes the insect report from {zone:1446}."] = "{zone:1454}을(를) 지나 비행 조련사로 가는 길에 골목길에 들르세요. {npc:7010}이(가) {zone:1446}의 곤충 보고서를 받습니다.",
		["Pestlezugg's samples come from {zone:1449}."] = "페슬저그의 표본은 {zone:1449}에서 구합니다.",
		["Rage Scar yetis"] = "분노한 무쇠설인",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "토막나무 주둔지에서 길을 따라 동쪽으로 가세요. {npc:11548}은(는) 길에서 조금 벗어난 {area:1235}, 얼라이언스의 {area:3137} 바로 서쪽에서 기다립니다. 서쪽에서 접근하고 아즈샤라 파수꾼과 자로데누스(정예)를 피하세요.",
		["Ride into {zone:1447}"] = "{zone:1447}(으)로 이동",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "길을 따라 남쪽 {area:1938}(으)로 가세요. {npc:7771}이(가) 그 옆에 있습니다. 여기서 서쪽 길을 따라 내려가면 다음 가이드가 시작되는 {zone:1449}입니다.",
		["Sprite Darters"] = "화살요정용",
		["The Bloodsail ships"] = "붉은해적단 배",
		["The Droffers' shop is a few steps further into the Drag."] = "드로퍼 가게는 골목길로 몇 걸음 더 들어간 곳에 있습니다.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "명가 유령은 제단 바로 북쪽의 폐허를 떠돌고, 할다르 사티로스는 조금 더 북쪽에 진을 치고 있습니다.",
		["The Northspring harpies nest on the ridges in the far north-west, past the giants' hills. The Windcallers heal, so kill them first and pull one at a time."] = "북녘골 하피는 거인 언덕 너머 북서쪽 끝 능선에 둥지를 틉니다. 바람소환사는 치유를 하니 먼저 처치하고, 하나씩 끌어오세요.",
		["The flight from {area:75} lands on {area:35}'s upper deck. {npc:7406} has his workshop on the upper ring of the bay."] = "{area:75}에서 출발한 비행은 {area:35}의 위층 갑판에 내립니다. {npc:7406}의 작업장은 항구 위층 둘레에 있습니다.",
		["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "히포그리프 둥지는 남쪽 언덕, {area:2522} 주변에 있습니다. 둥지마다 {object:142071}에 넣을 알이 하나씩 있습니다.",
		["The {object:142071}, in the middle of town"] = "마을 한가운데의 {object:142071}",
		["Wandering Forest Walkers"] = "떠도는 나무정령",
		["Zeppelin to {zone:1454}"] = "비행선 타고 {zone:1454}(으)로",
		["{area:1099} flight master"] = "{area:1099}의 비행 조련사",
		["{item:18904}, on the Wave and Deep Striders in the water"] = "{item:18904}, 물속의 파도 거인과 성큼걸이 바다거인에게 사용",
		["{item:18958}, from the Sea Sprays"] = "{item:18958}, 바다 물보라 정령에게서",
		["{npc:5769}, on the {area:1639}"] = "{npc:5769}, {area:1639}",
		["{npc:6746}, at the inn: for Hamuul"] = "여관의 {npc:6746}: 하뮬에게",
		["{npc:6986}, the Drag"] = "골목길의 {npc:6986}",
		["{npc:7010}, the Drag"] = "{npc:7010}, 골목길",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}: 곰은 {zone:1448}에 있음",
		["{npc:7876}, beside the wind rider master"] = "와이번 조련사 옆의 {npc:7876}",
		["{npc:8659}, the {object:172960}"] = "{object:172960}의 {npc:8659}",
		["{quest:3761} is gathered in the next guide."] = "{quest:3761}은(는) 다음 가이드에서 모읍니다.",
		["{quest:7738}, a rare drop"] = "드물게 떨어지는 {quest:7738}",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back a few steps west to Felstone Farm, the first farm along the road; {npc:10778} waits in the house."] = "서쪽으로 몇 걸음 돌아가 길가의 첫 번째 농장인 펠스톤 농장으로 가세요. {npc:10778}은(는) 집 안에서 기다립니다.",
		["Back north-east to {area:251}."] = "북동쪽 {area:251}(으)로 돌아가세요.",
		["Below ground"] = "지하",
		["Bridge into {area:254}"] = "{area:254}(으)로 가는 다리",
		["Careful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd. The Hive Guards (54) and the Queen stand inside the hive: work the Workers and Wasps outside it."] = "주의: 일꾼 고리쉬는 생명력이 45% 아래로 떨어지면 50% 확률로 25미터 내 동료를 부릅니다. 벌집 경비병(54)과 여왕은 벌집 안에 있으니 밖의 일꾼과 말벌을 잡으세요.",
		["Careful: There are many ravasaurs roaming the area, so you can easily pull several at the same time."] = "주의: 이 지역에는 라바사우루스가 많이 돌아다녀 한 번에 여러 마리가 끌려오기 쉽습니다.",
		["Cross the south of the crater to the pylon on the western cliffs."] = "분화구 남쪽을 가로질러 서쪽 절벽의 수정탑으로 가세요.",
		["Eastern Pylon"] = "동쪽 수정탑",
		["Escort {npc:9999}"] = "{npc:9999} 호위",
		["Fly to {area:1637} and train before the boat to {area:16727}: the {zone:1458} stop later in this guide has no Hunter or Shaman trainer."] = "{area:16727}행 배를 타기 전에 {area:1637}(으)로 날아가 기술을 배우세요. 이 가이드 후반의 {zone:1458}에는 사냥꾼과 주술사 상급자가 없습니다.",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "절벽을 따라 남쪽, 불자루 오우거의 언덕인 {quest:3821}(으)로 가세요. {npc:9136}의 유해는 언덕 기슭에 있습니다.",
		["From here on pick up every {npc:271301} (blue, green, red, yellow) and every {quest:3761} pile you pass: 20 for Hamuul, and 5 more for Pestlezugg if you carry {quest:4496}."] = "지금부터 지나가는 {npc:271301}(파랑, 초록, 빨강, 노랑)과 {quest:3761} 더미를 모두 챙기세요. 하뮬에게 20개, {quest:4496}을(를) 가지고 있다면 페슬저그에게 5개 더 필요합니다.",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner. Careful: the Scarlets around the tents reach 54 and the Invokers cast: come in from the side nearest the command tent and leave the others be."] = "{area:152}에서 길을 따라 동쪽으로 {zone:1422}(으)로 가세요. 붉은십자군의 천막은 펠스톤 농장을 막 지나 {area:199}와(과) {area:200} 사이에 있습니다. {object:176092}(으)로 지휘 천막을 불태우고 스컬지 깃발을 꽂으세요. 주의: 천막 주변 붉은십자군은 54레벨까지 있고 기원사는 주문을 시전합니다. 지휘 천막에 가장 가까운 쪽으로 접근하고 나머지는 건드리지 마세요.",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "{area:1938}에서 서쪽으로 가 {zone:1449}(으)로 구불구불 내려가는 긴 비탈길을 타고, 분화구 북쪽 벽을 따라 절벽 동굴 속 야영지인 {area:541}(으)로 가세요. 이곳 주민은 모두 중립입니다.",
		["Gorillas"] = "고릴라",
		["Into the {zone:1427}"] = "{zone:1427}(으)로",
		["Into {zone:1449}"] = "{zone:1449}(으)로",
		["Keep the parcel: {npc:10781} is in the {zone:1458}. The next guide starts with {npc:10739} by the {area:202}, south-east of here."] = "꾸러미는 보관하세요. {npc:10781}은(는) {zone:1458}에 있습니다. 다음 가이드는 이곳 남동쪽 {area:202} 옆의 {npc:10739}에게서 시작합니다.",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "{npc:10267}의 편지는 보관하세요. {quest:4808}은(는) {zone:1452}의 {area:2255}에 있습니다.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "{npc:9118}의 {quest:4147}과(와) {npc:8737}의 편지는 이후 가이드를 위해 보관하세요.",
		["Lar'korwi Mates"] = "라르코르위의 짝",
		["Lashers and Threshers"] = "채찍줄기와 덩이줄기",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "{zone:1458}을(를) 나와 길을 따라 동쪽으로 {zone:1420}을(를) 지나 경계의 포세이큰 요새인 {area:152}로 가세요.",
		["Listen to {npc:8479}'s story once more."] = "{npc:8479}의 이야기를 한 번 더 들으십시오.",
		["North of Torwa, a dead Threshadon lies by the water. The {item:280417} lies on the ground a short ride west of {npc:9619}'s camp."] = "토르와 북쪽 물가에 죽은 쓰레샤돈이 있습니다. {item:280417}은(는) {npc:9619}의 야영지에서 서쪽으로 조금 간 땅 위에 있습니다.",
		["Northern Pylon"] = "북쪽 수정탑",
		["Only from level 53: her next errand is {quest:3822} (54), who walks the caves of {quest:3821} among ogres of 50-53."] = "53레벨부터만: 다음 의뢰는 {quest:3822}(54)입니다. 그는 50-53 오우거들 사이에서 {quest:3821}의 동굴을 돌아다닙니다.",
		["Out of the refuge"] = "야영지 밖으로",
		["Power Crystals and soil"] = "마력의 수정과 흙",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "분화구 동쪽을 따라 내려가 동쪽 절벽의 수정탑으로 가세요.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "동쪽을 따라 북쪽으로 가세요. 채찍줄기 붉은꽃잎덩굴손과 덩이줄기 붉은꽃잎덩굴손이 정글에 가득합니다.",
		["Ride south-west to {area:537}, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot.\nSouth of the hot springs, Dinosaur Bones lie on the ground among the Stegodons and drop from the Diemetradons nearby, which also carry the scales {npc:9998} wants. Careful: the Stegodons are elites (52-53): pick the bones up around them, don't pull them; the Elder Diemetradons are 53-55, take the smaller ones. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon.\nRide south-west along the western cliffs. Bloodpetal Trappers grow in the jungle there. Careful: the biggest Trappers are 53: pull them one at a time."] = "남서쪽으로 분화구 한가운데의 화산인 {area:537}(으)로 가세요. 그 기슭에 칼날가시 붉은꽃잎덩굴손이 자랍니다.\n온천 남쪽에서는 공룡 뼈가 스테고돈 사이 땅에 놓여 있고 근처 디메트로돈도 떨어뜨립니다. 디메트로돈은 {npc:9998}이(가) 원하는 비늘도 지니고 있습니다. 주의: 스테고돈은 정예(52-53)이니 끌지 말고 주변의 뼈만 주우세요. 덩치큰 디메트로돈은 53-55이니 작은 것을 잡으세요. 라바사우루스는 남서쪽에서 무리 지어 사냥합니다. 발톱은 {npc:8659}에게 가져가며, 가끔 구겨진 일지를 지닌 개체가 있습니다(희귀 획득물: 얻었을 때만 퀘스트를 받으세요). 레벨 57 스테고돈인 그러프는 피하세요.\n서쪽 절벽을 따라 남서쪽으로 가세요. 그곳 밀림에 질긴뿌리 붉은꽃잎덩굴손이 자랍니다. 주의: 가장 큰 것은 53레벨이니 하나씩 끌어오세요.",
		["Scarlet forward camp"] = "붉은십자군 전진 야영지",
		["Sentry Braziers"] = "감시용 화로",
		["Stegodons and ravasaurs"] = "스테고돈과 라바사우루스",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5405}: Scourgestones only drop while you wear it."] = "{quest:5096}을(를) 위해 델링턴 옆 상자에서 {object:176092}을(를) 챙기세요. 돌아오는 길에 완료합니다. {quest:5405}을(를) 착용하세요. 착용 중에만 스컬지석이 나옵니다.",
		["The Anvilrage dwarves of your {area:1584} run: {npc:9077}, in {area:340}."] = "{area:1584} 공략의 성난모루 드워프: {area:340}의 {npc:9077}.",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "라르코르위의 짝은 {npc:9619} 북서쪽 정글을 배회합니다.",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "수정 무더기는 분화구 곳곳에 있으며 {area:537} 주변에 많습니다. 수정탑용으로 색깔별로 몇 개씩 더 챙기세요.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "원정대의 상자는 동쪽 정글의 버려진 야영지에 있습니다.",
		["The expedition's lost equipment lies in the south-west jungle."] = "원정대의 잃어버린 장비는 남서쪽 정글에 있습니다.",
		["The gorillas live on the north-east plateau: {npc:9619} wants two pelts of each kind, and the Thunderers (52-53) are the biggest. Stay out of the deepest cave: {npc:9622} lives there."] = "고릴라는 북동쪽 고원에 삽니다. {npc:9619}은(는) 종류별로 가죽 2개씩을 원하며, 천둥고릴라(52-53)가 가장 셉니다. 가장 깊은 동굴에는 들어가지 마세요. {npc:9622}이(가) 삽니다.",
		["The hearth lands in {area:976}: {npc:11758} takes the {area:983} and Tran'rek Thistleshrub Valley, both done on the way into the crater."] = "귀환석을 쓰면 {area:976}에 도착합니다. {npc:11758}에게 {area:983}와(과) 트랜렉 엉겅퀴덤불 골짜기 퀘스트를 받으세요. 둘 다 분화구로 가는 길에 완료합니다.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "산을 나오면 55-57 오크로 가득한 {area:252} 옆입니다. 북쪽 절벽을 따라 동쪽 길로 {area:251}의 호드 야영지로 가세요.",
		["The pylon stands on the slope east of the refuge."] = "수정탑은 야영지 동쪽 비탈에 있습니다.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "뗏목은 남동쪽 호숫가에 있고, 작은 배낭은 그 옆 물속에 있습니다.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}. Careful: the Lurkers reach 54 and the Tar Lords stand among them: take the Tar Beasts (50-51) and Creepers (51-52)."] = "타르 구덩이는 피난처 바로 남쪽에 있습니다. 송진괴물, 송진껍질괴물, 송진이끼괴물이 {item:11834}을(를) 떨어뜨립니다. 주의: 송진껍질괴물은 54레벨까지 있고 우두머리 송진괴물도 섞여 있습니다. 송진괴물(50-51)과 송진이끼괴물(51-52)을 잡으세요.",
		["The {npc:9167} fly over the western cliffs around the pylon. Careful: the biggest are 54: pull them one at a time."] = "{npc:9167}은(는) 수정탑 주변 서쪽 절벽 위를 날아다닙니다. 주의: 가장 큰 것은 54레벨이니 한 마리씩 끌어오세요.",
		["Underwater"] = "물속",
		["Upstairs"] = "위층",
		["Use the Mangled Journal to start it"] = "구겨진 일지를 사용해 시작하세요",
		["Use the scale to start {quest:87494}, for {npc:9619}"] = "비늘을 사용해 {npc:9619}의 {quest:87494} 시작",
		["Western Pylon"] = "서쪽 수정탑",
		["the wooden sign beside {npc:9997}, by the flight master: the {npc:9167} (51-54) come on the pylon loop"] = "비행 조련사 옆, {npc:9997} 옆의 나무 표지판: {npc:9167}(51-54)는 수정탑 순회 때 처치",
		["{area:1584} is a dungeon for a group of five from about level 48, the biggest in the mountain: its Anvilrage dwarves are this quest's, and you need not go further in than they are. Its portal is deep inside the mountain, down the chain walkways from the bridge.\nInside: the Anvilrage Guardsmen, Wardens and Footmen. Then back out of the portal and on through the mountain's southern exit to the {zone:1428}."] = "{area:1584}은(는) 약 48레벨부터의 5인 파티용 던전으로, 산에서 가장 큰 던전입니다. 성난모루 드워프가 이 퀘스트의 대상이며, 그들이 있는 곳보다 더 깊이 들어갈 필요는 없습니다. 차원문은 산 깊숙한 곳, 다리에서 사슬 통로를 따라 내려간 곳에 있습니다.\n내부: 성난모루 경비병, 교도관, 보병. 그런 다음 차원문으로 나와 산의 남쪽 출구를 지나 {zone:1428}(으)로 가십시오.",
		["{area:340} flight master"] = "{area:340} 비행 조련사",
		["{area:340} is built into the cliffs on the {zone:1418}' west edge."] = "{area:340}은(는) {zone:1418} 서쪽 끝 절벽에 지어져 있습니다.",
		["{item:10575}, from the hoard"] = "{item:10575}, 보물에서",
		["{item:11116}, a rare drop"] = "{item:11116}, 희귀 획득물",
		["{item:280459}, a rare drop from the ravasaurs and Diemetradons"] = "라바사우루스와 디메트로돈의 희귀 획득물인 {item:280459}",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302}이(가) {zone:1452}의 {npc:9298}에게 보냅니다. 보관하세요.",
		["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "고블린 {npc:10302}은(는) 수정탑 바로 동쪽 {area:543}에 있습니다.",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{object:36078}, 박쥐 조련사 옆의 {npc:10879}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825}은(는) {object:36082}에 있습니다.",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "연금술 실험실의 {npc:8390}: 약병은 나중에 {zone:1447}에서 채웁니다",
		["{npc:9117}, at the back of the cave; below ground"] = "동굴 안쪽의 {npc:9117}, 지하",
		["{npc:9166} (50-52) fly over the east of the crater, from the slopes below the refuge southward; their webbed scales are for {npc:9998}, and {npc:9997}'s sign wants ten of them. Leave the {npc:9167} over the west for the pylon loop."] = "{npc:9166}(50-52)는 피난처 아래 비탈에서 남쪽까지, 분화구 동쪽 위를 납니다. 물갈퀴 비늘은 {npc:9998}에게 가져가고, {npc:9997}의 표지판은 10마리를 원합니다. 서쪽의 {npc:9167}는 수정탑 순회 때 잡으세요.",
		["{npc:9167}: kill these as you meet them"] = "{npc:9167}: 보이는 대로 처치하세요",
		["{npc:9618}, just outside"] = "바로 밖의 {npc:9618}",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619}은(는) 분화구 남동쪽 구석에 있습니다.",
		["{npc:9619}'s camp is in the south-east corner, a short ride from the {area:1942}."] = "{npc:9619}의 야영지는 남동쪽 구석에 있으며, {area:1942}에서 가깝습니다.",
		["{npc:9619}: {quest:4289}, the gorillas of the north-east plateau on the pylon loop"] = "{npc:9619}: {quest:4289}, 수정탑 순회 때 북동쪽 고원의 고릴라",
		["{npc:9619}: {quest:87492}, a short ride west of his camp"] = "{npc:9619}: {quest:87492}, 야영지에서 서쪽으로 조금",
		["{npc:9619}: {quest:87494}, if the scale dropped"] = "{npc:9619}: {quest:87494}, 비늘을 얻었다면",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "그다음 {npc:9623}은(는) {skill:202} 아이템인 {item:10561}을(를) 원합니다. 가지고 있지 않으면 건너뛰세요.",
		["{npc:9623}, the robot on the plateau; below ground"] = "고원의 로봇 {npc:9623}, 지하",
		["{npc:9998}, at the entrance"] = "입구의 {npc:9998}",
		["{npc:9998}, at the refuge entrance"] = "야영지 입구의 {npc:9998}",
		["{quest:3453} lies on the ground at {npc:8479}'s feet; {quest:3462} stands beside him."] = "{quest:3453}은(는) {npc:8479}의 발치 땅바닥에 놓여 있고, {quest:3462}은(는) 그 옆에 서 있습니다.",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822}은(는) {quest:3821}의 동굴과 갱도를 돌아다닙니다. 없으면 돌아올 때까지 입구 주변 오우거를 처치하세요.",
		["{quest:4081}: the Anvilrage dwarves, inside"] = "{quest:4081}: 성난모루 드워프, 내부",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill Greta's canteen at the corrupted moonwell in the middle of the southern camp."] = "북쪽의 {area:1763}(으)로 돌아가세요. 남쪽 야영지 한가운데의 오염된 달샘에서 그레타의 수통을 채우세요.",
		["Back north to {npc:8420} with the rune, then south-west along the road."] = "룬을 가지고 북쪽의 {npc:8420}에게 돌아간 뒤, 길을 따라 남서쪽으로 가세요.",
		["Back north-west to {npc:8420}."] = "북서쪽의 {npc:8420}에게 돌아가세요.",
		["Below ground"] = "지하",
		["Class trainer"] = "직업 전문가",
		["Derrington's watchtowers and Vandis' cauldron are done on a later visit: keep them."] = "데링턴의 감시탑과 반디스의 가마솥은 나중에 들를 때 처리합니다. 보관하세요.",
		["Diseased Wolves"] = "역병에 걸린 늑대",
		["Druid trainer"] = "드루이드 상급자",
		["Each of the camp's three officers (53) carries a seal: {npc:247006} in the middle of the camp, {npc:247013} at its eastern end, and {npc:246991}, who walks its western half: take him on the east side of his walk, where the arrow points.\nCareful: the {npc:250023}, a level 55-57 elite, stands at the camp's western edge, close to the far end of Hawkhelm's walk: wait for Hawkhelm to come back east."] = "야영지의 장교 세 명(53)이 각각 인장을 지니고 있습니다. {npc:247006}은(는) 야영지 중앙에, {npc:247013}은(는) 동쪽 끝에 있으며, {npc:246991}은(는) 서쪽 절반을 돌아다닙니다. 화살표가 가리키는 순찰 경로의 동쪽에서 처치하세요.\n주의: 55-57레벨 정예인 {npc:250023}이(가) 야영지 서쪽 가장자리, 호크헬름 순찰 경로의 반대쪽 끝 근처에 서 있습니다. 호크헬름이 다시 동쪽으로 올 때까지 기다리세요.",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "피멍울 초소 동쪽, 혼돈의 불길과 혼돈의 소산물이 돌아다니는 구덩이투성이 골짜기입니다. 각각 두 마리씩 처치한 뒤, 지옥 물 구덩이 세 곳을 모두 걸어서 찾아가세요.",
		["Fly to {area:1237}"] = "{area:1237}(으)로 날아가기",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner. Careful: the Scarlets around the tents reach 54 and the Invokers cast: come in from the side nearest the command tent and leave the others be."] = "{area:152}에서 길을 따라 동쪽으로 {zone:1422}(으)로 가세요. 붉은십자군의 천막은 펠스톤 농장을 막 지나 {area:199}와(과) {area:200} 사이에 있습니다. {object:176092}(으)로 지휘 천막을 불태우고 스컬지 깃발을 꽂으세요. 주의: 천막 주변 붉은십자군은 54레벨까지 있고 기원사는 주문을 시전합니다. 지휘 천막에 가장 가까운 쪽으로 접근하고 나머지는 건드리지 마세요.",
		["He camps by the {area:202}, south-east of {area:200}."] = "그는 {area:200} 남동쪽, {area:202} 옆에 야영하고 있습니다.",
		["Keep {quest:8465} for {zone:1452}."] = "{zone:1452}을(를) 위해 {quest:8465}을(를) 보관하세요.",
		["Makrinni Burrowers"] = "마크리니 굴파기",
		["Northern crater"] = "북쪽 구덩이",
		["On north-east across the middle of {zone:1447}: {npc:235903} camps by the road."] = "{zone:1447} 중앙을 가로질러 북동쪽으로 계속 가세요. {npc:235903}은(는) 길가에 야영하고 있습니다.",
		["Ride back west to {area:1237}."] = "서쪽의 {area:1237}(으)로 돌아가세요.",
		["Ride east to the ruins on the coast. The four tablets lie among the ruins, guarded by Spitelash naga (52-55): pull them one at a time."] = "동쪽 해안의 폐허로 가세요. 석판 네 개가 폐허 곳곳에 있으며, 원한의꼬리일족 나가(52-55)가 지키고 있습니다. 한 번에 한 마리씩 끌어오세요.",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}, just north of the blood elves."] = "블러드 엘프 바로 북쪽, {area:1227} 위 절벽에 있는 고블린 야영지로 북동쪽으로 가세요.",
		["Ride south to the northern edge of the {area:1221}. The Spitelash Sirens and Myrmidons (50-52) there carry {npc:8420}'s rune; it doesn't drop often, so work your way along the edge until it does."] = "남쪽 {area:1221}의 북쪽 가장자리로 가세요. 그곳의 원한의꼬리일족 세이렌과 미르미돈(50-52)이 {npc:8420}의 룬을 지니고 있습니다. 잘 나오지 않으니 나올 때까지 가장자리를 따라 처치하세요.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "남서쪽으로 펠스톤 농장을 지나 길을 따라 서쪽의 {area:152}(으)로 돌아가세요.",
		["Rimtori's camp is at the east end of the base camp. Read the {object:151286} there: on Forever the Sin'dorei Tome beside it then asks for the seals of the camp's three officers."] = "림토리의 야영지는 주둔지 동쪽 끝에 있습니다. 그곳의 {object:151286}을(를) 읽으세요. Forever에서는 그 옆의 신도레이 고서가 야영지 장교 세 명의 인장을 요구합니다.",
		["Scarlet forward camp"] = "붉은십자군 전진 야영지",
		["South-west along the road: {npc:235903} takes the satyrs."] = "길을 따라 남서쪽으로: {npc:235903}에게 사티로스를 제출하세요.",
		["Southern crater"] = "남쪽 구덩이",
		["Southern {area:1763}"] = "{area:1763} 남부",
		["The Horde camp just north of {area:1763}."] = "{area:1763} 바로 북쪽의 호드 야영지입니다.",
		["The Legashi satyrs"] = "레가시 사티로스",
		["The Makrinni Burrowers (50-51) dig in the sands just east of the ruins, on the way north-east; they and the buried caches there give up the Highborne Treasure Fragments."] = "마크리니 굴파기(50-51)는 폐허 바로 동쪽, 북동쪽으로 가는 길의 모래밭을 파고 있습니다. 이들과 그곳에 묻힌 은닉물에서 명가 보물 조각을 얻습니다.",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}. {npc:8420}'s four pieces of equipment lie in the crates around the camp; the Blood Elf Arcanists carry {npc:247473}'s wand.\nCareful: a {npc:250023}, a level 55-57 elite, stands at the west edge of the camp: work the blood elves from its east side."] = "블러드 엘프는 북동쪽 {area:1227} 옆 절벽에 야영하고 있습니다. {npc:8420}의 장비 네 개는 야영지 주변 상자에 있고, 블러드 엘프 비전술사가 {npc:247473}의 마법봉을 지니고 있습니다.\n주의: 야영지 서쪽 끝에 55-57레벨 정예인 {npc:250023}이(가) 서 있습니다. 블러드 엘프는 야영지 동쪽부터 처치하세요.",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "일기는 농가 안에, 장식장은 그 안에, 변소는 그 뒤에 있습니다. {npc:10816}이(가) 변소 열쇠를 지니고 있습니다. 변소를 열면 {npc:10836}이(가) 나오며, 그가 장식장 열쇠를 지니고 있습니다.",
		["The druids' camp is just past the border."] = "드루이드 야영지는 경계를 막 지나서 있습니다.",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "길은 맨 북동쪽 {area:1769} 터널 밖의 {npc:15395}에서 끝납니다.",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east. Careful: the biggest are 54: pull them one at a time."] = "늑대는 안돌할, {area:200}, {area:202} 사이의 들판을 돌아다닙니다. 동쪽으로 돌아가는 길에 마저 처치하세요. 주의: 가장 큰 것은 54레벨이니 한 마리씩 끌어오세요.",
		["The {area:1763} moonwell"] = "{area:1763} 달샘",
		["The {object:661778} stands just south of the vale, by the road north: its bauble starts a quest for {npc:9996} at {area:1997}."] = "{object:661778}은(는) 골짜기 바로 남쪽, 북쪽으로 가는 길가에 있습니다. 석상의 장신구로 {area:1997}의 {npc:9996}에게 가는 퀘스트가 시작됩니다.",
		["Upstairs"] = "위층",
		["Western crater"] = "서쪽 구덩이",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.\nTake a {object:176092} from the crate next to Derrington for {quest:5096}."] = "경로의 이전 방문 때 이것을 놓쳤습니다. 지금 이것부터 합니다. 금방 끝나며 뒤에 이어지는 퀘스트를 열어 줍니다.\n{quest:5096}을(를) 위해 델링턴 옆 상자에서 {object:176092}을(를) 챙기세요.",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["{area:200} farmhouse"] = "{area:200} 농가",
		["{item:246680}, from the Blood Elf Arcanists"] = "블러드 엘프 비전술사에게서 얻는 {item:246680}",
		["{item:246721}, from {npc:246991}"] = "{npc:246991}에게서 얻는 {item:246721}",
		["{item:246722}, from {npc:247013}"] = "{npc:247013}에게서 얻는 {item:246722}",
		["{item:246725}, from {npc:247006}"] = "{npc:247006}에게서 얻는 {item:246725}",
		["{item:277958}, from the Angerclaw bears"] = "성난발톱 곰에게서 {item:277958}",
		["{item:277959}, from the Felpaw wolves"] = "악령발 늑대에게서 {item:277959}",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: 올빼미야수는 {zone:1452}에 있습니다",
		["{npc:10920}, beside {npc:10921}: {quest:86577}, the organs of {zone:1448}'s bears and wolves"] = "{npc:10921} 옆의 {npc:10920}: {quest:86577}, {zone:1448}의 곰과 늑대 장기",
		["{npc:11554}, at the south edge of the camp"] = "야영지 남쪽 가장자리의 {npc:11554}",
		["{npc:235903}: {quest:86746}, the satyrs north of the blood elves' camp"] = "{npc:235903}: {quest:86746}, 블러드 엘프 야영지 북쪽의 사티로스",
		["{npc:247473}: {quest:91569}, a wand from the blood elves' arcanists"] = "{npc:247473}: {quest:91569}, 블러드 엘프 비전술사의 마법봉",
		["{npc:3326}, the {object:172960}"] = "{object:172960}의 {npc:3326}",
		["{npc:8576}: {quest:91531}, for {npc:4485} in {zone:1454}"] = "{npc:8576}: {quest:91531}, {zone:1454}의 {npc:4485}에게",
		["{npc:8578}'s camp"] = "{npc:8578}의 야영지",
		["{npc:8587}: the tome goes to {npc:3326} in {zone:1454}"] = "{npc:8587}: 고서는 {zone:1454}의 {npc:3326}에게 갑니다",
		["{npc:8659} takes the ravasaur claws from Un'Goro; he stands in the {object:172960}, a short walk from the middle of the city."] = "{npc:8659}이(가) 운고로의 랩터사우루스 발톱을 받습니다. 그는 도시 중앙에서 조금 걸어가면 나오는 {object:172960}에 있습니다.",
		["{npc:8659}, the {object:172960}"] = "{object:172960}의 {npc:8659}",
		["{npc:9529}, on the west side of the camp"] = "야영지 서쪽의 {npc:9529}",
		["{quest:91538}: for {npc:8587} in {area:1237}"] = "{quest:91538}: {area:1237}의 {npc:8587}에게",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Back south to {npc:7775}. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by {area:976} later."] = "남쪽의 {npc:7775}에게 돌아가세요. 비약은 보관하고 아직 마시지 마세요. 마시면 죽는데, 나중에 {area:976} 근처에서 가에리얀을 만나는 방법이 바로 그것입니다.",
		["Chillwind chimaeras"] = "서리바람 키메라",
		["Fly to {area:1099}"] = "{area:1099}(으)로 날아가기",
		["Fly to {area:1638}"] = "{area:1638}(으)로 날아가기",
		["Gregor's quests lead to other zones: keep them."] = "그레고르의 퀘스트는 다른 지역으로 이어집니다. 보관하세요.",
		["Ice Thistle yetis"] = "얼음엉겅퀴설인",
		["Linken's letter"] = "링쿠의 편지",
		["Raging Owlbeasts"] = "흉포한 올빼미야수",
		["Ride south from the tunnel: {npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "터널에서 남쪽으로 가세요. {npc:9298}은(는) 골짜기 서쪽, {area:2246}의 김이 오르는 웅덩이 사이에 야영하고 있습니다.",
		["The Jadefire moonwell"] = "비취불꽃 달샘",
		["The Matriarchs and Patriarchs that carry Umi's horns are 56-58: leave them for that later stop."] = "우미의 뿔을 지닌 맹렬한 설인과 덩치큰 설인은 56-58레벨입니다. 나중 방문 때까지 남겨 두세요.",
		["The {item:11242} grows inside a ruined building north of {npc:7775}'s camp, east of the harpies' {area:1114}: climb in through the broken part of its wall."] = "{item:11242}은(는) 하피의 {area:1114} 동쪽, {npc:7775} 야영지 북쪽의 무너진 건물 안에서 자랍니다. 벽의 부서진 곳으로 들어가세요.",
		["{area:2255} is the goblin town on the east side of the valley, past the owlbeast hills."] = "{area:2255}은(는) 골짜기 동쪽, 올빼미야수 언덕 너머의 고블린 마을입니다.",
		["{area:2408} flight master"] = "{area:2408} 비행 조련사",
		["{item:11243}, {npc:7775}'s reward"] = "{item:11243}, {npc:7775}의 보상",
		["{item:12565}, at the Jadefire moonwell"] = "비취불꽃 달샘에서 {item:12565}",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556}은(는) {area:1769} 터널의 {zone:1452} 쪽 출구, 나오는 바로 그 자리에 서 있습니다.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}의 {npc:3033}, {npc:246344}",
		["{npc:9529}, on the west side of the Sanctuary"] = "성소 서쪽의 {npc:9529}",
		["{npc:9996}'s kitten"] = "{npc:9996}의 새끼 고양이",
		["{npc:9996}: the {quest:86612}"] = "{npc:9996}: {quest:86612}",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123}은(는) {zone:1450}에서 기다립니다. 나중을 위해 보관하세요.",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084}은(는) 나중에 {zone:1448}에 갈 때 {object:176091}에서 완료합니다.",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "눈사태일족 털보숭이가 드물게 떨어뜨리는 {quest:8471}",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
		["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "정화된 물은 {zone:1448}의 {area:2479}(으)로 갑니다. 나중을 위해 보관하세요.",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Fly to {area:392}"] = "{area:392}(으)로 날아가기",
		["In the {object:172958}."] = "{object:172958}에 있습니다.",
		["Lady Sylvanas holds the {object:36126}."] = "실바나스 여왕은 {object:36126}에 있습니다.",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "리브의 작업장은 {area:392} 부두 북쪽 끝에 있으며, {object:149036}은(는) 그 안에 있습니다.",
		["Upstairs"] = "위층",
		["Zeppelin to {zone:1458}"] = "{zone:1458}행 비행선",
		["{npc:11615}: the termites are in {area:2627}, on the next guide"] = "{npc:11615}: 흰개미는 다음 가이드의 {area:2627}에 있습니다",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{object:172957}의 {npc:15188}: {zone:1451}을(를) 위해 보관하세요",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901}은(는) {area:392} 바로 북쪽 해안에 야영하고 있습니다.",
		["{npc:6522} stands in the {object:36073}."] = "{npc:6522}은(는) {object:36073}에 서 있습니다.",
		["{npc:7010} works in the Drag."] = "{npc:7010}은(는) 시장 거리에 있습니다.",
		["{npc:8393}, beside him"] = "그 옆의 {npc:8393}",
		["{npc:8403}, nearby"] = "근처의 {npc:8403}",
		["{npc:8659}, the {object:172960}"] = "{object:172960}의 {npc:8659}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050}은(는) {zone:1422}의 {npc:10778}에게 돌아갑니다. 보관하세요.",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["A {item:13140} dropped: the Jaedenar Enforcers, Darkweavers, Warlocks and Legionnaires of Shadow Hold carry one now and then. Use it to start the quest, then free {npc:11018} from her cage in the cave's south end on your way out."] = "{item:13140}이(가) 나왔습니다. 그림자 요새의 자에데나르 집행자, 암흑술사, 흑마법사, 군단병이 가끔 지니고 있습니다. 사용해서 퀘스트를 시작한 뒤, 나가는 길에 동굴 남쪽 끝 우리에서 {npc:11018}을(를) 풀어 주세요.",
		["Andorhal watchtowers and silos"] = "안돌할 감시탑과 저장고",
		["Back south to the Sanctuary, a short ride."] = "남쪽 성소로 돌아가세요. 금방입니다.",
		["Back to {area:2268}"] = "{area:2268}(으)로 돌아가기",
		["Below ground"] = "지하",
		["Both quests lead to {zone:1451}: keep them."] = "두 퀘스트 모두 {zone:1451}(으)로 이어집니다. 보관하세요.",
		["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "주의: {npc:10411}은(는) 전투 중이 아닐 때 투명해지며, 전투가 시작되면 바위날개 가고일을 부릅니다. 3마리만 존재하며 15분마다 다시 나타납니다.",
		["Class trainer"] = "직업 전문가",
		["Diseased Grizzlies"] = "오염된 불곰",
		["Fly to {area:1638}"] = "{area:1638}(으)로 날아가기",
		["Fly to {area:2268}"] = "{area:2268}(으)로 날아가기",
		["Fly to {area:272}"] = "{area:272}(으)로 날아가기",
		["Follow the road east from the {zone:1422}, over the river and across the whole {zone:1423}, to the {object:92525}'s chapel in the far east."] = "{zone:1422}에서 길을 따라 동쪽으로 가서 강을 건너고 {zone:1423} 전체를 가로질러, 동쪽 끝에 있는 {object:92525}의 예배당으로 가세요.",
		["Free Darrowshire Spirits: talk to them"] = "대로우샤이어 영혼 해방: 말 걸기",
		["From the tunnel's {zone:1452} exit, ride south to {area:2246}."] = "터널의 {zone:1452} 출구에서 남쪽 {area:2246}(으)로 가십시오.",
		["Keep {quest:5152}: {npc:10927} lives at {area:197} in the {zone:1422}."] = "{quest:5152}은(는) 보관하세요. {npc:10927}은(는) {zone:1422}의 {area:197}에 살고 있습니다.",
		["Mark {npc:10902} with the {item:12815}"] = "{item:12815}(으)로 {npc:10902} 표시",
		["Mark {npc:10903} with the {item:12815}"] = "{item:12815}(으)로 {npc:10903} 표시",
		["Mark {npc:10904} with the {item:12815}"] = "{item:12815}(으)로 {npc:10904} 표시",
		["Mark {npc:10905} with the {item:12815}"] = "{item:12815}(으)로 {npc:10905} 표시",
		["Moontouched Owlbeasts"] = "달빛 깃든 올빼미야수",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "새끼 역병사냥개와 역병박쥐는 {area:2260} 북쪽 언덕을 돌아다니고, 청소부구더기가 그 사이를 기어다닙니다. 북쪽 {area:2627} 방향으로 나아가세요.",
		["Plaguehounds and their runts roam the shores of the lake south-west of the chapel; Plaguebats and Carrion Grubs share the ground. Careful: the biggest Plaguehounds are 56, pull them one at a time.\nThe shattered sword lies on the ground north-west of the lake."] = "역병사냥개와 그 새끼들은 예배당 남서쪽 호숫가를 돌아다니며, 역병박쥐와 청소부구더기도 같은 곳에 있습니다. 주의: 가장 높은 역병사냥개는 56레벨이니 한 번에 한 마리씩 끌어오세요.\n부러진 검은 호수 북서쪽 땅에 있습니다.",
		["Pristine Yeti Horns"] = "온전한 설인 뿔",
		["Ride back south to {area:272} and fly to {area:2268}."] = "남쪽의 {area:272}(으)로 돌아가 {area:2268}(으)로 날아가세요.",
		["Ride east along the road into the {zone:1423}. {npc:1855} lives in a small house by the {area:2619}, just north of the road at the border; his three hunts are on this guide's ground."] = "길을 따라 동쪽의 {zone:1423}(으)로 가세요. {npc:1855}은(는) 경계의 길 바로 북쪽, {area:2619} 옆의 작은 집에 삽니다. 그의 사냥 퀘스트 세 개는 이 가이드의 지역에서 진행됩니다.",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Careful: they are 57-58: pull them one at a time.\nCareful: Hailspite, level 60 elites, gather in the snowfields south-east of {area:2255}, where a few Moontouched Owlbeasts roam too: stay on the slopes north of town."] = "동쪽의 {area:2255}(으)로 가서 북쪽으로 나가세요. 달빛 깃든 올빼미야수는 {area:2241} 남쪽 비탈의 언덕을 돌아다닙니다. 주의: 57-58레벨이니 한 번에 한 마리씩 끌어오세요.\n주의: 60레벨 정예인 헤일스파이트가 {area:2255} 남동쪽 설원에 모여 있고, 그곳에도 달빛 깃든 올빼미야수 몇 마리가 돌아다닙니다. 마을 북쪽 비탈에 머무르세요.",
		["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "{area:272}에서 길을 따라 북쪽으로 가세요. {npc:10927}의 집은 {area:197}의 길가에 있으며, {npc:10936}의 기념비는 그 뒤 묘지에 있습니다.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "북서쪽의 안도할로 가세요. {npc:10667}은(는) 마을 서쪽의 폐허가 된 여관에서 기다립니다. 안의 해골들은 54-57레벨이니 가장자리로 다니세요.",
		["Ride south to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "길을 따라 남쪽의 {area:2264}(으)로 가세요. {item:15447}은(는) 10분 안에 상합니다. 마을의 스컬지를 빨리 처치하고, 일곱 조각을 바로 {item:15454}(으)로 빻으세요.\n주의: 보이지 않는 하수인은 생명력이 40%로 떨어지면 25미터 안의 동료에게 도움을 요청합니다. 전투 중이 아닐 때는 {spell:10228}(으)로 투명해지기도 합니다. 마을 안에서 도움 요청이 일어나면 많은 몹이 전투에 합류할 수 있습니다. 마을 외곽에서 싸우면 이 위험이 줄어듭니다.\n퀘스트 목록에 {quest:5211}이(가) 있으면(이 가이드 시작 부분에서 {npc:11063}에게 받음), 마을 주변의 스컬지가 다로우샤이어 영혼을 남깁니다. 각 영혼에게 말을 걸어 해방하세요. {item:15447} 작업을 시작하기 전에 영혼들을 해방하세요.",
		["Scarlet Crusade"] = "붉은십자군",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one.\nCareful: a {npc:10996}, a level 58-59 elite, can stand in Andorhal, as at many other spots of the {zone:1422}: give it room."] = "연대기는 안도할 마을 회관의 곰팡이 슨 고서 사이에 있습니다. 맞는 것을 찾을 때까지 열어 보세요.\n주의: {zone:1422}의 다른 여러 곳처럼 안도할에도 58-59레벨 정예인 {npc:10996}이(가) 있을 수 있습니다. 거리를 두세요.",
		["The book lies in the ruined inn of {area:2627}; the undead in the town are 54-56, so pull them one at a time.\nThe Large Termite Mounds stand all over the hills east of {area:2627}. Use the {item:15042} on each mound you pass.\nCareful: Ziggurat Protectors (58, elite) stand by the ziggurats east and north-east of the town: take the mounds nearer the town and stay clear of them."] = "책은 {area:2627}의 폐허가 된 여관에 있습니다. 마을의 언데드는 54-56레벨이니 한 번에 한 마리씩 끌어오세요.\n큰 흰개미집은 {area:2627} 동쪽 언덕 곳곳에 있습니다. 지나가는 흰개미집마다 {item:15042}을(를) 사용하세요.\n주의: 지구라트 파수병(58레벨, 정예)이 마을 동쪽과 북동쪽 지구라트 옆에 서 있습니다. 마을에 가까운 흰개미집을 이용하고 그들을 피하세요.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "인형의 머리와 양쪽 몸통은 {npc:10926} 주변의 집들에 있습니다. 가방에서 합치세요.",
		["The skull sits in the {area:2622}, among Blighted Horrors and Plague Monstrosities."] = "해골은 {area:2622}의 황폐의 그림자와 역병의 괴수 사이에 있습니다.",
		["The {area:2479}"] = "{area:2479}",
		["To {area:197}"] = "{area:197}(으)로",
		["Umi's horns, carried from your last {area:2255} stop: the yeti hills start just south-east of {area:2255}. Only Matriarchs and Patriarchs drop horns, and the Patriarchs reach 58: pull them one at a time."] = "지난 {area:2255} 방문 때 받은 우미의 뿔 퀘스트: 설인 언덕은 {area:2255} 바로 남동쪽에서 시작됩니다. 우두머리 암컷과 수컷만 뿔을 떨어뜨리며, 수컷은 58레벨까지 있으니 한 번에 한 마리씩 끌어오세요.",
		["Underwater"] = "물속",
		["Upstairs"] = "위층",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "경로의 이전 방문 때 이것을 놓쳤습니다. 지금 이것부터 합니다. 금방 끝나며 뒤에 이어지는 퀘스트를 열어 줍니다.",
		["Zaeldarr lurks just west of {area:2262}."] = "잴다르는 {area:2262} 바로 서쪽에 숨어 있습니다.",
		["a message for {npc:11063} at {area:2268}"] = "{area:2268}의 {npc:11063}에게 전할 전갈",
		["{area:2627}: kill these as you meet them"] = "{area:2627}: 만나는 대로 처치하세요",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "{npc:10926}의 유령은 남서쪽의 {area:2262} 폐허에 서 있습니다.",
		["{npc:10927}, upstairs"] = "{npc:10927}, 위층",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner; {npc:12384} sits inside the hut."] = "유령 {npc:11140}은(는) 북서쪽 구석, {area:2627}의 오두막 옆에 서 있습니다. {npc:12384}은(는) 오두막 안에 앉아 있습니다.",
		["{npc:12384}, inside"] = "{npc:12384}, 안쪽",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}의 {npc:3033}, {npc:246344}",
		["{quest:5086} are in {zone:1448}, on a later trip: keep it."] = "{quest:5086}은(는) 나중에 {zone:1448}에 갈 때 처리합니다. 보관하세요.",
		["{quest:5211}'s spirits come with the {area:2264} stop later in this guide: keep it."] = "{quest:5211}의 영혼은 이 가이드 후반의 {area:2264} 단계에서 함께 처리합니다. 보관하세요.",
		["{quest:5510}: the {area:2627} undead drop them while you wear the {item:12846}"] = "{quest:5510}: {item:12846}을(를) 착용하고 있으면 {area:2627}의 언데드가 떨어뜨립니다",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "마파람 마을로 돌아가 탑에 오르세요. 꼭대기의 벌집을 건드리면 잠복꾼 하이브아쉬가 나옵니다. 그중 하나가 {item:17346}을(를) 지니고 있습니다.",
		["Back to {area:3425}"] = "{area:3425}(으)로 돌아가기",
		["Below ground"] = "지하",
		["Class trainer"] = "직업 전문가",
		["Collect twenty Encrypted Twilight Texts from the cultists here, ten for {npc:15306} and ten for Ortell. Take them from the Twilight Avengers and Geolords; leave the Flamereavers and Stonecallers (59-60)."] = "이곳 이교도에게서 암호화된 황혼의 문서 스무 개를 모으세요. {npc:15306}에게 열 개, 오르텔에게 열 개입니다. 황혼의 복수자와 대지군주에게서 얻고, 화염약탈자와 돌소환사(59-60)는 피하세요.",
		["Dredge Crushers and Pincers"] = "망치미늘벌레와 집게전갈",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "작살미늘벌레, 돌꼬리전갈, 모래그물 바위거미가 요새 바로 북쪽 모래밭에 함께 있습니다.",
		["Drink the {item:11243} at the graveyard just east of {area:976}: it kills you, and only as a ghost can you see {npc:9299}, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard."] = "{area:976} 바로 동쪽 묘지에서 {item:11243}을(를) 마시세요. 마시면 죽으며, 유령 상태에서만 그 정북쪽 언덕의 바위 틈에 있는 {npc:9299}을(를) 볼 수 있습니다. 그곳에서 그에게 말을 건 뒤 시체로 달려가 부활하세요. 그가 알려 주는 눈에 띄는 묘비는 그 묘지에 있습니다.",
		["Escort {npc:9999}"] = "{npc:9999} 호위",
		["Flayers and Rock Stalkers"] = "채찍전갈과 바위거미",
		["Fly to {area:1637}"] = "{area:1637}(으)로 날아가기",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "서쪽 모래언덕을 따라 북쪽으로 가세요. 망치미늘벌레와 돌꼬리집게전갈은 여기서부터 요새 쪽까지 퍼져 있습니다.",
		["Inside: {quest:4493}, if you took it in {zone:1454} on the {zone:1447} guide"] = "안쪽: {zone:1447} 가이드 중 {zone:1454}에서 {quest:4493}을(를) 받았다면",
		["Mar'alith's next errand, Into the Maw of Madness, leads into {area:2744} among elites. Skip it."] = "마랄리스의 다음 심부름인 '광기의 아가리 속으로'는 정예가 있는 {area:2744} 안으로 이어집니다. 건너뛰세요.",
		["Only if you took {quest:4496} in {area:976} on the way here: the Gorishi of the {area:540}, south of {area:537}, drop the Scent Gland, and most of the crater's beasts and plants drop {item:11018}."] = "이곳으로 오는 길에 {area:976}에서 {quest:4496}을(를) 수락한 경우에만: {area:537} 남쪽 {area:540}의 고리시 벌레가 향기샘을 떨어뜨리고, 분화구의 야수와 식물 대부분이 {item:11018}을(를) 떨어뜨립니다.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "동쪽 {area:537}(으)로 가서 올라가 정상 근처 용암 분출구에서 {npc:10541}을(를) 사용한 뒤, 서쪽 {npc:10302}에게 돌아가세요.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "북동쪽의 {area:3077}(으)로 가세요. 그 옆의 고갯길로 {zone:1451}을(를) 떠납니다.",
		["Ride north-east to {area:3447}."] = "북동쪽의 {area:3447}(으)로 가세요.",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "남동쪽으로 운고로 절벽 아래의 {area:3447}(으)로 가세요.",
		["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "남서쪽의 {area:2738} 폐허로 가세요. {npc:11801}을(를) 위한 {object:179565}은(는) 무너진 집 중 한 곳 안에 있습니다.",
		["Ride west to the Horde camp north of {area:2744}."] = "서쪽으로 {area:2744} 북쪽의 호드 야영지로 가세요.",
		["Scare {npc:7583} with {item:12928}"] = "{item:12928}(으)로 {npc:7583} 겁주기",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "남부 사막 곳곳에서 실리시스트 모래기둥이 솟아오릅니다. 모래기둥이 남긴 실리시스트 속으로 걸어 들어가, 키리카의 야영지에 있는 호드의 실리시스트 추출기까지 가져가세요. 싸우거나 탈것에 오르면 떨어뜨립니다.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "돌꼬리채찍전갈과 긴다리 바위거미는 키리카의 야영지 남서쪽 모래언덕을 돌아다닙니다.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "운고로 분화구에서 오는 고갯길은 {zone:1451} 북동쪽의 묘지인 {area:3077}(으)로 이어집니다. {npc:13220}은(는) 무덤 사이에 서 있습니다.",
		["The spare texts from the cultists"] = "이교도에게서 얻은 남는 문서",
		["Twilight Vanguard"] = "황혼의 선봉대",
		["Use {item:12928} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "{area:976}의 고블린 소녀 {npc:7583}에게 {item:12928}을(를) 사용하세요. {npc:10977}와(과) {npc:10978}은(는) 나중에 경로 중 놀래 줍니다.",
		["{area:976} flight master"] = "{area:976} 비행 조련사",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302}이(가) {zone:1452}의 {npc:9298}에게 보냅니다. 보관하세요.",
		["{npc:11803} walks the Vanguard camp in the far south-west. Keep every {item:20404} the cultists drop: {npc:15306} and Ortell want ten each later."] = "{npc:11803}은(는) 맨 남서쪽의 선봉대 야영지를 돌아다닙니다. 이교도가 떨어뜨리는 {item:20404}은(는) 모두 보관하세요. 나중에 {npc:15306}와(과) 오르텔이 각각 열 개씩 원합니다.",
		["{npc:11804} stands in the outpost west of {area:3425}. Keep any Encrypted Twilight Texts that drop here too."] = "{npc:11804}은(는) {area:3425} 서쪽 전초기지에 서 있습니다. 이곳에서 떨어지는 암호화된 황혼의 문서도 보관하세요.",
		["{npc:15200} holds the camp in the west."] = "{npc:15200}은(는) 서쪽 야영지를 차지하고 있습니다.",
		["{npc:15306}, on the west side of the Hold"] = "요새 서쪽의 {npc:15306}",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771}은(는) {area:976} 남쪽, {area:1336}(으)로 가는 길가에 야영하고 있습니다.",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "{npc:9684}의 소굴은 수정탑 바로 남쪽에 있습니다. 그곳에서 {npc:9619}의 미끼를 사용하세요. {npc:9684}은(는) 레벨 56이고 공격이 강하니 생명력을 가득 채우고 시작하세요.",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999}이(가) 길을 잃고 지친 채 마루에 앉아 있습니다.",
		["{quest:3914} goes back to {npc:8737} in Un'Goro: keep it."] = "{quest:3914}은(는) 운고로 분화구의 {npc:8737}에게 돌아갑니다. 보관하세요.",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "다시 나무구렁일족 동굴로 들어가 {zone:1452} 쪽 출구로 나가세요. {npc:9298}은(는) 바로 밖 온천 옆에 있습니다.",
		["Below ground"] = "지하",
		["Class trainer"] = "직업 전문가",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "{area:431}(으)로 날아간 뒤 길을 따라 북서쪽으로 달려 {zone:1440}에서 {zone:1448}(으)로 가세요. {area:2479}은(는) 경계를 막 지난 곳의 드루이드 야영지입니다.",
		["Frostfire Winterfall camp"] = "얼음불꽃 눈사태일족 야영지",
		["Ice Thistle yetis"] = "얼음엉겅퀴설인",
		["In the {object:172961}."] = "{object:172961}에 있습니다.",
		["North of Donova, at the tunnel's {zone:1452} exit."] = "도노바 북쪽, 동굴의 {zone:1452} 출구에 있습니다.",
		["Ride back west along the road to {area:2246}."] = "길을 따라 서쪽 {area:2246}(으)로 돌아가세요.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "길을 따라 북쪽으로 {area:1763}을(를) 지나 {area:1997}(으)로 가세요.",
		["Ride north to {area:2255}."] = "북쪽 {area:2255}(으)로 가세요.",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "나무구렁일족 동굴을 지나 {zone:1450}(으)로 가세요. {npc:11939}은(는) {area:2361}의 한 집에서 책을 읽고 있습니다.",
		["With 30 {quest:6031} in your bags: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "가방에 {quest:6031} 30개가 있다면: 길을 따라 북쪽 {area:1769}(으)로 가세요. {npc:11557}이(가) 입구 바로 안에서 거래합니다.",
		["{npc:11556} takes the beads only once {quest:8464} is handed in: any Winterfall furbolg can carry them, and the camps just south of {npc:11556} are the closest."] = "{npc:11556}은(는) {quest:8464}을(를) 제출한 뒤에야 구슬을 받습니다. 눈사태일족 털보숭이는 누구나 구슬을 지니고 있을 수 있으며, {npc:11556} 바로 남쪽 야영지가 가장 가깝습니다.",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "{npc:11801}의 악령덩굴 조각은 {area:2577}이(가) 필요합니다. 건너뛰세요.",
		["{quest:8464}'s village is north-east of {area:2255}, on this guide's way back from {area:2256}."] = "{quest:8464}의 마을은 {area:2255} 북동쪽, 이 가이드에서 {area:2256}에서 돌아오는 길에 있습니다.",
		["{zone:1454} flight master"] = "{zone:1454} 비행 조련사",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "{npc:3126}은(는) {area:362} 서쪽 평원을 기어다닙니다. 하나를 길들인 뒤 {npc:3171}에게 돌아가세요.",
		["Back east to Sen'jin on the way to the {area:368}."] = "{area:368}(으)로 가는 길에 동쪽 센진 마을로 돌아가세요.",
		["Back to the Den"] = "동굴 막사로 돌아가기",
		["Back to the Den: {npc:3143} takes {quest:804}'s claw and {npc:5887}, just outside, has {quest:1516} now that you are level 4."] = "소굴로 돌아가세요. {npc:3143}에게 {quest:804}의 집게발을 제출하고, 4레벨이 되었으니 바로 밖의 {npc:5887}에게서 {quest:1516}을(를) 받을 수 있습니다.",
		["Below ground"] = "지하",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "불타는 칼날단 이교도가 {quest:827}의 동굴을 차지하고 있으며, 누구든 {item:4871}을(를) 떨어뜨립니다. 14레벨 흑마법사 {npc:3204}은(는) 깊숙한 곳에 서 있으며 {item:4903}을(를) 떨어뜨립니다.\n주의: {quest:827}에서는 공허방랑자가 불타는 칼날단 이교도 옆에서 싸우고, {npc:3204}(14)은(는) 자기 공허방랑자와 함께 안쪽에서 기다립니다. 목걸이는 입구 근처에서 이교도를 하나씩 끌어와 얻으세요. {item:4903}은(는) 선택 사항입니다. 13레벨이 아니고 함께할 친구도 없다면 {npc:3204}은(는) 건드리지 마세요.",
		["Careful: Ukorsbane (8) is elite and walks among the Ridgeshade spiders in the camp south of {area:362}: pull the spiders away from him."] = "주의: Ukorsbane(8)은(는) 정예이며 {area:362} 남쪽 야영지의 Ridgeshade 거미 사이를 걸어 다닙니다. 거미를 그에게서 멀리 끌어내십시오.",
		["Class trainer"] = "직업 전문가",
		["Druid trainer"] = "드루이드 상급자",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "하급 지옥사냥개는 골짜기 북쪽, 동굴 아래 비탈을 돌아다닙니다.",
		["Fizzle holds the Burning Blade camp on {area:369}, just north of Misha's hut. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "피즐은 미샤의 오두막 바로 북쪽, {area:369}의 불타는칼날단 야영지를 차지하고 있습니다. 사냥꾼: 가는 길에 {item:15908}(으)로 {npc:3099}을(를) 길들이세요.\n주의: 불타는칼날단 이교도들이 피즐을 둘러싸고 있으며, 일부는 연결되어 있어 두 마리씩 덤비고, 빨리 다시 나타납니다.\n주의: 12레벨 정예 할리코르가 도마뱀들 사이로 {area:369}을(를) 돌아다닙니다. 끌어오기 전에 그를 살피세요.",
		["Free {npc:275811} and see her safely out of the crag"] = "{npc:275811}을(를) 풀어 주고 무사히 밖으로 데려가세요",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nCareful: the trolls stand close together and the Voodoo Trolls cast from range: pull one at a time. {quest:826} himself is level 10."] = "섬들을 지나 남쪽으로 가세요. 로아 우상은 남쪽 섬 곳곳에 있으며, 부두교 트롤과 주술에 걸린 트롤이 이를 지키고 사술 걸린 펜던트를 떨어뜨립니다. {quest:826}와(과) 민시나의 우리는 가장 남쪽 섬에 있습니다.\n주의: 트롤들은 서로 가까이 서 있고 부두교 트롤은 원거리에서 주문을 겁니다. 하나씩 끌어오세요. {quest:826} 자신은 10레벨입니다.",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "동굴 안에서 첫 갈림길은 직진하고, 이어서 오른쪽으로 가 왼편 개울을 따라 폭포까지 가세요. 곡괭이는 바위 기둥 뒤 물가에서 빛나고 있습니다.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "동굴 안에서 개울을 건너 오른쪽 벽을 따라 끝까지 돌아가세요. {npc:3183}이(가) 끝에서 기다립니다.",
		["Level 11"] = "11레벨",
		["Level 7"] = "7레벨",
		["Level 9"] = "9레벨",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "미샤의 오두막은 도마뱀들의 남쪽에 있습니다. 서쪽 {area:814}을(를) 따라 있는 악어가 {item:4891}을(를) 가지고 있습니다.",
		["North-east to the beach below {area:370}, north of {npc:275657}: Spitelash Scouts and Attendants hold it. Hunters: tame a {npc:3107} on the beach."] = "북동쪽으로 {npc:275657} 북쪽, {area:370} 아래 해변으로 가세요. 원한의꼬리일족 정찰병과 수행원이 그곳을 차지하고 있습니다. 사냥꾼: 해변에서 {npc:3107}을(를) 길들이세요.",
		["Quilboars and scouts hold the huts west of town, where the prickly pears grow; dustrunners and battleguards hold the camps farther west."] = "가시멧돼지와 정찰병이 가시배가 자라는 마을 서쪽 오두막을, 사막길잡이와 전투호위병이 더 서쪽의 야영지를 차지하고 있습니다.",
		["Spitelash naga"] = "원한의꼬리일족 나가",
		["Tame it with the {item:15908}"] = "{item:15908}(으)로 길들이세요",
		["The Scorpid Workers roam the slope south of {npc:3287}; pick the Cactus Apples by the cactuses on the way.\nThe {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "일꾼전갈은 {npc:3287} 남쪽 비탈을 돌아다닙니다. 가는 길에 선인장 옆에서 선인장 사과를 따세요.\n{quest:792}은(는) 골짜기 북쪽의 동굴인 {area:365} 아래 비탈에 득실거립니다.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "부들과 창풀은 골목길 동쪽, {object:172958}의 물가를 따라 자랍니다.",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}."] = "요새는 {area:362} 남동쪽 해안에 있습니다. 약탈자의 도끼, 활, 방패는 요새 외곽에 있습니다. 선원과 해병이 {item:4870}을(를) 떨어뜨립니다.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "무기는 동굴 막사와 훈련장 주변에 있고, {npc:3098}은(는) 골짜기 바닥 전체를 돌아다닙니다.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595}은(는) 방금 싸운 이교도들 사이, {area:817} 안에 있습니다.",
		["Through Sen'jin on the way west to {area:366}: {npc:3304} takes the eyes and mucus now."] = "서쪽 {area:366}(으)로 가는 길에 센진 마을을 지나세요. 이제 {npc:3304}에게 눈과 점액을 제출할 수 있습니다.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "천둥도마뱀과 번개도마뱀은 {zone:1454}(으)로 가는 북쪽 길가의 {area:369}에서 풀을 뜯으며, 어느 것이든 {item:6486}을(를) 떨어뜨릴 수 있습니다. 다음 가이드가 {area:379}을(를) 지날 때 {npc:5810}이(가) 받습니다.\n주의: 12레벨 정예 할리코르가 도마뱀들 사이로 {area:369}을(를) 돌아다닙니다. 끌어오기 전에 그를 살피세요.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "천둥도마뱀과 번개도마뱀은 {npc:3293} 바로 서쪽과 남서쪽의 {area:369}에서 풀을 뜯습니다.\n주의: 12레벨 정예 할리코르가 도마뱀들 사이로 {area:369}을(를) 돌아다닙니다. 끌어오기 전에 그를 살피세요.",
		["Thunder lizards on the way north"] = "북쪽으로 가는 길의 천둥 도마뱀",
		["To {zone:1454}"] = "{zone:1454}(으)로",
		["Top up here to level 11 before {npc:3203} (12) and his imp: the Thunder Lizards (9-10) graze on the ridge just west of Misha's hut."] = "{npc:3203}(12)과(와) 그의 임프에게 가기 전에 여기서 11레벨까지 올리세요. 천둥도마뱀(9-10)은 미샤의 오두막 바로 서쪽 산등성이에서 풀을 뜯습니다.",
		["Top up here to level 7 before {npc:3192} (8) and the marines at the top of the keep."] = "요새 꼭대기의 {npc:3192}(8)와(과) 해병에게 가기 전에 여기서 7레벨까지 올리세요.",
		["Top up here to level 9 before the southern isles: the Voodoo and Hexed Trolls there are 8-9 and {quest:826} is 10."] = "남쪽 섬에 가기 전에 여기서 9레벨까지 올리세요. 그곳의 부두교 트롤과 주술에 걸린 트롤은 8-9레벨이고 {quest:826}은(는) 10레벨입니다.",
		["Training weapons and boars"] = "훈련용 무기와 멧돼지",
		["Underwater"] = "물속",
		["Upstairs"] = "위층",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."] = "얕은 물을 건너 북쪽 메아리 섬으로 가세요. 그곳의 랩터들 사이를 우두머리 암컷이 배회합니다.\n듀로타 호랑이는 섬과 센진 남쪽 해안을 돌아다니며, 채찍꼬리 알은 섬과 해변을 따라 둥지에 있습니다.",
		["Wake {quest:5441} with the {item:16114}"] = "{item:16114}(으)로 {quest:5441} 깨우기",
		["grind on {npc:3121}"] = "{npc:3121} 사냥",
		["grind on {npc:3128}"] = "{npc:3128} 사냥",
		["grind on {npc:3130}"] = "{npc:3130} 사냥",
		["the {object:654925} on the ground beside her"] = "그녀 옆 땅바닥의 {object:654925}",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366}은(는) 센진 서쪽에 있습니다. 공격 계획서 세 개는 켄타우로스 천막 사이 땅바닥에 있습니다. {npc:275811}도 그곳에 붙잡혀 있습니다.",
		["{area:817}'s mouth"] = "{area:817} 입구",
		["{npc:10176}, where you start"] = "{npc:10176}, 시작 지점",
		["{npc:11025} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:202} 숙련도가 20이 되면 {npc:11025}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809}은(는) {area:362} 바로 남쪽에 야영하고 있습니다. {spell:1229451} 효과가 나타날 때까지 그의 모닥불 옆에 앉으세요(/sit). 전문 기술을 배웠다면 {npc:265809}에게서 해당 기술의 야영 기초(Camping 101) 퀘스트도 받을 수 있으며, 그 기술의 상급자에게 완료하세요. {area:362} 또는 다음 가이드 시작 지점인 {zone:1454}에 있습니다.",
		["{npc:265809}'s campfire"] = "{npc:265809}의 모닥불",
		["{npc:265809}: for Jandi"] = "{npc:265809}: Jandi에게 전달",
		["{npc:265809}: for Jhag"] = "{npc:265809}: Jhag에게 전달",
		["{npc:265809}: for Karolek"] = "{npc:265809}: 카롤렉에게 전달",
		["{npc:265809}: for Snang"] = "{npc:265809}: Snang에게 전달",
		["{npc:265809}: for Thuwd"] = "{npc:265809}: 투우드에게 전달",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}: {npc:11025}에게 전달",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809}: {npc:11046}에게 전달",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}: {npc:3175}에게 전달",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}: {npc:5943}에게 전달",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: 마법부여사 전용, 잔여물은 {item:275724}을(를) 마력 추출해서 얻습니다",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657}은(는) {area:362} 동쪽 해안에 서 있습니다. 삼지창, 깃발, 단검은 그 주변 해변에 있습니다.",
		["{npc:3102} hooves"] = "{npc:3102} 발굽",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, {area:362}에 돌아가서",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: 정예 바다 거인 {npc:275666}",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143}은(는) 동굴 입구 바로 안쪽에, {npc:3159}은(는) 그 뒤 동굴 안쪽에 서 있습니다.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143}은(는) {npc:10176} 바로 서쪽 건물인 동굴 막사 안에서 기다립니다.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, 감시탑 안",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, 동굴 막사 옆의 전사 상급자",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, 동굴 막사 옆의 사냥꾼 상급자",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, 동굴 막사의 도적 상급자",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, 동굴 안쪽의 흑마법사 상급자",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, 동굴 막사 옆의 주술사 상급자",
		["{npc:3175} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:186} 숙련도가 20이 되면 {npc:3175}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "{npc:3192}은(는) 요새 꼭대기에서 기다리며, 그의 열쇠로 옆 상자를 열면 {item:4881}이(가) 들어 있습니다.",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287}은(는) 동굴 막사 북서쪽 언덕 기슭에 부상당한 채 누워 있습니다.",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it.\nCareful: the voidwalker you summon hits hard and it is the fight Warlocks die to most in {zone:1454}: start at full health and mana, send your imp in, keep Corruption and Immolate on it, and use a healthstone if you have one."] = "{npc:5875}은(는) {object:172982} 아래 협곡인 {object:172960}에 있습니다. 그에게 {item:6535}을(를) 건넨 뒤, 옆의 소환진에서 {item:7464}을(를) 사용하고 공허방랑자를 물리쳐 속박하세요.\n주의: 소환한 공허방랑자는 강하게 공격하며, {zone:1454}에서 흑마법사가 가장 많이 죽는 전투입니다. 생명력과 마나를 가득 채우고 시작하고, 임프를 먼저 보내고, 부패와 제물을 계속 걸어 두고, 생명석이 있다면 사용하세요.",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, 동굴 막사 입구의 마법사 상급자",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887}은(는) 동굴 막사 바깥에 서 있습니다. {area:639}은(는) 그 바로 남쪽 언덕입니다. 그곳에서 {item:6635}을(를) 마셔 {npc:5891}을(를) 보고, {item:6656}을(를) {npc:5887}에게 가져가세요.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873}, {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, {area:639} 위",
		["{npc:5943} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:129} 숙련도가 20이 되면 {npc:5943}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786}은(는) 골짜기 동쪽 출구의 길 위에 서 있습니다.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, 요리용 모닥불 옆",
		["{quest:790}, a large scorpid (level 4), prowls the slope just west of the Den, below {npc:3287}, on the way north to the {area:365}."] = "큰 전갈인 {quest:790}(4레벨)은(는) {area:365}(으)로 북쪽으로 가는 길, {npc:3287} 아래 소굴 바로 서쪽 비탈을 배회합니다.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828}은(는) 나가 해변 서쪽, {quest:827} 남쪽 언덕에 진을 치고 있습니다.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "{zone:1454} 정문은 {area:817} 바로 서쪽에 있습니다. {npc:5875}은(는) {object:172982} 아래 협곡인 {object:172960}에 서 있습니다.",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "{spell:1229451}을(를) 얻을 때까지 {npc:263664}의 모닥불 옆에서 /앉기 하세요",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "하늘사제 앤더스와 쓰러진 경비병들은 탑 바로 남서쪽에 있습니다. 시신에서 라니의 행운의 깃털과 섀도송 가문 인장을 챙기세요.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "다시 {quest:92529}: 알아케스 폭풍소환사와 {npc:251662}이(가) 마을을 메우고 있고, {object:576179}은(는) 집들 사이에 있으며, {npc:251966}은(는) 남동쪽 끝에서 기다립니다.",
		["Back to Boro in {area:16635} with the Signet."] = "인장을 가지고 {area:16635}의 보로에게 돌아가세요.",
		["Back to {area:16635}"] = "{area:16635}(으)로 돌아가기",
		["Back to {area:16638}"] = "{area:16638}(으)로 돌아가기",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "{npc:268592}에게 돌아가세요. 그가 {npc:268762}에 불을 붙이면, 시간이 끝나기 전에 불꽃을 곧장 {area:16638}의 {npc:252382} 옆 {npc:268679}(으)로 가져가세요.",
		["Below ground"] = "지하",
		["Cast {spell:1259686} near the {object:460001}"] = "{object:460001} 근처에서 {spell:1259686}을(를) 시전하세요",
		["Class trainer"] = "직업 전문가",
		["Find {npc:258130}"] = "{npc:258130}을(를) 찾으세요",
		["Follow the road south to {area:16624}, in the middle of the isle. {npc:251523} stands on its east side, {npc:251902} in the middle, {npc:254089} just north-west of her, {npc:263664} by the campfire on the west side. With a profession learned, {npc:263664} also offers its Camping 101: its trainer stands in the village."] = "길을 따라 남쪽으로 섬 한가운데의 {area:16624}에 가세요. {npc:251523}은(는) 마을 동쪽에, {npc:251902}은(는) 한가운데에, {npc:254089}은(는) 그녀 바로 북서쪽에, {npc:263664}은(는) 서쪽 모닥불 옆에 있습니다. 전문 기술을 배우면 {npc:263664}이(가) 해당 야영 101 퀘스트도 줍니다. 그 기술의 상급자는 마을에 있습니다.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "북쪽 {area:16631}(으)로 가세요. {npc:257944}이(가) 숲 남쪽 끝에서 야영합니다.",
		["Head north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "북동쪽 {area:17675}(으)로 가세요. 알아케스 야영지는 그 바로 서쪽에 있으며, {npc:252666}은(는) 야영지 북쪽 끝에 있습니다. 신도는 모두 알아케스 바람석 부적을 떨어뜨릴 수 있습니다.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "남서쪽 {area:17674}(으)로 가세요. {npc:252155}은(는) 꼭대기에 있고, {item:254871}은(는) 그 옆에 있습니다.",
		["Heal the injured druids in the Nightfang Den"] = "밤송곳니 굴의 다친 드루이드를 치유하세요",
		["Listen to {npc:252448}'s story"] = "{npc:252448}의 이야기를 들으세요",
		["Listen to {npc:256083}"] = "{npc:256083}의 이야기를 들으세요",
		["Northern {zone:1412}"] = "{zone:1412} 북부",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "성가신 구름벌레와 {npc:250873}이(가) 마을 바로 남동쪽 숲을 돌아다닙니다.",
		["Raw Windstones"] = "{object:613286}",
		["Skyhoppers"] = "하늘폴짝이",
		["Skyhoppers hop about the fields just west of Valennia."] = "하늘폴짝이는 발레니아 바로 서쪽 들판을 뛰어다닙니다.",
		["Spread the {item:278078} off {area:1641}"] = "{area:1641}에서 {item:278078}을(를) 피우세요",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "잘 익은 폭풍사과와 펄럭날개 가루가 과수원 곳곳에 있고, 굶주린 좀도둑이 과수원을 습격합니다. 돌풍타조는 과수원 동쪽 들판에서 풀을 뜯습니다. 부서진 피조물은 과수원 북쪽 끝에 떠 있습니다.",
		["Take {zone:1456}'s west lift down: the road at its foot runs south-east across {zone:1412} to the {zone:1413}."] = "{zone:1456}의 서쪽 승강기를 타고 내려가십시오. 그 아래 길은 남동쪽으로 {zone:1412}을(를) 가로질러 {zone:1413}까지 이어집니다.",
		["Tame {npc:254588}"] = "{npc:254588} 길들이기",
		["Tell {npc:252800} you're ready"] = "{npc:252800}에게 준비되었다고 말하세요",
		["The Al'Aketh camp"] = "알아케스 야영지",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "{object:613286}은(는) 마을 주변 비탈에 있는 파란 수정입니다.",
		["The apprentices practise north-east of the village.\nThe bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones."] = "수습생들은 마을 북동쪽에서 수련합니다.\n좀도둑 야영지는 마을 북동쪽에 있으며, \"사악한 바람\" 베닉이 가장 위쪽 야영지를 차지하고 있습니다. 좀도둑들이 훔친 바람석을 지니고 있습니다.",
		["The hippogryph nests are north-west of the {area:17674}, west of {quest:92529}. The Matriarch sits at their western end; {item:263493} lies on the ground around the nests."] = "히포그리프 둥지는 {area:17674} 북서쪽, {quest:92529} 서쪽에 있으며, 히포그리프 어미는 둥지 서쪽 끝에 있습니다. {item:263493}은(는) 둥지 주변 땅에 있습니다.",
		["The orchard"] = "과수원",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "구름벌레 여왕은 선돌에서 돌아오는 길, 숲 남동쪽 끝에 떠 있습니다.",
		["The road from {zone:1412} meets the {area:458} at {area:378}: {npc:10378}, the wind rider master, stands beside {npc:3418} on your way north to the Crossroads."] = "{zone:1412}에서 오는 길은 {area:378}에서 {area:458}와(과) 만납니다. 와이번 조련사 {npc:10378}은(는) 북쪽 크로스로드로 가는 길에 {npc:3418} 옆에 서 있습니다.",
		["The standing stones"] = "선돌",
		["The turncoat"] = "배신자",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}, just north of {npc:273017}."] = "배신자의 집은 {area:16638} 북서쪽 {area:16626}, {npc:273017} 바로 북쪽에 있습니다.",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629}은(는) {area:16638} 북쪽에 있습니다. 경비병들을 뚫고 동쪽의 {npc:253576}에게 가세요.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {object:148418}"] = "{object:148418}",
		["To {zone:1454}"] = "{zone:1454}(으)로",
		["Underwater"] = "물속",
		["Upstairs"] = "위층",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "{area:1641} 남쪽 절벽의 의식용 깔개와 향로에서 {item:278078}을(를) 사용하세요.",
		["Valennia asks you to hear out both leaders: {npc:251968} of the Horde and {npc:252475} of the Alliance. {npc:252475}'s name shows red to you, but he talks to you all the same, and the quest needs both."] = "발렌니아는 두 지도자의 이야기를 모두 들어 보라고 합니다. 호드의 {npc:251968}와(과) 얼라이언스의 {npc:252475}입니다. {npc:252475}의 이름은 빨간색으로 보이지만 그래도 대화할 수 있으며, 퀘스트에는 두 사람 모두 필요합니다.",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "이제 섬을 완전히 떠납니다. {npc:259119}이(가) 비행선이 내리는 곳에서 기다립니다.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "섬 북쪽의 {area:16635}에서 깨어납니다. {npc:251362}은(는) 길가에, {npc:251361}은(는) 마을 한가운데에 있습니다.",
		["drink the {item:6635} at the {area:16988}, just east of the village, to see the {npc:251166}"] = "마을 바로 동쪽 {area:16988}에서 {item:6635}을(를) 마시고 {npc:251166}을(를) 보세요",
		["search the dead cultist in the house"] = "집 안의 죽은 신도를 뒤지세요",
		["search the wardrobe"] = "옷장을 뒤지세요",
		["talk to {npc:251684}"] = "{npc:251684}와(과) 대화하세요",
		["talk to {npc:251902}"] = "{npc:251902}와(과) 대화하세요",
		["talk to {npc:251968}"] = "{npc:251968}와(과) 대화하세요",
		["talk to {npc:252155}"] = "{npc:252155}와(과) 대화하세요",
		["talk to {npc:252476}"] = "{npc:252476}와(과) 대화하세요",
		["talk to {npc:253844}"] = "{npc:253844}와(과) 대화하세요",
		["talk to {npc:257554}"] = "{npc:257554}와(과) 대화하세요",
		["the bounty board"] = "현상수배 게시판",
		["{area:16624} turn-ins"] = "{area:16624} 퀘스트 완료",
		["{area:16624}: kill these as you meet them"] = "{area:16624}: 만나는 대로 처치하세요",
		["{area:16635} turn-ins"] = "{area:16635} 퀘스트 완료",
		["{area:16663} is west of {area:16638} along the coast road."] = "{area:16663}은(는) 해안 길을 따라 {area:16638} 서쪽에 있습니다.",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105}은(는) {npc:257944}의 야영지 주변에 자라고, 그 위로 그늘돌풍 괴성조가 날아다닙니다. {item:265141}은(는) 그녀 동쪽의 알아케스 야영지에 있습니다.",
		["{item:278079}, from {npc:3014}"] = "{npc:3014}에게서 {item:278079}",
		["{item:278080}, from {npc:3012}"] = "{npc:3012}에게서 {item:278080}",
		["{item:278081}, from {npc:3005}"] = "{npc:3005}에게서 {item:278081}",
		["{item:278083}, from {npc:3027}"] = "{npc:3027}에게서 {item:278083}",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363}은(는) 마을 동쪽 {area:17678}에 있습니다. {npc:251143}와(과) 알아케스 전향자가 그녀 바로 북쪽에 모여 있습니다. {object:460001}은(는) 그녀 바로 북동쪽에 있으니, 그 옆에서 종족 특성 {spell:1259686}을(를) 시전하세요.",
		["{npc:250926} prowl the slopes south-west of the village, on the way to {npc:252095}.\nThe Ursera den is west of the village. {npc:251115}, their matriarch, sits at its far end."] = "{npc:250926}은(는) {npc:252095}에게 가는 길, 마을 남서쪽 비탈을 배회합니다.\n우르세라 굴은 마을 서쪽에 있습니다. 그들의 어미인 {npc:251115}은(는) 굴 맨 안쪽에 있습니다.",
		["{npc:251361}'s errands"] = "{npc:251361}의 심부름",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: 상급자가 보낸 쪽지",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}: {item:282418}을(를) 살펴보세요",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: {item:9547}을(를) 읽으세요",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "드루이드 상급자 {npc:251373}: {npc:251361} 뒤편 나무의 1층",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}: {npc:5873}와(과) {item:5175}",
		["{npc:251389}, in the watchtower"] = "감시탑 안의 {npc:251389}",
		["{npc:251905}, {npc:251906}, {npc:251991}, {npc:252172} and {npc:251523} all stand in {area:16624}. If you are still short of {item:5469}, the Galestriders graze just west of the village; the Al'Aketh camps south and south-east of it are a level or two higher."] = "{npc:251905}, {npc:251906}, {npc:251991}, {npc:252172}, {npc:251523}은(는) 모두 {area:16624}에 있습니다. {item:5469}이(가) 아직 부족하다면 마을 바로 서쪽에서 질풍타조가 풀을 뜯습니다. 마을 남쪽과 남동쪽의 알아케스 야영지는 한두 레벨 더 높습니다.",
		["{npc:251913} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:164} 숙련도가 20이 되면 {npc:251913}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:251964}, in the watchtower"] = "감시탑 안의 {npc:251964}",
		["{npc:251992} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:356} 숙련도가 20이 되면 {npc:251992}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:251993} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:165} 숙련도가 20이 되면 {npc:251993}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:252095} waits in {area:16622}, south-west of the village. The Al'Aketh camp is just beyond her; {npc:256935} leads it.\nCareful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095}은(는) 마을 남서쪽 {area:16622}에서 기다립니다. 알아케스 야영지는 그 바로 너머에 있으며, {npc:256935}이(가) 이끕니다.\n주의: {npc:256935}은(는) 충격 주문을 시전합니다. 다른 신도가 끼어들지 않도록 싸우기 전에 떨어뜨려 끌어내십시오.",
		["{npc:252377} stands beside {npc:256083}, just north-west of {area:16638}."] = "{npc:252377}은(는) {area:16638} 바로 북서쪽, {npc:256083} 옆에 있습니다.",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {npc:2523}, {item:5176}, {item:263412}",
		["{npc:252448} and {npc:256083}"] = "{npc:252448}와(과) {npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130}, {npc:258134}은(는) {npc:257944} 동쪽 교단 야영지에 있습니다. {npc:254151}은(는) 야영지 가장자리에 있습니다. 할리엔은 {quest:94490}도 떨어뜨리니 읽어서 다음 퀘스트를 시작하세요. {quest:94489}은(는) 밤송곳니 굴에 들어가 다친 드루이드 7명을 치유하고 {npc:258130}을 찾으세요.",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589}은(는) 마을 남쪽 무리발톱 사이에 숨어 있습니다. {npc:254589}은(는) 정예이니 파티를 권장합니다.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083}은(는) 마을 바로 북서쪽 {area:16626}에 있습니다.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247}은(는) {area:16629}(으)로 가는 {area:16638} 북쪽 길에서 기다립니다.",
		["{npc:257018} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:129} 숙련도가 20이 되면 {npc:257018}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:257019} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:171} 숙련도가 20이 되면 {npc:257019}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:257022} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:186} 숙련도가 20이 되면 {npc:257022}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:257024} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:393} 숙련도가 20이 되면 {npc:257024}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196}이(가) 제단 서쪽에서 {item:263993}을(를) 지니고 있습니다.",
		["{npc:257944} again"] = "다시 {npc:257944}",
		["{npc:257944}, last time"] = "마지막으로 {npc:257944}",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "착륙장 옆의 {npc:259118}: {zone:1456}의 {npc:3033}에게",
		["{npc:259119}: keep it: Thrall in {zone:1454}, at the start of the next guide"] = "{npc:259119}: 보관하세요. 다음 가이드 시작에 {zone:1454}의 스랄",
		["{npc:268592}, at the Shrine of Flames just south-east of the orchard"] = "{npc:268592}, 과수원 바로 남동쪽 불꽃의 제단",
		["{npc:268602}, on the hill west of the falls just north of the watchtower"] = "{npc:268602}, 감시탑 바로 북쪽 폭포 서쪽 언덕",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}은(는) 타우렌 향을 원합{npc:3014}. 약초상 니다, 마법부여 상인 {npc:3012}, 가죽세공 상인 {npc:3005}, 요리 상인 {npc:3027}에게서 재료 네 가지를 사서 {item:278078}(으)로 합치세요.",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529}은(는) 셴다르 마을 남쪽에 있습니다. 마을 가장자리에서 {npc:257065}을(를) 만나고, 그 뒤편 집의 옷장을 뒤지세요.",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "{spell:1229451}을(를) 얻을 때까지 카가의 모닥불 옆에서 /앉기",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "동쪽의 {area:358}(으)로 돌아가세요. 뾰족털일족 주술사는 그곳 가시멧돼지 사이에 있습니다.",
		["Back north-west up to {area:221}."] = "북서쪽으로 올라가 {area:221}(으)로 돌아가세요.",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "야영지의 {npc:5888}에게 돌아가세요. {npc:5891}은(는) 야영지 동쪽 고원에서 기다립니다. 그곳에서 {item:6635}을(를) 마시면 보입니다. {item:6656}을(를) 예언자에게 가져가세요.",
		["Back west to the camp."] = "서쪽의 야영지로 돌아가세요.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "전투멧돼지는 제단 북쪽에서 풀을 뜯고, 뾰족털 가시멧돼지는 북동쪽 협곡을 차지하고 있습니다. {npc:8554}은(는) 협곡 동쪽 끝에 서 있고, {object:3076}은(는) 야영지 바닥에 있습니다.",
		["Below ground"] = "지하",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{spell:18960}을(를) 시전하세요. {npc:11802}은(는) {area:2361}에 있고, {quest:5930}은(는) 북서쪽 숲에 있습니다. {npc:11802}은(는) 자기 건물 위층에 서 있습니다. 건물 안에서 올라가세요. 화살표는 층을 구분하지 못합니다.",
		["Class trainer"] = "직업 전문가",
		["Class turn-in in {area:1638}"] = "{area:1638}에서 직업 퀘스트 완료",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "북서쪽으로 {zone:1456}을(를) 지나 {zone:1412} 맨 북쪽의 {area:398}(으)로 가세요.",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}. With a profession learned, Kaga also offers its Camping 101, which its trainer takes: in Bloodhoof or on the {zone:1456} stop."] = "길을 따라 {area:220}에서 북쪽으로 나가세요. {npc:265810}은(는) {area:222} 바로 남쪽 길에서 기다립니다. {spell:1229451}을(를) 얻을 때까지 그녀의 모닥불 옆에서 /앉기 하세요. 전문 기술을 배웠다면 카가가 야영 기초 퀘스트도 주며, 해당 전문 기술 상급자에게 완료합니다. 상급자는 블러드후프 마을이나 {zone:1456}에 있습니다.",
		["From {area:1639}, take {zone:1456}'s north lift down: at its foot the way runs east along the ledge, then south-east across {zone:1412} to the {zone:1413}."] = "{area:1639}에서 {zone:1456}의 북쪽 승강기를 타고 내려가십시오. 그 아래에서 길은 바위턱을 따라 동쪽으로, 그다음 남동쪽으로 {zone:1412}을(를) 가로질러 {zone:1413}까지 이어집니다.",
		["Galak centaurs"] = "갈라크일족 켄타우로스",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "북쪽으로 {zone:1456} 동쪽의 {area:225}(으)로 가세요. {npc:3233}은(는) 바위 기슭에 서 있습니다. 뾰족털일족 약탈자는 매장지를 파헤치고 있고, {npc:2994}은(는) 꼭대기에서 기다립니다.",
		["Over the bridge below {area:379} and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "{area:379} 아래 다리를 건너 강의 {zone:1411} 쪽 기슭을 따라 남쪽으로, 좁은 길이 산을 오르는 곳까지 가십시오. {npc:5900}이(가) 꼭대기의 제단을 지킵니다. 올라가는 길에 가장자리를 조심하고, 같은 길로 다시 내려오십시오.",
		["Prairie Wolves, Wiry Swoops and Adult Plainstriders roam the plains around the village; the plains just south of it, toward the well, hold them without the Elder Plainstriders (8-9) and Prairie Wolf Alphas (9-10) that roam farther out."] = "초원늑대, 뾰족깃검독수리, 다자란 초원타조가 마을 주변 평원을 돌아다닙니다. 마을 바로 남쪽, 우물 방향 평원에는 더 바깥을 돌아다니는 덩치큰 초원타조(8-9)와 우두머리 초원늑대(9-10) 없이 이들만 있습니다.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "승강기를 타고 고원으로 올라가세요. {npc:2995}은(는) 중앙 고지에서 윈드라이더를 돌보고, {npc:3057}은(는) 그곳 큰 천막에 서 있습니다.",
		["Spread the {item:278078} off {area:1641}"] = "{area:1641}에서 {item:278078} 뿌리기",
		["Tame it with the {item:15908}"] = "{item:15908}(으)로 길들이기",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "회색갈기일족 놀은 발굴지 남쪽, 블러드후프 마을 서쪽의 {area:818}을(를) 차지하고 있습니다. {npc:272203}은(는) 그들의 야영지에 붙잡혀 있습니다. 밖으로 데리고 나오세요.",
		["The Seer's tent stands at the foot of the cougars' hills."] = "예언자 그레이텅의 천막은 퓨마가 사는 언덕 기슭에 있습니다.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "성난바람하피는 우물 북쪽과 서쪽의 {area:819}을(를) 차지하고 있습니다.",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "{area:404}의 드워프들이 발굴조사단장의 곡괭이를 지니고 있습니다. 발굴현장 안의 드워프 대장간에서 부수세요.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "향은 10분 안에 다 탑니다. 남쪽 언덕을 따라 곧장 동쪽의 {object:660739}(으)로 달려가세요.",
		["The shrine of An'she and Mu'sha"] = "안셰와 무샤의 제단",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "돌은 동쪽으로 가는 길에 있는 {zone:1412} 출구 고갯길에 있습니다. 그곳에서 {item:15710}을(를) 사용하고 초승달발톱을 물리치세요.",
		["The {object:177525}"] = "{object:177525}",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes them when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "천둥 도마뱀과 번개가죽이 {zone:1454}(으)로 가는 북쪽 길 옆 {area:369}에서 풀을 뜯습니다. 어느 것이든 {item:6486}을(를) 떨어뜨릴 수 있습니다. 다음 가이드가 {area:379}을(를) 지날 때 {npc:5810}이(가) 받습니다.\n주의: 12레벨 정예 Halikor가 도마뱀 사이에서 {area:369}을(를) 돌아다닙니다. 끌어오기 전에 그가 있는지 살피십시오.",
		["Thunder lizards on the way north"] = "북쪽으로 가는 길의 천둥 도마뱀",
		["To {zone:1454}"] = "{zone:1454}(으)로",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "{area:1641}의 남쪽 절벽에 있는 의식용 깔개와 향로에서 {item:278078}을(를) 사용하세요.",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "{area:221}의 고원에서 시작합니다. {npc:2980}와(과) 족장은 한가운데 큰 천막 옆에 서 있습니다.",
		["{area:379} sits above the {area:814} bridge on the road to {zone:1454}: {npc:5810} stands beside {npc:3337}."] = "{area:379}은(는) {zone:1454}(으)로 가는 길의 {area:814} 다리 위에 있습니다. {npc:5810}은(는) {npc:3337} 옆에 서 있습니다.",
		["{item:278079}, from {npc:3014}"] = "{npc:3014}에게서 사는 {item:278079}",
		["{item:278080}, from {npc:3012}"] = "{npc:3012}에게서 사는 {item:278080}",
		["{item:278081}, from {npc:3005}"] = "{npc:3005}에게서 사는 {item:278081}",
		["{item:278083}, from {npc:3027}"] = "{npc:3027}에게서 사는 {item:278083}",
		["{item:4703}, at the digsite forge"] = "{item:4703}, 발굴현장 대장간에서",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203}: 굶주린 평원퓨마는 {area:225} 주변 평원을 돌아다닙니다",
		["{npc:10278} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:164} 숙련도가 20이 되면 {npc:10278}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:10378}, beside {npc:3418}"] = "{npc:3418} 옆의 {npc:10378}",
		["{npc:11047} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:171} 숙련도가 20이 되면 {npc:11047}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:11051} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:197} 숙련도가 20이 되면 {npc:11051}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:11071} takes it once your {skill:333} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:333} 숙련도가 20이 되면 {npc:11071}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:265810}: for {npc:10278}"] = "{npc:265810}: {npc:10278}에게",
		["{npc:265810}: for {npc:11047}"] = "{npc:265810}: {npc:11047}에게",
		["{npc:265810}: for {npc:11051}"] = "{npc:265810}: {npc:11051}에게",
		["{npc:265810}: for {npc:11071}"] = "{npc:265810}: {npc:11071}에게",
		["{npc:265810}: for {npc:3001}"] = "{npc:265810}: {npc:3001}에게",
		["{npc:265810}: for {npc:3013}"] = "{npc:265810}: {npc:3013}에게",
		["{npc:265810}: for {npc:3069}"] = "{npc:265810}: {npc:3069}에게",
		["{npc:265810}: for {npc:5938}"] = "{npc:265810}: {npc:5938}에게",
		["{npc:265810}: for {npc:5939}"] = "{npc:265810}: {npc:5939}에게",
		["{npc:265810}: for {npc:6290}"] = "{npc:265810}: {npc:6290}에게",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}은(는) 타우렌 향을 원합{npc:3014}. 약초 상인 니다, 마법부여 재료 상인 {npc:3012}, 가죽세공 재료 상인 {npc:3005}, 요리 재료 상인 {npc:3027}에게서 재료 네 가지를 사서 {item:278078}(으)로 합치세요.",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182}은(는) 마을 북쪽 가장자리에 서 있습니다. 카일은 초원타조에게서 얻는 {item:287505}을(를) 원합니다.",
		["{npc:277182}, at the north end of the village"] = "마을 북쪽 끝의 {npc:277182}",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{zone:1456}의 하물에게 갈 {npc:2948}",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984}은(는) 우물 남쪽, {area:404} 가장자리에 서 있습니다.",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991}은(는) 야영지 동쪽 가장자리 천막 옆에 앉아 있으며, {object:2907}은(는) 그 옆에 있습니다.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{zone:1456}의 {npc:3057}에게 갈 {npc:2993}",
		["{npc:3001} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:186} 숙련도가 20이 되면 {npc:3001}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:3013} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:182} 숙련도가 20이 되면 {npc:3013}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:3059}, the warrior trainer; inside"] = "전사 상급자 {npc:3059}, 안",
		["{npc:3060}, the druid trainer beside him"] = "그 옆의 드루이드 상급자 {npc:3060}",
		["{npc:3061}, the hunter trainer"] = "사냥꾼 상급자 {npc:3061}",
		["{npc:3062}, the shaman trainer in camp"] = "야영지의 주술사 상급자 {npc:3062}",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "{npc:3063}의 퀘스트: 그 옆에서 풋내기 전사 세 명(또는 결투로 플레이어)을 이기세요.",
		["{npc:3065} stands at the north end of {area:222}. Tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a {npc:2970} to the north-west."] = "{npc:3065}은(는) {area:222} 북쪽 끝에 서 있습니다. {item:15908}(으)로 길들이세요: 평원의 {npc:2956}, 마을 북쪽의 {npc:2959}, 북서쪽의 {npc:2970}.",
		["{npc:3069} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:165} 숙련도가 20이 되면 {npc:3069}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "{npc:3067} 옆의 {npc:3069}: {quest:97934}",
		["{npc:3418} stands at {area:378}, where the road from {zone:1412} meets the {area:458} north to the Crossroads."] = "{npc:3418}은(는) {zone:1412}에서 오는 길이 크로스로드로 향하는 북쪽의 {area:458}과 만나는 {area:378}에 서 있습니다.",
		["{npc:3418}: for {npc:3429} at the Crossroads"] = "{npc:3418}: 크로스로드의 {npc:3429}에게",
		["{npc:3429}, by the wind rider tower"] = "윈드라이더 탑 옆의 {npc:3429}",
		["{npc:3441}: for {quest:860} at the Crossroads"] = "{npc:3441}: 크로스로드의 {quest:860}에게",
		["{npc:3615}, the wind rider master"] = "윈드라이더 조련사 {npc:3615}",
		["{npc:5769}: for {npc:3448} at the Crossroads"] = "{npc:5769}: 크로스로드의 {npc:3448}에게",
		["{npc:5888} stands in {area:221}. {quest:1519} needs level 4, which you reach with the turn-ins here."] = "{npc:5888}은(는) {area:221}에 서 있습니다. {quest:1519}에는 4레벨이 필요하며, 여기서 퀘스트를 제출하면 도달합니다.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}: {npc:5873}, {item:5175}",
		["{npc:5907} stands alone on the ridge above the Razormane camp, north-east of the Crossroads on the road to {area:379}."] = "{npc:5907}은(는) 크로스로드 북동쪽, {area:379}(으)로 가는 길의 서슬갈기일족 야영지 위 능선에 홀로 서 있습니다.",
		["{npc:5938} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:356} 숙련도가 20이 되면 {npc:5938}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:5939} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:129} 숙련도가 20이 되면 {npc:5939}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:6290} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:393} 숙련도가 20이 되면 {npc:6290}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:6290}, beside {npc:3067}: {quest:97936}"] = "{npc:3067} 옆의 {npc:6290}: {quest:97936}",
		["{npc:6746}: {quest:5926}, for {npc:3033} on {area:1639}"] = "{npc:6746}: {area:1639}의 {npc:3033}에게 가는 {quest:5926}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, then hunt the cougars south through the hills towards the Seer's tent at their foot."] = "{npc:6775}은(는) 야영지 서쪽 끝, 산지퓨마가 돌아다니는 언덕의 북서쪽 모퉁이에 서 있습니다. 그의 퀘스트를 받은 다음, 언덕을 지나 남쪽으로, 기슭에 있는 예언자의 천막 쪽으로 퓨마를 사냥하며 가세요.",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "{npc:3126}은(는) {area:362} 서쪽 평원을 기어다닙니다. 하나를 길들인 뒤 {npc:3171}에게 돌아가세요.",
		["Back east to Sen'jin on the way to the {area:368}."] = "{area:368}(으)로 가는 길에 동쪽 센진 마을로 돌아가세요.",
		["Back to the Den"] = "동굴 막사로 돌아가기",
		["Back to the Den: {npc:3143} takes {quest:804}'s claw and {npc:5887}, just outside, has {quest:1516} now that you are level 4."] = "소굴로 돌아가세요. {npc:3143}에게 {quest:804}의 집게발을 제출하고, 4레벨이 되었으니 바로 밖의 {npc:5887}에게서 {quest:1516}을(를) 받을 수 있습니다.",
		["Below ground"] = "지하",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "불타는 칼날단 이교도가 {quest:827}의 동굴을 차지하고 있으며, 누구든 {item:4871}을(를) 떨어뜨립니다. 14레벨 흑마법사 {npc:3204}은(는) 깊숙한 곳에 서 있으며 {item:4903}을(를) 떨어뜨립니다.\n주의: {quest:827}에서는 공허방랑자가 불타는 칼날단 이교도 옆에서 싸우고, {npc:3204}(14)은(는) 자기 공허방랑자와 함께 안쪽에서 기다립니다. 목걸이는 입구 근처에서 이교도를 하나씩 끌어와 얻으세요. {item:4903}은(는) 선택 사항입니다. 13레벨이 아니고 함께할 친구도 없다면 {npc:3204}은(는) 건드리지 마세요.",
		["Class trainer"] = "직업 전문가",
		["Druid trainer"] = "드루이드 상급자",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "하급 지옥사냥개는 골짜기 북쪽, 동굴 아래 비탈을 돌아다닙니다.",
		["Fizzle holds the Burning Blade camp on {area:369}, just north of Misha's hut. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "피즐은 미샤의 오두막 바로 북쪽, {area:369}의 불타는칼날단 야영지를 차지하고 있습니다. 사냥꾼: 가는 길에 {item:15908}(으)로 {npc:3099}을(를) 길들이세요.\n주의: 불타는칼날단 이교도들이 피즐을 둘러싸고 있으며, 일부는 연결되어 있어 두 마리씩 덤비고, 빨리 다시 나타납니다.\n주의: 12레벨 정예 할리코르가 도마뱀들 사이로 {area:369}을(를) 돌아다닙니다. 끌어오기 전에 그를 살피세요.",
		["Follow the road east out of the valley to {area:367} on the coast.\nCareful: Ukorsbane (8) is elite and walks among the Ridgeshade spiders in the camp south of {area:362}: pull the spiders away from him."] = "길을 따라 동쪽으로 골짜기를 나가 해안의 {area:367}까지 가세요.\n주의: Ukorsbane(8)은(는) 정예이며 {area:362} 남쪽 야영지의 산마루그늘 거미 사이를 돌아다닙니다. 거미를 그에게서 떼어 끌어오세요.",
		["Free {npc:275811} and see her safely out of the crag"] = "{npc:275811}을(를) 풀어 주고 무사히 밖으로 데려가세요",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nCareful: the trolls stand close together and the Voodoo Trolls cast from range: pull one at a time. {quest:826} himself is level 10.\nWade back west to the shore south of Sen'jin when the isles are done."] = "섬들을 지나 남쪽으로 가세요. 로아 우상은 남쪽 섬 곳곳에 있으며, 부두교 트롤과 주술에 걸린 트롤이 이를 지키고 사술 걸린 펜던트를 떨어뜨립니다. {quest:826}와(과) 민시나의 우리는 가장 남쪽 섬에 있습니다.\n주의: 트롤들은 서로 가까이 서 있고 부두교 트롤은 원거리에서 주문을 겁니다. 하나씩 끌어오세요. {quest:826} 자신은 10레벨입니다.\n섬을 마치면 얕은 물을 건너 서쪽 센진 남쪽 해안으로 돌아가세요.",
		["Heal and fortify {npc:12430}"] = "{npc:12430} 치유하고 강화하기",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "동굴 안에서 첫 갈림길은 직진하고, 이어서 오른쪽으로 가 왼편 개울을 따라 폭포까지 가세요. 곡괭이는 바위 기둥 뒤 물가에서 빛나고 있습니다.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "동굴 안에서 개울을 건너 오른쪽 벽을 따라 끝까지 돌아가세요. {npc:3183}이(가) 끝에서 기다립니다.",
		["Level 11"] = "11레벨",
		["Level 7"] = "7레벨",
		["Level 9"] = "9레벨",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "미샤의 오두막은 도마뱀들의 남쪽에 있습니다. 서쪽 {area:814}을(를) 따라 있는 악어가 {item:4891}을(를) 가지고 있습니다.",
		["North-east to the beach below {area:370}, north of {npc:275657}: Spitelash Scouts and Attendants hold it. Hunters: tame a {npc:3107} on the beach."] = "북동쪽으로 {npc:275657} 북쪽, {area:370} 아래 해변으로 가세요. 원한의꼬리일족 정찰병과 수행원이 그곳을 차지하고 있습니다. 사냥꾼: 해변에서 {npc:3107}을(를) 길들이세요.",
		["Quilboars and scouts hold the huts west of town, where the prickly pears grow; dustrunners and battleguards hold the camps farther west."] = "가시멧돼지와 정찰병이 가시배가 자라는 마을 서쪽 오두막을, 사막길잡이와 전투호위병이 더 서쪽의 야영지를 차지하고 있습니다.",
		["Spitelash naga"] = "원한의꼬리일족 나가",
		["Tame it with the {item:15908}"] = "{item:15908}(으)로 길들이세요",
		["The Scorpid Workers roam the slope south of {npc:3287}; pick the Cactus Apples by the cactuses on the way.\nThe {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "일꾼전갈은 {npc:3287} 남쪽 비탈을 돌아다닙니다. 가는 길에 선인장 옆에서 선인장 사과를 따세요.\n{quest:792}은(는) 골짜기 북쪽의 동굴인 {area:365} 아래 비탈에 득실거립니다.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "부들과 창풀은 골목길 동쪽, {object:172958}의 물가를 따라 자랍니다.",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}."] = "요새는 {area:362} 남동쪽 해안에 있습니다. 약탈자의 도끼, 활, 방패는 요새 외곽에 있습니다. 선원과 해병이 {item:4870}을(를) 떨어뜨립니다.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "무기는 동굴 막사와 훈련장 주변에 있고, {npc:3098}은(는) 골짜기 바닥 전체를 돌아다닙니다.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595}은(는) 방금 싸운 이교도들 사이, {area:817} 안에 있습니다.",
		["Through Sen'jin on the way west to {area:366}: {npc:3304} takes the eyes and mucus now."] = "서쪽 {area:366}(으)로 가는 길에 센진 마을을 지나세요. 이제 {npc:3304}에게 눈과 점액을 제출할 수 있습니다.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "천둥도마뱀과 번개도마뱀은 {zone:1454}(으)로 가는 북쪽 길가의 {area:369}에서 풀을 뜯으며, 어느 것이든 {item:6486}을(를) 떨어뜨릴 수 있습니다. 다음 가이드가 {area:379}을(를) 지날 때 {npc:5810}이(가) 받습니다.\n주의: 12레벨 정예 할리코르가 도마뱀들 사이로 {area:369}을(를) 돌아다닙니다. 끌어오기 전에 그를 살피세요.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "천둥도마뱀과 번개도마뱀은 {npc:3293} 바로 서쪽과 남서쪽의 {area:369}에서 풀을 뜯습니다.\n주의: 12레벨 정예 할리코르가 도마뱀들 사이로 {area:369}을(를) 돌아다닙니다. 끌어오기 전에 그를 살피세요.",
		["Thunder lizards on the way north"] = "북쪽으로 가는 길의 천둥 도마뱀",
		["To {zone:1454}"] = "{zone:1454}(으)로",
		["Top up here to level 11 before {npc:3203} (12) and his imp: the Thunder Lizards (9-10) graze on the ridge just west of Misha's hut."] = "{npc:3203}(12)과(와) 그의 임프에게 가기 전에 여기서 11레벨까지 올리세요. 천둥도마뱀(9-10)은 미샤의 오두막 바로 서쪽 산등성이에서 풀을 뜯습니다.",
		["Top up here to level 7 before {npc:3192} (8) and the marines at the top of the keep."] = "요새 꼭대기의 {npc:3192}(8)와(과) 해병에게 가기 전에 여기서 7레벨까지 올리세요.",
		["Top up here to level 9 before the southern isles: the Voodoo and Hexed Trolls there are 8-9 and {quest:826} is 10."] = "남쪽 섬에 가기 전에 여기서 9레벨까지 올리세요. 그곳의 부두교 트롤과 주술에 걸린 트롤은 8-9레벨이고 {quest:826}은(는) 10레벨입니다.",
		["Training weapons and boars"] = "훈련용 무기와 멧돼지",
		["Underwater"] = "물속",
		["Upstairs"] = "위층",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there; Durotar Tigers roam the isle and the shore south of Sen'jin."] = "물을 건너 북쪽 메아리 섬으로 가세요. 붉은발톱랩터 어미가 그곳 랩터들 사이를 어슬렁거리고, 듀로타 호랑이가 섬과 센진 남쪽 해안을 돌아다닙니다.",
		["Wake {quest:5441} with the {item:16114}"] = "{item:16114}(으)로 {quest:5441} 깨우기",
		["grind on {npc:3121}"] = "{npc:3121} 사냥",
		["grind on {npc:3128}"] = "{npc:3128} 사냥",
		["grind on {npc:3130}"] = "{npc:3130} 사냥",
		["the {object:654925} on the ground beside her"] = "그녀 옆 땅바닥의 {object:654925}",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366}은(는) 센진 서쪽에 있습니다. 공격 계획서 세 개는 켄타우로스 천막 사이 땅바닥에 있습니다. {npc:275811}도 그곳에 붙잡혀 있습니다.",
		["{area:817}'s mouth"] = "{area:817} 입구",
		["{npc:10176}, where you start"] = "{npc:10176}, 시작 지점",
		["{npc:11025} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:202} 숙련도가 20이 되면 {npc:11025}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:11378} first, just east of the Den as you come down from the cave; then inside the Den ({npc:3143}, your trainer, {npc:3707}), and {npc:3145} and {npc:5887} at the entrance on the way out east to {npc:6786}."] = "동굴에서 내려오면 먼저 동굴 막사 바로 동쪽의 {npc:11378}, 그다음 동굴 막사 안({npc:3143}, 직업 상급자, {npc:3707}), 그리고 동쪽의 {npc:6786}에게 나가는 길에 입구의 {npc:3145}와(과) {npc:5887}입니다.",
		["{npc:12430} kneels behind the rocks just off the road south of {area:362}, on your way to the keep. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12430}은(는) 요새로 가는 길에, {area:362} 남쪽 길에서 살짝 벗어난 바위 뒤에 무릎을 꿇고 있습니다. 그녀에게 {spell:613}(2레벨)을 시전한 뒤 {spell:1243}을(를) 시전하세요. {spell:613} 1레벨은 인정되지 않습니다.",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809}은(는) {area:362} 바로 남쪽에 야영하고 있습니다. {spell:1229451} 효과가 나타날 때까지 그의 모닥불 옆에 앉으세요(/sit). 전문 기술을 배웠다면 {npc:265809}이(가) 야영 101 퀘스트도 줍니다. 해당 기술 전문가에게 전달하세요. 전문가는 {area:362}에 있거나, 다음 가이드 시작 지점인 {zone:1454}에 있습니다.",
		["{npc:265809}'s campfire"] = "{npc:265809}의 모닥불",
		["{npc:265809}: for Jandi"] = "{npc:265809}: Jandi에게 전달",
		["{npc:265809}: for Jhag"] = "{npc:265809}: Jhag에게 전달",
		["{npc:265809}: for Karolek"] = "{npc:265809}: 카롤렉에게 전달",
		["{npc:265809}: for Snang"] = "{npc:265809}: Snang에게 전달",
		["{npc:265809}: for Thuwd"] = "{npc:265809}: 투우드에게 전달",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}: {npc:11025}에게 전달",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809}: {npc:11046}에게 전달",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}: {npc:3175}에게 전달",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}: {npc:5943}에게 전달",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: 마법부여사 전용, 잔여물은 {item:275724}을(를) 마력 추출해서 얻습니다",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657}은(는) {area:362} 동쪽 해안에 서 있습니다. 삼지창, 깃발, 단검은 그 주변 해변에 있습니다.",
		["{npc:3102} hooves"] = "{npc:3102} 발굽",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, {area:362}에 돌아가서",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: 정예 바다 거인 {npc:275666}",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143}은(는) 동굴 입구 바로 안쪽에, {npc:3159}은(는) 그 뒤 동굴 안쪽에 서 있습니다.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143}은(는) {npc:10176} 바로 서쪽 건물인 동굴 막사 안에서 기다립니다.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, 감시탑 안",
		["{npc:3175} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:186} 숙련도가 20이 되면 {npc:3175}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "{npc:3192}은(는) 요새 꼭대기에서 기다리며, 그의 열쇠로 옆 상자를 열면 {item:4881}이(가) 들어 있습니다.",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287}은(는) 동굴 막사 북서쪽 언덕 기슭에 부상당한 채 누워 있습니다.",
		["{npc:3706}, beside {npc:266940}: the {item:16606}"] = "{npc:3706}, {npc:266940} 옆: {item:16606}",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, {zone:1454}의 {npc:6018}에게 줄 것: 보관하세요",
		["{npc:3706}, in the barracks beside {npc:266940}"] = "{npc:3706}, {npc:266940} 옆 병영 안",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, 동굴 막사의 사제 상급자",
		["{npc:3707}, the priest trainer at the Den: for {npc:3706} in {area:362}"] = "{npc:3707}, 동굴 막사의 사제 상급자: {area:362}의 {npc:3706}에게 전달",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it.\nCareful: the voidwalker you summon hits hard and it is the fight Warlocks die to most in {zone:1454}: start at full health and mana, send your imp in, keep Corruption and Immolate on it, and use a healthstone if you have one."] = "{npc:5875}은(는) {object:172982} 아래 협곡인 {object:172960}에 있습니다. 그에게 {item:6535}을(를) 건넨 뒤, 옆의 소환진에서 {item:7464}을(를) 사용하고 공허방랑자를 물리쳐 속박하세요.\n주의: 소환한 공허방랑자는 강하게 공격하며, {zone:1454}에서 흑마법사가 가장 많이 죽는 전투입니다. 생명력과 마나를 가득 채우고 시작하고, 임프를 먼저 보내고, 부패와 제물을 계속 걸어 두고, 생명석이 있다면 사용하세요.",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887}은(는) 동굴 막사 바깥에 서 있습니다. {area:639}은(는) 그 바로 남쪽 언덕입니다. 그곳에서 {item:6635}을(를) 마셔 {npc:5891}을(를) 보고, {item:6656}을(를) {npc:5887}에게 가져가세요.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873}, {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, {area:639} 위",
		["{npc:5943} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:129} 숙련도가 20이 되면 {npc:5943}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786}은(는) 골짜기 동쪽 출구의 길 위에 서 있습니다.",
		["{npc:9796} stands just outside the Den's entrance."] = "{npc:9796}은(는) 동굴 막사 입구 바로 바깥에 서 있습니다.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, 요리용 모닥불 옆",
		["{quest:790}, a large scorpid (level 4), prowls the slope just west of the Den, below {npc:3287}, on the way north to the {area:365}."] = "큰 전갈인 {quest:790}(4레벨)은(는) {area:365}(으)로 북쪽으로 가는 길, {npc:3287} 아래 소굴 바로 서쪽 비탈을 배회합니다.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828}은(는) 나가 해변 서쪽, {quest:827} 남쪽 언덕에 진을 치고 있습니다.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "{zone:1454} 정문은 {area:817} 바로 서쪽에 있습니다. {npc:5875}은(는) {object:172982} 아래 협곡인 {object:172960}에 서 있습니다.",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["/sit by her campfire until you get {spell:1229451}"] = "{spell:1229451}을(를) 얻을 때까지 그녀의 모닥불 옆에서 /앉기 하세요",
		["Ask {npc:10666} for his report"] = "{npc:10666}에게 보고를 요청하세요",
		["Ask {npc:1496} for his report"] = "{npc:1496}에게 보고를 요청하세요",
		["Ask {npc:251001} for his report"] = "{npc:251001}에게 보고를 요청하세요",
		["Back to the church"] = "교회로 돌아가기",
		["Back to {area:154}"] = "{area:154}(으)로 돌아가기",
		["Back up the road and through {area:159} to its west end."] = "길을 따라 돌아가 {area:159}을(를) 지나 서쪽 끝까지 가세요.",
		["Beat {npc:6784} in the duel"] = "결투에서 {npc:6784}을(를) 이기세요",
		["Below ground"] = "지하",
		["Crusader's Outpost"] = "붉은십자군 전초기지",
		["Dry Branches"] = "마른 가지",
		["Eleanor camps just south-west of town. With a profession learned, she also offers its Camping 101, which its trainer takes: in {area:159}, at Linnea's camp, or in the {zone:1458} in the next guide."] = "엘리노어 섀클턴은 마을 바로 남서쪽에서 야영합니다. 전문 기술을 배웠다면 그녀가 해당 야영 기초 퀘스트도 주며, 그 기술의 상급자에게 가져가면 됩니다. 상급자는 {area:159}, 리니아의 야영지, 또는 다음 가이드의 {zone:1458}에 있습니다.",
		["Eleanor: for {npc:2114}"] = "엘리노어: {npc:2114}에게",
		["Eleanor: for {npc:2132}"] = "엘리노어: {npc:2132}에게",
		["Eleanor: for {npc:3523}"] = "엘리노어: {npc:3523}에게",
		["Eleanor: for {npc:3549}"] = "엘리노어: {npc:3549}에게",
		["Eleanor: for {npc:4586}"] = "엘리노어: {npc:4586}에게",
		["Eleanor: for {npc:4598}"] = "엘리노어: {npc:4598}에게",
		["Eleanor: for {npc:4605}"] = "엘리노어: {npc:4605}에게",
		["Eleanor: for {npc:5695}"] = "엘리노어: {npc:5695}에게",
		["Eleanor: for {npc:5759}"] = "엘리노어: {npc:5759}에게",
		["Eleanor: for {npc:6289}"] = "엘리노어: {npc:6289}에게",
		["Escort {npc:275954} out of the outpost"] = "{npc:275954}을(를) 전초기지 밖으로 호위하세요",
		["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "길을 따라 북쪽 {area:154}(으)로 가세요. 어둠의사제 사비스가 교회 앞에 서 있습니다.",
		["Follow the road east past the cult's farm. Bleeding Horrors and Wandering Spirits haunt the graves on the east side of the farmstead, where the {quest:99142} grows: Linnea wants eight of each.\nThe Scarlet Friars camp just north-east of the graves; {npc:1664} stands among them.\nThe spiders lurk in the woods at the far east end of the glades.\nCareful: Riptear (13) is elite and prowls west and north of the Scarlet Friars' camp: watch for him before you pull."] = "길을 따라 동쪽으로 교단 농장을 지나가세요. 피투성이 좀비와 떠도는 영혼은 농장 동쪽 무덤에 출몰하며, 그곳에 {quest:99142}이(가) 자랍니다. 리니아는 각각 8개를 원합니다.\n붉은십자군 수사는 무덤 바로 북동쪽에 야영하며, {npc:1664}이(가) 그들 사이에 있습니다.\n거미는 숲 동쪽 끝 숲속에 숨어 있습니다.\n주의: 립티어(13)는 정예이며 붉은십자군 수사 야영지의 서쪽과 북쪽을 배회합니다. 끌기 전에 그를 살피세요.",
		["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}.\nCareful: Rotting undead and Darkeye Bonecasters near the Agamands can join a fight as adds."] = "길을 따라 북서쪽 {area:157}(으)로 가세요. {npc:1657}은(는) 방앗간 남쪽 묘지를 걸어 다니고, 니사, 그레고르, {npc:1656}은(는) 방앗간 안에 출몰합니다. 덜그럭거리는 해골병사와 금이간 해골병사는 갈비뼈를, 검은눈 해골마법사는 두개골을 떨어뜨리며, 누구든 {item:2839}을(를) 떨어뜨릴 수 있습니다.\n주의: 아가만드 근처의 썩어가는 언데드와 검은눈 해골마법사가 싸움에 합류할 수 있습니다.",
		["Follow the road south-east from {area:159} past the zeppelin towers."] = "{area:159}에서 남동쪽 길을 따라 비행선 탑을 지나가세요.",
		["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "{area:159}에서 남동쪽 길을 따라 비행선 탑을 지나가세요. 리니아, 크리스토프, {npc:3549}이(가) 길가에서 야영합니다.",
		["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "{area:159}에서 남서쪽 길을 따라 붉은십자군 야영지로 가세요. {npc:1662}은(는) 남쪽 끝에 있으며, 그곳의 붉은십자군은 모두 반지를 떨어뜨릴 수 있습니다.",
		["Heal and fortify {npc:12428}"] = "{npc:12428}을(를) 치유하고 인내를 걸어 주세요",
		["Leave {area:154} by the road north-east. {npc:6784} stands by the farmhouse at the {area:156}; {npc:1519} stands by the road just past it."] = "북동쪽 길로 {area:154}을(를) 떠나세요. {npc:6784}은(는) {area:156}의 농가 옆에 서 있고, {npc:1519}은(는) 그 바로 너머 길가에 서 있습니다.",
		["Level 6"] = "레벨 6",
		["Listen to Leonid and {npc:246378}, then talk to him again"] = "리어니드와 {npc:246378}의 대화를 들은 뒤 그에게 다시 말을 거세요",
		["Mindless Zombies"] = "넋 나간 좀비",
		["Offer aid to the {npc:246143}"] = "{npc:246143}에게 도움을 주세요",
		["On the way back west, the Cult of the Damned holds the farm just south-east of {npc:1495}'s camp. The Necrotic Crystal Fragments lie on the ground among the cultists, and the cultists carry some too.\nCareful: the cultists (10-12) stand close together and the Neophytes cast: pull one at a time from the edge of the farm."] = "서쪽으로 돌아가는 길에, 저주받은 자의 교단이 {npc:1495}의 야영지 바로 남동쪽 농장을 차지하고 있습니다. 괴저 수정 파편은 교단원들 사이 땅에 놓여 있고, 교단원들도 일부 가지고 있습니다.\n주의: 교단원(10-12)은 붙어 서 있고 수습생은 주문을 씁니다. 농장 가장자리에서 하나씩 끄세요.",
		["Only if the letter dropped"] = "편지를 얻었을 때만",
		["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side. {npc:1661} wants their paws and wings: kill them as you meet them while you clear the skeletons."] = "덜그럭거리는 해골은 {area:154} 북쪽의 폐허가 된 집들을 배회합니다. 새끼 승냥이와 그늘박쥐는 마을 곳곳을 돌아다니고, 승냥이와 병든 그늘박쥐는 마을 동쪽에 있습니다. {npc:1661}은(는) 그들의 발과 날개를 원합니다. 해골을 처치하면서 만나는 대로 처치하세요.",
		["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "마른 가지는 {area:159} 남서쪽 끝 주변 땅에 떨어져 있습니다.",
		["The Scarlet Converts and Initiates hold the farm east of {area:154}. {npc:1919} wanders between the farmhouses: his remains are for {quest:6395}."] = "붉은십자군 순례자와 견습마법사가 {area:154} 동쪽 농장을 차지하고 있습니다. {npc:1919}은(는) 농가 사이를 돌아다닙니다. 그의 유해는 {quest:6395}에 필요합니다.",
		["The Scarlet camp"] = "붉은십자군 야영지",
		["The Scarlet farm"] = "붉은십자군 농장",
		["The Wanted poster beside Zygand"] = "자이간드 옆의 현상수배 전단",
		["The pumpkins grow in the Scarlet-held fields just north-west of the farmhouse.\nCareful: Farmers stand close to the pumpkins, so you can pull more than one at once. Scarlet mobs are found around the edges of the farm and a bit to the northwest. {npc:1936} (8, rare) walks the field."] = "호박은 농가 바로 북서쪽, 붉은십자군이 차지한 밭에서 자랍니다.\n주의: 농부들이 호박 가까이에 서 있어 한 번에 여럿을 끌 수 있습니다. 붉은십자군은 농장 가장자리와 약간 북서쪽에 있습니다. {npc:1936}(8, 희귀)이(가) 밭을 걸어 다닙니다.",
		["The zombies shamble around the graveyard and the houses just east of the church."] = "좀비는 교회 바로 동쪽의 묘지와 집 주변을 배회합니다.",
		["The {area:154} trainers stand around the church"] = "{area:154}의 상급자들은 교회 주변에 있습니다",
		["The {npc:1931}, in the inn's cellar"] = "여관 지하실의 {npc:1931}",
		["The {npc:246143}"] = "{npc:246143}",
		["The {object:164662} lie beside the ruined houses in the north of {area:154}."] = "{object:164662}은(는) {area:154} 북쪽의 폐허가 된 집 옆에 있습니다.",
		["Tirisfal Pumpkins"] = "티리스팔 호박",
		["Top up here to level 6 before the pumpkins: the Tirisfal Farmers and Scarlet Warriors in the fields are 6-7. The Decrepit Darkhounds (5-6) roam the hills just east of the farm."] = "호박을 하기 전에 여기서 레벨 6까지 채우세요. 들판의 티리스팔 농부와 붉은십자군 전사는 6-7레벨입니다. 광포한 암흑사냥개(5-6)는 농장 바로 동쪽 언덕을 돌아다닙니다.",
		["Use the {item:286176} on five idle Deathguards around town"] = "마을 주변에서 빈둥거리는 죽음의경비병 5명에게 {item:286176}을(를) 사용하세요",
		["Vile Fin Attackers"] = "Vile Fin Attacker",
		["Vile Fin Seers"] = "Vile Fin Seer",
		["Walk south from {area:159} to the {area:153} and down into the {area:1497}. {npc:4568} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "{area:159}에서 남쪽 {area:153}(으)로 가서 {area:1497}(으)로 내려가세요. {npc:4568}은(는) {object:36082}에 있습니다. 붉은십자군 야영지는 폐허 바로 서쪽입니다.",
		["Walk south from {area:159} to the {area:153} and down into the {area:1497}. {npc:5675} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "{area:159}에서 남쪽 {area:153}(으)로 가서 {area:1497}(으)로 내려가세요. {npc:5675}은(는) {object:36082}에 있습니다. 붉은십자군 야영지는 폐허 바로 서쪽입니다.",
		["You rise in the crypt at the south end of {area:154}. {npc:1568} waits just outside."] = "{area:154} 남쪽 끝의 지하실에서 깨어납니다. {npc:1568}이(가) 바로 밖에서 기다립니다.",
		["grind on {npc:1547}"] = "{npc:1547} 사냥",
		["{item:16333}, from {npc:1919}"] = "{npc:1919}에게서 {item:16333}",
		["{item:2320} from {npc:2118}, for Gretchen"] = "그레첸 데드마에게 줄 {item:2320}, {npc:2118}에게서 구입",
		["{item:2839}, a rare drop"] = "희귀 획득품 {item:2839}",
		["{item:7227}, in the farmstead's garden"] = "농장 정원의 {item:7227}",
		["{npc:12428} kneels by the north gate of {area:159}'s graveyard, on your way north. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Fortitude first does not count."] = "{npc:12428}은(는) 북쪽으로 가는 길에 있는 {area:159} 묘지 북문 옆에 무릎 꿇고 있습니다. 그에게 {spell:613}(2레벨)을 시전한 뒤 {spell:1243}을(를) 시전하세요. 인내를 먼저 걸면 인정되지 않습니다.",
		["{npc:1495}'s camp"] = "{npc:1495}의 야영지",
		["{npc:1499}, in the town hall"] = "마을 회관 안의 {npc:1499}",
		["{npc:1500}, in the inn"] = "여관 안의 {npc:1500}",
		["{npc:1560}, in the inn"] = "여관 안의 {npc:1560}",
		["{npc:1569}: the scroll for {npc:244808}"] = "{npc:1569}: {npc:244808}에게 줄 두루마리",
		["{npc:1570}, in the church"] = "교회 안의 {npc:1570}",
		["{npc:1661}, beside the church; inside"] = "교회 옆의 {npc:1661}, 안",
		["{npc:2114} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:182} 숙련도가 20이 되면 {npc:2114}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:2114}, beside Johaan: {quest:97957}"] = "연금술사 요한 옆의 {npc:2114}: {quest:97957}",
		["{npc:2119}, the warrior trainer; inside"] = "전사 상급자 {npc:2119}, 안",
		["{npc:2122}, the rogue trainer"] = "도적 상급자 {npc:2122}",
		["{npc:2123}, the priest trainer in the church"] = "교회 안의 사제 상급자 {npc:2123}",
		["{npc:2123}, the priest trainer in the church, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him now: the wounded guard Beryl sends you to needs it."] = "교회 안의 사제 상급자 {npc:2123}이(가) {area:159}의 {npc:2129}에게 보냅니다. 지금 그에게서 {spell:613}(2레벨)을 배우세요. 베릴이 보내는 부상당한 경비병에게 필요합니다.",
		["{npc:2123}: for {npc:2129} in {area:159}"] = "{npc:2123}: {area:159}의 {npc:2129}에게",
		["{npc:2124}, the mage trainer, in the church"] = "교회 안의 마법사 상급자 {npc:2124}",
		["{npc:2126}, the warlock trainer"] = "흑마법사 상급자 {npc:2126}",
		["{npc:2128}: {npc:4568} in the {zone:1458} takes it"] = "{npc:2128}: {zone:1458}의 {npc:4568}에게 가져가세요",
		["{npc:2129}, upstairs"] = "위층의 {npc:2129}",
		["{npc:2129}, upstairs: the {item:16607}"] = "위층의 {npc:2129}: {item:16607}",
		["{npc:2132} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:171} 숙련도가 20이 되면 {npc:2132}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:2132}, beside Johaan: {quest:97951}"] = "연금술사 요한 옆의 {npc:2132}: {quest:97951}",
		["{npc:2132}, beside Johaan; inside"] = "연금술사 요한 옆의 {npc:2132}, 안",
		["{npc:246152}, the Paladin trainer"] = "성기사 상급자 {npc:246152}",
		["{npc:267009} stands at {npc:1495}'s camp, on the road to the cult's farm."] = "{npc:267009}은(는) 교단 농장으로 가는 길의 {npc:1495} 야영지에 있습니다.",
		["{npc:3523} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:197} 숙련도가 20이 되면 {npc:3523}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:3523}, by the road west of {area:159}: {quest:97961}"] = "{area:159} 서쪽 길가의 {npc:3523}: {quest:97961}",
		["{npc:3549} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:165} 숙련도가 20이 되면 {npc:3549}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:4551}, the bat handler, on the way down from the Ruins"] = "폐허에서 내려오는 길의 박쥐 조련사 {npc:4551}",
		["{npc:5675}: he offers {quest:1473} only once this is handed in"] = "{npc:5675}: 이것을 제출해야만 {quest:1473}을(를) 줍니다",
		["{npc:5695} takes it once your {skill:333} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:333} 숙련도가 20이 되면 {npc:5695}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:5724}: {npc:5675} in the {zone:1458} takes it"] = "{npc:5724}: {zone:1458}의 {npc:5675}이(가) 받습니다",
		["{npc:5759} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:129} 숙련도가 20이 되면 {npc:5759}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:5759}, by the bar: {quest:97955}"] = "바 옆의 {npc:5759}: {quest:97955}",
		["{npc:6289} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{skill:393} 숙련도가 20이 되면 {npc:6289}이(가) 받습니다. 그때까지 채집하거나 제작하십시오. 그동안 가이드는 계속 진행됩니다.",
		["{npc:6289}, beside {npc:3549}: {quest:97960}"] = "{npc:3549} 옆의 {npc:6289}: {quest:97960}",
		["{npc:6390} waits in the mausoleum on the hill just north of town: open the gate and fight him."] = "{npc:6390}은(는) 마을 바로 북쪽 언덕의 묘지에서 기다립니다. 문을 열고 그와 싸우십시오.",
		["{object:1661} is under the {area:153}, beside the zeppelin towers. {npc:5675} is in the {object:36082}: use the {item:6284} on the summoning circle beside him and defeat the voidwalker. {npc:4606} is in the {object:36070}. {npc:4568} is in the {object:36082} too."] = "{object:1661}은(는) 비행선 탑 옆 {area:153} 아래에 있습니다. {npc:5675}은(는) {object:36082}에 있습니다. 그 옆의 소환진에서 {item:6284}을(를) 사용하고 공허방랑자를 물리치세요. {npc:4606}은(는) {object:36070}에 있습니다. {npc:4568}도 {object:36082}에 있습니다.",
		["{object:178090} is in the {area:154} graveyard, beside the church."] = "{object:178090}은(는) 교회 옆 {area:154} 묘지에 있습니다.",
		["{object:37098} stands beside {npc:1662} at the camp's south end."] = "{object:37098}은(는) 야영지 남쪽 끝 {npc:1662} 옆에 있습니다.",
		["{quest:90902}: the {npc:259377} lie around the church. Heal five of them with {spell:635}."] = "{quest:90902}: {npc:259377}이(가) 교회 주변에 누워 있습니다. 그중 5명을 {spell:635}(으)로 치유하세요.",
		["{quest:91208}: the {npc:246143} fled into the hills west of the church, on the way to {area:155}."] = "{quest:91208}: {npc:246143}은(는) {area:155}(으)로 가는 길, 교회 서쪽 언덕으로 도망쳤습니다.",
} end)()
t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "모험: 세계 지도 탐험",
		["Adventure: {npc:16042}"] = "모험: {npc:16042}",
		["All 13 Hyjal Summit bosses are a point. Hyjal Summit is a new 20-player Forever raid at the top of {zone:2482}, near Nordrassil, open from 9 December; its bosses are not in our data, so tick it off once all 13 are down."] = "Hyjal Summit 우두머리 13명을 모두 처치하면 1점입니다. Hyjal Summit은(는) Forever의 새 20인 공격대로, {zone:2482} 꼭대기의 놀드랏실 근처에 있으며 12월 9일부터 열립니다. 우두머리가 우리 데이터에 없으니, 13명을 모두 처치하면 직접 체크하십시오.",
		["All 8 Barrow Deeps bosses are a point. Barrow Deeps is a new 10-player Forever raid beneath {zone:2482}, entered from {zone:2482}, {zone:1452} or {area:1216} and open from 9 December; its bosses are not in our data, so tick it off once all 8 are down."] = "Barrow Deeps 우두머리 8명을 모두 처치하면 1점입니다. Barrow Deeps은(는) Forever의 새 10인 공격대로, {zone:2482} 아래에 있으며 {zone:2482}, {zone:1452}, {area:1216}에서 들어가고 12월 9일부터 열립니다. 우두머리가 우리 데이터에 없으니, 8명을 모두 처치하면 직접 체크하십시오.",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "직업은 27점을 줍니다: 각 직업이 25, 45, 60레벨에 도달할 때마다 1점입니다. 계정 전체에서 직업마다 한 번만 계산되므로, 이미 키운 직업의 두 번째 캐릭터는 점수를 주지 않고 새 직업은 점수를 줍니다. 보통 처음으로 25레벨에 도달한 캐릭터가 유산 시스템 자체를 해금합니다.",
		["Classes: level 25"] = "직업: 레벨 25",
		["Classes: level 45"] = "직업: 레벨 45",
		["Classes: level 60"] = "직업: 레벨 60",
		["Dire Maul East"] = "혈투의 전장 동쪽",
		["Dire Maul North"] = "혈투의 전장 북쪽",
		["Dire Maul West"] = "혈투의 전장 서쪽",
		["Dungeons: level 15-25"] = "던전: 레벨 15-25",
		["Dungeons: level 26-45"] = "던전: 레벨 26-45",
		["Dungeons: level 46-60"] = "던전: 레벨 46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "제작 전문 기술은 각각 150, 225, 300에서 1점씩, 총 3점을 줍니다. 단계는 계정 전체에서 전문 기술마다 한 번만 계산됩니다. Polestar 가이드 \"{skill:171} 1-300\"(전문 기술)을 따르십시오. 제작 전문 기술 150 달성으로도 유산 시스템이 해금됩니다.",
		["Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character. Forever's new zones are part of the map: the {zone:2548}, {zone:2652} and {zone:2482}, a level 60 zone."] = "한 캐릭터로 세계 지도 전체를 탐험하면 1점이며, 유산 시스템을 해금할 수도 있습니다. 모두 같은 캐릭터로 탐험해야 합니다. Forever의 새 지역도 지도에 포함됩니다: {zone:2548}, {zone:2652}, 그리고 60레벨 지역인 {zone:2482}.",
		["Follow the Polestar Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it. Exploration: Zephras Isle covers the Skyborne island; whether its map counts towards this challenge is not confirmed yet."] = "Polestar 탐험 가이드를 따르십시오: 탐험: 동부 왕국 1-30, 30-45, 45-60과 탐험: 칼림도어 1-30, 30-45, 45-60. 발견하는 모든 지역을 추적합니다. 탐험: 제프라스 섬은 스카이본 섬을 다룹니다. 이 섬의 지도가 이 도전에 포함되는지는 아직 확인되지 않았습니다.",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "Polestar 가이드 \"{skill:164} 1-300\"(전문 기술)을 따르십시오.",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "Polestar 가이드 \"{skill:165} 1-300\"(전문 기술)을 따르십시오.",
		["Follow the Polestar guide \"{skill:197} 1-300\" (Professions)."] = "Polestar 가이드 \"{skill:197} 1-300\"(전문 기술)을 따르십시오.",
