		["{area:2279}, Live side"] = "{area:2279}, 산 자 구역",
		["{area:2279}, Undead side"] = "{area:2279}, 언데드 구역",
		["{area:718} (appears after the {npc:3678}'s event)"] = "{area:718}({npc:3678} 이벤트 후에 나타남)",
		["{area:796}: Armory"] = "{area:796}: 무기고",
		["{area:796}: Cathedral"] = "{area:796}: 대성당",
		["{area:796}: Graveyard"] = "{area:796}: 묘지",
		["{area:796}: Library"] = "{area:796}: 도서관",
		["{npc:16012} then offers your class's {quest:9007}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "그다음 {npc:16012}이(가) 직업별 {quest:9007}을(를) 줍니다. 이 도전의 마지막 퀘스트로, 직업별 던전 세트 투구와 가슴 방어구를 받아 강화해 줍니다.",
		["{npc:16013} then offers your class's {quest:8999}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "그다음 {npc:16013}이(가) 직업별 {quest:8999}을(를) 줍니다. 이 도전의 마지막 퀘스트로, 직업별 던전 세트 투구와 가슴 방어구를 받아 강화해 줍니다.",
		["{npc:16033} offers it once {quest:8996} is turned in"] = "{quest:8996}을(를) 제출하면 {npc:16033}이(가) 줍니다",
		["{npc:16073}, inside Upper Blackrock Spire after Mea Culpa (no spawn in the data: the arrow leads to {npc:16033}'s {area:254})"] = "검은바위 첨탑 상층에서 '군주 발타라크여, 내 탓이오.' 이후의 {npc:16073} (데이터에 생성 위치 없음: 화살표는 {npc:16033}이(가) 있는 {area:254}(으)로 안내합니다)",
} end)()
t.guides["forever/miscellaneous/cozy-sleeping-bag"] = (function() return {
		["Along the coast to {zone:1436}"] = "해안을 따라 {zone:1436}(으)로",
		["At the gate in {area:1057} between Arathi and {area:287}, turn north and follow the wall on the {area:287} side to a fallen cart leaning against it. Jump up the cart and its ladder onto the wall, then over the rocks to the hidden camp. Some characters cannot fit under the cargo netting at the camp; another race or a smaller form gets through."] = "아라시와 {area:287} 사이 {area:1057}의 관문에서 북쪽으로 꺾어 {area:287} 쪽 성벽을 따라가면 성벽에 기대 쓰러진 수레가 있습니다. 수레와 사다리를 밟고 성벽 위로 올라간 뒤, 바위를 넘어 숨겨진 야영지로 가세요. 일부 캐릭터는 야영지의 화물 그물 아래를 지나갈 수 없으니, 다른 종족이나 더 작은 변신 형태로 지나가세요.",
		["Careful: off the dam's ledge you land in the river below it, in the {zone:1437}. Climb out on its west bank well before the waterfall at about 65,77: the fall kills. Then head north-west to the road and follow it north over {area:880} into Arathi, or hearth if your Hearthstone is set at {area:272}."] = "주의: 댐의 바위턱에서 떨어지면 그 아래 {zone:1437}의 강에 떨어집니다. 약 65,77의 폭포에 한참 못 미친 곳에서 서쪽 기슭으로 올라오십시오. 폭포에서 떨어지면 죽습니다. 그다음 북서쪽 길로 가서 길을 따라 북쪽으로 {area:880}을(를) 건너 아라시로 가거나, 귀환석이 {area:272}에 설정되어 있다면 귀환하십시오.",
		["From {object:3202} follow Stranglethorn's west coast north to {zone:1436}, swimming where the beach runs out. It is shorter than the jungle road north and keeps you clear of Stranglethorn's level 30+ beasts and of {zone:1431}."] = "{object:3202}에서 가시덤불 골짜기 서쪽 해안을 따라 북쪽 {zone:1436}(으)로 가고, 해변이 끊기는 곳에서는 헤엄치십시오. 북쪽 정글 길보다 짧고, 가시덤불 골짜기의 30레벨 이상 야수와 {zone:1431}을(를) 피할 수 있습니다.",
		["Out of the river"] = "강에서 나오기",
		["Passing {area:272} on the way to {zone:1432}? Set your Hearthstone here: after the dam, it brings you back next to {area:1057} instead of the long walk through the {zone:1437} and Arathi. Skip this step to keep your Hearthstone where it is."] = "{zone:1432}(으)로 가는 길에 {area:272}을(를) 지납니까? 이곳에 귀환석을 설정하십시오. 댐 다음에 {zone:1437}와(과) 아라시를 지나 먼 길을 걷는 대신 {area:1057} 바로 옆으로 돌아올 수 있습니다. 귀환석을 지금 위치에 두려면 이 단계를 건너뛰십시오.",
		["Stonetalon from the north"] = "북쪽에서 돌발톱 산맥으로",
		["Stranglethorn's west coast"] = "가시덤불 골짜기 서쪽 해안",
		["West bank"] = "서쪽 기슭",
		["West bank, before the waterfall"] = "폭포 전의 서쪽 기슭",
		["{area:272} on the way"] = "가는 길의 {area:272}",
		["{zone:1413}' way into Stonetalon runs through {area:1702}, and the road on to the hills passes {area:2539} and {area:460}: all Horde posts. Come in from the north instead. With the {area:467} flight path, fly there and follow the road south. Otherwise fly to {area:415} and walk south-west to the {area:1276}, the tunnel from {zone:1440} into Stonetalon."] = "{zone:1413}에서 돌발톱 산맥으로 가는 길은 {area:1702}을(를) 지나고, 언덕으로 이어지는 길은 {area:2539}와(과) {area:460}을(를) 지납니다. 모두 호드 거점입니다. 대신 북쪽에서 들어가십시오. {area:467} 비행 경로가 있다면 그곳으로 날아가 길을 따라 남쪽으로 가십시오. 없다면 {area:415}(으)로 날아가 남서쪽 {area:1276}까지 걸어가십시오. {zone:1440}에서 돌발톱 산맥으로 이어지는 터널입니다.",
} end)()
