t.guides["forever/professions/blacksmithing"] = (function() return {
		["10 {item:12799} for {item:12773}: {item:12799} turns up in about one {object:175404}, {object:177388} or {object:180215} in 143: keep the ones you find while mining."] = "{item:12773}에 쓸 {item:12799} 10개: {item:12799}은(는) {object:175404}, {object:177388}, {object:180215} 약 143개 중 하나에서 나옵니다. 채광하며 얻은 것은 보관하십시오.",
		["168 {item:3575} for {spell:3501}: {skill:186}: smelt {item:2772}."] = "{spell:3501}에 쓸 {item:3575} 168개: {skill:186}: {item:2772} 제련.",
		["19 {item:7909} for {quest:7654}: {item:7909} turns up in about one {object:2047} or {object:123309} in 500: keep the ones you find while mining."] = "{quest:7654}에 쓸 {item:7909} 19개: {item:7909}은(는) {object:2047}, {object:123309} 약 500개 중 하나에서 나옵니다. 채광하며 얻은 것은 보관하십시오.",
		["19 {item:7910} for {quest:7654}: {item:7910} turns up in about one {object:2047} or {object:123309} in 143: keep the ones you find while mining."] = "{quest:7654}에 쓸 {item:7910} 19개: {item:7910}은(는) {object:2047}, {object:123309} 약 143개 중 하나에서 나옵니다. 채광하며 얻은 것은 보관하십시오.",
		["195 {item:3859} for {item:6040}: {skill:186}: smelt {item:3575} and Coal."] = "{item:6040}에 쓸 {item:3859} 195개: {skill:186}: {item:3575}와(과) 석탄 제련.",
		["2026 {item:12359} for {item:12773}, {item:12775} and {quest:7654}: {skill:186}: smelt {item:10620}."] = "{item:12773}, {item:12775}, {quest:7654}에 쓸 {item:12359} 2026개: {skill:186}: {item:10620} 제련.",
		["206 {item:8170} for {item:12773} and {item:12775}: {skill:393}: beasts of level 48-60. Skin {npc:8598}, Plaguehound and {npc:8596} here (level 48-60); the {skill:393} guide routes this."] = "{item:12773}와(과) {item:12775}에 쓸 {item:8170} 206개: {skill:393}: 48-60레벨 야수. 여기서 {npc:8598}, 역병사냥개, {npc:8596}의 가죽을 벗기세요(48-60레벨). {skill:393} 가이드에 경로가 있습니다.",
		["210 {item:2840} for {spell:2666}: {skill:186}: smelt {item:2770}."] = "{spell:2666}에 쓸 {item:2840} 210개: {skill:186}: {item:2770} 제련.",
		["320 {item:2841} for {spell:2672}: {skill:186}: smelt {item:2840} and {item:3576}."] = "{spell:2672}에 쓸 {item:2841} 320개: {skill:186}: {item:2840}와(과) {item:3576} 제련.",
		["320 {item:3860} for {item:7930}: {skill:186}: smelt {item:3858}."] = "{item:7930}에 쓸 {item:3860} 320개: {skill:186}: {item:3858} 제련.",
		["44 {item:1210} for {item:7945}: {item:1210} turns up in about one {object:1731}, {object:1732} or {object:1733} in 100: keep the ones you find while mining."] = "{item:7945}에 쓸 {item:1210} 44개: {item:1210}은(는) {object:1731}, {object:1732}, {object:1733} 약 100개 중 하나에서 나옵니다. 채광하며 얻은 것은 보관하십시오.",
		["596 {item:3860} for {item:7933} and {item:7945}: {skill:186}: smelt {item:3858}."] = "{item:7933}와(과) {item:7945}에 쓸 {item:3860} 596개: {skill:186}: {item:3858} 제련.",
		["Artisan {skill:164}"] = "전문 {skill:164}",
		["Back to a {skill:164} trainer: {spell:2672} (from 95, 5s)."] = "{skill:164} 상급자에게 돌아가세요: {spell:2672}(95부터, 5실버).",
		["Back to a {skill:164} trainer: {spell:2674} (from 100, 10s)."] = "{skill:164} 상급자에게 돌아가세요: {spell:2674}(100부터, 10실버).",
		["Back to a {skill:164} trainer: {spell:7223} (from 160)."] = "{skill:164} 상급자에게 돌아가세요: {spell:7223}(160부터).",
		["Back to a {skill:164} trainer: {spell:9918} (from 175)."] = "{skill:164} 상급자에게 돌아가세요: {spell:9918}(175부터).",
		["Expert raises the cap from 150 to 225 for 50s (Classic's price; Forever's is not in the data); it needs {skill:164} 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance {npc:4258} ({zone:1455}); Horde {npc:3355} ({zone:1454}). The arrow picks the nearest of your faction. Learn now: {spell:3501} (from 140) and {spell:3337} (from 100, 10s). 150-225 takes about 10s of recipes and 28s of vendor goods, plus 234 {item:2838}, 168 {item:3575}, 195 {item:3859}, 320 {item:3860} and 30 {item:7912} to gather or buy."] = "숙련 단계는 50실버(클래식 가격이며, Forever 가격은 데이터에 없습니다)로 최대 숙련도를 150에서 225로 올립니다. {skill:164} 125와 캐릭터 레벨 20이 필요하므로, 125가 되면 언제 들러도 배울 수 있습니다. 가르치는 상급자는 몇 명뿐입니다: 얼라이언스는 {npc:4258}({zone:1455}), 호드는 {npc:3355}({zone:1454})입니다. 화살표가 진영의 가장 가까운 상급자를 가리킵니다. 지금 배우세요: {spell:3501}(140부터), {spell:3337}(100부터, 10실버). 150-225에는 제조법 약 10실버와 상인 재료 약 28실버, 그리고 채집하거나 살 {item:2838} 234개, {item:3575} 168개, {item:3859} 195개, {item:3860} 320개, {item:7912} 30개가 듭니다.",
		["Expert {skill:164}"] = "숙련 {skill:164}",
		["Journeyman raises the cap from 75 to 150 for 5s; it needs {skill:164} 50 and character level 10, so you can take it on any visit from 50. Not every {skill:164} trainer teaches it: Alliance {npc:3136} ({zone:1431}), {npc:252479} ({zone:2521}), {npc:10276} ({zone:1455}) and {npc:5511} ({zone:1453}); Horde {npc:276067} ({zone:1420}), {npc:252479} ({zone:2521}), {npc:4596} ({zone:1458}), {npc:2998} ({zone:1456}), {npc:1383} ({zone:1454}) and {npc:3478} ({zone:1413}). The arrow picks the nearest of your faction. Learn now: {spell:2666} (from 45, 2s) and {spell:3326} (from 50, 2s 50c). 75-150 takes about 19s 50c of recipes and 18c of vendor goods, plus 256 {item:2836}, 28 {item:2838}, 210 {item:2840} and 320 {item:2841} to gather or buy."] = "수습 단계는 5실버로 최대 숙련도를 75에서 150으로 올립니다. {skill:164} 50과 캐릭터 레벨 10이 필요하므로, 50이 되면 언제 들러도 배울 수 있습니다. 모든 {skill:164} 상급자가 가르치지는 않습니다: 얼라이언스는 {npc:3136}({zone:1431}), {npc:252479}({zone:2521}), {npc:10276}({zone:1455}), {npc:5511}({zone:1453}), 호드는 {npc:276067}({zone:1420}), {npc:252479}({zone:2521}), {npc:4596}({zone:1458}), {npc:2998}({zone:1456}), {npc:1383}({zone:1454}), {npc:3478}({zone:1413})입니다. 화살표가 진영의 가장 가까운 상급자를 가리킵니다. 지금 배우세요: {spell:2666}(45부터, 2실버), {spell:3326}(50부터, 2실버 50코퍼). 75-150에는 제조법 약 19실버 50코퍼와 상인 재료 약 18코퍼, 그리고 채집하거나 살 {item:2836} 256개, {item:2838} 28개, {item:2840} 210개, {item:2841} 320개가 듭니다.",
		["Journeyman {skill:164}"] = "수습 {skill:164}",
